    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:30.014107+00:00","domain":"probability theory","id":"claim_b7263d82e9d5a7677e44ead2c046fb87b31eecc5b3516ff97853588fdf24b0fd","kind":"concept","schema_version":1,"statement":"[Lemma 6 of arXiv:2605.04684, 'Ergodicity of stochastic functional differential equation with jumps and finite delay'] Let $N(\d t,\d z)$ be a Poisson random measure on $\mathscr{B}\left(\mathbb{R}_{+}\right) \otimes \mathcal{Z}$ with compensator $\nu(\d z)\d t$  and fix $T>0$. Let $Y$ be the solution to the SDE
\begin{equation}
    \mathrm{d} Y(t)  =-\lambda Y(t) \mathrm{d} t+\int_{Z}h(t,z) \widetilde{N}(\d t,\d z) ,\quad Y(0)  =0,
\end{equation}
where $h$ is predictable with almost surely c\`agl\`ad sample paths.
\begin{enumerate}
\item If $\mathbb{E}\left(\int_{0}^{T} \int_{Z}|h(t, z)| \nu(\d z) \d t\right)<\infty$, then for any stopping time $\tau$, there exists a function $\varrho:[0, \infty) \rightarrow[0, \infty)$ with $\lim _{\lambda \rightarrow \infty} \varrho(\lambda)=0$ such that
\begin{equation}
    \begin{split}
        \mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}|Y(t)|^{p}\right)& \leq \varrho(\lambda) \bigg[\mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}\int_{Z}|h(t,z)|^{q}\nu(\d z)\right)^{p/q}\bigg].
    \end{split}
\end{equation}
holds for any $q \in[1,2]$ and $p \in(0, q]$.

\item If  $\mathbb{E}\left(\int_{0}^{T} \int_{Z}|h(t, z)|^{2} \nu(\d z) \d t\right)<\infty$ and $p \geq 2$, then for any stopping time $\tau$, there exists a function $\varrho:[0, \infty) \rightarrow[0, \infty)$ with $\lim _{\lambda \rightarrow \infty} \varrho(\lambda)=0$ such that
\begin{equation}
    \begin{split}
        \mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}|Y(t)|^{p}\right)& \leq \varrho(\lambda) \bigg[\mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}\int_{Z}|h(t,z)|^{2}\nu(\d z)\right)^{p/2}\\
        &\qquad\qquad +\mathbb{E}\left(\sup _{0 \leq t \leq \tau \wedge T}\int_{Z}|h(t,z)|^{p}\nu(\d z)\right)\bigg].
    \end{split}
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:15:08.968221+00:00","domain":"probability theory","id":"claim_b728aac3f45006173f95a72ed72ac79570537d9f65bfe45f176a1908fe55d5cd","kind":"concept","schema_version":1,"statement":"[Theorem Theorem_corners_moments of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] Let $\{y^n_i\}_{1\leq i\leq k\leq N}\in \mathcal G_N$ be the G$\beta$E corners process of  variance $\tau$. Fix $m=1,2,\dots$ and take $2m$ positive integers $N_m\le N_{m-1}\le \dots \le N_1\le N$ and $k_1,k_2,\dots,k_m$. We have
 \begin{equation} 
  \mathbb E \left[ \prod_{\ell=1}^m \left(\sum_{i=1}^{N_\ell} \bigl(y^{N_\ell}_i\bigr)^{k_\ell}\right) \right]= \mathcal P_{k_m}^{N_m} \cdots \mathcal P_{k_2}^{N_2} \mathcal P_{k_1}^{N_1} \left[\exp\left(\frac{\tau}{2} \sum_{i=1}^N (x_i)^2\right)\right]_{x_1=\dots=x_N=0}.
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:59:24.049687+00:00","domain":"probability theory","id":"claim_b72c80179a98b3ad43baa59c2a37c987b66df3a574daf6d0f02aa8d33d6f91dc","kind":"theorem","schema_version":1,"statement":"[Proposition prop:critical-shift of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] As $s\to\infty$,
\begin{equation}
 \mathcal R_{N,\beta}(s)
 =2N-\frac{(N-2)^2}{4s}
