\end{align*}

and  (i) $\Rightarrow$ (iv) always holds true.  But (iv) $\Rightarrow$ (i) holds for all $X,Y\in \mathcal{X}_{[a,b]}$ if and only if $n\le 3$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:30:50.722765+00:00","domain":"probability theory","id":"claim_b76fd414b5ceed303926e72d20c992ededcb6f300f331b81618813d1880cc020","kind":"theorem","schema_version":1,"statement":"[Theorem GLML of arXiv:2609.02769, 'Divergence-Free Approximation in Sobolev and Lebesgue Spaces on general unbounded domains '] Let $\mathcal{H}$ be a Hilbert space, and let $\mathcal{V}$ and $\mathcal{E}$ be Banach spaces satisfying the Gelfand triple (equation eqn-gelfand of the paper). Let $1<p<\infty$, and set $p'=\frac{p}{p-1}$. Suppose that
	\begin{align*}
		\boldsymbol{y}\in
		\mathrm{L}^2(0,T;\mathcal{V})
		\cap
		\mathrm{L}^p(0,T;\mathcal{E})
	\end{align*}
	and
	\begin{align*}
		\boldsymbol{y}'=\boldsymbol{y}_1+\boldsymbol{y}_2
		\ \text{in }\mathcal{D}'(0,T;\mathcal{V}'+\mathcal{E}'),
	\end{align*}
	where
	\begin{align*}
		\boldsymbol{y}_1\in \mathrm{L}^2(0,T;\mathcal{V}'),
		\ 
		\boldsymbol{y}_2\in \mathrm{L}^{p'}(0,T;\mathcal{E}').
	\end{align*}
	Then $\boldsymbol{y}$ admits a unique representative, still denoted by
	$\boldsymbol{y}$, such that
	\begin{align*}
		\boldsymbol{y}\in \mathrm{C}([0,T];\mathcal{H}).
	\end{align*}
	Moreover, the map
	$t\mapsto\|\boldsymbol{y}(t)\|_{\mathcal{H}}^2$
	is absolutely continuous on $[0,T]$, and
	\begin{align*}
		\frac{\mathrm{d}}{\mathrm{d}t}\|\boldsymbol{y}(t)\|_{\mathcal{H}}^2
		=
		2\langle\boldsymbol{y}_1(t),\boldsymbol{y}(t)\rangle_{\mathcal{V}',\mathcal{V}}
		+
		2\langle\boldsymbol{y}_2(t),\boldsymbol{y}(t)\rangle_{\mathcal{E}',\mathcal{E}}
	\end{align*}
	for a.e.\ $t\in[0,T]$. Consequently, for every $0\leq s\leq t\leq T$, we have
	\begin{equation*}
		\begin{aligned}
			\|\boldsymbol{y}(t)\|_{\mathcal{H}}^2
			-
			\|\boldsymbol{y}(s)\|_{\mathcal{H}}^2
			=&
			2\int_s^t
			\langle\boldsymbol{y}_1(r),\boldsymbol{y}(r)\rangle_{\mathcal{V}',\mathcal{V}}
			\,\mathrm{d}r
			+
			2\int_s^t
			\langle\boldsymbol{y}_2(r),\boldsymbol{y}(r)\rangle_{\mathcal{E}',\mathcal{E}}
			\,\mathrm{d}r.
		\end{aligned}
	\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:11:11.713333+00:00","domain":"probability theory","id":"claim_b77059c7a665df82a1e9c25e308a2dc6a4542fcbe3700985e29d16a0e43a6f48","kind":"lemma","schema_version":1,"statement":"[Lemma lem:leading-field-convex-corner of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] Let $\rho_0\in H^1(\Omega)$ be the ordinary weak harmonic solution with boundary data $e_0$, and suppose its two incident traces are sidewise $C^{2,\gamma}$ with the same value at $V_m$, written $\rho_0(V_m):=e_0(V_m)$. Let $\alpha_c$ satisfy
