{"assumptions":[],"created_at":"2026-10-26T20:56:25.277879+00:00","domain":"probability theory","id":"claim_b873e6d150fccabb6a19d21d270289d6bc85af4faddfd2d7507ece7111463ea1","kind":"lemma","schema_version":1,"statement":"[Lemma 11 of arXiv:2606.21433, 'Central limit theorem for\\ the averaged Adam optimizer'] Let  $\beta\in(0,1)$,  $q\in(1-\beta,1]$, $\delta\in(0,\infty)$, $N\in\N\cup\{\infty\}$
and let $v^*$ be as in \cref{def:v_star}.
Moreover, let $(Z_n)_{n\in-\N_0}$ be a real-valued process that is adapted with respect to a filtration $(\cG_n)_{n\in-\N_0}$. We let
\bas{
\cR_{N}=\bigl\{\forall k\in\{-N+1,\dots,0\}: \P( Z_k^2 \ge \delta | \cG_{k-1}) \ge q \bigr\}
}
Then one has that 
\bas{
\E\Bigl[\1_{\cR_{N}} \1_{\bigl\{\sum_{k=-N+1}^0 \1_{\{Z_k^2\ge \delta\}}\ge 2\bigr\}} v^*((\1_{\{k> -N\}} Z_k)_{k\in-\N_0})^{-1}\Bigr]\le \frac\beta{(1-\beta)} \Bigl(\frac { q}{\beta-(1-q)}\Bigr)^2\, \delta^{-1}
}
and
\bas{
\P\Bigl(\cR_{N} \cap\Bigl\{\sum_{k=-N+1}^0 \1_{\{Z_k^2\ge \delta\}}\le 1\Bigr\}\Bigr)\le  (1-q)^{N-1} (1+(N-1)q).
}","status":"unverified"}

