{"assumptions":[],"created_at":"2026-10-27T23:00:22.667974+00:00","domain":"probability theory","id":"claim_b8c4bcb65063bbf9d8cac8e2c3471d185ca010494bd92d899eff746537e41dbf","kind":"concept","schema_version":1,"statement":"[Lemma eq: branching rule of arXiv:2411.01104, 'Gaussian universality of $p$-adic random matrix products via corners'] (Branching rule) For $\lambda=(\lambda_1,\ldots,\lambda_n)\in \Sig_n, \mu=(\mu_1,\ldots,\mu_{n-1}) \in \Sig_{n-1}$ with $\mu \prec_P \lambda$, let
\begin{equation}
    \psi_{\lambda/\mu}(t):= \prod_{\substack{i \in \mathbb{Z} \\ m_i(\mu) = m_i(\lambda)+1}} (1-t^{m_i(\mu)}).
\end{equation}
Then for $\lambda\in\Sig_n,\mu\in\Sig_{n-k}$, we have
\begin{equation}
P_{\lambda/\mu}(x_1,\ldots,x_k;t)=\sum_{\mu = \lambda^{(1)} \prec_P \lambda^{(2)} \prec_P \cdots \prec_P \lambda^{(k)}= \lambda} \prod_{i=1}^{k-1} x_i^{|\lambda^{(i+1)}|-|\lambda^{(i)}|}\psi_{\lambda^{(i+1)}/\lambda^{(i)}}(t).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:29:14.933138+00:00","domain":"probability theory","id":"claim_b8c5417525f3a8cd7bc42726f8817e12a47afa262df9d202385dcd4b70904f10","kind":"concept","schema_version":1,"statement":"[Lemma lem.TransitionGreen of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] The following estimates hold for the transition kernel $\overline{p}_t(\{0,1\},Y)$ and the Green function $\overline{g}_\lambda(Y)$:
		\begin{enumerate}
			\item [LandimGaussian] There exist finite positive constants $C_1,C_2,C_3$ such that for every $t>C_1$ and every $x<y$, the following estimate holds:
			\begin{equation*}
				\overline{p}_t(\{0,1\},\{x,y\})\leqslant \frac{2C_1}{1+t}\left(\exp\left(-\frac{\left\Vert{(x,y)}\right\Vert_{2}^2}{C_2t}\right)+\exp\left(-\frac{\left\Vert{(x,y)}\right\Vert_2}{C_2\log t}\right)\1_{\left\Vert{(x,y)}\right\Vert_2\geqslant \frac{C_3et}{\log t}}\right),
			\end{equation*}
			where the norm $\left\Vert{(x,y)}\right\Vert_2$ is defined as $\left\Vert{(x,y)}\right\Vert_2^2:=x^2+(y-1)^2.$
			\item [CarinciExact]
			The Laplace transform of the transition kernel for every $x<y$ is given by:
			\begin{equation*}
				\overline{g}_\lambda(\{x,y\})\\
				=\frac{1}{8\pi^2\mathbf{D}(\rho)}\int_{\pi}^{\pi}\int_{-\pi}^{\pi}\frac{e^{i(k_1 x+k_2(y-1))}+{\mathsf{A}}(\frac{k_1+k_2}{2},\lambda)e^{i(k_1 y+k_2(x-1))}}{2+\lambda-(\cos k_1+\cos k_2)}\, {\mathrm{d}} k_1\, {\mathrm{d}} k_2,
			\end{equation*}
			where the function ${\mathsf{A}}(k,\lambda)$ is defined as:
			\begin{equation*}
				{\mathsf{A}}(k,\lambda):=2\frac{\cos k\cdot(\xi_{\lambda,k}^{-2}-1)}{\cos k\cdot(\xi_{\lambda,k}^{-2}-1)-2(x_{\lambda,k}-\cos k)}-1,
			\end{equation*}
			with
			\begin{equation*}
				\xi_{\lambda,k}=x_{\lambda,k}-\sqrt{x_{\lambda,k}^2-1},\qquad x_{\lambda,k}=\frac{1}{\cos k}\left(1+\frac{\lambda}{2}\right).
			\end{equation*} 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:47:40.729309+00:00","domain":"probability theory","id":"claim_b8c60ab9c994891f6b2f4070d57d822e31c11054ee3334293265010caab3b187","kind":"concept","schema_version":1,"statement":"[Corollary coro:OU-back-time-used of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Suppose that $|m_0|=\mathsf{m}_{3}$, and define $T_0$ by:  
    \begin{align*}
