{"assumptions":[],"created_at":"2026-10-26T20:59:25.042624+00:00","domain":"probability theory","id":"claim_b920916f46ed1169d9c51d57954593239e09778b3d101e32d3fcb56f18575ad8","kind":"lemma","schema_version":1,"statement":"[Lemma 2 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] For any $n \in \mathbb{N}$, any $p \in [1,\infty]$, and any $B \subseteq N_{n}$, let 
	\begin{align}
	 \sqrt{	\operatorname{Var} \left( |B|^{-1/2} \sum_{i \in B} g(Z_{i})   \right) } \lesssim    \min \left\{  	\Gamma^{\mathrm{sum}}_{p}(B) ,  	\Gamma_p^{\sharp}(B) |B|^{1/2p}  \right\} \max_{i \in B}  ||g||_{L^{2p}(P_{Z_{i}})}, 
	\end{align}
where 
\begin{align*}
	\Gamma^{\mathrm{sum}}_{p}(B) : = \left\{  
	\begin{array}{ll}
		\sqrt{ \sum_{\rho \in R(B)}  	\frac{|S_{B}(\rho)|}{|B|}  \left( \alpha_{ \mathcal{F} , B }(\rho)  \right)^{1-\frac{1}{p} } }  & if~p \in (1,\infty] \\
		\sqrt{ \sum_{\rho \in R(B)}  	\frac{|S_{B}(\rho)|}{|B|} }  & if~p = 1
	\end{array}
	\right.
\end{align*}
and \begin{align*}
	\Gamma_p^{\sharp}(B)
	:=
	\left\{  
		\begin{array}{ll}
	\sqrt{ \left(
	\int_0^1
	\left[
	\sum_{\rho\in R(B)}
	\frac{|S_B(\rho)|}{|B|}
	1\{\alpha_{\mathcal F,B}(\rho)\geq u\}
	\right]^{\frac{p}{p-1}}
	du
	\right)^{1-\frac{1}{p} } } & if~p \in (1,\infty] \\
	\sqrt{ \sum_{\rho \in R(B)}  	\frac{|S_{B}(\rho)|}{|B|} }  & if~p = 1	
	 	\end{array}
 		 \right.
\end{align*}
with $R(B) : = \{ r \in \{ 0,1, \ldots, n-1\} \cup \{\infty\}    \colon 	S_{B}(r) \ne \emptyset  \}$.\footnote{We set $d_{n}(i,i) = 0$ and $\alpha_{\mathcal{F} , B }(0) = 1$. The case $r=\infty$ captures pairs that are not connected, which by our conditions are independent and thus $\alpha_{\mathcal{F} , B }(\infty) : =  0$.}

Moreover, if $\max_{i \in B} ||dP_{Z_{i}}/dP_0||_{\infty} \leq C$, for some measure $P_0$, then the norm can be taken to be $||.||_{L^{2p}(P_0)}$ and the factor $|B|^{1/2p}$ in expression  \ref{eqn:var.bound.text} can be dispensed with.","status":"unverified"}

