\item for any $v\in W^{1,p}_0(U)$, $t\in [0,T]$, $\mathbb{P}$-a.s.
\[\int_U X_t v\,\mathrm{d} z=\int_U x_0 v\,\mathrm{d} z-\int_0^t\int_U |\nabla X_s|^{p-2}(\nabla X_s \cdot \nabla v)\,\mathrm{d} z\, \mathrm{d} s +\int_U v B \, W_t \,\mathrm{d} z.\]
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.391303+00:00","domain":"probability theory","id":"claim_b95d1a3d785638052ae2f571da67e04d68814b42770e562b5d7bc52f66e90153","kind":"concept","schema_version":1,"statement":"[Theorem th:volume-of-critical-cluster of arXiv:2606.11503, 'Percolation on hierarchical lattices'] There exists constants $d_f$ (referred as the fractal dimension of $\mathcal{C}_{\{a_k, b_k\}}$) and $\uc{c:volume_low}, \uc{c:volume_high} > 0$ such that, at $p_\star$,
  \begin{equation}

    \uc{c:volume_low} d_f^k
    \leq \mathbb{E}_{p_\star}^{k} \big[ |\mathcal{C}_{\{a_k, b_k\}}| \big]
    \leq \uc{c:volume_high} d_f^k.
  \end{equation}
  Moreover, $d_f$ satisfies:
  \begin{enumerate}[\quad a)]
  \item $d_f < |\mathcal{E}_{1}|$,
  \item $d_f > \max \{ \deg^{\mathrm{out}}(a_1), \deg^{\mathrm{in}}(b_1), \deg(a_1) \wedge \deg(b_1) \}$.
  \end{enumerate}
  As a consequence, we obtain an estimate for the annealed one-arm connection probability.
  If $E_k$ denotes an uniformly selected edge in $G_k$, then
  \begin{equation}

    \uc{c:volume_low} \d_{k}(a_k, b_k)^{-\alpha_1}
    \leq \; \mathbb{P}_{p_\star}^{k} \big( E_k \leftrightarrow \{a_k, b_k\} \big)
    \leq \; \uc{c:volume_high} \d_{k}(a_k, b_k)^{-\alpha_1},
  \end{equation}
  where $\alpha_1 = \log \big( |\mathcal{E}_{1}|/d_f \big) / \log \d_{1}(a_1, b_1)$ is called the one-arm exponent. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.065122+00:00","domain":"probability theory","id":"claim_b95d34a8d61b966682ee8d8e7f4514e1aea2644567f0abd18e4a85eb98d93012","kind":"theorem","schema_version":1,"statement":"[Proposition 11 (Growth estimates of $u$ and $A_s u$) of arXiv:2606.00586, 'Stein's Method for Convergence Rates of Invariant Measures in the Nonlocal-to-Local Limit'] Assume $b$ satisfies \eqref{eq:dispt}, $f\in L^\infty (\mR^d)$ with $\|f\|_{L^\infty}\leq 1$. Then 
    \begin{enumerate}[(a)]
        \item There exists a solution $u$ to \eqref{eq:poisson} such that 
        \begin{equation}
            |u(x)|\leq C (1+|x|^{p_0}), \quad x\in \mR^d 
        \end{equation}
        where $C$ only depends on $\Theta$. 
        \item If $b$ also satisfies \eqref{eq:growth}, then for each $s$, $u\in \cX_{s,\eps}$ and $A_s u$ given by \eqref{eq:def_As} satisfies 
        \begin{equation}
            \big| A_s u(x) \big| \leq C  \exp\left(\frac{\kappa}{20d\theta} |x|^\theta\right), \quad x\in \mR^d, 
        \end{equation}
    where $C$ only depends on $\Theta$. 
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:29:35.103803+00:00","domain":"probability theory","id":"claim_b96238db59878a98e1a861d686cf2737e05c68c8a3a18cd1c544681666adee09","kind":"concept","schema_version":1,"statement":"[Theorem 1 (\cite{Li2025}) of arXiv:2609.03823, 'Weak rainbow saturation numbers of paths, stars and cycles'] Let $H$ be a non-empty graph. Then the following statements hold.
