\item[(ii)] $\sup_{n \in \mathbb{N}} \mathbb{E} \int_0^T \Vert \phi_n(s) \Vert_{\newone{V}}^\beta< \infty$.
\end{trivlist}
Then the laws $\{\mathbb{P}_n^2: n \in \mathbb{N}\}$ of $\phi_n$ are tight on 
$\bZ_{T,2}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:37:09.015355+00:00","domain":"probability theory","id":"claim_b986eb4a8716598a86fd66fbb23206d158e94729de12481ea69638492437aaa4","kind":"definition","schema_version":1,"statement":"[Definition def:bracket_regular of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] Fix $T > 0$ and $z_0 \in \mathcal{X}$. An operator $A \in \mathrm{Op}^{\beta_\star}$ is bracket-regular if:
  \begin{enumerate}[label=(\roman*)]
    \item for every $k \in \mathbf{Z}^2_*$ the commutator $[H^k, A]$ is bounded on both
      of the scales we shall test it against:
      \begin{enumerate}[label=(i-\alph*), ref=(i-\alph*)]
        \item $[H^k, A] \in \mathrm{Op}^{\beta_\star}$ with
          $\sup_{k \in \mathbf{Z}^2_*}  |k|^{-2} \| [H^k, A] \|_{\mathrm{Op}^{\beta_\star}} < \infty$,
        \item $[H^k, A] \in \mathcal{L}(H^{\beta_\star-2}; H^2)$ with
          $\sup_{k \in \mathbf{Z}^2_*} |k|^{-4} \| [H^k, A] \|_{\mathcal{L}(H^{\beta_\star-2};\, H^2)} < \infty$,
      \end{enumerate}
    \item the map $s\mapsto [G_{w_s}, A]$ belongs to $C( (0, T];
      \mathcal{L}(H^{\beta_\star-2}; H^2))$ almost surely,
    \item the commutator ${[L^0_{w}, A]}$ satisfies $ \|{[L^0_{w}, A]}
      \|_{\mathcal{L}(H^{\beta_\star}; \mathcal{H})} \lesssim \| w \|_{H^{s_\star-2}}$.
  \end{enumerate}
  A subspace $\mathfrak{g} \subseteq \mathrm{Op}^{\beta_\star}$ is \emph{bracket-generated} if $\mathfrak{g} = \bigcup_{j \geqslant 0} \mathfrak{g}_j$ for an increasing sequence of subspaces starting from $\mathfrak{g}_0 = \mathrm{Span}(H^k \colon k \in \mathbf{Z}^2_*)$ and satisfying
  \begin{equation}
    \mathfrak{g}_{j+1} = \mathfrak{g}_j + \mathrm{Span}(\mathcal{B}_j) ,
    \qquad
    \mathcal{B}_j \subseteq \bigl\{ [\Delta, A], \ [H^k, A] \colon A \in \mathfrak{g}_j , \ k \in \mathbf{Z}^2_* \bigr\} ,
  \end{equation}
  for some countable sets $\mathcal{B}_j$ such that the generators $H^k$ and every element of every $\mathcal{B}_j$ are bracket-regular. Bracket-regular operators form a linear space and every element of a bracket-generated family is bracket-regular.","status":"unverified"}

