{\rm d}_{\textsc{tv}}(t) & := &  \sup_{\mu\in\mathcal{P}(\mathbb{X})}{\rm d}_{\textsc{tv}}\left(\mu P_t,\pi\right) \  = \ \max_{x\in\mathbb{X}}{\rm d}_{\textsc{tv}}\left(P_t(x,\cdot),\pi\right).
\end{eqnarray*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:19:00.880614+00:00","domain":"probability theory","id":"claim_b9aa8b9aabbbbc4abfe08f9322da75e35629a6c6c160c55f97b78c20078dec78","kind":"concept","schema_version":1,"statement":"[Theorem 32 (Random-time peeking penalty) of arXiv:2608.20337, 'Information on trajectories:\\ martingales and random times'] Let $E_t(\lambda) = \exp(\lambda Y_t - \overline\Psi_t(\lambda))$ be a nonnegative supermartingale with $E_0(\lambda) \leq 1$, as in Proposition~\ref{prop:supermart-relax}(iii).
Define the peeking penalty $\cP_\tau(\lambda) := \log \E[E_\tau(\lambda)]$, and assume $0 < \E[E_\tau(\lambda)] < \infty$.
Then for every $Q \ll \widehat P$ with $Q(\{\Amart{\tau}_t=0\})=0$,
\begin{equation}
  \cP_\tau(\lambda)
  = \lambda \E_Q[Y_t] - \E_Q[\overline\Psi_t(\lambda)]
    + \E_Q[\log \Amart{\tau}_t] - \KL(Q\|\widehat P) + \KL(Q\|Q^\star_\tau),
\end{equation}
where $\dd Q^\star_\tau/\dd\widehat P \propto \Amart{\tau}_t\,E_t(\lambda)$; dropping the residual $\KL(Q\|Q^\star_\tau) \geq 0$ gives the variational (supremum) form.
For $\lambda > 0$ and any $A \in \sigma(\tau,\cF_\tau)$ such that on $A$ one has $Y_\tau \geq x$ and $\overline\Psi_\tau(\lambda) \leq c$, $\PP(A) \leq \exp\!\bigl(-\lambda x + c + \cP_\tau(\lambda)\bigr)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.712884+00:00","domain":"probability theory","id":"claim_b9ab76303720c525eba2cc33d0a943f9c4d1eb008d91a6e82f0d68b2adc86eb4","kind":"lemma","schema_version":1,"statement":"[Lemma lem:c_asymptotics of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For any given integer  $t \ge 2$,   the product of $t$   Chebyshev polynomials of the second kind admits a linearization
    \begin{equation}
        \Big(\frac{1}{m+1} U_m(x)\Big)^t = \sum_{k \ge 0} c_t(m; k) \, \frac{1}{k+1}U_k(x),
    \end{equation}
    where
    $c_t(m; k) = 0$ unless $k \equiv tm \pmod 2$.
    As $m \to \infty$, if   $k \equiv tm \pmod 2$ and
    $k = \lfloor \xi m \rfloor$ with $\xi \in (0, t)$,  then  the coefficients satisfy the asymptotic
    \begin{equation}
        c_t(m; k) \sim \frac{2}{m}   \, \xi \, \mathcal{P}_t(\xi),
    \end{equation}
    where   $\mathcal{P}_t(\xi)$ is defined  by (equation eq:Pt_def of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:20:30.621749+00:00","domain":"probability theory","id":"claim_b9b0575bfc2adc8c9293302088031c49f12ccf41b6caf45cb70a6b5985b8346f","kind":"concept","schema_version":1,"statement":"[Prop 9 of arXiv:2609.01889, 'Sufficiency of Hall's Condition for Graphic List Coloring'] Suppose $H,G,X\in \mathcal{G}(V)$. 
\begin{enumerate}
\item If $G$ has an isolated vertex, then no pair $(H,G)$ satisfies Hall's condition.
    \item   If $(H,G)$ satisfies Hall's condition and $X$ is a spanning subgraph of $H$, then $(X,G)$ satisfies Hall's condition.
    \item If $(H,G)$ satisfies Hall's condition and $G$ is a spanning subgraph of $X$, then $(H,X)$ satisfies Hall's condition.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.679094+00:00","domain":"probability theory","id":"claim_b9b187243040d087ce9af1f5f6ea24fc9bc01b9aff3d3328289799b96c3fd6c8","kind":"lemma","schema_version":1,"statement":"[Lemma 22 of arXiv:2609.02699, '\vspace{-0.5 cm}Gauge theory and symplectic structures'] On an almost K\"ahler $3$-fold, write
