{"assumptions":[],"created_at":"2026-10-27T19:26:26.797716+00:00","domain":"probability theory","id":"claim_bab00033031286cf9f58ce379033c76d0650a35aa301e4fc0f77669e691a4a47","kind":"theorem","schema_version":1,"statement":"[Proposition prop:physical-coagulation-equation of arXiv:2608.05105, 'Cluster-Cluster model in $\mathbb{Z}^d$'] For \(\alpha\ge-1\) and every \(k\ge1\),
\begin{equation}

\begin{aligned}
    c_k'(t)
    =\frac{1}{2d(t)}
      \sum_{i=1}^{k-1}K_\alpha(i,k-i)c_i(t)c_{k-i}(t) -\frac{c_k(t)}{d(t)}
      \sum_{j\ge1}K_\alpha(k,j)c_j(t),
\end{aligned}
\end{equation}
with \(c_1(0)=1\) and \(c_k(0)=0\) for \(k\ge2\). Moreover,
\begin{equation}

    d'(t)=-\sum_{k\ge1}k^{-\alpha}c_k(t).
\end{equation}
Equivalently, the particle densities satisfy

\begin{equation}

\begin{aligned}
    V_k'(t)
    &=\frac{k}{2d(t)}\sum_{i=1}^{k-1}
      \frac{K_\alpha(i,k-i)}{i(k-i)}V_i(t)V_{k-i}(t) 
      -\frac{kV_k(t)}{d(t)}\sum_{j\ge1}  \frac{K_\alpha(k,j)}{k j} V_j(t).
\end{aligned}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.677425+00:00","domain":"probability theory","id":"claim_bab09b461681c6af61c14098b11eb8e93fc9f074bd405ebeba5bcae0b20f9979","kind":"lemma","schema_version":1,"statement":"[Lemma lem:g(k)-k-small of arXiv:2602.14998, 'Random geometric graphs with smooth kernels: sharp detection threshold and a spectral conj'] There is a constant $C>0$ depending only on $k_0$ such that the following holds for all $k \le k_0$. 
