{"assumptions":[],"created_at":"2026-10-26T19:32:15.338580+00:00","domain":"probability theory","id":"claim_bbb370c46810401efc03da7ff3e5d8d21041737ac19bce41d7cf6d4c9e2b8d89","kind":"concept","schema_version":1,"statement":"[Theorem 4 of arXiv:2506.15044, '2506.15044'] \begin{itemize}
  \item [$(1)$] $H$ is a $\mathbb{B}$-predictable (resp. $\mathbb{B}$-locally bounded predictable) process if and only if there exists a predictable (resp. locally bounded predictable) process $\widetilde{H}$ satisfying
\begin{equation}
H=\widetilde{H}\mathfrak{I}_\mathbb{B}.
\end{equation}
  The process $\widetilde{H}$ is called a {\bf coupled  predictable} (resp. {\bf locally bounded predictable}) {\bf process} for $H$.
  \item [$(2)$] Let $X$ be a $\mathbb{B}$-optional process. Then $X$ is a $\mathbb{B}$-thin process if and only if $XI_\mathbb{B}$ is a thin process. Provided that for all $t>0$,
      $\sum_{s\leq t}|(XI_\mathbb{B})_s|$ is a.s. finite, the $\mathbb{B}$-restriction of $\sum_{s\leq \cdot}(XI_\mathbb{B})_s$ is called the $\mathbb{B}$-{\bf summation process} of $X$, denoted by $\Sigma X$, i.e.,
   \[
   \Sigma X=\left(\sum_{s\leq \cdot}(XI_\mathbb{B})_s\right)\mathfrak{I}_\mathbb{B}.
   \]
  \item [$(3)$] Let $\mathcal{D}$ be a class of processes which is stable under stopping, and suppose that $X\in \mathcal{D}^\mathbb{B}$ with the FCS $(T_n,X^{(n)})$. Define the predictable set $\mathbb{C}$ of interval type as
\[
\mathbb{C}=\bigcup\limits_{n}\llbracket{0,T_n}\rrbracket.
\]
Then there exists $\widetilde{X}\in\mathcal{D}^\mathbb{C}$ with the FCS $(T_n,\widetilde{X}^{T_{n}})$ satisfying $XI_\mathbb{B}=\widetilde{X}I_\mathbb{B}$ and
\begin{equation}
\widetilde{X}^{T_1}=(X^{(1)})^{T_1},\quad \widetilde{X}^{T_{n+1}}=\widetilde{X}^{T_{n}}+(X^{(n+1)})^{T_{n+1}}-(X^{(n+1)})^{T_n}, \; n\in \mathbf{N}^+.
\end{equation}
  The sequence $((T_n,X^{(n)}),\widetilde{X})$ (or simply $(T_n,X^{(n)},\widetilde{X})$) is called a {\bf continuation} for $X\in \mathcal{D}^\mathbb{B}$.
  \item [$(4)$] Let $\mathbb{B}$ be given by \eqref{B}, and let $\mathcal{D}$ be a class of processes. Suppose that $(X^{(n)})\subseteq \mathcal{D}$ denotes a sequence of processes, and that $(T_n)$ is an increasing sequence of stopping times, satisfying $T_n\uparrow T$ and $\bigcup\limits_{n=1}^{{+\infty}}\llbracket{0,T_n}\rrbracket\supseteq \mathbb{B}$. If for any $k, l\in \mathbf{N}^+$ with $k\leq l$,
      \begin{equation*}
      X^{(k)}I_{\mathbb{B}\llbracket{0,T_k}\rrbracket}=X^{(l)}I_{\mathbb{B}\llbracket{0,T_k}\rrbracket},
      \end{equation*}
then $X\in \mathcal{D}^\mathbb{B}$ with the FCS $(T_n,X^{(n)})$, where $X$ is defined by
\begin{equation*}
      X=\left(X^{(1)}_0I_{\llbracket{0}\rrbracket}+\sum\limits_{n=1}^{{+\infty}}X^{(n)}I_{\rrbracket{T_{n-1},T_n}
      \rrbracket}\right)\mathfrak{I}_\mathbb{B},\quad T_0=0.
      \end{equation*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

