{"assumptions":[],"created_at":"2026-10-27T06:21:45.247848+00:00","domain":"probability theory","id":"claim_bc4513a7d1a333c31f609a2c08efdfbb76b6a2c8a0a3bc778fbd6f25c3ba8ec6","kind":"theorem","schema_version":1,"statement":"[Proposition 27 of arXiv:2607.26564, 'Stochastic Scalar Conservation Laws on Moving Hypersurfaces'] Let $O$ be a bounded convex open set in $\mathbb{R}^n$ and the equation \eqref{eq59} be satisfied in $H^{-1}(O)$ for some $u=(u^1,\cdots, u^m)$. Assume that for $i \in \{1,\cdots,m\}$, $l \in \{1,\cdots,n\}$, and any open set $V \subset \subset O$, the coefficients $K^{il}$, $Y^i$ and $P^i$ belong to $L^2(\Omega; L^2([0,T]; L^2(V)))$, and $u^i \in L^2(\Omega; C([0,T]; L^2(V))) \cap L^2(\Omega; L^2([0,T]; H^1(V)))$. Let $F_t(\theta, x)$, $A_{1,t}(\theta, x)$, $A_{2,t}(\theta,x)$ $C_t(\theta,x)$, $\gamma_t(\theta,x)$ be real-valued predictable processes on $\Omega \times [0,T] \times O \times \mathbb{R}^m$ such that:
\begin{itemize}
\item [(A1)] $F_0(\theta, x)$ is $\mathcal{F}_0$-measurable.
\item [(A2)] For any $\omega \in \Omega$, $t \in [0,T]$ and $\theta \in O$, $F_t(\theta,\cdot) \in C^2(\mathbb{R}^m)$ and $C_t(\theta, \cdot) \in C^1(\mathbb{R}^m)$.
\item[(A3)] There exist an event $\Omega_{O}$ of full probability such that for each $\omega \in \Omega_{O}$, $F_t(\theta,x)$, $\nabla_{x}F_t(\theta, x)$, $\nabla^2_{x}F_t(\theta, x)$, $A_{1,t}(\theta, x)$, $A_{2,t}(\theta, x)$, $C_t(\theta, x)$, $\nabla_{x}C_t(\theta, x)$ and $\gamma_t(\theta,x)$ are continuous in $(t,\theta,x) \in [0,T] \times O \times \mathbb{R}^m$.

\item [(A4)] For any open set $V \subset \subset O$, there exists an event $\Omega_{V}$ of full probability, a random variable $C_V(\omega)$ and a positive constant $\widetilde{C_V}$ such that for each $t \in [0,T]$, $\theta \in V$, $x_1, x_2 \in \mathbb{R}^m$ and $\omega \in \Omega_{V}$
    \begin{equation}
     |A_{1,t}(\theta,x_1) - A_{1,t}(\theta,x_2)| \leq C_V(\omega)(1+ |x_1| + |x_2|)|x_1-x_2|, \quad |A_{2,t}(\theta,x_1)| \leq \widetilde{C_V},
     \end{equation}
     \begin{equation}
     |\nabla_{x}C_t(\theta, x_1)| \leq \widetilde{C_V}, \quad |\nabla^2_xF_t(\theta, x_1)| \leq \widetilde{C_V}, \quad |\gamma_t(\theta, x_1)| \leq \widetilde{C_V},
     \end{equation}






    \begin{equation}
    |\nabla_{\theta}\nabla_{x}F_t(\theta, x_1) - \nabla_{\theta}\nabla_{x}F_t(\theta, x_2) | \leq C_V(\omega)\{|x_1 - x_2| +|\gamma_t(\theta, x_1) - \gamma_t(\theta, x_2)|(1 + |x_1|)\}.
    \end{equation}
\item[(A5)] Let $A_t(\theta, x)= A_{1,t}(\theta,x) + A_{2,t}(\theta,x)$. For each $\theta \in O$ and $x \in \mathbb{R}^m$, $\mathbb{P}$-a.s.
\[ F_t(\theta, x) = F_0(\theta, x) + \int_0^t A_s(\theta, x)ds + \int_0^t C_s(\theta, x)dB_s  \]
for all $t \in [0,T]$.
\end{itemize}
Let $\psi \in C_c^1([0,T] \times O)$. Then $\mathbb{P}$-a.s.
\begin{eqnarray}
& &   \big\langle F_t(\theta, u(t,\theta)), \psi(t,\theta) \big\rangle \nonumber\\
&=& \big\langle F_0(\theta, u_0(\theta)), \psi(0,\theta) \big\rangle + \int_0^t \big\langle F_s(\theta, u(s,\theta)), \partial_t\psi(s,\theta) \big\rangle ds  \nonumber\\
  & & +\int_0^t \big\langle C_s(\theta, u(s,\theta)), \psi(s,\theta) \big\rangle dB_s + \int_0^t \big\langle \partial_{x_i}F_s(\theta, u(s,\theta))P^i(s,\theta), \psi(s,\theta) \big\rangle dB_s\nonumber\\
  & & + \int_0^t \big\langle A_s(\theta, u(s,\theta)), \psi(s,\theta) \big\rangle ds
      + \frac{1}{2}\int_0^t\big\langle \partial^2_{x_ix_j}F_s(\theta, u(s,\theta))P^i(s,\theta)P^j(s,\theta), \psi(s,\theta) \big\rangle ds  \nonumber\\
  & & - \int_0^t \big\langle \partial^2_{x_i\theta_l}F_s(\theta, u(s,\theta))K^{il}(s,\theta), \psi(s,\theta) \big\rangle ds
      -\int_0^t \big\langle \partial^2_{x_ix_j}F_s(\theta, u(s,\theta))\partial_{\theta_l}u^{j}(s,\theta)K^{il}(s,\theta), \psi(s,\theta) \big\rangle ds\nonumber\\
  & & - \int_0^t \big\langle \partial_{x_i}F_s(\theta, u(s,\theta))K^{il}(s,\theta), \partial_{\theta_l}\psi(s,\theta) \big\rangle ds
      + \int_0^t \big\langle \partial_{x_i}F_s(\theta, u(s,\theta))Y^i(s,\theta), \psi(s,\theta) \big\rangle ds \nonumber\\
  & & + \int_0^t \big\langle \partial_{x_i}C_s(\theta, u(s,\theta))P^i(s,\theta), \psi(s,\theta) \big\rangle ds \nonumber\\
  \end{eqnarray}
for all $t\in[0,T]$.","status":"unverified"}

