{"assumptions":[],"created_at":"2026-10-27T10:15:36.157928+00:00","domain":"probability theory","id":"claim_bcd0a6a30ed2bc85d4cba62020b8d15843788976655a88d1d8f3970863cfb753","kind":"lemma","schema_version":1,"statement":"[Lemma 7 (Uniform remainder of a finite Debye hierarchy) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] For $z\in[0,z_0]$, define
\[
 N_M(z)=\sum_{j=0}^Mz^jN_j,\qquad
 V_M(z)=\sum_{j=0}^Mz^jV_j,\qquad
 \Phi_M(z)=\sum_{j=0}^Mz^j\Phi_j,
\]
and put $\ell_j=s+3(M-j)+5$ for $0\le j\le M$.
Assume that the coefficient identities
\eqref{eq:coefficient-mass}--\eqref{eq:coefficient-poisson} hold through
order $M$, that the base profile has the bounds of
\cref{prop:smooth-simple-wave}, and that
\begin{equation}
\begin{split}
 \mathcal B_M={}&
 \sum_{j=1}^M\sup_{t_0\le t\le T}\bigl(
 \norm{(N_j,V_j,\Phi_j)(t)}_{H^{\ell_j}}
 +\norm{\pa_t(N_j,V_j,\Phi_j)(t)}_{H^{\ell_j-1}}\bigr)<\infty.

\end{split}
\end{equation}
Suppose also that the positive-order coefficients and their derivatives tend
to zero at spatial infinity.  Then, uniformly for $0\le z\le z_0$,
\begin{equation}
\begin{split}
 &\norm{\mathcal F_n(z)}_{H^{s+1}}
 +\norm{\mathcal F_u(z)}_{H^{s+1}}
 +\norm{\mathcal F_\phi(z)}_{H^{s+1}}
 +\norm{\pa_t\mathcal F_\phi(z)}_{H^s}
 \le C_{\mathcal B_M,t_0,T}z^{M+1},

\end{split}
\end{equation}
where
\begin{align}
 \mathcal F_n(z)&=\pa_tN_M(z)+\pa_1(N_M(z)V_M(z)),
 \\
 \mathcal F_u(z)&=\pa_tV_M(z)+V_M(z)\pa_1V_M(z)
 +\pa_1h_i(N_M(z))+\pa_1\Phi_M(z),
 \\
 \mathcal F_\phi(z)&=z\pa_1^2\Phi_M(z)
 -e^{\Phi_M(z)}+N_M(z).

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:43:44.247216+00:00","domain":"probability theory","id":"claim_bcd2fd08fcd4c5c872ec9303f52561cc955ba4a9c37b92eccb5f973afd3d29e8","kind":"concept","schema_version":1,"statement":"[Lemma 9 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Define the functions

\begin{align}
\begin{aligned}
R_\varepsilon(y) &\coloneqq \rho_\varepsilon(y) - \rho_\varepsilon(y)V_K(y)\int_{\mb T^d}\m K_\varepsilon(y-x)U_K(x)\rho_0(x)\,\dd x,\\
Q_\varepsilon(x) &\coloneqq \rho_0(x) - \rho_0(x) U_K(x)\int_{\mb T^d} \m K_\varepsilon(x-y) V_K(y)\rho_\varepsilon(y)\,\dd y.
\end{aligned}
\end{align}

Then, we have
\begin{align*}
\Big\|\frac{R_\varepsilon}{\rho_\varepsilon}\Big\|_{L^2(\mb T^d)} \leq C\varepsilon^{K+1}
\quad\mx{and}\quad
\Big\|\frac{Q_\varepsilon}{\rho_0}\Big\|_{L^2(\mb T^d)} \leq C\varepsilon^{K+1},
\end{align*}

for some constant $C > 0$ depending on the regularity set $\mathcal{RS}_{\rm SBE}^{(K)}(0, \varepsilon)$. Here, the set $\mathcal{RS}_{\rm SBE}^{(K)}(t, t+\varepsilon)$ with a given time point $0\leq t\leq 1-\varepsilon$ contains the elements
\begin{align}
\begin{cases}
\|u_{t,0}\|_{\m C^0}, \cdots \|u_{t,K}\|_{\m C^0}, \|u_{t,0}\|_{H^{2K+2}}, \cdots, \|u_{t,K}\|_{H^{2K+2}},\\
\|v_{t,0}\|_{\m C^0}, \cdots \|v_{t,K}\|_{\m C^0}, \|v_{t,0}\|_{H^{2K+2}}, \cdots, \|v_{t,K}\|_{H^{2K+2}},\\
\sup\big\{\|\rho_s^{(k)}\|_{\m C^{2k'}}: t\leq s\leq t+\varepsilon, \,\, k,k'\in\mb N,\,\,k+k'\leq K+1\big\},
\end{cases}
\end{align}
where $u_{t, k}$ and $v_{t,k}$ are defined by Equation~\eqref{eqn: uvtk}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:27:14.777927+00:00","domain":"probability theory","id":"claim_bcd41096e3bcf9ecdec28a3ef92fa1a87ad17477049ed29a73ee50ce71b4610e","kind":"lemma","schema_version":1,"statement":"[Lemma 2 (Cap Move) of arXiv:2608.22816, 'A Cap-Move Reformulation of Ling's Proof of Samuels' Conjecture'] Let $S = \sum_{i=1}^n X_i$ with $\bE[S]<\lambda$, and $S_i^a$ be the counterpart after applying the cap move $X_i \mapsto X_i\wedge a$. Also define $p=\bP(S<\lambda), p_i^a=\bP(S_i^a<\lambda)$, and
\begin{align}
	b(S) &:= \bE[S] - \bE\qth{S\mid S < \lambda },  \\
	r(S) &:= \lambda - \bE\qth{S\mid S < \lambda }.  
\end{align}
Then $b(S)\ge b(S_i^a)$, and 
