{"assumptions":[],"created_at":"2026-10-27T14:04:39.779380+00:00","domain":"probability theory","id":"claim_bce7d5e06303d950a862e4b94cae37fdb3aa870a5b7a0cafb92ef16ed5f3da9e","kind":"concept","schema_version":1,"statement":"[Proposition Prop:PW_estimate of arXiv:2609.02325, 'A Payne-Weinberger inequality\\for quantum dot Dirac operators'] Let 
