	&\hspace{-0.5cm}+ \int_0^t \big\langle \; \mathscr{U}(r), \, \beta(.) \dfrac{\mathbf{s}(r)\big(\mathbf{s}(r)+\mathbf{r}(r)\big)}{\mathbf{a}^2(r)}\varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr + \big\langle\, \mathscr{M}^S(t)\, , \, \varphi\; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} 
	\\[2mm]
	\big\langle \;  \mathscr{V}(t), \varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} &= \mu_I\int_0^t \!\!\big\langle \,  \mathscr{V}(r)\; ,\; \Delta\varphi \, \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}} dr - \int_0^t\big\langle \; \mathscr{V}(r), \, \beta(.) \dfrac{\mathbf{i}(r)\big(\mathbf{i}(r)+\mathbf{r}(r)\big)}{\mathbf{a}^2(r)}\varphi \; \big\rangle_{\!{\mathrm{H}^{-1},\mathrm{H}^{1}}}  dr\\
