{"assumptions":[],"created_at":"2026-10-28T02:47:21.611207+00:00","domain":"probability theory","id":"claim_bd8b47391a61a3c8eec5b83fd476eddb4c137e2c2e2ecc193e184a7df067193e","kind":"concept","schema_version":1,"statement":"[Proposition asso-game:characterization of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] \enskip 

\begin{enumerate}[(i)]
\item  Let $U:{\mathcal I}\rightarrow \mathbb{R}$ be a continuous function and define
\begin{align*}
\tau^{D_i}&:= \inf\{t \geq 0: X_t \in D_i\}, \enskip i=1,2,\\ 
D_1&:=\{x \in {\cal I}: \tilde f(x)= U(x)\},\\
D_2&:=\{x \in {\cal I}: \tilde g(x)= U(x)\}.
\end{align*}
Suppose that $e^{-r(t\wedge \tau^{D_1})}U(X_{t\wedge \tau^{D_1}}), 0 \leq t \leq \infty$ is a submartingale, that $e^{-r(t\wedge \tau^{D_2})}U(X_{t\wedge \tau^{D_2}}), 0 \leq t \leq \infty$ is a supermartingale, for each $X_0=x \in {\mathcal I}$ and that $\tilde f(x)\leq U(x)\leq\tilde g(x)$, for each $x \in {\mathcal I}$. Then, the equilibrium in Proposition (thm:assoc-game of the paper) is given by $V=U$ and $D_i^*=D_i, \enskip i=1,2$. 

\item It holds that $\in  D_1^* \cap D_2^*=B^{g \leq f}$ and the value function of the associated game satisfies 
\begin{align*}
V(x)= 
\begin{cases}
    \tilde f(x), 				&  x \in  D_1^*\\
    \tilde g(x), 				&  x \in  D_2^*\\
   \tilde f(x) =\tilde g(x), 				&  x \in  D_1^* \cap D_2^*=B^{g \leq f},
		 \end{cases}
\end{align*}
as well as
\begin{align}
\begin{split}
V(x)= 
\begin{cases}
			h(x), &  x \in {B^{g\leq h \leq f}} \subseteq D_1^* \cap D_2^*= B^{g \leq f}\\
			g(x), &  x \in {B^{h<g<f}} \subseteq D_1^* \cap D_2^*=B^{g \leq f}\\
			f(x), &  x \in {B^{g<f<h}} \subseteq D_1^* \cap D_2^*=B^{g \leq f},
		 \end{cases}
\end{split}
\end{align}
and
\begin{align}
\begin{split}
V(x)= 
\begin{cases}
			f(x), &  x \in  D_1^*\cap B^{f \leq g}\\
			g(x), &  x \in  D_2^* \cap B^{f \leq g}\\
            f(x)=g(x), &  x \in  D_1^*\cap D_2^* \cap B^{f \leq g}= B^{f = g}.
		 \end{cases}
\end{split}
\end{align}
Moreover, $f(x)\leq V(x)\leq g(x)$ or $g(x)\leq V(x)\leq f(x)$, for each $x\in {\cal I}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.503964+00:00","domain":"probability theory","id":"claim_bd8ca411d166cd0a9e8851b3fa41304506987b4ee72575b503bb6a1c5f977d3c","kind":"theorem","schema_version":1,"statement":"[Proposition 72 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $Y$ be a continuous $\bbr^{m \times d}$-valued process, and let $Y'$ be a continuous $\bbr^{m \times d \times d}$-valued processes such that $(Y,Y') \in \scrd_X^{2 \alpha}([0,T],\bbr^{m \times d})$ on $N_1^c$. Then the following statements are true:
\begin{enumerate}
\item The $\bbr^m$-valued rough integral
\begin{align*}
\int_0^T Y_s \, d \mathbf{B}^{\rm Strat}_s = \lim_{|\Pi| \to 0} \sum_{[u,v] \in \Pi} ( Y_u B_{u,v} + Y_u' \bbb_{u,v}^{\rm Strat} )
