{"assumptions":[],"created_at":"2026-10-27T22:46:36.162457+00:00","domain":"probability theory","id":"claim_c082de21add6b3d709c8bce8d7d429e151a4f235c9887d11d6581002ab25e2f0","kind":"lemma","schema_version":1,"statement":"[Lemma Lem_FamilyOfSmoothingKernels of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let
  $\chi \in C_c^\infty(\mathbb{R},[0,1])$ and $\rho \in C_c^\infty(\mathbb{R},[0,1])$ such that
  \begin{equation*}
    \chi|_{[-1,1]} = 1, \quad
    \supp(\chi) \subseteq [-2,2], \quad
    \rho(0) = 1, \quad\text{and}\quad
    \supp(\rho) \subseteq [-1,1].
  \end{equation*}
  Define the \defined{family of smoothing kernels} $\paren{\sigma_\varepsilon : \varepsilon \in (0,1) }$ by 
  \begin{equation*}
    \sigma_\varepsilon(r) \coloneq \mathscr{M}^{-1}(\chi_\varepsilon)(r) \rho(\log(r))
  \end{equation*}
  with $\chi_\varepsilon(\xi) \coloneq \chi(\varepsilon\xi)$.
  The following hold:
  \begin{enumerate}
  \item

    For every $\varepsilon \in (0,1]$, $k \in {\mathbf{N}}_0$, and $\xi \in \mathbb{R}$
    \begin{align}

      \abs{\mathscr{M}(\sigma_\varepsilon)(\xi)}
      &\lesssim_{\rho,k}
        \varepsilon^{-k}\bracket{\xi}^{-k}, \\


      \abs{\mathscr{M}(\sigma_\varepsilon)(\xi)-1}
      &\lesssim_{\rho,k}
        \varepsilon^k\bracket{\xi}^k, \\


      \abs{\varepsilon\partial_\varepsilon \mathscr{M}(\sigma_\varepsilon)(\xi)}
      &\lesssim_{\chi,\rho,k}
        \varepsilon^{-k}\bracket{\xi}^{-k}, \quad\text{and} \\


      \abs{\varepsilon\partial_\varepsilon \mathscr{M}(\sigma_\varepsilon)(\xi)}
      &\lesssim_{\chi,\rho,k}
        \varepsilon^{k}\bracket{\xi}^{k}.
    \end{align}
  \item












    For every $\varepsilon \in (0,1]$, $k \in \mathbb{Z}$, and $\xi \in \mathbb{R}$
    \begin{equation*}
      \abs{\varepsilon^{-1}\mathscr{M}(w_{\log} \sigma_\varepsilon)}
      \lesssim_{\chi,\rho,k}
      \varepsilon^k\bracket{\xi}^k \quad\text{and}\quad
      \abs{\partial_\varepsilon \mathscr{M}(w_{\log} \sigma_\varepsilon)}
      \lesssim_{\chi,\rho,k}
      \varepsilon^k\bracket{\xi}^k.
    \end{equation*}    

  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:38:58.722525+00:00","domain":"probability theory","id":"claim_c084c0872ba3846bb85c3d2c9ad0ad64a63d393b32d8fc46279d7912d9ed88a1","kind":"concept","schema_version":1,"statement":"[Lemma gNtNlmt of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Following hold for ${\sf g}_N$ when $\textbf{a}^{(\emptyset)} =0$.
