and 
\begin{equation*}
	Du_{\varepsilon} \rightarrow Du_{0} + \overline{D}_{\omega}u_{1} + \overline{D}_{y}u_{2} \quad  \;\textup{in} \; L^{\Phi}(Q\times\Omega)^{d}-weak \,\digamma\, \Sigma ,  
