{"assumptions":[],"created_at":"2026-10-26T19:37:51.450862+00:00","domain":"probability theory","id":"claim_c1ea44a6c04219ff061353c70a69e03b6886868598478d1ebaf7c842f004a24c","kind":"definition","schema_version":1,"statement":"[Definition 10 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Define
\begin{equation*}
	\psi(x) \coloneqq \begin{cases}
		1 & \text{if } 0\leq x< \frac12,\\
		-1 & \text{if } \frac12\leq x< 1, \\
		0 & \text{otherwise.}
	\end{cases}
\end{equation*}
Then, for $j \in \N_0$ and $k =0,\ldots,2^j-1$, set
$$\psi_{j,k}(x) \coloneqq 2^\frac{j}{2} \psi(2^jx-k) \qquad (x \geq 0).$$
Next, let $\{\phi_i : i \in \N\}$ be the set of functions in $L^2([0,1])$ given by $\phi_1 \coloneqq \1_{[0,1]}$ and $\phi_i \coloneqq \psi_{j,k}$ whenever $i=2^j +k+1$ for $j \in \N_0$ and $k=0,\ldots,2^j-1$.\footnote{$\{\phi_i : i \in \N\}$ is an orthonormal basis of $L^2([0,1])$, usually referred to as the \emph{Haar basis}.}
Finally, for each $i,n \in \N$, define
\begin{align*}
    e_i^n(x) & \coloneqq \phi_i(x-(n-1)) \qquad (x \geq 0),  \\
    c_{e_i^n} & \coloneqq \sqrt{1+\ln\left(i\right) + \ln\left(n\right)}.
\end{align*}
We call $\cB \coloneqq \{e_i^n : i,n\in \N\}$ the Haar basis of $H \coloneqq L^2(\R_+)$ and $c = (c_e)_{e \in \cB}$ the Brownian weights on $\cB$.
The set $\cB$ is, in fact, an orthonormal basis of $H = L^2(\R_+)$.","status":"unverified"}

