{"assumptions":[],"created_at":"2026-10-27T07:17:17.071394+00:00","domain":"probability theory","id":"claim_c21230e6926e172b37651a40c02dc1cac028cdc9b7293b626e2b53c238a722d9","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2608.19753, 'Uniform large deviation principles for the stochastic heat equation over unbounded sets of'] Let the conditions of Theorem \ref{th:Lp} be satisfied. Let 
\[
\tilde{p}\in
\begin{cases}
(4,\frac{2pq}{\lambda p-q}), \, &\text{if } q<\lambda p,\\
(4,\infty), &\text{if } q\geq \lambda p. 
\end{cases}
\]  
Let  $N\in[0,\infty)$, let $u\in L^2(0,T;L^2(D))$ with $\|u\|_{L^2(0,T;L^2(D))}\leq N$, and let $x\in L^q(D)$. 
Define mappings $\Psi_x^b, \Psi_x^{\sigma,u}\col E_T \to E_T$  and $\Psi_x^\sigma\col L^{\tilde p}(\Om;E_T)\to L^{\tilde p}(\Om;E_T)$ by
\begin{align}
\begin{split}
    \Psi_x^b(\phi)(t,\xi) &\ceqq\int_0^t \int_D G(t-s,\xi-\eta) b(S(s)x(\eta) + \phi(s,\eta))\dd\eta \dd s\\
    \Psi_x^{\sigma,u}(\phi)(t,\xi) &\ceqq \int_0^t \int_D G(t-s,\xi-\eta) \sigma(S(s)x(\eta) + \phi(s,\eta) )u(s,\eta) \dd\eta \dd s\\
    \Psi_x^\sigma(\phi)(t,\xi) &\ceqq \int_0^t \int_D G(t-s,\xi-\eta) \sigma(S(s)x(\eta) + \phi(s,\eta))W(\dd\eta \dd s).
    \end{split}
\end{align}  

The mappings above are well-defined, and the following Lipschitz bounds hold for all   $\phi,\psi \in E_T$,   $\tilde\phi,\tilde\psi\in L^{\tilde p}(\Om;E_T)$, and $t\in(0,T]$:
\begin{align}
\begin{split}
\|\Psi_x^{b}(\phi)-\Psi_x^{b}(\psi)\|_{E_t}^{\tilde{p}} 
    &\lesssim_{T,\tilde p} \int_0^t \|\phi-\psi\|_{E_s}^{\tilde{p}}\dd s,\\ 
    \|\Psi_x^{\sigma,u}(\phi)-\Psi_x^{\sigma,u}(\psi)\|_{E_t}^{\tilde p} 
    &\lesssim_{N,T,p,\tilde p} \int_0^t \|\phi-\psi\|_{E_s}^{\tilde p} \dd s,\\ 
    \|\Psi_x^{\sigma}(\tilde\phi)-\Psi_x^{\sigma}(\tilde\psi)\|_{L^{\tilde{p}}(\Om;E_t)}^{\tilde{p}}
    &\lesssim_{T,p,\tilde p} \int_0^t \|\tilde\phi-\tilde\psi\|_{L^{\tilde{p}}(\Om;E_s)}^{\tilde{p}}\dd s.  
 \end{split}
 \end{align}   
Furthermore,  $\Psi_x^b$ and $\Psi_x^{\sigma,u}$ with $u\in \A_N$ (see \eqref{eq:AN}) are also well-defined as mappings $L^{\tilde p}(\Om;E_T)\to L^{\tilde p}(\Om;E_T)$, and the first two bounds in \eqref{eq:PsiLip} hold a.s.\ for $\phi,\psi\in L^{\tilde p}(\Om;E_T)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:04.989042+00:00","domain":"probability theory","id":"claim_c212e4e50dd6aca9dd4542f17077bbc8f501f0197629945cee4812c3cbb68f43","kind":"theorem","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.00756, '\textbf{Stochastic ordering tools for continuous-time Markov chains and applications to re'] Consider a set $E \subseteq \mathbb{Z}^d$ and two rate matrices $q^X, q^Y : E \times E \longrightarrow \mathbb{R}_{\geq 0}$ with finite diagonal elements, extended to functions $\bar{q}^X, \bar{q}^Y : E \times \mathbb{Z}^d \longrightarrow \mathbb{R}_{\geq 0}$ by setting them equal to zero on $E \times (\mathbb{Z}^d \setminus E)$. Let $\rho \subseteq E \times E$ be a binary relation on $E$ such that for each $(x,y) \in \rho$ and $\xi \in \Z^d$ we have
\begin{enumerate}[label=\textup{(}\textit{\alph*}\textup{)}]
    \item $(x+\xi,y) \notin \rho \implies \bar{q}^X(x,x+\xi) \leq \bar{q}^Y(y,y+\xi)$,

    \item $(x,y+\xi) \notin \rho \implies \bar{q}^X(x,x+\xi) \geq \bar{q}^Y(y,y+\xi)$,

    \item $(x+\xi,y+\xi) \notin \rho \implies (x+\xi,y+\xi) \notin E \times E$.

\end{enumerate}
Then, for each pair of initial conditions $\rb{x^0, y^0} \in \rho$, there exist two CTMCs $X$ and $Y$ on the same probability space, with common state space $E$ and transition rates $q^X$ and $q^Y$, such that $X(0) = x^0$, $Y(0) = y^0$ and
\begin{equation*}
    \P \Brb{\brb{X(t),Y(t)} \in \rho \ \ \forall t \in [0, \tau^X \wedge \tau^Y)} = 1.
\end{equation*}","status":"unverified"}

