{"assumptions":[],"created_at":"2026-10-27T05:37:14.575324+00:00","domain":"probability theory","id":"claim_c22d05384b017dd0907f420dbd4a6fe65f16897dd576d0849ec7adc7502066de","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2607.11076, 'Smoluchowski-Kramers Approximation for Stochastic Differential Equations driven by Fractio'] Let $\mathscr{X}$ be a metric space with metric $\rho$. On the $\sigma$-algebra of its Borel subsets, let $\mu^{\varepsilon}$ be a family of probability measures depending on a parameter $\varepsilon>0$. Let $\lambda(\varepsilon)$ be a positive real-valued function going to $+\infty$ as $\varepsilon\downarrow 0$ and let $S(x)$ be a function on $\mathscr{X}$ assuming values in $[0,\infty]$. We shall say that $\lambda(\varepsilon)S(x)$ is an action function for $\mu^{\varepsilon}$ as $\varepsilon\downarrow 0$ if the following assertions hold:

		\begin{itemize}
			\item[(0)] the set $\Phi(s)=\{x:S(x)\leq s\}$ is compact for every $s\geq 0$;

			\item[(I)] for any $\delta>0$, any $\gamma>0$ and any $x\in\mathscr{X}$ there exists an $\varepsilon_{0}>0$ such that
			\begin{equation}
				\mu^{\varepsilon}\{y:\rho(x,y)<\delta\}\geq \exp\{-\lambda(\varepsilon)[S(x)+\gamma]\},
			\end{equation}
			for all $\varepsilon\leq \varepsilon_{0}$;

			\item[(II)] for any $\delta>0$, any $\gamma>0$ and any $s>0$ there exists an $\varepsilon_{0}>0$ such that
			\begin{equation}
				\mu^{\varepsilon}\{y:\rho(y,\Phi(s))\geq \delta\}\leq \exp\{-\lambda(\varepsilon)(s-\gamma)\},
			\end{equation}
			for all $\varepsilon\leq \varepsilon_{0}$.
		\end{itemize}

		If $X^{\varepsilon}$ is a family of random elements of $\mathscr{X}$ defined on the probability spaces $(\Omega^{\varepsilon},\mathscr{F}^{\varepsilon},\mathbb{P}^{\varepsilon})$, then the action function for the family of the distributions $\mu^{\varepsilon}$, $\mu^{\varepsilon}(A)=\mathbb{P}^{\varepsilon}(X^{\varepsilon}\in A)$ is called the action function for the family $X^{\varepsilon}$.In this case formulas (\ref{mu1}) and (\ref{mu2}) take the form:
		\[
		\begin{aligned}
			&\mathbb{P}^\varepsilon\{\rho(X^\varepsilon, x) < \delta\} \geq \exp\{-\lambda(\varepsilon)[S(x) + \gamma]\}, \\
			&\mathbb{P}^\varepsilon\{\rho(X^\varepsilon, \Phi(s)) \geq \delta\} \leq \exp\{-\lambda(\varepsilon)(s-\gamma)\}.
		\end{aligned}
		\]

		Separately, the functions $S(x)$ and $\lambda(\varepsilon)$ will be called the normalized action function and normalizing coefficient.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:05:52.397700+00:00","domain":"probability theory","id":"claim_c2313725e7139b67e744cda1bfc3010a0e8f4ac8dfe80bc35006086541793446","kind":"definition","schema_version":1,"statement":"[Definition netsandlevels of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] In this definition we always refer to $D=(D_1,D_2,D_3)$ as the collection of three disjoint intervals $D_1,D_2,D_3\subset[n]$ of cardinality $c_0^2n/12$ each, and we also use $D$ to denote the union $D=D_1\cup D_2\cup D_3$.
Fix two constants $\epsilon,\epsilon_1>0$. We define the following sets, threshold functions and discrete approximations:
\begin{enumerate}
    \item 
Subsets indicating the value of $v$ and $r$ on $D$:
$$\begin{aligned}\mathcal{I}(D):=&\{(v,r)\in \mathbb{S}^{n-1}\times\mathbb{S}^{n-1}:\langle v,r\rangle=0,\\&(\kappa_0+\kappa_0/2)n^{-1/2}\leq |v_i|,|r_j|\leq(\kappa_1-\kappa_0/2)n^{-1/2},\forall i\in D_1,\forall j\in D_2,\\&|v_i|,|r_i|\leq \sqrt{\frac{96}{c_0^2n}},\forall i\in D_1\cup D_2\cup D_3,\quad |\sin(v_D,r_D)|\geq c_{\rho,\delta}^2c_0^2/64 \}.\end{aligned}$$

$$\begin{aligned}\mathcal{I}'(D):=&\{(v,r)\in \mathbb{R}^{n+n}:\quad |\langle v,r\rangle|\leq \frac{1}{10},\\&\kappa_0n^{-1/2}\leq |v_i|,|r_j|\leq \kappa_1n^{-1/2},\forall i\in D_1,\forall j\in D_2\\&|v_i|,|r_i|\leq \sqrt{\frac{100}{c_0^2n}}\forall i\in D_1\cup D_2\cup D_3,\quad |\sin(v_D,r_D)|\geq c_{\rho,\delta}^2c_0^2/128 \}.\end{aligned}$$

\item For fixed $D$ and constants $0<\epsilon\leq\epsilon_1$, and any $c\in\mathbb{R}$ define the following sets
$$\begin{aligned}
\mathcal{P}_{\epsilon_1}(c)&:=\{(v,w)\in\mathbb{R}^n\times\mathbb{R}^n:\|v\|_2=1,\frac{9}{10}\leq\|w\|_2\leq\frac{11}{10},\exists r\in\mathbb{S}^{n-1}\text{ such that }\\&w=cv+\epsilon_1r,\quad (v,r)\in\mathcal{I}(D)
\},\end{aligned}$$  
$$\begin{aligned}\mathcal{P}^0_\epsilon(c)&:=\{(v,w)\in\mathbb{R}^{n}\times\mathbb{R}^{n}:\|v\|_2=1,\frac{9}{10}\leq\|w\|_2\leq\frac{11}{10},\exists r\in\mathbb{S}^{n-1},\exists t\in\mathbb{R},|t|\leq\epsilon\\&\text{such that }w=cv+tr,\quad (v,r)\in\mathcal{I}(D)\}.\end{aligned}$$

\item Discrete approximation of $\mathcal{P}_{\epsilon_1}$ and for $\mathcal{P}_\epsilon^0$ at scale $\epsilon:$ when $\epsilon_1\geq \epsilon$,
$$\begin{aligned}
\Lambda_{\epsilon,\epsilon_1}(c):=&\{
(v,w)\in B_n(0,2)\times B_n(0,2): v\in 4\epsilon n^{-1/2}\cdot\mathbb{Z}^n,\\&\text{ there exists } r\in B_n(0,2)\cap \frac{4\epsilon}{ \epsilon_1}n^{-1/2}\cdot\mathbb{Z}^n\text { such that }
w=cv+\epsilon_1r,\\&(v,r)\in \mathcal{I}'(D).\end{aligned}
$$

$$
\Lambda_\epsilon^0:=\{(v,v)\in B_n(0,2)\times B_n(0,2):v\in 4\epsilon n^{-1/2}\cdot\mathbb{Z}^n,v\in\mathcal{I}'(D)\}
$$(For a single vector $v$, we use $v\in \mathcal{I}'(D)$ to mean that $v$ satisfies all the conditions in $\mathcal{I}'(D)$ imposed on $v$, ignoring all the restrictions imposed on $r$.)

In the case when $D=[d]=[c_0^2n/4]$, we further make the following definitions:
\item Threshold: given $L>0$, $\epsilon_1>0$, for $(v,w)\in\mathcal{P}_{\epsilon_1}$(c) or $(v,w)\in{\Lambda_{\epsilon,\epsilon_1}}(c)$ define
\begin{equation}
