{"assumptions":[],"created_at":"2026-10-27T07:06:18.014375+00:00","domain":"probability theory","id":"claim_c2f434128cb4817cb16518b71fcd5fd657aad5921ab8d41b14803d44827afd69","kind":"lemma","schema_version":1,"statement":"[Lemma 20 of arXiv:2608.14802, 'Dynamical Gibbs-non-Gibbs transitions for finite-alphabet models on trees'] Let $l,\widetilde{l}\in \left(\Delta^{q-1}\right)^{d+1}$ with $l=(l^{(1)},\dots,l^{(d+1)})$ and $\widetilde{l}=(\widetilde{l}^{(1)},\dots,\widetilde{l}^{(d+1)})$. Define 
    \begin{equation}
R_{t,k}(l)
:=\frac{1}{Z(l)}\sum_{a\in S} P_t(a,k)H_a(l)~~\text{where}~~H_a(l)
:=\prod_{m=1}^{d+1}\sum_{b\in S} Q(a,b)l^{(m)}(b)
\end{equation}
and $Z(l):=\sum_{a\in S}H_a(l)$ for all $t>0$ and $k,a \in S$. Then, the following estimate in terms of $l$ and $\widetilde{l}$ holds for the root marginals 
\begin{equation}
    |R_{t,k}(l)-R_{t,k}(\widetilde{l})|\leq 2\left(\frac{\max_{i,j\in S}Q(i,j)}{\min_{i,j\in S}Q(i,j)}\right)^{d+1}\sum^{d+1}_{i=1}\|l^{(i)}-\widetilde{l}^{(i)}\|_{1}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:23:37.875155+00:00","domain":"probability theory","id":"claim_c2f578e85601503e78312995724d41a1690d91e631fae123147e7fa2bf6d3401","kind":"lemma","schema_version":1,"statement":"[Lemma 34 of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] Let $\varphi$ be an admissible solution of
    \eqref{eq:Extension_problem_TX} with boundary trace $f$, and suppose that
    the hypotheses of Lemma \ref{lem:relation_partialn_and_g} are satisfied.
    Then the following
    cancellation form of Green's formula holds:
    \begin{align*}
        f(x)=G_W\bigl(\partial_n^{(W)}\varphi\bigr)(x),
    \end{align*}
    where, for $q\in \mathcal{S}_0(X)$,
    \begin{align*}
        G_Wq(x)=\frac{1}{\kappa_W}
        \sum_{\substack{B\in\mathcal B\\B\ni x}}
        \frac{1}{W(B,B')}\int_Bq(y)\,dm(y).
    \end{align*}
    If, in addition,
    \begin{align*}
        \sum_{D\supseteq B_{x,y}}\frac{1}{W(D,D')}<+\infty,
        \qquad x\ne y,
    \end{align*}
    then the pointwise kernel representation is valid:
    \begin{align*}
        f(x)=\int_XG_W(x,y)\partial_n^{(W)}\varphi(y)\,dm(y),
    \end{align*}
    where
    \begin{align*}
        G_W(x,y)=\frac{1}{\kappa_W}
        \sum_{\substack{B\in\mathcal B\\B\supseteq B_{x,y}}}
        \frac{1}{W(B,B')}.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.526061+00:00","domain":"probability theory","id":"claim_c2f6df7edd2ffb02d6d9177d0b978f28c18310aba032e33ce59004f2ed4d6cea","kind":"concept","schema_version":1,"statement":"[Theorem Thm:SLLN of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Suppose that $\{X_k\}_{k\geq 1}$ is a d-dimensional $\alpha$-mixing stationary sequence on a regular sublinear expectation space $(\Omega,\mathcal{H},\hat{\mathbb{E}})$ for some $\alpha>0$ with $\hat{\mathbb{E}}[|X_1|^{2}]<\infty$. Let
   $\Gamma_*$ be defined as in (equation eq:Gamma* of the paper).
     Then 
     \begin{equation*}
         \lim_{n\to\infty}dist\left(\frac{1}{n}\sum_{k=1}^nX_k,\Gamma_*\right)=0, \ \text{$\hat{\mathbb{E}}$-q.s.,}
     \end{equation*}
     where $dist(x,\Gamma_*):=\inf_{y\in \Gamma_*}|x-y|$. In particular, this implies that all limit points of the sequence $\{\frac{1}{n}\sum_{k=1}^nX_k\}_{n=1}^\infty$ are contained within the set  $\Gamma_*$, $\hat\mathbb{E}$-q.s. For the case when 
 $d=1$,
     \begin{equation*}
       -\hat{\mathbb E}[-X_1] \le \inf_{x\in \Gamma_*}x\leq \liminf_{n\to\infty}\frac{1}{n}\sum_{k=1}^nX_k\leq \limsup_{n\to\infty}\frac{1}{n}\sum_{k=1}^nX_k\leq \sup_{x\in \Gamma_*}x\leq\hat{\mathbb E}[X_1], \ \text{$\hat\mathbb{E}$-q.s.} 
     \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:55.638516+00:00","domain":"probability theory","id":"claim_c2f7ea93df2dcb7bd2d96df51d9acaf452012ca2a9f415909948a34352f36885","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] Suppose that \eqref{Assump2:A_n_to_infinite} and \eqref{Assump2:last_term} hold. Then, for $\mu$-a.e.~$x$,
