            \, \frac{c_1 s}{2}, &\textup{if $d \ge 3$ or $(d = 2$ and $\alpha > 2)$,} \\[0.2em]
            \, \frac{c_1 s}{2 \log \log s}, &\textup{if $d = 2$ and $\alpha = 2$,} \\[0.2em]
            \, \frac{c_1 s}{2 \log s}, &\textup{if $d = 2$ and $\alpha < 2$,}
        \end{cases} \quad
        s = \begin{cases}
        \, r^2, &\textup{if } \alpha > 2, \\[0.2em]
        \, \frac{r^2}{\log r}, &\textup{if } \alpha = 2, \\[0.2em]
        \, r^\alpha, &\textup{if } \alpha < 2,
    \end{cases} 
    \end{align}
    and $c_1$ is the same constant in Lemma~(lemma: range_estimates_main_text of the paper). Let $\mathrm{Fant}$ denote the set of all $\mathrm{fantastic}$ vertices.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:54:57.474951+00:00","domain":"probability theory","id":"claim_c38ed6726dadd93e9b9823bcde545059c36753938f78e54f46d8fb37ce9eef86","kind":"lemma","schema_version":1,"statement":"[Lemma lem  : Topology/GMT/Gradient of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Let $D \in \RegPD[\mu]$, and $\gamma: \intervalleff0T \rightarrow X$ be a Lipschitz path.

