{"assumptions":[],"created_at":"2026-10-27T21:12:46.885888+00:00","domain":"probability theory","id":"claim_c3a30ee48c91a0c9210a89d8e6b7c090b201afd295c40563eea9a04ae2f064e7","kind":"concept","schema_version":1,"statement":"[Lemma GrC0proj of arXiv:2608.09856, '\bf Mass erasure on measured $\bbR$-trees,\\ applications to L\'evy forests'] Let $(E, d)$ be Polish. Here, $d_{\mathtt{Haus}}$ stands for the Hausdorff distance on $(E,d)$ and $d_{\mathtt{Pro}}$ for the Prokhorov distance on $\mathcal{M}_f(E)$. 
Let $T$ and $T^\prime$ be closed subsets of $E$. Let $\rho \! \in \!  T$ and $\rho^\prime \! \in \!  T^\prime$. 
We assume that $(T, d, \rho)$ and that $(T', d, \rho^\prime)$ are rooted $\mathbb{R}$-trees. Let $\tau$ (resp.~$\tau^\prime$) be a closed connected subset of $T$ (resp.~of $T^\prime$) which contains $\rho$ (resp.~$\rho^\prime$). Let $f_\tau$ (resp.~$f_{\tau^\prime}$) be the projection of $T$ onto $\tau$ (resp.~of $T^\prime$ onto $\tau^\prime$). 
\begin{compactenum}

\smallskip

\item[$(i)$] We assume that $d_{\mathtt{Haus}} (T, T^\prime) \! < \!   \varepsilon $ and $d_{\mathtt{Haus}} (\tau , \tau^\prime) \! < \!  \eta $. Then \vspace{-1mm}
\begin{equation}

\forall (\sigma , \sigma^\prime) \in T\! \times \! T^\prime , \qquad \big( \, d(\sigma, \sigma^\prime) \leq \varepsilon \;  \Longrightarrow \;  \, d( f_\tau (\sigma) , f_{\tau^\prime} (\sigma^\prime)) \leq 2\varepsilon + 3\eta \,\big). 
\end{equation}
\item[$(ii)$] Let $\mu \! \in \!  \mathcal{M}_f (T)$ and $\mu^\prime \! \in \!  \mathcal{M}_f (T^\prime)$, i.e.~$\mu, \mu'\! \in \!  \mathcal{M}_f(E)$ and $\mu(E\backslash T)\! = \!  \mu'(E\backslash T')\! = \!  0$. 
In the setting of $(i)$, we assume furthermore that $d_{\mathtt{Pro}} (\mu, \mu^\prime) \! < \!  \varepsilon$. Then, 
\begin{equation}

d_{\mathtt{Pro}} (\mathtt{P}_{\!\tau} \mu , \mathtt{P}_{\!\tau^\prime} \mu^\prime) \leq 2\varepsilon + 3 \eta \; .
\end{equation}
\end{compactenum} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:58:10.028236+00:00","domain":"probability theory","id":"claim_c3a6e0adf05db09e9cc790795b673044a4199eed5c3f1eb5410130284c59207f","kind":"lemma","schema_version":1,"statement":"[Lem decoration-moments of arXiv:2607.21428, 'Subcritical percolation and network archaeology on random recursive tree substrate network'] Conditional on \(\mathcal{F}_n\), the variables
		\((\widetilde X_u:u\in\mathcal{B}_n^{\operatorname{root}})\) are independent.  Moreover, they are
		conditionally independent of the internal root-blob genealogy.  On the event
		of Lemma~(lem:singly-attached-decorations of the paper), put
		\[
		X_u:=|D_u|,\qquad u\in\mathcal{B}_n^{\operatorname{root}},
		\]
		where \(D_u\) includes the skeleton vertex \(u\).  Off this event set
		\(X_u=1\) for definiteness; this convention only affects an \(o(1)\) event.
		Then
		\begin{equation}

			\mathbb P\left(
			X_u=\widetilde X_u\text{ for all }u\in\mathcal{B}_n^{\operatorname{root}}
			\right)\to1.
		\end{equation}
		Moreover, for every \(\zeta>0\), there exists a finite deterministic
		\(C_\zeta>1\) such that the \(\mathcal{F}_n\)-measurable event
		\[
		E_n^{\mathrm{mom}}(C_\zeta)
		:=
		\left\{
		1\leqslant \mathbb E[\widetilde X_u\mid\mathcal{F}_n]\leqslant C_\zeta
		\text{ and }
		\mathbb E[\widetilde X_u^2\mid\mathcal{F}_n]\leqslant C_\zeta
		\text{ for all }u\in\mathcal{B}_n^{\operatorname{root}}
		\right\}
		\]
		satisfies
		\begin{equation}

			\limsup_{n\to\infty}
			\mathbb P\left(E_n^{\mathrm{mom}}(C_\zeta)^c\right)
			\leqslant\zeta .
		\end{equation}
		In addition,
		\begin{equation}

			\max_{u\in\mathcal{B}_n^{\operatorname{root}}} X_u=o_{\mathbb P}(|\mathcal{B}_n^{\operatorname{root}}|).
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:49.200355+00:00","domain":"probability theory","id":"claim_c3a7899f5350c7e72a3e64305cc24f86a80544265fd03faa55e04b800f0fe817","kind":"lemma","schema_version":1,"statement":"[Lemma 33 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let us recall the processes $\wtilde{M}_m$ and $\wtilde{M}$ defined in \eqref{eqn-martingale} and \eqref{eqn-martingale-1}, respectively. Then, for fixed $\psi \in L^2(\bO)$ and $0\le s\leq t \le T$
