	c(p_c-p)^{-1/2}\leq \tilde{L}(p)\leq C(p_c-p)^{-1/2}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:27:32.352030+00:00","domain":"probability theory","id":"claim_c3f6a620154054c220cb0761090b17d2ede9a1bcca14001b9a379fc49029c45f","kind":"theorem","schema_version":1,"statement":"[Proposition prop_estimatecarreduchamp_kthderivative of arXiv:2509.18045, 'Density convergence on Markov diffusion chaos via Stein's method'] Assume  $q, N\in \mathbb{N}$. Let $\mathcal{Z}$  be  the  Pearson  distribution  associated with (equation sde_pearson of the paper) that has mean $m$, and satisfy   $\lim_{x\to u^{-}} p^{(k)}(x)=0, \forall k\leq N$ and admit densities that are differentiable up to the $N$-th order. Suppose that $X$ belongs to $\mathcal{A}$, and is an eigenfunction of the generator $L$ corresponding to the eigenvalue $-q$ and admits a density differentiable up to the $N$-th order. Set $F=X+m$ and recall the definitions of $S_n,Q_n$ at (equation def_SnandQ_n of the paper). Assume that  $S_1^{-1}\in L^{4N+4}(E,\mu)$ and that 
\begin{align*}
\E{\mathcal{U}_1(N,x,F)^2}+\E{\mathcal{U}_2(N,x,F)^2}+\sum_{3\leq i\leq 6}\E{\mathcal{U}_i(N,F)^2}<\infty\,,  
\end{align*}
where $U_i,1\leq i\leq 6$ are the functions defined in Lemmas (lemma_xinlandu of the paper), (lemma_steinmethod_xlessthanl of the paper) and (lemma_steinmethod_xmorethanu of the paper). \    
Then $F$ admits a density that is differentiable up to the $N$-th order. Moreover, for $k\leq N$, the following pointwise density estimate holds for $x\in\mathbb{R}$:   
    \begin{align*}
      &\abs{p_F^{(k)}(x)-p_\mathcal{Z}^{(k)}(x)}\\
      &\leq   \brac{\E{\mathcal{U}_2(k,x,F)^2}^{1/2}+\E{\mathcal{U}_4(k,F)^2}^{1/2}+\E{\mathcal{U}_6(k,F)^2}^{1/2} }\frac{1}{q^2} \mathbb{E}{\left[ Q_1 ^2\right]}^{1/2}
      \\
     &+\sum_{P_{k+1}}\E{\abs{\frac{c\brac{i_1,i_2,i_3,i_4,j_1,\ldots,j_{k+1},n_1,\ldots,n_{k+1}}{\prod_{r=1}^{k+1}S_{j_r}^{n_r} } F^{i_4}}{S_1^{i_2}b(F)^{i_3} }}^2 S_1}^{1/2} \\ &\hspace{10em}\brac{\prod_{m=2}^{i_1-1}\mathbb{E}{\left[ \left\vert LQ_m \right\rvert^2 S_1\right]}^{\frac{1}{2^{i_1+1-m}}}}\mathbb{E}{\left[ (LQ_1)^2\right]}^{\frac{1}{2^{i_1-4}}}\mathbb{E}{\left[ Q_1^2\right]}^{\frac{1}{2^{i_1-4}}}\,,  
    \end{align*}
where  $P_{k}$ is the set of multi-indices specified in Proposition (prop_densitydecompose of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:57:59.882767+00:00","domain":"probability theory","id":"claim_c3fac9b5fad123f68bf38d05d3a4d62e0617921451ba99efd3b9bdc1c04732bf","kind":"definition","schema_version":1,"statement":"[Definition def:three of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] {cgv2025StecconiTodino}}{}]
We define three deterministic positive real numbers associated to $M,g,\phi$: the \emph{average variance $\sigma$}, the \emph{average frequency $\lambda$} as follows.
\begin{equation} 
\sigma^2=\sigma(\phi)^2:=\fint_M 
\mathbb{E}\left\{ \phi(x)^2\right\} dx,\quad \lambda^2=\lambda(\phi)^2:=\frac{1}{\sigma^2}\fint_M \mathbb{E}\left\{ \|d_x\phi\|^2\right\} dx,
\end{equation} 
and the \emph{maximal eccentricity} of $\phi$:
\begin{equation}\begin{aligned} 
\varepsilon=\varepsilon(\phi):=\max_{x\in M,\ u\in S(T_xM)}\left|\frac{\sqrt{\mathbb{E}\left\{ |\langle d_x\phi,u\rangle|^2\right\}}}{\sigma\lambda}\sqrt{n}-1\right| 
\\
+\max_{x\in M}\left|\frac{\sqrt{\mathbb{E}\left\{ \phi(x)^2\right\}}}{\sigma}-1\right|
+
\max_{x\in M,\ u\in S(T_xM)}\left|\langle d_x\frac{\sqrt{\mathbb{E}\left\{ \phi(\cdot)^2\right\}}}{\sigma}, u\rangle \right|\frac{\sqrt{n}}{\lambda}.
\end{aligned}\end{equation}
When $\varepsilon(\phi)=0$, we say that $\phi$ is a \emph{homothetic field}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.196345+00:00","domain":"probability theory","id":"claim_c3fc46fa63c54d371bdd7fda01323e79258b4cd65c3722d59b7fd75d79564ea1","kind":"concept","schema_version":1,"statement":"[Lem 28 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For any $y\in \al, z\in \ar$ and $x\in A_{y,z}$, there exists $\mathcal S'$ with $\mathbb P(\mathcal S')\geq 1-\exp(-N^{\delta})$ such that the following holds.
