{"assumptions":[],"created_at":"2026-10-26T19:36:44.529478+00:00","domain":"probability theory","id":"claim_c41e04ae2054d1581601ce73838a01a8f94fa1106621f997d72ce6c58284ea67","kind":"concept","schema_version":1,"statement":"[Lemma 16 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\delta >0$. In the same setting as Lemma \ref{lemma support sbm interval}, we have that
        \begin{equation*}
        \overline{\bigcup_{0 \leq s \leq \delta} \text{supp}(\mathcal{Y}_s)} = \text{supp}(\mu_{\rm d}) \cup \overline{\bigcup_{i \in I} \{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\}} \hspace{0.5cm} \mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}\text{-a.s.}
    \end{equation*}
    \begin{proof}
        For $i \in I$ recall the measures $\mathcal{Z}_{s, i}$ from \eqref{equation components of total measure oosbm}. We first note that
        \begin{equation*}
            \overline{\bigcup_{0 \leq s \leq \delta} \text{supp}(\mathcal{Y}_s)} = \overline{\bigcup_{s \in (0,\delta) \cap \mathbb{Q}} \text{supp}(\mathcal{Z}_s)} = \text{supp}(\mu_d) \cup \overline{\bigcup_{i \in I} \bigcup_{s \in (0,\delta) \cap \mathbb{Q}} \text{supp}(\mathcal{Z}_{s, i})}.
        \end{equation*}
        To prove the result we now show for each $i \in I$ that
        \begin{equation*}
            \overline{\bigcup_{s \in (0,\delta) \cap \mathbb{Q}} \text{supp}(\mathcal{Z}_{s, i})} = \overline{\{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\}}.
        \end{equation*}
        The first inclusion follows from the proof of Lemma \ref{lemma supports sbm and oosbm} which states that 
        \begin{equation*}
            \text{supp} (\mathcal{Z}_{s,i}) = \overline{\{\hat{w}^i_{T^{1/m}_{s,n,i}}: m \in \mathbb{N}, 1 \leq n \leq M_i^{1/m}\}}
        \end{equation*}
        and we note that for all $s<\delta$, $s \in \mathbb{Q}$, $m \in \mathbb{N}, 1 \leq n \leq M_i^{1/m}$, we have that $H^i_{T^{1/m}_{s, n, i}}(\delta)=f^i_{T^{1/m}_{s, n, i}}$, since $T_{s,n,i}^{1/m}$ is a downcrossing time. From this, it follows that
        \begin{equation*}
            \bigcup_{s \in (0,\delta) \cap \mathbb{Q}} \text{supp}(\mathcal{Z}_{s, i}) \subseteq \overline{\{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\}}.
        \end{equation*}
        It remains to show the reverse inclusion. We consider
        \begin{equation*}
            \sum_{i \in I} \delta_{((b_i,s_i), f^i, x^{i, \delta})}
        \end{equation*}
        where $I$, $(b_i, s_i)$, $f^i$ are the same as for the original Brownian snake defined in \eqref{equation snake poisson random measure} and where $x^{i, \delta}$, $i \in I$, are defined as follows. For $i \in I$, we let $x^{i, \delta} = (w^{i, \delta}, v^i)$ where $v^i$ is the usual subordinator component for $x^i=(w^i, v^i)$, and where for $r \in [0,\sigma(f^i)]$, $u \in [0,f^i_r]$, we define $w^{i, \delta}_r(u) = w^i_r(u \wedge H^i_r(\delta))$. It follows that $x^{i, \delta}$ is a bivariate Brownian snake where the second component is a subordinator and the first component is Brownian path stopped at a time determined by the subordinator. We claim that
        \begin{equation*}
            \{\hat{w}^i_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\} = \{\hat{w}^{i, \delta}_r: r \in [0,\sigma(f^i)], f^i_r = H^i_r(\delta)\}.
        \end{equation*}
        This is because for $r \in [0,\sigma(f^i)]$ with $f^i_r = H^i_r(\delta)$ we have that 
        \begin{equation*}
            \hat{w}^i_r = w^i_r(f^i_r) = w^i_r(f^i_r \wedge H^i_r(\delta)) = \hat{w}^{i, \delta}_r. 
        \end{equation*}
        We can also define a measure $\mathcal{Z}^{\delta}_{s, i}$ by
        \begin{equation*}
            \langle \mathcal{Z}^{\delta}_{s, i}, \Phi \rangle = \int_{r=0}^{\sigma(f^i)} \Phi(\hat{w}^{i, \delta}_r) d\ell_{s, i}(r)
        \end{equation*}
        for any Borel-measurable function $\Phi$. Like our original snake, $x^i$, our new snake, $x^{i, \delta}$, has head of the snake process $(\hat{w}^{i, \delta}_r)_{0 \leq r \leq \sigma(f^i)}$ which is continuous. We can apply the results of Lemmas \ref{lemma supports sbm and oosbm} and \ref{lemma support sbm interval} to $(\mathcal{Z}^{\delta}_{s, i}, s \geq 0)$. Specifically, we can let $(\mathcal{Y}^{\delta}_{s, i})_{s \geq 0}$ be a continuous modification of $(\mathca (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:02:34.839653+00:00","domain":"probability theory","id":"claim_c41f04fa79e8d0128d87fc07717d0b5ecb2cbad65bb73b7bdbf43ac2db883bca","kind":"theorem","schema_version":1,"statement":"[Proposition 11 (Angular representation of negative shape-factor moments) of arXiv:2607.20680, 'Exact Scale--Shape Factorization of the Typical Poisson--Voronoi Cell Volume in Arbitrary '] Fix \(k\geq d+1\) with \(p_{d,k}>0\).  Then
  \begin{equation}

    \E[A_k^{-k}]
    =
    \frac{1}{dkp_{d,k}}
    \int_{\Theta_{d,k}}
      G(\theta)^{-k}\,
      \dd\Haus^{dk-1}(\theta),
  \end{equation}
with equality in \([0,\infty]\).

Define
  \begin{equation}

    M_{d,k}(\varepsilon)
    =
    \Haus^{dk-1}
    \bigl(
      \{\theta\in\Theta_{d,k}:G(\theta)\leq\varepsilon\}
    \bigr),
    \qquad \varepsilon>0.
  \end{equation}
If there exist \(C<\infty\), \(\delta>0\), and \(\varepsilon_0>0\) such that
  \begin{equation}

    M_{d,k}(\varepsilon)
    \leq C\varepsilon^{k+\delta},
    \qquad 0<\varepsilon\leq\varepsilon_0,
  \end{equation}
then
  \begin{equation}

    \E[A_k^{-k}]<\infty.
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:11.633175+00:00","domain":"probability theory","id":"claim_c41f5aeaef4aea2e52dc11dd7141875f0b894570aeeb8af66980da7f527df441","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2605.31088, 'On couplings for kinetic Langevin diffusions'] Assume that $\gamma^2>4\alpha\geq 0$. 
Then there exist $z, \tilde{z}\in \R^{2d}$ and a constant $C>0$ such that for all $h>0$, $k\in \N$ one has
\begin{equation}
    \dTV{\law(Z_k^h),\law(\tilde Z_k^h)} \leq C e^{\lambda_{-} hk} | \tilde{z} - z |.
\end{equation}
Conversely, for every $z\neq \tilde{z}\in \R^{2d}$, every $h>0$ and every Markovian coupling $\mu_h$ of $(Z_k^h,\tilde{Z}_k^h)_{k\in \N}$ there exist constants $k_{\mu_h}\in\N$, $c_{\mu_h} >0$ and $c>0$ (with $c$ independent of $\mu_h$) such that for all $k\geq k_{\mu_h}$ one has
\begin{equation}
    \mu_h(Z_k^h\neq \tilde{Z}_k^h) \geq c\min\big( c_{\mu_h}(hk+1)^{-\nicefrac{1}{2}}, c_{\mu_h} e^{\lambda_{+} hk},  h^{-1} e^{\lambda_{-} hk} \big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.248504+00:00","domain":"probability theory","id":"claim_c41fd38a90e6b6c740a283908d4539420f2dbc2cee016796aa1c6aad40c6c0d8","kind":"concept","schema_version":1,"statement":"[Proposition 16 (Interpolation) of arXiv:2605.22146, 'Poisson approximation of the largest gaps between zeros of a stationary Gaussian process'] The map $t \mapsto \P[A_t]$ is absolutely continuous on $[0,1]$ with a.e.\ derivative
 \begin{align}

   \frac{d}{dt} \P[A_t] =  \sum_{\ell < \ell'} \sum_{I_i \in \mathcal{C}_\ell, I_j \in \mathcal{C}_{\ell'}}  \sigma_i \sigma_j  \int \int K(x,y)  p_t(x,y) \, \mu_{I_i}(dx) \mu_{I_j}(dy)   
\end{align}
where, if $x \in \textrm{int}(I_i)$ and $y \in \textrm{int}(I_j)$,
\begin{equation}

 p_t(x,y) :=  \E \big[   |f_t''(x)| |f_t''(y)|   \id_{A_t^{xy}} \big| f_t(x) = f_t(y) = f_t'(x) = f_t'(y) = 0 \big] \tilde{\varphi}_t(x,y) ,
 \end{equation}
 and $\tilde{\varphi}_t(x,y)$ denotes the density at zero of the Gaussian vector $(f_t(x), f_t(y), f_t'(x), f_t'(y))$, whereas if $x \in \partial I_i$ (resp.\ $y \in \partial I_j$) the terms $f''_t(x)$ and $f'_t(x)$ (resp.\ $f''_t(y)$ and $f'_t(y)$) are removed from the integrand, conditioning, and Gaussian density in \eqref{e:p}. 

In particular, \eqref{e:inter} implies that
\begin{align}

& \P \big[ \cap_i \calP^{\sigma_i}_{I_i} \big] -  \prod_{\ell \ge 1} \P \big[ \cap_{I_i \in \mathcal{C}_\ell} \calP_{I_i}^{\sigma_i}  \big]  \\
& \nonumber \qquad \qquad =  \int_0^1  \sum_{\ell < \ell'} \sum_{I_i \in \mathcal{C}_\ell, I_j \in \mathcal{C}_{\ell'}} \sigma_i \sigma_j  \int \int K(x,y)  p_t(x,y) \, \mu_{I_i}(dx) \mu_{I_j}(dy)  \, dt      .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:43:45.389071+00:00","domain":"probability theory","id":"claim_c420270a74e7e46d83274091881388e2779ab7192287977dc177c60bafe5a187","kind":"concept","schema_version":1,"statement":"[Proposition 16 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] For each $r > 0$, write
\begin{equation*}
	V_r \defeq \left\{z \in \BC : 0 < \Re(z) < r, \ 0 < \Im(z) < 1\right\};
\end{equation*}
write $T_r$ (resp.\ $B_r$) for the closed top (resp.\ bottom) side of $V_r$; let $\Gamma_{V_r}$ be a non-nested CLE$_4$ in $V_r$. (By convention, the quadrilateral $(V_r; T_r, B_r)$ has conformal modulus $1/r$.) Then there is a deterministic constant $c \in (0, 1)$ such that 
\begin{equation*}
	\BP\!\left\lbrack D_{\Gamma_{V_r}}^{V_r}(T_r, B_r) \le 1/r\right\rbrack \ge c
\end{equation*}
for all sufficiently large $r > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

