{"assumptions":[],"created_at":"2026-10-26T21:02:38.611189+00:00","domain":"probability theory","id":"claim_c433733e6fcda42abd63ad31beed5ed23da5f49c9b620a64d77715c5a30d32f3","kind":"concept","schema_version":1,"statement":"[Corollary 23 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] Let $\bar w_k, 0\le k\le n-1$ be the solution to the recursion
    \begin{equation}
    \bar w_{k+1}=\frac{X_k^2+Y_k^2-\mu_n}{Y_k^2} \,  \gamma_k  \bar w_k-\frac{X_k^2}{Y_k^2}  \gamma_k \gamma_{k-1} \bar w_{k-1},\qquad \bar w_0=\bar w_1=m_n.
    \end{equation}
    Let $\psi_*$ be the solution to the SDE \eqref{AirySDE_1} with Neumann initial condition $\psi_*(0)=1,\psi_*'(0)=0$. Then we have
        \begin{align}
        (m_n^{-1}\bar w_{\lfloor xm_n\rfloor}, \bar w_{\lfloor xm_n\rfloor +1}-\bar w_{\lfloor xm_n\rfloor}) \Rightarrow (\psi_*(x),\psi_*'(x)),
    \end{align}
    in law with respect to the Skorokhod topology on compact subsets of $\R_+$. Moreover, the convergence results \eqref{eq:ubar_conv} and \eqref{eq:wbar_conv} hold jointly. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:06:55.290841+00:00","domain":"probability theory","id":"claim_c433abafce4f80b3643fd5fa9c234611a0605bde08a7bec62ce5c54d034e256f","kind":"concept","schema_version":1,"statement":"[Theorem thm:error-estimate-ms of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $Q, G$ be as defined in (equation eq:CG-res-gen of the paper). Then, there exist constants $\varepsilon_0, c_0, C_0, C_1,C_2, \beta > 0$ such that the following result holds. For $\varepsilon \in (0,\varepsilon_0)$ let $t \mapsto \mu^\varepsilon_t \in \mathcal{P}(\mathcal{X})$ and $t \mapsto \eta^\varepsilon_t\in \mathcal{P}(\mathcal{Y})$ be the solutions to
    \begin{equation*}
        \begin{dcases}
            \dfrac{\,\mathrm{d}}{\,\mathrm{d} t} \mu^\varepsilon_t = (L^\varepsilon)^T \mu_t^\varepsilon, \\
            \mu_{t = 0}^\varepsilon = \mu_0^\varepsilon,
        \end{dcases} \qquad \begin{dcases}
            \dfrac{\,\mathrm{d}}{\,\mathrm{d} t} \eta^\varepsilon_t = (N^\varepsilon)^T \eta_t^\varepsilon, \\
            \eta^\varepsilon_{t = 0} = \eta_0^\varepsilon,
        \end{dcases}
    \end{equation*}
    where we assume the following on the initial conditions $\mu_0^\varepsilon, \eta_0^\varepsilon$: 
    \begin{itemize}
        \item (strictly positive initial data) $\hat{\mu}_0^\varepsilon(x) \geq c_0$ and $\eta_0^\varepsilon(y) \geq c_0$ for all $\varepsilon \in (0, \varepsilon_0)$ and for all $x \in \mathcal{X}$ and all $y \in \mathcal{Y}$ respectively,
        \item (convergence) $\mu^\varepsilon_0$, $\hat{\mu}_0^\varepsilon = \xi_\#\mu^\varepsilon_0$ (see (equation eq:CGDyn-def of the paper)) and $\eta_0^\varepsilon$ converge in $\mathcal{P}(\mathcal{Y})$ as $\varepsilon \rightarrow 0$, 
        and
        \item (relative entropy estimate) for all $\varepsilon \in (0,\varepsilon_0)$
        \begin{equation*} 
        \mathscr{H}_{\eta_0^\varepsilon}\left(\frac{\hat{\mu}_0^\varepsilon}{\eta_0^\varepsilon}\right) \leq C_0 \varepsilon.
    \end{equation*}
    \end{itemize}
    Then, the estimate
    \begin{equation}
        \mathscr{H}_{\eta_t^\varepsilon} \left(\frac{\hat{\mu}_t^\varepsilon}{\eta_t^\varepsilon}\right) \leq \varepsilon C_1 e^{-\beta t}
    \end{equation}
    holds for all $t \geq 0$ and all $\varepsilon \in (0,\varepsilon_0)$. 
    In particular, the time-uniform estimate
    \begin{equation}
        \sup_{t \geq 0} \mathscr{H}_{\eta_t^\varepsilon} \left(\frac{\hat{\mu}_t^\varepsilon}{\eta_t^\varepsilon}\right) \leq C_2 \varepsilon
    \end{equation}
    holds for all $\varepsilon \in (0,\varepsilon_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:25.282107+00:00","domain":"probability theory","id":"claim_c4360bf967a01dbc40e444b1387bba5b8b82a742c6ab86099eef49df40dfb2c6","kind":"definition","schema_version":1,"statement":"[Defn 4 of arXiv:2606.21778, 'Pontryagin Maximum Principle in Free Probability Theory'] A free Brownian motion $(W_t)_{t\geq 0}$ is a family elements of $\mathcal{A}$ adapted to the filtration $\mathbb{F}=(\mathcal{A}_t)_{t\geq 0}$, which admits the following properties:
	\begin{enumerate}
		\item $W_t$ is a self-adjoint element of $\mathcal{A}$ with semi-circular distribution of mean zero and variance $t$, 		
		\item For all $s,t$ with $s\leq t$, the element $W_t-W_s$ is free of $\mathcal{A}_s$ and has a semi-circular distribution with mean $0$ and variance $t-s$.
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:25.272176+00:00","domain":"probability theory","id":"claim_c438c1178690a170b46c18c0f2c95cf6d5124b0c3ea2a033d8963ee87143fabb","kind":"concept","schema_version":1,"statement":"[Proposition 7 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] For $n\ge a$, let
\begin{equation*}
s_n=\Big(\frac{a(2p-1)}{2a(1-p)-1}\Big)^2\sum_{k=a}^{n}(b_kc_k^{-1})^2.
\end{equation*}
Then,\vspace{.1cm}\\
\noindent{(i)} for $0\le p< (4a-1)/4a$, we have
\begin{equation*}
\lim_{n\to\infty}\frac{s_n}{n^{4a(1-p)-1}}=\frac{(\Gamma(a(2p-1)+1))^2}{4a(1-p)-1},
\end{equation*} 
\noindent{(ii)} for $p=(4a-1)/4a$, we have
\begin{equation*}
\lim_{n\to\infty}\frac{s_n}{\log n}=\Big(\Gamma\Big(a+\frac{1}{2}\Big)\Big)^2,\ \ \text{and}
\end{equation*}
\noindent{(iii)} for $(4a-1)/4a<p\le 1$, we have $\lim_{n\to\infty}s_n=l$,
where $l$ is some non zero constant. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:43:44.268422+00:00","domain":"probability theory","id":"claim_c439a085904362069eca7ed766075813b15746574e8f62f9a60a33179566aef0","kind":"concept","schema_version":1,"statement":"[Proposition 1 (Proposition 1.1 and Theorem 1.2 in \cite{AizenmanJung2007}, and Theorem 1 in \cite{Swart2018}) of arXiv:2604.15753, 'The truncation property and continuity for \\ the long-range contact process on $\mathbb{Z'] Consider the LRCP  on $\bZ^d$, $d\geq 1$, with $\lambda \in \Lambda$ and $\delta>0$. 
\begin{enumerate}
    \item[i)] The process is subcritical if and only if $\chi(\lambda,\delta)<\infty$ and there exists some $\tau<0$ such that
    \begin{equation}
     \inf_{t >0 } \frac{1}{t} \log  \bE_{\lambda,\delta} \left[  \left| \left\{ x\in \bZ^d \colon \eta_t^o(x)=1\right\} \right| \right] = \tau.
    \end{equation}
     Moreover, if the process is subcritical, then $\bar{\nu}_{\lambda,\delta} = \delta_{\underline{0}}$.
    \item[ii)] If the process is critical, then $\chi(\lambda,\delta)=\infty$.
\item[iii)]   If the process is supercritical, then  $\chi(\lambda,\delta)=\infty$ and $\bar{\nu}_{\lambda,\delta} \neq \delta_{\underline{0}}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:12:13.460252+00:00","domain":"probability theory","id":"claim_c43ab1ad899e60cace1dbafc667aea57b8f360eb2a6f544e42fdf7afc8616e22","kind":"lemma","schema_version":1,"statement":"[Lemma 4 of arXiv:2608.28307, 'Rigidity of closed $\lambda$-self-expanders'] Let $x:M^n\to \mathbb{R}^{n+1}$ be a $\lambda$-self-expander, then we have
\begin{equation}
\begin{split}
