{"assumptions":[],"created_at":"2026-10-27T12:48:49.913053+00:00","domain":"probability theory","id":"claim_c4d90ffa607626ff15c6aa5e3e626c97f560b7483d7f0c751f40c8b171cb1816","kind":"definition","schema_version":1,"statement":"[Definition defi:sol of arXiv:2511.12692, 'A stochastic flow approach to De Giorgi--Nash--Moser estimates for SPDE\lowercase{s} with '] Let Assumptions (ass:quasilinear of the paper) and (ass:quasilinear_data of the paper) be satisfied,
 $\sigma$ be a stopping time and 
$
U:(0,\sigma)\times \Omega\to W^{1,q}(\mathbb{T}^d)
$
be progressively measurable. 
\begin{enumerate}[{\rm(1)}]
\item We say that $(U,\sigma)$ is a \emph{local $(p,\kappa,q)$-solution} to (equation eq:SPDE_quasi of the paper) if there exists a sequence of stopping times $(\sigma_j)_{j\geq 1}$ for which $\sigma_j \to\sigma$ a.s. and for all $j\ge 1$
\begin{align}

U\in L^p(0,\sigma_j,w_{\kappa};W^{1,q}(\mathbb{T}^d))\cap C([0,\sigma_j];B^{1-2\frac{1+\kappa}{p}}_{q,p}(\mathbb{T}^d)), \qquad \text{a.s.,}
\end{align}
and
\begin{align}

U(t) - U_0 =\int_0^t \nabla \cdot (A(\cdot,U)\cdot \nabla U)\,\mathrm{d} s 
+\sum_{n\geq 1} \int_0^t (B_n \cdot\nabla) U\,\mathrm{d} w^n_s,\qquad t\in [0,\sigma_j].
\end{align}
\item We call a local $(p,\kappa,q)$-solution $(U,\sigma)$ to (equation eq:SPDE_quasi of the paper) \emph{unique} if for any other local $(p,\kappa,q)$-solution $(V,\tau)$ to (equation eq:SPDE_quasi of the paper) it holds a.s.\ $U=V$ on $[0,\sigma\wedge \tau )$.
\item We call a local $(p,\kappa,q)$-solution $(U,\sigma)$ to (equation eq:SPDE_quasi of the paper) \emph{maximal} if for any other local $(p,\kappa,q)$-solution $(V,\tau)$ to (equation eq:SPDE_quasi of the paper) it holds $\tau\leq \sigma$ a.s.\ and $U=V$ on $[0,\sigma\wedge \tau )$.
\item We call a local $(p,\kappa,q)$-solution $(U,\sigma)$ to (equation eq:SPDE_quasi of the paper) \emph{global} if  a.s.\ $\sigma=\infty$. In this case, we simply write $U$ instead of $(U,\sigma)$.
\end{enumerate}","status":"unverified"}

