\]
and assume $\sigma_r<1$. For any
$1<R<\sigma_r^{-1}$, set
$q_R:=1-\alpha+\alpha\sigma_rR<1$.
Almost surely, there are finite random constants $C_R$ and $N_R$ such
that, for all $n\geq N_R$ and $m\geq0$,
\begin{equation}
\lVert A_n^m\rVert
\leq
C_Rq_R^m.

\end{equation}
Consequently, for bounded input histories,
\begin{equation}
x_t^{(\infty)}
:=
\alpha\sum_{k=0}^{\infty}
A_n^kW_{\rm in}^{(n)}u_{t-1-k}

\end{equation}
is well defined for all sufficiently large $n$, and
\begin{equation}
\limsup_{n\to\infty}
\frac1{\sqrt n}
\left\|
x_t^{(\infty)}-x_t^{(L)}
\right\|
\leq
\frac{\alpha C_R\sigma_{\rm in}U}
{\sqrt{d_{\rm in}}(1-q_R)}
q_R^{L+1}

\end{equation}
almost surely.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.662853+00:00","domain":"probability theory","id":"claim_c4f4f3c175cbac90d3c2d3eb46d12802ccb4cfb85212cb6520894561214db8b9","kind":"concept","schema_version":1,"statement":"[Theorem 4 (\cite{S11}) of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] For any $\alpha\geq 1$ and $\delta>0$, $L_G^{\alpha+\delta}(\Omega_T)\subset L_{\mathcal{E}}^{\alpha}(\Omega_T)$. More precisely, for any $1<\gamma<\beta:=(\alpha+\delta)/\alpha$ and $\gamma\leq 2$, we have
	\begin{displaymath}
