{"assumptions":[],"created_at":"2026-10-26T20:46:26.258417+00:00","domain":"probability theory","id":"claim_c5453994c17989ed660d81da948763b33ab45a7507ccf55a92c55e2d240d5926","kind":"definition","schema_version":1,"statement":"[Dfn 79 ({\cite[Definitions 2.5.6 and 8.1.1) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {HDP18}}]\quad\par
  \begin{itemize}
    \item [$\rm{(i)}$]For a real-valued random variable $X$, we define its sub-Gaussian norm 
  $\|X\|_{\psi_2}$ by setting
  \begin{align*}
    \|X\|_{\psi_2}:=\inf\{t>0:E[\exp(X^2/t^2)]\le 2\}.
  \end{align*}
   \item [$\rm{(ii)}$]Let $(X_t)_{t\in T}$ be a real-valued stochastic process on a metric space $(T,d)$.
   We say the process has a sub-Gaussian increments if there exists a constant $K\in (0,\infty)$
   such that
   \begin{align}
    \|X_t-X_s\|_{\psi_2}\le Kd(s,t),\qquad s,\;t\in T.
   \end{align}
  \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:15.353529+00:00","domain":"probability theory","id":"claim_c545c27a5ff2dfa4cab3b0b48435866fe2add284c70a3e3addecfe7737402bbb","kind":"theorem","schema_version":1,"statement":"[Theorem 5 of arXiv:2506.16260, 'Fractional Compound Poisson Random Fields on Plane'] For $\alpha_1=1$, the distribution function (\ref{fcprfdf}) reduces to
		\begin{equation*}
			\mathrm{Pr}\{\mathscr{Y}_{1,\alpha_2}(t_1,t_2)\leq y\}=E_{\alpha_2,1}(-\lambda t_1t_2^{\alpha_2})\textbf{1}_{[0,\infty)}(y)+\int_{-\infty}^{y}f_{\mathscr{Y}_{1,\alpha_2}}(x,t_1,t_2)\,\mathrm{d}x,\ y\in\mathbb{R},\ (t_1,t_2)\in\mathbb{R}^2_+.
		\end{equation*}
		Here,
		\begin{equation}
			f_{\mathscr{Y}_{1,\alpha_2}}(x,t_1,t_2)=\frac{e^{-\sigma y}}{y}\sum_{n=1}^{\infty}\frac{(\lambda\sigma t_1t_2^{\alpha_2}y)^n}{(n-1)!}E_{\alpha_2,n\alpha_2+1}^{n+1}(-\lambda t_1t_2^{\alpha_2})\textbf{1}_{[0,\infty)}(y),
		\end{equation}
		where $E_{\alpha,\beta}^\gamma(\cdot)$, $\alpha>0$, $\beta\in\mathbb{R}$, $\gamma\in\mathbb{R}$ is the three parameter Mittag-Leffler function defined in (\ref{tpml}).

		The function $f_{\mathscr{Y}_{1,\alpha_2}}(x,t_1,t_2)$ solves the following partial differential equation:
		\begin{equation}
			\sigma\frac{\partial^{\alpha_2}}{\partial t_2^{\alpha_2}}f_{\mathscr{Y}_{1,\alpha_2}}(x,t_1,t_2)=-\bigg(\lambda t_1+\frac{\partial^{\alpha_2}}{\partial t_2^{\alpha_2}}\bigg)\frac{\partial}{\partial y}f_{\mathscr{Y}_{1,\alpha_2}}(x,t_1,t_2),\ t_1\ge0
		\end{equation}
		with $f_{\mathscr{Y}_{1,\alpha_2}}(x,t_1,0)=0$, where $\frac{\partial^{\alpha}}{\partial t_2^{\alpha}}$ is the Caputo fractional derivative defined in (\ref{caputoder}).
		 Also,
		\begin{equation*}
			\int_{0}^{\infty}f_{\mathscr{Y}_{1,\alpha_2}}(x,t_1,t_2)\,\mathrm{d}y=1-E_{\alpha_2,1}(-\lambda t_1t_2^{\alpha_2}).
		\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:45:17.711807+00:00","domain":"probability theory","id":"claim_c54e959dee979153641d1a7aabb85386f52456107762cca6d270edf7fc1908ac","kind":"theorem","schema_version":1,"statement":"[Proposition prop:first_singular_value of arXiv:2604.11761, 'The smallest singular value of signed random combinatorial matrices'] Let $n \in \mathbb{N}$ be even and let \(M\) be an \(m\times n\) random matrix, $1\le m \le n$, whose rows are independent and uniformly distributed over the set of \(\{-1,0,1\}\)-vectors with exactly \(n/2\) zero coordinates. Then for all $t \geq C_3$, we have
