        \end{equation}
    \end{enumerate}
    Additionally, for $f\in \mathscr{C}^{0,\varrho}_{\mathrm{pw}}S_d$, we will denote 
    \begin{equation}
        \mathscr{U}_f:=\bigcup_{j=1}^s \partial U_j

    \end{equation}
    the set of potential singularities of $f(\cdot,\xi)$ in $[0,1]^d$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.744058+00:00","domain":"probability theory","id":"claim_c62a04b76bb3afecd2e65112f87a09e499804ec632a96e8db63ba80d36fa2bc6","kind":"definition","schema_version":1,"statement":"[Defn of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] We define the following subsets of $\mathsf{H}(\mathbb{C})$,
