{"assumptions":[],"created_at":"2026-10-27T19:58:40.874999+00:00","domain":"probability theory","id":"claim_c71023e91c93109720e2d9381f2e113e875d3d8080dcf62e99cc08ef3fcfb6bb","kind":"concept","schema_version":1,"statement":"[Theorem thm:OGP of arXiv:2605.10911, 'The stochastic block model has the overlap graph property for modularity'] [\bf Modularity has OGP] 
Fix real numbers $a>b>0$, and integer $k\geq 3$.
For any $\nu\in \left(\frac{1}{2(k-1)}, \frac{1}{k}\right)$ and {$\varepsilon>0$}, there exist $\mu = \mu(\nu)$ and $c=c(\varepsilon)$ such that the following holds for $n$ large enough.

Let $p=p(n)=\omega\; a / n$ and $q=q(n)=\omega \; b/n$ be such that $\omega>c$, and let $G \in \mathcal{G}(n,k,p,q)$ with planted partition $\mathcal{P}$. Then with probability at least $1-\varepsilon$, for every $k$-part partition $\mathcal{A}$ with 
\begin{equation}

q_\mathcal{A}(G) \ge \frac {a-b}{a+(k-1)b} \left( 1 - \frac {1}{k} - \frac {2}{k^2} \right) - \mu,
\end{equation} 
either $d(\mathcal{A}, \mathcal{P}) \le \frac {{1}}{2(k-1)}$ or $d(\mathcal{A}, \mathcal{P}) \ge \nu$.
Moreover, there are partitions $\mathcal{A}$ satisfying the latter. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:19:46.240076+00:00","domain":"probability theory","id":"claim_c712abb0e336ad06612f94349bfcfc1216044e5b1212ef05889124e13f4cd8b3","kind":"concept","schema_version":1,"statement":"[Thm 6 (cf. \cite{St99a}) of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $u$ be a reference density (i.e. satisfying \eqref{eq:exists_u}-\eqref{eq:LFP}) such that condition $\mathbf{H_{a,b}^{\sqrt{u}}}$ is fulfilled.
    Then the following assertions hold for each $N>0$:
    \begin{enumerate}
        \item[(i)] There exists a maximal extension $\left(\overline{\sf L}_1^N,{\sf{D}(\overline{\sf{L}}_1^N)}\right)$ of $\left(\overline{\sf L},C_c^{\infty}((0,N)\times \mathbb{R}^d)\right)$ on $L^1\left([0,N)\times \mathbb{R}^d;\overline{\mu}_N\right)$ satisfying the following properties:
        \begin{enumerate}
            \item[(i.1)] It generates a $C_0$-semigroup $\left(\overline{T}_t^N\right)_{t\geq 0}$ on $L^1\left([0,N)\times \mathbb{R}^d;\overline{\mu}_N\right)$, which can be extended (keeping the same notation) as a $C_0$-semigroup of contractions on every $L^p\left([0,N)\times \mathbb{R}^d;\overline{\mu}_N\right)$, $p\in[1,\infty)$, whose corresponding generator is further denoted by $\left(\overline{\sf L}_p^N,{\sf{D}(\overline{\sf{L}}_p^N)}\right)$. 
            \item[(i.2)] $\left(\overline{T}_t^N\right)_{t\geq 0}$ is of evolution type, namely for every $t\geq 0$
            \begin{equation}
                \overline{T}_t^Nf(s,x)=1_{[0,N-t)}(s)\overline{T}_t^N \left(f(s+t,\cdot)\right)(s,x), 
            \end{equation}
            a.e. $(s,x)\in [0,N)\times \mathbb{R}^d$ and $f\in L^p\left([0,N)\times \mathbb{R}^d; \overline{\mu}_N\right)$, $1\leq p\leq \infty$.
        \end{enumerate}
        \item[(ii)] There exists a right (hence strong Markov) process (see \Cref{defi 4.4})
        \begin{equation*}
        X^N=\left(\Omega^N,\mathcal{F}^N,\left(\mathcal{F}^N(t)\right)_{t\geq 0},\left(X^N(t)\right)_{t\geq 0},\mathbb{P}_{s,x}^N, (s,x)\in [0,N)\times \mathbb{R}^d\right),
        \end{equation*} 
        with lifetime $\zeta^N$ and shift operators  $\left(\theta^N(t)\right)_{t}$, such that the following are satisfied: 
        \begin{enumerate}
            \item[(ii.1)] Its transition function $\left(\overline{P}_t^N\right)_{t\geq 0}$ and corresponding resolvent $\overline{\mathcal{U}}^N:=\left(\overline{U}_\alpha^N\right)_{\alpha>0}$ are such that for each $f\in b\mathcal{B}([0,N)\times \mathbb{R}^d)$, $\overline{U}_\alpha^Nf$ is a $\overline{\mu}_N$-version of $\left(\alpha-\overline{L}^N_1\right)^{-1}f$, $\alpha>0$. 
            \item[(ii.2)] For $(s,x)\in [0,N)\times \mathbb{R}^d \quad \overline{\mu}_N\mbox{-a.e.}$ we have
            \begin{equation}
                \overline{\mathbb{P}}^N_{s,x}\left( [0,\zeta^N)\ni t\mapsto X^N(t) \in [0,N)\times \mathbb{R}^d \mbox{ is continuous }  \right)=1.
            \end{equation}
            \item[(ii.3)] If we set $X^N(t)=(X^N_1(t),X^N_2(t)), t\geq 0$, then for $(s,x)\in [0,N)\times \mathbb{R}^d \quad \overline{\mu}_N\mbox{-a.e.}$ we have
            \begin{equation}
            \overline{\mathbb{P}}^N_{s,x}\left( X^N_1(t)\neq t+s; t<\zeta^N  \right)=0.
            \end{equation}
            \item[(ii.4)] For every $N>0$, and every $\overline{\nu}\in \mathcal{P}([0,N)\times \mathbb{R}^d)$ which satisfies $\overline{\nu}\leq c \overline{\mu}_N$ for some constant $c>0$, the process $X^N$ solves the $\mathbb{P}^N_{\overline{\nu}}$-martingale problem associated with  $\left(\overline{\sf L}, C_c^{\infty}((0,\infty)\times \mathbb{R}^d))\right)$ in the sense that
            \begin{equation}
                f(X^N(t\wedge \zeta^N))-f(X^N(0))-\int_0^{t\wedge \zeta^N} \overline{\sf L}f(X^N(s))\; ds, \quad t\geq 0
            \end{equation}
            is an $\left(\mathcal{F}^N(t)\right)$-martingale under $\mathbb{P}^N_{\overline{\nu}}:=\int_{[0,N)\times \mathbb{R}^d} \mathbb{P}^N_{s,x} \; \overline{\nu}(ds,dx)$, for all $f\in C_c^{\infty}((0,\infty)\times \mathbb{R}^d)$.
        \end{enumerate}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:04:55.815884+00:00","domain":"probability theory","id":"claim_c714ceb2fa8179097c87519d142d569766a1d944eb684e1cf15dbb75e78fa255","kind":"concept","schema_version":1,"statement":"[Lemm l:conditional-variance-variational of arXiv:2607.18194, 'Temperature chaos in directed polymers'] Let $X$ be a square-integrable random variable and let $Y$ be a random $d$-dimensional vector on the same probability space, for some $d\in\mathbb{N}$.
    Then
    \begin{align*}
        \mathbb{E}[\Var(X|Y)]
        = \mathbb{E}[(X-\mathbb{E}[X|Y])^2]
        = \inf_f \mathbb{E}[(X-f(Y))^2],
    \end{align*}
    where the infimum is over all measurable functions $f:\mathbb{R}^d\to\mathbb{R}$ such that $f(Y)$ is square-integrable. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

