{"assumptions":[],"created_at":"2026-10-27T20:06:06.303659+00:00","domain":"probability theory","id":"claim_c73870290d99bc346958439076a90907dba7dec6dd32f844136cf05c50e7dde3","kind":"lemma","schema_version":1,"statement":"[Lemma lem:gen-smooth-evaluation of arXiv:2605.26652, 'Pathological Large Deviations of the KMP Process in Dimension $d\ge 2$'] For any twice-differentiable test function $\varphi\in C^2(\mathbb T^d)$, there exist constants $\epsilon_{N,\varphi,H,K}$, vanishing as $N\to\infty$, such that, $\mathbb{Q}^{N,K}$-almost surely, for all $0\le t\le T$,
\begin{equation}
\left|\mathcal L^{N,H,K}_t\langle \varphi, \pi_N(\xi^N_t)\rangle-\frac12\langle \Delta\varphi,\pi_N(\xi^N_t)\rangle-\mathfrak D_{t,\varphi}^{N,K}(\xi^N_t)\right|\le \epsilon_{N,\varphi,H,K}.
\end{equation} 
Moreover, the $\mathbb{Q}^{N,K}$-martingale
\[
M^{N,\varphi}_t:=\langle \varphi, \pi_N(\xi^N_t)\rangle-\langle \varphi, \pi_N(\xi^N_0)\rangle-\int_0^t\mathcal L^{N,H,K}_s\langle \varphi, \pi_N(\xi^N_s)\rangle ds
\]
has predictable quadratic variation at most
\begin{equation}

[M^{N,\varphi}]_t\le \frac{C_{\varphi,H,K}}{N^d}\int_0^t\|\xi^N_s\|_{L^2_N}^2 ds.
\end{equation}","status":"unverified"}

