{"assumptions":[],"created_at":"2026-10-27T07:23:05.284452+00:00","domain":"probability theory","id":"claim_c74a38bd81f35cbb9ea6180820d16ae2905b31e179b1fc85bf1442045c44a211","kind":"concept","schema_version":1,"statement":"[Corollary 1 (Closed-form sparse loading update) of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] Let $\Ab^{(t)}=(a_{rc}^{(t)})$ be the unpenalized reduced loading estimate in \eqref{eq:main-4}, and let $\psi_{rr}^{(t)}$ be the $r$th diagonal entry of $\Psib^{(t)}$. The unique minimizer of $\mathcal{L}_{\rho} \left(\Lambdab\mid\thetab^{(t)} \right)$ in \eqref{eq:penalized-reduced-loading-objective} over $\Lambdab\in\CC^{p\times k}$ is $\Lambdab^{(t+1)}$, with entries
\begin{align}
  \lambda_{rc}^{(t+1)}
  &=
  \mathcal{T}_{\rho\psi_{rr}^{(t)}/2}
  \left(
    a_{rc}^{(t)}
  \right),
  \qquad
  r=1,\ldots,p,
  \quad
  c=1,\ldots,k,

\end{align}
where the complex soft-thresholding operator is given by
\begin{align}
  \mathcal{T}_{\rho\psi_{rr}^{(t)}/2}
  \left(
    a_{rc}^{(t)}
  \right)
  &=
  \begin{cases}
    \displaystyle
    \left(
      1-
      \frac{\rho\psi_{rr}^{(t)}}
           {2|a_{rc}^{(t)}|}
    \right)
    a_{rc}^{(t)},
    &
    |a_{rc}^{(t)}|
    >
    \dfrac{\rho\psi_{rr}^{(t)}}{2},
    \\[3mm]
    0,
    &
    |a_{rc}^{(t)}|
    \leq
    \dfrac{\rho\psi_{rr}^{(t)}}{2}.
  \end{cases}

\end{align}
All entries of $\Lambdab^{(t+1)}$ can be updated simultaneously. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:49.835801+00:00","domain":"probability theory","id":"claim_c74cd5bd4198c9e449fbd3009a0bd8364ff5311185c413518319c57ad23ced35","kind":"concept","schema_version":1,"statement":"[Theorem 7 (Pure jump L\'evy noise) of arXiv:2506.12834, 'Space-time fractional stochastic partial differential equations driven by L\'evy white noi'] Let $p\in[1,2]$ and  the parameters $(\alpha,\beta,\gamma,d,p)$ satisfy the inequality
  \begin{equation}
    p\alpha+\min\left\{\frac{\alpha}{\beta}(p\gamma-p+1),-p \right\}>d(p-1).
  \end{equation}
  Assume that there exist positive functions $a_1\in L^p(\R^d),a_2\in L^1(\R^d),a_3\in L^p(\R^d)$ such that the following growth conditions:
\begin{equation}
  |f(t,x,z)|+\sum_{j=1}^{d} |q_j(t,x,z)| \le a_1(x)+ C|z|,
\end{equation}
\begin{equation}
  \int_{\E}|h(t,x,z;\xi)|^p\mu(\ud\xi)  \le a_2(x)+ C|z|^p,
\end{equation}
and Lipschitz conditions
\begin{align}
   &|f(t,x,z_1)-f(t,x,z_2)|+\sum_{j=1}^{d} |q_j(t,x,z_1)-q_j(t,x,z_2)| \le \big[a_3(x)+C(|z_1|+|z_2|)\big] |z_1-z_2|,
\end{align}
\begin{equation}
  \int_{\E}|h(t,x,z_1;\xi)-h(t,x,z_2;\xi)|^p\mu(\ud\xi)  \le C|z_1-z_2|^p,
\end{equation}
hold for all $(t,x)\in[0,T]\times\R^d$ and $z_1,z_2,z_3\in\R$. Let $\cF_0$-measurable $u_0,u_1:\R^d\times\Omega\to\R$ satisfy
\begin{equation}
\begin{cases}
  \displaystyle \E\left[\int_{\R^d}|u_0(x,\cdot)|^p\ud x\right]<\infty, & \mbox{if } \beta\in(0,1] \vspace{0.2cm}\\
  \displaystyle \E\left[\int_{\R^d}|u_0(x,\cdot)|^p\ud x\right]+ \E\left[\int_{\R^d}|u_1(x,\cdot)|^p\ud x\right]<\infty , & \mbox{if } \beta\in(0,2).
\end{cases}
\end{equation}
Then  there exist a unique local solution to \eqref{e:de-solution2} with the following property
\begin{equation*}
  \E \left[\Vert u(t\wedge\tau,\cdot)\Vert_p^p\right]<\infty,
\end{equation*}
for all $t\in[0,T]$.  Furthermore, there exists a predictable modification for the solution $u(t)$ of \eqref{e:de-solution2}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

