{"assumptions":[],"created_at":"2026-10-26T20:59:53.170645+00:00","domain":"probability theory","id":"claim_c8f1af4a0c4731ac68db258f34616f5cd7403761ce680557ff4840450915324d","kind":"lemma","schema_version":1,"statement":"[Lemma 41 (Global Regularity and Gradient Estimates) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] Let Assumptions \ref{ass:smoothing}, \ref{ass:coefficients}, and \ref{ass:problem_data} hold. For any $\varepsilon > 0$ and $t \in [0, T)$, the mild solution $u_\varepsilon \in \mathcal{C}_m([0, T] \times H)$ to equation \eqref{eq:hjb_penalized} satisfies:
\begin{enumerate}[label={(\textit{\roman*})}, leftmargin=*]
    \item \emph{Continuous Differentiability.} The mapping $u_\varepsilon(t, \cdot)$ is continuously Fréchet differentiable on $H$. Defining the penalty term $\Pi_\varepsilon := \frac{1}{\varepsilon}(u_\varepsilon - \Phi)^+$, the spatial gradient satisfies:
    \begin{equation}

        \|\nabla u_\varepsilon(t, x)\|_H \le C_1 \left[ \|\Psi\|_{\mathcal{B}_m} (T-t)^{-\gamma} + \big( \|f\|_{\mathcal{B}_{m, T}} + \|\Pi_\varepsilon\|_{\mathcal{B}_{m, T}} \big) \frac{(T-t)^{1-\gamma}}{1-\gamma} \right] w_m(x), \quad \forall x \in H.
    \end{equation}

    \item \emph{Local Equi-Hölder Continuity.} For any radius $R > 0$ and exponent $\beta \in (0, 1)$ satisfying $\gamma(1+\beta) < 1$, the spatial gradient is locally $\beta$-Hölder continuous. Setting $C_R := C_{3}(1 + R^m)$, for all $x, y \in B_R \subset H$:
    \begin{equation}

        \|\nabla u_\varepsilon(t, x) - \nabla u_\varepsilon(t, y)\|_H \le C_R \left[ \|\Psi\|_{\mathcal{B}_m} (T-t)^{-\gamma(1+\beta)} + \big( \|f\|_{\mathcal{B}_{m, T}} + \|\Pi_\varepsilon\|_{\mathcal{B}_{m, T}} \big) \frac{(T-t)^{1-\gamma(1+\beta)}}{1-\gamma(1+\beta)} \right] \|x - y\|_H^\beta.
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:50:30.565766+00:00","domain":"probability theory","id":"claim_c8f1f699a036369950ebd5579ed228253e76c536515bf8a6c5b6fe447e5ff0b1","kind":"definition","schema_version":1,"statement":"[Definition 17 of arXiv:2605.30616, 'Brownian motion: the hyperbolic number setting'] Let $Z_{1}$ and $Z_{2}$ be two (not necessarily independent) $N(0,1)$
random variables defined on $(\Omega,\mathcal{C})$. The $\mathbb{H}$-valued random variable 
\begin{equation}
U\begin{pmatrix}Z_{1} & 0\\
0 & Z_{2}
\end{pmatrix}U,
\end{equation}
is called the $\mathbb{H}$-valued normal Gaussian variable associated
to $Z_{1}$ and $Z_{2}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.122835+00:00","domain":"probability theory","id":"claim_c8f33741cf01ca82154853a66e9d580e7f8ae452f977e78a81394ad6439461b2","kind":"theorem","schema_version":1,"statement":"[Proposition prop:free-Poisson-moments of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] The limiting measure $\mu_{c,\lambda,v}$ is the free compound-Poisson law with
rate $1/c$ and jump distribution $\operatorname{Law}(cR)$. For every $k\ge1$ it has the
finite moment
\begin{equation}
  M_k=\int t^k\,\mu_{c,\lambda,v}(\,\mathrm{d} t)
  =\sum_{\pi\in\mathrm{NC}(k)}c^{k-|\pi|}
  \prod_{V\in\pi}\mathbb{E} R^{|V|}.

\end{equation}
Equivalently, its free cumulants are
\begin{equation}
  \kappa_k=c^{k-1}\mathbb{E} R^k
  =c^{k-1}\exp\!\left(\frac{k(k-1)}2\lambda v\right).

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:46:12.278472+00:00","domain":"probability theory","id":"claim_c8f4017bbc5da64da152ab85b0dea64484baf438ea5540ce71b812efdf616513","kind":"definition","schema_version":1,"statement":"[Definition 10 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] A continuous $H$-valued $\mathcal{F}_{t}$-adapted process $\{X_{t}^{\epsilon} \}_{t \in I}$ is called a solution of Eq. \eqref{eq: SPDE} in the finite time interval $I=[t_0,t_1]$ ($t_1>t_0$), if for its $\d t \otimes \d \P$-equivalence class $\{\hat{X}_{t}^{\epsilon} \}_{t \in I}$, we have $\hat{X}_{t}^{\epsilon} \in L^2(I \times \Omega, \d t \otimes \d \P; V)$ and $\P$-a.s.
    \begin{equation} 
        X^{\epsilon}_t= X^{\epsilon}_{t_0} + \int_{t_0}^{t} A^{\epsilon}(\bar{X}^{\epsilon}_s) \, \d s + \sqrt{\epsilon} \int_{t_0}^{t} B(\bar{X}^{\epsilon}_s) \, \d W_s, \quad t \in [t_0,t_1],
    \end{equation}
    where $\bar{X}_{t}^{\epsilon}$ is any $V$-valued progressively measurable $\d t \otimes \d \P$-version of $\hat{X}_{t}^{\epsilon}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:38.597638+00:00","domain":"probability theory","id":"claim_c8f4341fdd95a7e61c5a5dea9323aebc2a9ded8e9642b27020c545773c19528d","kind":"concept","schema_version":1,"statement":"[Theorem 18 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Assume that Assumption~\ref{ass:joint-minorization} holds and that the multiplicative drift condition \eqref{eq:regenerative-drift} is satisfied. Then there exists $\theta_1>0$ such that, for the split chain started from the atom,

\begin{equation*}
\Ee_{\mathfrak a}\left[\exp\{\theta_1(L_1+|Y_1|_1)\}\right]<\infty.
\end{equation*}

Consequently all polynomial moment assumptions imposed on $L_1$ and $Y_1$ in this paper are satisfied. If a transition reward $g$ satisfies

\begin{equation*}
|g(x,y,k)|\leq c_g(1+|k|_1)
\end{equation*}

for some finite constant $c_g$, then

\begin{equation*}
\Ee_{\mathfrak a}\left[\exp\{\theta_2 R_1^*(g)\}\right]<\infty
\end{equation*}

for some $\theta_2>0$. In particular, the reward moment assumptions used in the functional inverse theorem hold, and the one-cycle reward measures used in the regenerative lattice proof are exponentially summable. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.349596+00:00","domain":"probability theory","id":"claim_c8f640265c48c79a812cdc0ded9cb656b319f582c005749488b0144db1dfcb56","kind":"theorem","schema_version":1,"statement":"[Proposition pr:cons-M of arXiv:2412.01489, 'One- and two-particle spectral gap identities for the symmetric inclusion process and rela'] Define, for all integers $k\ge 2$, 	the following \textquotedblleft restricted\textquotedblright\ annihilation operator $\hat{\mathfrak a}_k : \mathbb{R}^{\Omega_{k-1}}\to \mathbb{R}^{\Omega_k}$ as
	\begin{equation}
		\hat{\mathfrak a}_k g(\eta)\coloneqq \sum_{x\in V} \eta_x\,g(\eta-\delta_x)\; \text{,}\;\;\qquad g\in \mathbb{R}^{\Omega_{k-1}}\; \text{,}\;\;\eta\in \Omega_k\; \text{.} 
	\end{equation}
	Then, we have \begin{equation}
		M_{\hat\alpha,k}\,\hat{\mathfrak a}_k = \hat{\mathfrak a}_k\, M_{\hat\alpha,k-1}\; \text{.}
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.237736+00:00","domain":"probability theory","id":"claim_c8f88d2221a2eb6c3da587d3668fe432fdc4cb71e7fb8e65fef1827afceba0e8","kind":"lemma","schema_version":1,"statement":"[Lemma lem:inserted_int of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] Let $X = (X_t)_{t \in [0,T]}$ be an $\mathbb{R}^d$-valued continuous semimartingale. Then, for all ${\color{NavyBlue}{\mathbf{v_1}}}, {\color{NavyBlue}{\mathbf{v_2}}} \in V$ and $j \in \{1,\ldots,d\}$, 
    \begin{equation}
        \int_0^t \sigX[s]^{{\color{NavyBlue}{\mathbf{v_1}}}} \sigX[s,t]^{{\color{NavyBlue}{\mathbf{v_2}}}} \circ dX_s^j = \sigX[t]^{{\color{NavyBlue}{\mathbf{v_1 j v_2}}}}, \quad t \in [0,T].
    \end{equation}
    Consequently, for $\bm{\ell}_1, \bm{\ell}_2 \in \TA$,
    \begin{equation}
        \int_0^t \bracketsigX[s]{\bm{\ell}_1} \bracketsigX[s,t]{\bm{\ell}_2} \circ dX_s^j = \bracketsigX{\bm{\ell}_1 \otimes{\color{NavyBlue}{\mathbf{j}}}\otimes \bm{\ell}_2}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:11:02.359497+00:00","domain":"probability theory","id":"claim_c8fbbeb2c5ef647351d1d9df62e6612ace6ce1e88bf3205a25bede98e5797602","kind":"concept","schema_version":1,"statement":"[Prop of arXiv:2507.09421, 'Stability of randomly switching stochastic reaction networks with asymptotically linear tr'] The CRN from Example (ex:trans thms don't apply with superlinear reactions of the paper), viewed as a CRN with one species in one environment, is associated to a matrix in the sense of equation (equation eq:associated CRN of the paper). The corresponding mixed matrix is Hurwitz unstable, but nevertheless the CRN is positive recurrent.
\begin{proof}
    Notice that if $\mathcal R$ denotes the set of reactions, then
    \begin{align*}
    \sum_{y\to y'\in\mathcal R}\lambda_{y\to y'}(x)(y'_m-y_m)&=1+x-x(x-1)(x-2)+x(x-1)(x-2)\\
    &=x+1\\
    &=x+o(x).
    \end{align*}
    The corresponding matrix has a single, positive, element, namely $1$, and hence is Hurwitz unstable. So the only thing stopping us from applying Theorem (thm:fast-switching-transience of the paper) or Theorem (thm:slow-switching-transience of the paper) (or, for that matter, Corollary (cor:one-environment-transience of the paper)) is the existence of fast reactions $2S\leftarrow 3S\rightarrow 4S$.

    However, this CRN is positive recurrent. One can see this either directly by considering the Lyapunov function $f(x)=\log(x+1)$, or by applying the criteria from [Xu_Hansen_Wiuf_2022].
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:25:44.973343+00:00","domain":"probability theory","id":"claim_c8fbd2c2b7fb940777bea1ec9841d3df24af4b2614226946540c4c3291398f40","kind":"lemma","schema_version":1,"statement":"[Lemma 25 (Dirichlet append step) of arXiv:2605.11451, '2605.11451'] Let $Y$ be a projection generated by a $d$-dimensional $p$-ball through the sign-Dirichlet representation. Appending one coordinate with coefficient $c\ge0$ gives
\begin{equation}
 \widetilde Y=(1-T)^\alpha Y+cT^\alpha\eps,
\end{equation}
where $\eps$ is a Rademacher sign and
\[
 T\sim\operatorname{Beta}(\alpha,1+d\alpha)
\]
is independent of $Y$ and $\eps$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:03:35.716824+00:00","domain":"probability theory","id":"claim_c8fdf2cd7db8473ad726cf195a59ba4888f9d43fb57dbaa4cf16e08b3a8f4fe2","kind":"concept","schema_version":1,"statement":"[Thm partitionFunctionBound of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Fix $\beta\ge0$ and assume $0\le\mathsf{s}<\mathsf{d}/2$ and $\mu\in L^\infty\cap\mathcal{P}({\mathbb{R}}^\mathsf{d})$; if $\mathsf{s}=0$, assume in addition
\begin{align}
\int_{({\mathbb{R}}^\mathsf{d})^2}|\log |x-y||\,\mathop{}\!\mathrm d\mu^{\otimes2}(x,y)<\infty.
\end{align}
\begin{enumerate}[(i)]
\item\emph{(Uniform bound.)}  There is a finite constant $C_{\mathrm{ub}}(\beta,\mu)$ such that
\begin{align}
\sup_{N\ge1}{\mathsf{K}}_{N,\beta}(\mu)\le C_{\mathrm{ub}}(\beta,\mu).
\end{align}
\item\emph{(Quantitative convergence.)}  If $\mathsf{s}=0$, assume moreover that
\begin{align}
\int_{{\mathbb{R}}^\mathsf{d}}e^{-4\beta h_\mu}\,\mathop{}\!\mathrm d\mu<\infty,
\qquad \tilde{\mathsf{g}}\in L^2(\mu^{\otimes2}).
\end{align}
Then there are constants $C_{\mathrm{rate}}(\beta,\mu)<\infty$ and, in the logarithmic case, $c_{\log}(\beta,\mu)>0$ such that, for all $N\ge1$,
\begin{align}
\Big|{\mathsf{K}}_{N,\beta}(\mu)-{\mathsf{K}}_{\infty,\beta}(\mu)\Big|
\le C_{\mathrm{rate}}(\beta,\mu)
\begin{cases}
(\log(e+N))^{-\frac{\mathsf{d}-2\mathsf{s}}{2\mathsf{s}}}, & 0<\mathsf{s}<\mathsf{d}/2,\\[0.4em]
(e+N)^{-c_{\log}(\beta,\mu)}, & \mathsf{s}=0.
\end{cases}
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:11:35.837720+00:00","domain":"probability theory","id":"claim_c8fe74b7f657a3d7b0c54934779c14cbd2c03ddbca2f25fa28d60e44cf93dcab","kind":"theorem","schema_version":1,"statement":"[Prop prop-4corr of arXiv:2607.25567, 'Random Trees in Hyperbolic FPP'] If {$[ 1: \xi: a: b]\ll 0$, }then $c_{a1\xi}(\omega)$ and $X_{b1\xi}(\omega)$
	are {nearly independent}.
	If {$[ 1: \xi: a: b] \gg 0$, }  then $c_{a1\xi}(\omega)$ and $c_{b1\xi}(\omega)$
	are nearly the same.

	More precisely, there exists $C\geq 1, \, c\in (0,1)$ such that 
