{"assumptions":[],"created_at":"2026-10-27T15:07:17.255974+00:00","domain":"probability theory","id":"claim_c9888c4048409546a4362976a9ba8e27f754dcf93b3e4e61187ac9ccac98c552","kind":"concept","schema_version":1,"statement":"[Lemma RR_TT of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] Consider the setting of Lemma~(AJSJAsd of the paper). Then the following statements are valid.
	\begin{itemize}
		\item For every \( \omega^-, \omega^+ \in \mathcal{B}_H \) and all \( 0 \leq \tau \leq s \leq t \), the following identity holds:
		\begin{align}
			\begin{split}            
				\mathcal{D}_{H} P_{t}(\omega^-, \omega^+)(\tau - t)
				&- \mathcal{D}_{H} P_{t}(\omega^-, \omega^+)(-t)
				\\&= \mathcal{D}_{H} P_{s}(\omega^-, \omega^+)(\tau - s)
				- \mathcal{D}_{H} P_{s}(\omega^-, \omega^+)(-s).
			\end{split}
		\end{align}

		\item For all \( r \leq 0 \) and \( \omega^- \in \mathcal{B}_H \), we have 
		\begin{align}
			(\mathcal{D}_{H} \vartheta_{t} \omega^-)(r)
			= \mathcal{D}_{H} \omega^-(-t + r)
			- \mathcal{D}_{H} \omega^-(-t).
		\end{align}







		Define the process \( (B_t^H)_{t \in \mathbb{R}} \) by
		\begin{align*}
			B_t^H =B_{t}^{H}(\omega^-,\omega^+):=
			\begin{cases}
				- \bigl( \mathcal{D}_H P_t(\omega^-, \omega^+) \bigr)(-t), & t \geq 0, \\[6pt]
				\mathcal{D}_H \omega^-(t), & t \leq 0.
			\end{cases}
		\end{align*}
		Then \( (B_t^H)_{t \in \mathbb{R}} \) denotes a two-sided fractional Brownian motion with Hurst parameter \( H \), adapted to the canonical filtration \( (\mathcal{F}_{-\infty}^t)_{t \in \mathbb{R}} \) generated by the underlying Brownian motion appearing in the Mandelbrot-van Ness representation.

