{"assumptions":[],"created_at":"2026-10-27T11:40:59.350874+00:00","domain":"probability theory","id":"claim_cb1d651774e1be5aabbb15a609f43d274beebc7baf688afd70ed0c01b66e740f","kind":"theorem","schema_version":1,"statement":"[Proposition 22 of arXiv:2609.03954, 'Galois representations ramified at one prime via relative deformation theory'] For every $j\ge j_0$ there exist continuous representations
\[
 \tau_j:G_{\{p\}}\longrightarrow\GG(\Z/p^j\Z)
\]
and
\[
 \varrho_{j+R}:G_{\{p\}}
 \longrightarrow\GG(\Z/p^{j+R}\Z)
\]
such that
\begin{enumerate}[label=\textup{(\arabic*)}]
\item $\varrho_{j+R}\pmod{p^j}=\tau_j$;
\item $\tau_{j+1}\pmod{p^j}=\tau_j$;
\item $\varrho_{j+R}\pmod{p^R}=\rho_R$;
\item $\tau_{j_0}=\rho_{2A}^*\pmod{p^{j_0}}$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:43:43.441024+00:00","domain":"probability theory","id":"claim_cb1def45856c746ad5e760ca3b02143d885303633618a1ceb35baef44c11c0f6","kind":"theorem","schema_version":1,"statement":"[Proposition prop:Converse of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] Let $1 \leq p \leq q$, $(\mathcal{F}_p,\Gamma_p,\Psi)$ be a $p$-energy structure and $\nu$ be a Borel measure on $X$. Assume that the pair $x_0 \in X$ and $R_0 \in (0,\diam(X))$ satisfies the following condition. There are constants $L_0,\sigma \geq 1$ such that, whenever $x \in X$ and $r > 0$ with
    \begin{equation*}
        B(x,r) \cap B(x_0,R_0) \neq \emptyset \text{ and } 0 < r \leq R_0,
    \end{equation*}
    it holds for every $f \in \mathcal{F}_p$,
    \begin{equation}
    \left(\int_{B(x,r)} \abs{\tilde{f} - f_{B(x,r)}}^{q} \, d\nu \right)^{\frac{1}{q}} \leq L_0 \left(\int_{B(x,\sigma r)} d\Gamma_p\Span{f} \right)^{\frac{1}{p}}.
    \end{equation}
    Then there is a constant $C \geq 1$ such that
    \begin{equation}
        \nu(B(x_0,R_0))^{\frac{1}{q}} \leq C L_0 \left( \frac{\mu(B(x_0,R_0))}{\Psi(x_0,R_0)} \right)^{\frac{1}{p}}.
    \end{equation}
    This result is quantitative in the sense that $C$ depends only on the constants in (eq:UCap of the paper), (equation eq:muDoubling of the paper), (equation eq:RadDiam of the paper), the constants associated to $\Psi$ in (equation eq:Psi of the paper), $\sigma,\, p$ and $q$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:55:27.165929+00:00","domain":"probability theory","id":"claim_cb1dfb7643e14d9bd3ef299364d84c2a0262d6cf82c2ba57ca4626a713a90280","kind":"lemma","schema_version":1,"statement":"[Lemma Y N is open of arXiv:2609.04072, 'Oort's conjecture for split unitary Shimura varieties'] The set of $\overline{\mathbb{F}}_p$-points
    \begin{equation}
        Y_{\Lambda_0}(\overline{\mathbb{F}}_p)=\{M\in \mathcal{C}_{\Lambda_0}(\overline{\mathbb{F}}_p) \mid \operatorname{Aut}(M,F)=\Gamma_{\operatorname{gen}}\}
    \end{equation}
    defines an open subscheme $Y_{\Lambda_0}$ of $\mathcal C_{\Lambda_0}$. 

    Moreover it is dense in $\mathcal C_{\Lambda_0}$ if and only if for all $\gamma\in \operatorname{Aut}(\Lambda_0,F)\setminus \Gamma_{\operatorname{gen}}$ there exists a Dieudonné lattice $M\in \mathcal C_{\Lambda_0}(\overline{\mathbb{F}}_p)$ such that $\gamma\notin \operatorname{Aut}(M,F)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:04.861594+00:00","domain":"probability theory","id":"claim_cb215bf35bf309f6db935c252737adeea2478441ac5316a761f52348d2c66ede","kind":"concept","schema_version":1,"statement":"[Prp 40 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] Under the above setting, where $\{X_l\}_{l \in \Z}$ is given by \eqref{fGn def}, the following holds for every $k \in \N_0$ and $r \in [1,\infty]$.
\begin{enumerate}[\normalfont(1)]
    \item When $m = 2$, 
    \begin{align}
        \norm{\rho_{F_n}^{} - \rho_{\cN}^{}}_{W^{k,r}(\R)} \propto
        \begin{cases}
            n^{-\frac{1}{2}} &\quad  \text{if \  $H \in (0,\frac{2}{3})$},\\
            n^{-\frac{1}{2}}(\log n)^2 &\quad \text{if \  $H = \frac{2}{3}$},\\
            n^{-\frac{9}{2}+ 6H} &\quad \text{if \  $H \in (\frac{2}{3}, \frac{3}{4})$}.
        \end{cases}
    \end{align}
    \item When $m = 3$, 
    \begin{align}
        \norm{\rho_{F_n}^{} - \rho_{\cN}^{}}_{W^{k,r}(\R)} \propto
        \begin{cases}
            n^{-1} &\quad  \text{if \  $H \in (0, \frac{3}{4})$},\\
            n^{-1}(\log n)^3 &\quad \text{if \  $H = \frac{3}{4}$},\\
            n^{-10+12H} &\quad \text{if \  $H \in (\frac{3}{4}, \frac{5}{6})$}.
        \end{cases}
    \end{align}
    \item When $m = 4$, 
    \begin{align}
        \norm{\rho_{F_n}^{} - \rho_{\cN}^{}}_{W^{k,r}(\R)} \propto
        \begin{cases}
            n^{-\frac{1}{2}} &\quad  \text{if \  $H \in (0,\frac{5}{6})$},\\
            n^{-\frac{1}{2}}(\log n)^2 &\quad \text{if \  $H = \frac{5}{6}$},\\
            n^{-\frac{21}{2} + 12H} &\quad \text{if \  $H \in (\frac{5}{6}, \frac{7}{8})$}.
        \end{cases}
    \end{align}
    \item When $m \geq 5$ is an odd integer,
    \begin{align}
        \norm{\rho_{F_n}^{} - \rho_{\cN}^{}}_{W^{k,r}(\R)} \propto
        \begin{cases}
            n^{-1} &\quad  \text{if \  $H \in (0,\frac{3}{4})$},\\
            n^{-1}(\log n) &\quad \text{if \  $H = \frac{3}{4}$},\\
            n^{4H-4} &\quad \text{if \  $H \in (\frac{3}{4}, 1-\frac{1}{2m-2})$},\\
            n^{4H-4}(\log n)^2 &\quad \text{if \  $H = 1-\frac{1}{2m-2}$},\\
            n^{2 -4m + 4mH} &\quad \text{if \  $H \in (1-\frac{1}{2m-2}, 1-\frac{1}{2m})$}.
