{"assumptions":[],"created_at":"2026-10-27T23:03:39.761317+00:00","domain":"probability theory","id":"claim_cb2a5e0bc58bd1de0b8a4cfe613d7bfc5ea3d6f22e962459224756290b31b029","kind":"lemma","schema_version":1,"statement":"[Lemma lem:moment-bound:H^0_epsilon of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] Assume the hypotheses of~(thm:well-posed of the paper) and let $U_0=(u_0,\eta_0)\in \mathcal{H}^0_\mu$. Then

\begin{enumerate}[noitemsep,topsep=0pt,wide=0pt,label=\arabic*.,ref=\theassumption.\arabic*]
\item For all $\beta$ sufficiently small independent of $\mu\in\mathcal{M}_\delta$, 
\begin{equation}
\mathbb{E} \exp\left({\beta\Psi_0(U(t))}\right)\le e^{-c_0t}\exp\left({\beta\Psi_0(U_0)}\right)+C_0,\quad t\ge 0,
\end{equation}
where $\Psi_0$ is as in (equation form:Psi_0 of the paper) and $c_0=c_0(\beta)>0$, $C_0=C_0(\beta)>0$ do not depend on $U_0\in\mathcal{H}^0_\mu$, $t\ge 0$ and $\mu\in\mathcal{M}_\delta$. 

\item For all $n\ge 1$, there exist positive constants $c_{0,n},\tilde{c}_{0,n}$ and $C_{0,n}$ independent of $U_0\in\mathcal{H}^0_\mu$, $t\ge 0$ and $\mu\in\mathcal{M}_\delta$ such that
\begin{equation}  
\emph{d} \Psi_0(U(t))^n\le -c_{0,n} \Psi_0(U(t))^n\emph{d} t+\tilde{c}_{0,n}\emph{d} t+\emph{d} M_{0,n}(t),
\end{equation} 
where $M_{0,n}(t)$ is the semi-martingale given by
\begin{equation} 
M_{0,n}(t)=\int_0^t n\Psi_0(U(r))^{n-1}\langle u(t),Q\emph{d} w(r)\rangle_H. 
\end{equation}
Furthermore,
\begin{equation} 
\mathbb{E}\Psi_0(U(t))^n \le e^{-c_{0,n}t}\Psi_0(U_0)^n+C_{0,n},\quad t\ge 0.
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:33.548589+00:00","domain":"probability theory","id":"claim_cb2b55083b797e8eaf44958240032ab340ad0249548d4c79b8c97519a7ddb221","kind":"theorem","schema_version":1,"statement":"[Proposition 12 of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] Let $f$ and $g$ be as in \cref{lem:ODE}.
	Assume that $f^2(t)\geq 4g(t)$ for all $t\geq 0$, that $f(t) \to \infty$ and $g(t)/f(t) \to 0$ as $t \to \infty$.
	Then there exists a time $T>0$, an increasing function $\theta_l:[T,\infty)\to(-\pi/2,0]$ and a decreasing function $\theta_u:[T,\infty)\to[0,\pi/2)$ with
	\begin{equation*}
		\theta_l(t)\to0 \quad \text{and} \quad \theta_u(t)\to0 \quad \text{as } t\to\infty,
	\end{equation*}
	such that:

	\begin{itemize}
		\item[(a)] For each $t_0\ge T$, any solution $\theta$ to \cref{eq:ODE:theta} satisfying
		      \begin{equation*}
			      \theta(t_0)\in[\theta_u(t_0),\pi/2]
		      \end{equation*}
		      converges to $\pi/2$ as $t\to\infty$.

		\item[(b)] For each $t_0\ge T$, any solution $\theta$ to \cref{eq:ODE:theta} satisfying
		      \begin{equation*}
			      \theta(t_0)\in[-\pi/2,\theta_l(t_0)]
		      \end{equation*}
		      converges to $-\pi/2$ as $t\to\infty$.
	\end{itemize}

	Moreover, $\theta_u$ and $\theta_l$ can be chosen explicitly as
	\begin{equation}
		\theta_u(t)
		=
		\sup_{s\ge t} \arctan\!\left(
		\frac{f(s) - \sqrt{f^2(s)-4g_+(s)}}{2}
		\right),
		\qquad t\ge T,
	\end{equation}
	and
	\begin{equation}
		\theta_l(t)
		=
		\inf_{s\ge t} \arctan\!\left(
		\frac{f(s) - \sqrt{f^2(s)+4g_-(s)}}{2}
		\right),
		\qquad t\ge T,
	\end{equation}
	where $g_+:=\max\{g,0\}$ and $g_-:=\max\{-g,0\}$.
	In particular, for any solution $\theta$ of \cref{eq:ODE:theta}, every accumulation point of the trajectory
	$(\theta(t))_{t\geq 0}$ belongs to the set $\{-\pi/2,0,\pi/2\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.348838+00:00","domain":"probability theory","id":"claim_cb2bdb3b355e1c4866156f758ded2c2bbfe8bdb4d00546f6000504de1b5e3227","kind":"concept","schema_version":1,"statement":"[Lemma lem:4.4 of arXiv:2412.01489, 'One- and two-particle spectral gap identities for the symmetric inclusion process and rela'] \sk{Assume that (equation eq:cond-far of the paper) holds, and} suppose that $\ell\in\bbr{1}{k}$, $m\in\bbr{1}{\ell}$
