{"assumptions":[],"created_at":"2026-10-27T05:44:28.092876+00:00","domain":"probability theory","id":"claim_cb3ea04db36e234520a014e6439a58386820231f61d07ccdfa11fccbcb0f2cfd","kind":"theorem","schema_version":1,"statement":"[Prop 29 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] Given a probabilistic set-up $(\Omega,\mathfrak{F},{\mathbb F}= \{\mathfrak{F}_t\}_{t\geq 0},\mathbb{P},(W_t)_{t\geq 0})$ as defined in Subsection \ref{Notations}, and an ${\mathcal F}_0-$measurable initial condition $X_0$ with values in ${\mathcal U}^2({\mathbb S} )$ satisfying ${\mathbb E}[\| X_0\|_2^p] < + \infty$ for all $p \geq 1$, a pair of  processes $(X_t,{\eta}_t)_{t \geq 0}$ solves the equation \eqref{RHSE2} initialized at $X_0$, if and only if
    item $(i)$ in Definition \ref{Defi 317} holds true and there exists a continuous 
    ${\mathbb F}-$adapted process $(\zeta_t)_{t \geq 0}$ with values in ${\mathcal H}_{\rm Sym}^{-2}({\mathbb S})$ such that 
\begin{enumerate}
\item[(i)] $({\zeta}_t)_{t\geq 0}$ starts from $0$ at $0$ and, with probability 1, for any $\varphi \in \mathcal{H}_{\mathrm{Sym}}^{2}(\mathbb{S})\cap \mathcal{U}^2(\mathbb{S})$ the path $t\mapsto\langle {\zeta}_t, \varphi\rangle$ is non-decreasing;
\item[(ii)]  with probability 1, for any $\varphi \in 
\mathcal{H}_{\mathrm{Sym}}^{2}(\mathbb{S})$, for all $t \geq 0$
\begin{align*}
\langle X_t, \phi \rangle =
\langle X_0,\phi \rangle   + \int_0^t \langle X_r,\Delta_{\mathbf{x}} \phi \rangle \mathrm{d}r + \langle {\zeta}_t,\phi\rangle +\langle W_t,\phi\rangle, \quad t \geq 0;
\end{align*}
\item[(iii)] for any $t\geq 0$,
\[ 
\lim_{\epsilon \searrow 0}
\mathbb{E} \biggl[   \int_{0}^{t}  {\rm e}^{\epsilon \Delta} X_r \cdot 
\mathrm{d} \zeta_r    \biggr]=\frac{t}2 ,
\]
with the integral being interpreted as in Theorem \ref{thm:integral:varsigma};
\item[(iv)] with probability 1, for any $\varphi \in {\mathcal{H}_{\mathrm{Sym}}^{2}(\mathbb{S}) \cap \mathcal{U}^2(\mathbb{S})}$, the process 
\begin{equation}

\biggl( \langle \varphi,\zeta_t \rangle -
\frac12 \int_0^t \int_{\mathbb S} \frac{D_{\mathbf{x}} \varphi({\mathbf x})}{D_{\mathbf{x}} X_r({\mathbf x})} 
 \ud r{\mathrm d} {\mathbf x} \biggr)_{t \geq 0}
