{"assumptions":[],"created_at":"2026-10-26T19:16:49.556920+00:00","domain":"probability theory","id":"claim_cb549816f30f06413e5371769fdc87c66019dc0f7e676e76ca051814483918d5","kind":"concept","schema_version":1,"statement":"[Cor* 3 ({Cor.~\ref{c:LST}, \ref{c:GC}}) of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] Let $\mu=\sine_2$ or $\mu=\Airy_2$.    The following hold: 
\begin{enumerate}[{\rm (a)}]
\item  $(${\bf geodesical convexity}$)$ The space~$(\dom{\Ent_\QP}, {\mssW}_{2, \mssd_\U})$ is an extended geodesic metric space. Furthermore, the entropy~$\Ent_\QP$ is geodesically convex along every ${\mssW}_{2, \mssd_\U}$-geodesic $(\nu_t)_{t \in [0,1]}$$:$ for every $\nu_0, \nu_1 \in \dom{\Ent_\QP}$ with $\mssW_{2, \mssd_\U}(\nu_0, \nu_1)<\infty$, there exists a $\mssW_{2, \mssd_\U}$-constant speed geodesic $(v_t)_{t \in [0,1]}$ connecting $\nu_0$ and $\nu_1$ such that 
\begin{align*}
\Ent_\QP(\nu_t) \le (1-t)\Ent_{\QP}(\nu_0) + t \Ent_{\QP}(\nu_1)\cquad t \in [0,1] \fstop
\end{align*}
\item   $(${\bf RCD property}$)$ The extended metric measure space $(\U, \tau_\mrmv, \mssd_\U, \QP)$ is an $\RCD(0,\infty)$ space. For $\QP=\sine_2$, the curvature bound $K=0$ is the optimal constant. 
Furthermore, $(\mcT_t^{\U, \QP})_{t \ge 0}$ is identified with the heat flow on $\U$ (see also Thm.~\ref{it:IDD}).

\vspace{2mm}

\item    $(${\bf Distorted Brunn--Minkowski inequality}$)$ Let $A_0, A_1 \subset \U$ be Borel sets with $\QP(A_0)\QP(A_1)>0$ and define $\nu_0:=\frac{\1_{A_0}}{\QP(A_0)} \cdot \mu$ and $\nu_1:=\frac{\1_{A_1}}{\QP(A_1)} \cdot \mu$. Suppose $\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)<\infty$. Define the $t$-barycentre $(0 \le t \le 1)$ as 
$$[A_0, A_1]_t:=\{\eta \in \U: \eta=\gamma_t,\ \gamma \in {\rm Geo}(\U, \mssd_\U),\ \gamma_0 \in A_0,\ \gamma_1 \in A_1\} \comma$$
where ${\rm Geo}(\U, \mssd_\U)$ is the space of constant speed geodesics in $\U$. 
 Then, 

\begin{align*}
\log \frac{1}{\mu\bigl([A_0, A_1]_t \bigr)} \le (1-t)	\log \frac{1}{\mu(A_0)} + t \log \frac{1}{\mu(A_1)}  \fstop
\end{align*}

\item    $(${\bf HWI inequality}$)$ For~$\nu_0 \in \dom{\Ent_\QP}, \nu_1 \in \mcP(\U)$, 
$$\Ent_{\QP}(\nu_0) \le \Ent_{\QP}(\nu_1)+2\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)\Fis_{\QP}(\nu_0)^{1/2} \comma$$
where $\Fis$ is {\it the Fisher information} ${\sf F}_\QP(\nu) =\frac{1}{4}|{\sf D}_{{\mssW}_{2, \mssd_\U}}^- \Ent_\QP(\nu)|^2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

