        \end{equation}
        for any $N$ sufficiently large, $t>0$ and $e^t\gamma<\frac{1}{10}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:31:57.873008+00:00","domain":"probability theory","id":"claim_cbec9526cc055537c5205e1835b5a54d0a4ad33e6f8b32d0f4bba61a2b9b1495","kind":"theorem","schema_version":1,"statement":"[Proposition prop:quasicont-conseq of arXiv:2510.13659, 'On the energy image density conjecture of Bouleau and Hirsch'] Let  $(X,d,\mu, \mathcal{E}_p, \mathcal{F}_p, \Gamma_p)$ be a regular $p$-Dirichlet space.
		If $f\in \mathcal{F}_p$ is quasicontinuous and let $A\subset X$ be Borel measurable, then the following hold: 
		\begin{enumerate}
			\item If $\cCap(A)=0$, then $\Gamma_p\langle f\rangle(A)=0$.
			\item If $g \in \Lip(\mathbb{R})$ with $g(0)=0$, then $g \circ f \in \mathcal{F}_p$ and 
			\[
			\Gamma_p\langle g\circ f\rangle  \le( \Lip_a[g] \circ f)^p \cdot \Gamma_p\langle f\rangle.
			\]
			\item If $g\in \Lip(\mathbb{R}^n)$ with $g(0)=0$, and $f=(f_1,\dots, f_n)$ with $f_i\in \mathcal{F}_p$ and $f_i$ are quasicontinuous, then
			\begin{equation} 
				\Gamma_p\langle g\circ f\rangle  \le \left(1 \vee n^{(p-2)/2}\right) (\Lip_a[g] \circ f)^p\cdot \sum_{i=1}^n \Gamma_p\langle f_i\rangle.
			\end{equation}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:51:11.967575+00:00","domain":"probability theory","id":"claim_cbedd347b001c953bb1ac5a55229263b329e318352937a1630548989b12a9b1d","kind":"theorem","schema_version":1,"statement":"[Theorem 5 (Singular lifting, counterterms, and gauge) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] The defects in \eqref{cc:eq-lifting-defect} obey the nonabelian identity
\begin{equation}
 \widetilde\alpha_{t,v}(\Omega_{s,u,v})\star\Omega_{s,v,t}
 =\operatorname{Ad}_{\widetilde\alpha_{t,u}(Q_{s,u})}
      (\Omega_{u,v,t})\star\Omega_{s,u,t}

\end{equation}
for \(s\le u\le v\le t\).  If
\(Q'_{s,t}=r_{s,t}\star Q_{s,t}\), \(r_{s,t}\in K\), then
\begin{equation}
 \Omega'_{s,u,t}
 =\widetilde\alpha_{t,u}(r_{s,u})\star
  \operatorname{Ad}_{\widetilde\alpha_{t,u}(Q_{s,u})}(r_{u,t})
  \star\Omega_{s,u,t}\star r_{s,t}^{-1}.

\end{equation}
Consequently, corrected lifts
\(\widetilde\Phi_{s,t}=k_{s,t}\star Q_{s,t}\) are causal exactly when
\begin{equation}
 k_{s,t}=\widetilde\alpha_{t,u}(k_{s,u})\star
 \operatorname{Ad}_{\widetilde\alpha_{t,u}(Q_{s,u})}(k_{u,t})
 \star\Omega_{s,u,t}.

\end{equation}

Nevertheless, the unrestricted interval problem has no algebraic existence
obstruction.  If \(H_t\in p^{-1}(A_t)\), \(H_0={\mathbf 1}\), then
\begin{equation}
 L^H_{s,t}:=
 \bigl(\widetilde\alpha_{t,s}(H_s)\bigr)^{-1}\star H_t

\end{equation}
is a causal lift, and every causal lift has this form with
\(H_t=L_{0,t}\).  The based vertex gauges \(b_t\in K\), \(b_0={\mathbf 1}\), act by
\begin{equation}
 (L^b)_{s,t}
 :=\widetilde\alpha_{t,s}(b_s)^{-1}\star L_{s,t}\star b_t,

\end{equation}
freely and transitively on all unrestricted lifts.  Thus causality
shows that \(\Omega\) is the defect of the chosen pointwise section rather
than an obstruction to an unrestricted rooted lift; it selects no
renormalization gauge.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:41:33.834927+00:00","domain":"probability theory","id":"claim_cbee05ed354ff91fc807f9e9a88b600567a10022ef03d4d86fbbd0b0c77dfeb7","kind":"lemma","schema_version":1,"statement":"[Lemma 7 of arXiv:2604.10820, 'A Strict Gap Between Relaxed and Partition-Constrained\\ Spectral Compression in a Six-Sta'] Let $K$ be a symmetric stochastic $3\times 3$ matrix with eigenvalues $1,\kappa_2,\kappa_3$.
Then
\begin{equation}
L=K^2=\frac13\mathbf 1\mathbf 1^\top+\kappa_2^2 v_2v_2^\top+\kappa_3^2 v_3v_3^\top
\end{equation}
for orthonormal $v_2,v_3\perp \mathbf 1$. Consequently,
\begin{equation}
\kappa_3^2\le \frac{3\ell_{ii}-1}{2}\le \kappa_2^2.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:48:45.314397+00:00","domain":"probability theory","id":"claim_cbef953e03e0a0115f561b85d65b257f2230c0e9389700ee43da9fc659d579c1","kind":"concept","schema_version":1,"statement":"[Lemma tricky of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] Let $E,F\subseteq \mathbb R^3$ be non-empty Borel sets. Let $\mu$ be a finite measure on $F$, and $\nu(y,\cdot)$ be a finite measure on $E$ for each $y\in F$. 
    Suppose $p(x,y)$, $s(y)$ and $r(z)$ are non-negative bounded Borel functions on $E\times F,\,F,\,E$, respectively, such that the following equality holds for all $x\in E$,
    \begin{equation}
        r(x)=\int _F p(x,y)\left (\int _E r(z)\nu(y,dz)\right )\mu(dy)+\int _F p(x,y)s(y)\mu(dy).
    \end{equation}
    Moreover, suppose there exists a constant $0\le a <1$ such that for all $x\in E$,
    \begin{equation}
        \int_F p(x,y)\nu(y,E)\mu(dy)\leq a,
    \end{equation}
    then for all $x\in E$,
    \begin{equation*}
        \int p(x,y)s(y)\mu(dy)\geq \dfrac{1-a}{1+(K(p)-1)a}r(x).
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:21:56.737045+00:00","domain":"probability theory","id":"claim_cbf037cb20048e0c65616168485d22ea3211951630ac0645525867f035ccd5d7","kind":"lemma","schema_version":1,"statement":"[Lemma le:4arm_good_fl of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] Fix $p \in (0,1)$. Let~$h$ be a GFF on~$\mathbf{D}$ with boundary values so that its flow line $\eta$ is an ${\rm SLE}_{\kappa}${} from $-i$ to $i$. Let $X^0_{0,1},X^0_{0,\epsilon}$ be as defined in~(equation eq:fl_annulus of the paper). Let $I_\epsilon$ be the event that there exist two strands $\eta_{w_1;\mathrm{in}}$, $\eta_{w_3;\mathrm{in}}$ of $X^0_{0,1}$ and a strand $\eta_{w_2;\mathrm{out}}$ of $X^0_{0,\epsilon}$ so that the following hold.
\begin{itemize}
 \item The continuations of $\eta_{w_i;\mathrm{in}}$, $i=1,3$, exit $A(0,\epsilon/4,3/4)$ on the inner boundary and without merging, and the continuation of $\eta_{w_2;\mathrm{out}}$ exits $A(0,\epsilon/4,3/4)$ on the outer boundary.
 \item Let $\widetilde{I}_\epsilon$ be the event that
 \begin{itemize}
  \item $\eta$ merges consecutively into $\eta_{w_1;\mathrm{in}}$, $\eta_{w_2;\mathrm{out}}$, $\eta_{w_3;\mathrm{in}}$ before hitting $B(i,1/8)$ and without crossing $A(0,1/4,3/4)$ (resp.\ $A(0,\epsilon/4,3\epsilon/4)$) inbetween,
  \item the event $\mathcal {E}_4$ in Proposition~(pr:alternating_crossing_simple of the paper) occurs for $\eta$.
 \end{itemize}
 The conditional probability of $\widetilde{I}_\epsilon$ given $\eta_{w_1;\mathrm{in}}$, $\eta_{w_2;\mathrm{out}}$, $\eta_{w_3;\mathrm{in}}$, $X^0_{0,1},X^0_{0,\epsilon}$, and the values of $h$ on $X^0_{0,1},X^0_{0,\epsilon}$ is at least $p$.
\end{itemize}
Then
\[\mathbf{P}[I_\epsilon]=O(\epsilon^{\alpha_{4,\kappa}+o(1)}).\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:09:23.971890+00:00","domain":"probability theory","id":"claim_cbf06a9ced292d1cd311a965b7e9608b0f95fc275251a2123ce2d8339dcac07c","kind":"theorem","schema_version":1,"statement":"[Proposition 14 of arXiv:2607.22438, 'A deterministic scalar reduction for the phase transition in two interacting urns'] Let $s_0\in(0,1)$ be the unique solution of
