{"assumptions":[],"created_at":"2026-10-27T16:03:35.732175+00:00","domain":"probability theory","id":"claim_cc2011bf8534054900c11ca0dc8cb86822475be40f207d17868b49ce2c195e25","kind":"concept","schema_version":1,"statement":"[Thm dynamicLinearStatisticsCLT of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Let $0\le\mathsf{s}<\mathsf{d}/2$, $\beta>0$, and $T>0$.  Let $(\mu^t)_{0\le t\le T}$ be a mean-field trajectory and $(f_N^t)_{0\le t\le T}$ the corresponding particle laws.  Assume the following.
\begin{enumerate}[(i)]
\item The particle system and mean-field equation are well posed in a class for which the time-dependent It\^o formulas used below are valid; the Brownian motions are independent of the initial configuration; $f_N^0={\mathbb{Q}}_{N,\beta}(\mu^0)$; and the estimate (equation eq:MFEdiffusiveGronwall of the paper) holds.  Moreover,
\begin{align}
\sup_{0\le t\le T}
\pa*{\|\mu^t\|_{L^\infty}+\mathcal A^t+\mathcal B^t}
<\infty.
\end{align}
If $\mathsf{s}=0$, assume in addition that
\begin{align}
\inf_{0\le t\le T} I_{\mu^t}>-\infty.
\end{align}
\item There are constants $0<c_{\beta,T}\le C_{\beta,T}<\infty$ and $C_{2\beta,T}<\infty$ such that
\begin{align}
&\inf_{N\ge1}\inf_{0\le t\le T}{\mathsf{K}}_{N,\beta}(\mu^t)\ge c_{\beta,T},
\qquad
\sup_{N\ge1}\sup_{0\le t\le T}{\mathsf{K}}_{N,\beta}(\mu^t)\le C_{\beta,T},\\
&\sup_{N\ge1}\sup_{0\le t\le T}{\mathsf{K}}_{N,2\beta}(\mu^t)\le C_{2\beta,T},
\end{align}
and $\mu^0$ satisfies the hypotheses of (prop:linearEmpiricalFluctuationCLT of the paper).
\item There is a real linear test space $\mathscr D_T\subset C_b^2({\mathbb{R}}^\mathsf{d})$ such that, for every $t\in[0,T]$ and $\phi\in\mathscr D_T$, the terminal-value problem
\begin{align}
-\partial_r f^r=\mathcal L_{\beta,\mu^r}f^r,
\qquad 0\le r\le t,
\qquad f^t=\phi,
\end{align}
has a unique real-valued classical solution, denoted by $f^r=\mathsf{U}^{r,t}\phi$, for which $f$, $\nabla f$, $\nabla^{\otimes2}f$, and $\partial_r f$ are jointly continuous and
\begin{align}
\sup_{0\le r\le t}
\pa*{
\|f^r\|_{L^\infty}
+\|\nabla f^r\|_{L^\infty}
+\|\nabla^{\otimes2}f^r\|_{L^\infty}
+\|\partial_r f^r\|_{L^\infty}}
<\infty.
\end{align}
The bound in (equation eq:dynamicAdjointRegularity of the paper) is uniform over each fixed finite family of terminal pairs $(t,\phi)$.
\end{enumerate}
Fix $k\ge1$, times $t_1,\ldots,t_k\in[0,T]$, and tests $\phi_1,\ldots,\phi_k\in\mathscr D_T$.  Then
\begin{align}
\pa*{S_N^{t_1}(\phi_1),\ldots,S_N^{t_k}(\phi_k)}
\Longrightarrow (G_1,\ldots,G_k),
\end{align}
where the vector on the right is centered Gaussian with covariance
\begin{align}
{\mathbb{E}}[G_aG_b]
={}&\Sigma_{\beta,\mu^0}\pa*{\mathsf{U}^{0,t_a}\phi_a,\mathsf{U}^{0,t_b}\phi_b}\\
&+\frac2\beta\int_0^{t_a\wedge t_b}
\int_{{\mathbb{R}}^\mathsf{d}}\nabla\mathsf{U}^{r,t_a}\phi_a\cdot
\nabla\mathsf{U}^{r,t_b}\phi_b\,\mathop{}\!\mathrm d\mu^r\,\mathop{}\!\mathrm d r.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

