{"assumptions":[],"created_at":"2026-10-28T02:56:14.308778+00:00","domain":"probability theory","id":"claim_cc4c477dbc0b662ee06a75da89ee4284d572cef7b6f701c163bf26841ccf80df","kind":"lemma","schema_version":1,"statement":"[Lemma uniformEY of arXiv:2412.09850, 'Averaging principles for time-inhomogeneous multi-scale SDEs via nonautonomous Poisson equ'] Suppose that Assumption {\rm(A1 of the paper)} holds. Then there is a constant $C>0$ such that
\begin{itemize}
\item[{\rm (i)}] for $t \ge s$, $x\in\mathbb{R}^{n}$ and $y\in\mathbb{R}^{m}$,
\begin{equation}
\mathbb{E}|Y_{t}^{s,x,y} |^{4} \le e^{-4\gamma\int^{t}_s \alpha(u)\,du}|y|^4+C(1+|x|^4);
\end{equation}
\item[{\rm (ii)}]   for $t \ge s$, $x_1,x_2\in\mathbb{R}^{n}$ and $y_1,y_2\in\mathbb{R}^{m}$,
\begin{equation}
\mathbb{E}|Y_t^{s,x_1,y_1}-Y_t^{s,x_2,y_2}|^{4}\le e^{-4\gamma\int^t_s \alpha(u)\,du }|y_1-y_2|^{4}+C|x_1-x_2|^{4}, 
\end{equation}\end{itemize}
where $\gamma\in(0,1)$ is the constant in (equation A12 of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:47:40.731953+00:00","domain":"probability theory","id":"claim_cc4d2c615e8d966c60410a87432c6dd256e67ce9af44f239e4e6878bf5172fc7","kind":"concept","schema_version":1,"statement":"[Lemma lem:free-energy-spiked of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Fix $\theta>1$ and let $ \alpha >0$. The free energy of the spiked matrix model is given by:
\begin{align} 
F(\alpha,\theta) := \lim_{N \to \infty}  \frac{1}{N} \log \int_{\mathbf{S}_N} e^{\beta H_N(x)} dx = 
\begin{cases}
    \frac{\alpha^2}{4\theta^2} &\text{if} \ \alpha <1 \\
 \frac{\alpha}{2\theta} (\theta + \frac{1}{\theta}) - \frac{1}{4\theta^2} - \frac{1}{2} \log(\alpha) - \frac{1}{2}         &\text{else} 
\end{cases} \, ,
\end{align}
where the limit exists $\mathbb{P}_M$ almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:10:05.676641+00:00","domain":"probability theory","id":"claim_cc506358d401ba8485c2e4c484d9f9abaa66f7f5581878083fb5c1b1791c290b","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] For integers $n,d\geq 1$ we have
$$
\sum_{\ell=1}^{n}
\stirling{n}{\ell}\,
2^{\,n-\ell}
\sum_{j=0}^{d-1}
\binom{\ell-1}{j}
=
\sum_{q\geq 0}
\stirlingb{n}{d-1-2q},
$$
where the numbers $\stirlingb{n}{k}$ with $n\in \{1,2,\ldots\}$, $k\in \mathbb Z$,  are defined by the generating function
$$
\sum_{k\in \mathbb Z} \stirlingb{n}{k} t^k
=
(t+1)(t+3)\cdots(t+2n-1).
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.370913+00:00","domain":"probability theory","id":"claim_cc50fd59fe97d3f5492353f9c15d85361078d89eb3be4aca439b1ab415e48cfb","kind":"theorem","schema_version":1,"statement":"[Theorem 9 of arXiv:2606.03661, '2606.03661'] Let $\alpha \in (0,1)$, $\nu \in \mathbb{R}$ and $m \in \mathbb{N}$. Then, the function $\Psi_\alpha^\nu(-\kappa t)$ admits the asymptotic expansion
\begin{equation}

\Psi_\alpha^\nu(-\kappa t) =  -\frac{G(1+\nu)}{G(2+\nu-\alpha)}
\sum_{k=1}^m \rho_k  
(\kappa t)^{-(\nu+k)} 
 + \mathcal{O}\left(|\kappa t|^{-(\nu+m+1/2)}\right),
\end{equation}
where 
\begin{equation}

\rho_k = \underset{\varepsilon=0}{\operatorname{Res}} \left[\frac{(\kappa t)^{-\varepsilon} \Gamma(\nu+k+\varepsilon)G(2-\alpha-k-\varepsilon)}{  G(1-k-\varepsilon)} \right], \qquad (k = 1,2,\ldots,m).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:14:57.714438+00:00","domain":"probability theory","id":"claim_cc562220532fca8db64ab237b5344ba727d9402492fd38adfbfe1cbdfacf97e9","kind":"concept","schema_version":1,"statement":"[Lemma lem:comparaison_esperances of arXiv:2605.30999, 'Functional central limit theorems for $U$-statistics of $\beta$-mixing data'] Let $\left(X_j\right)_{j\geqslant 1}$ be a strictly stationary sequence of random variables taking values in a measurable space $\pr{S,\mathcal{S}}$. Let $f\colon S^m\to \mathbb R$ be a measurable function, where $S^m$ is endowed with the product $\sigma$-algebra. 
Let $\left(m\left(u,v\right)\right)_{\substack{1\leqslant u\leqslant \ell\\ 1\leqslant v\leqslant r_u}}$ be integers such that 
\begin{equation*}
    m\left(1,1\right)<\dots<m\left(1,r_1\right)<m\left(2,1\right)<\dots< m\left(2,r_2\right)<\dots< m\left(\ell,1\right)<\dots<m\left(\ell,r_\ell\right).
\end{equation*}
Let $r=\sum_{u=1}^\ell r_u$. Let $\left(\xi_j\right)_{j=1}^r$ be a sequence of random variables such that for each $j$, $\xi_j$ has the same distribution as $X_1$ and 
\begin{multline*}
    \mathcal{L}\pr{\pr{\xi_{m\left(1,1\right)},\dots,\xi_{m\left(1,r_1\right)},\xi_{m\left(2,1\right)},
\dots,\xi_{m\left(2,r_2\right)},\dots,\xi_{m\left(\ell,1\right)},\dots,\xi_{m\left(\ell,r_\ell\right)}  }}\\
=\mathcal{L}\pr{X_{m\left(1,1\right)},\dots,X_{m\left(1,r_1\right)} }
\otimes \dots\otimes \mathcal{L}\pr{X_{m\left(\ell,1\right)},\dots,X_{m\left(\ell,r_\ell\right)} }.
\end{multline*}
Suppose that there exists a constant $R$ such that for each $x_1,\dots,x_m\in S$,  $\left|f\left(x_1,\dots,x_m\right)\right|\leqslant R$.
Then the following inequality takes place
\begin{multline}
    \abs{\E{f\pr{X_{m\left(1,1\right)},\dots,X_{m\left(\ell,r_\ell\right)} }}-
    \E{f\pr{\xi_{m\left(1,1\right)},\dots,\xi_{m\left(\ell,r_\ell\right)} }}}
\\    \leqslant 2\sum_{i=1}^{\ell-1}
    \beta\left(m\left(i+1,1\right)-m\left(i,r_i\right)\right)R.
\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:31:14.333160+00:00","domain":"probability theory","id":"claim_cc568ebf53edec744551bdda06445dfa48c77cd5ba0e3bb201e52729cd79e94a","kind":"concept","schema_version":1,"statement":"[Lemma circular_law of arXiv:2606.16609, 'On stability of outliers from the circular law'] Let $\{ \lambda_1, \dots, \lambda_N \}$ the spectrum of a complex Ginibre matrix conditioned on $\{ \lambda_1 = z \}$ with fixed $z \in \mathbb{C}$; almost surely, the empirical spectral distribution
$$
\frac{1}{N-1} \sum_{k=2}^N \delta_{\lambda_k}
$$
converges weakly to the circular law. That is to say that, for any continuous bounded function~$\phi$, we have
$$
\frac{1}{N-1} \sum_{k=2}^N \phi(\lambda_k) 
\xrightarrow[]{N \rightarrow \infty} 
\frac{1}{\pi} \int_{\mathbb{D}} \phi(z) \mathrm{d} z.
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:56:14.252141+00:00","domain":"probability theory","id":"claim_cc56d919f148a5af3bdc5927124878c9b9f722091d52d8cd1deda4564c6c341a","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_mu_pi_ineq_Prod of arXiv:2412.09532, 'Percolation on the stationary distributions of the voter model with stirring'] Let~$\Lambda \subset \mathbb{Z}^d$ be finite and let~$E,F \in \mathcal G^{(2)}_\Lambda$ be an increasing-decreasing event and a decreasing-increasing event, respectively. In the space of the graphical construction, we consider an~$\mathcal F_t$-measurable random configuration~$\eta \in \{0,1\}^\Lambda$ with the property that the coalescing random walks started at~$\{x \in \Lambda: \eta(x) = 0\}$ do not coalesce until time~$t$. Then for any~$\alpha,\beta \in (0,1)$ with~$\alpha > \beta$ and~$\mathsf v \ge 0$,
\begin{align*}
& \mu_{\alpha,\beta,\mathsf v}(E) \leq \mathbb{E} \Big[\pi_{\alpha,\beta}\big( (\zeta_1,\zeta_2): (\zeta_1\vee \eta , \zeta_2 \wedge (1-\eta) ) \in E \big)  \cdot \hspace{-2mm} \prod_{ \substack{ x,y \in \Lambda \setminus \Xi \\ x< y} } \big( 1+ h(Y^x_t,Y^y_t) \cdot (\widehat\theta^{-2}-1) \big) \Big], \\[2mm] 
& \mu_{\alpha,\beta,\mathsf v}(F) \leq \mathbb{E} \Big[\pi_{\alpha,\beta}\big( (\zeta_1,\zeta_2): (\zeta_1 \wedge (1-\eta), \zeta_2 \vee \eta ) \in E \big)  \cdot \hspace{-2mm} \prod_{ \substack{ x,y \in \Lambda \setminus \Xi \\ x< y} } \big( 1+ h(Y^x_t,Y^y_t) \cdot (\widehat\theta^{-2}-1) \big) \Big],
\end{align*}
where~$\widehat\theta := \min\{ 1-\alpha, \alpha - \beta, \beta \}$.
Moreover, assume that~$\Lambda' \subset \mathbb{Z}^d$ is a finite set disjoint from~$\Lambda$, and let~$F \in \mathcal G^{(2)}_{\Lambda'}$ be a decreasing-increasing event. Then,
\begin{equation}
\begin{aligned}
\mu_{\alpha,\beta,\mathsf v} \left( E \cap F \right) \leq  \mathbb{E}\Big[ \pi_{\alpha,\beta} \big( (\zeta_1,\zeta_2) &: (\zeta_1\vee \eta , \zeta_2 \wedge (1-\eta) ) \in E, (\zeta_1 \wedge (1-\eta), \zeta_2 \vee \eta ) \in F \big) \\[2mm]
& \cdot \prod_{ \substack{ x,y \in (\Lambda \cup \Lambda') \setminus \Xi \\ x< y} } \left( 1+ h(Y^x_t,Y^y_t) \cdot (\widehat\theta^{-2}-1) \right) \Big].
\end{aligned}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.127738+00:00","domain":"probability theory","id":"claim_cc5852a7019fbed8089839467e4e8537859e28b06422bd6b72d71392a6c1e43e","kind":"definition","schema_version":1,"statement":"[Def P of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] For each fixed natural numbers $\ell \leq L<N$, each $0\leq j\leq L$ and each $\eta\in\Omega_N$, let 
\begin{align}
    \mathbf{p}_{\ell;L}
    &:=
    \frac{1}{L+1}
    \sum_{j=0}^{L}
    \mathbf{p}_{\ell;L}^j
    \quad\text{with}\quad
    \mathbf{p}_{\ell;L}^j(\eta)
    :=
    \frac{\binom{m_j^L(\eta)}{\ell}}{\binom{L}{\ell}}
    \mathbf{1}
    \{
    m_j^L(\eta)\geq \ell
    \}
    .    
\end{align}
    We refer to the process induced by setting $\mathbf{c}=\mathbf{p}_{\ell;L}$ in (equation generic:gen of the paper) as $\text{PMM}_{L}(\ell)$, and its corresponding Markov generator as $\mathcal{L}_N^{\ell;L}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:47:32.880023+00:00","domain":"probability theory","id":"claim_cc59672f1b3d88ce01a190240d0966b8de871f0d659269c1e78e88efd5427005","kind":"theorem","schema_version":1,"statement":"[Proposition 12 of arXiv:2609.02478, 'Improved Weyl bounds on short intervals'] Let $k\ge3$ and $K=k(k-1)$.  For every sufficiently small fixed
