{"assumptions":[],"created_at":"2026-10-26T19:36:44.552908+00:00","domain":"probability theory","id":"claim_cc9bb6131c2f18a3b782541a88aa008eb744bd807debf61b131ba1fb77ac812c","kind":"concept","schema_version":1,"statement":"[Prop 5 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution to~\eqref{eq:abc-slow},\eqref{eq:intro-0Mass-Fast}, with corresponding initial data $(Q^i_0,P^i_0)$ for $i=1,2$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} and the parameter $\alpha\geq 0$. 
    \begin{enumerate}[label=(\roman*)]
        \item 
        For any $t\geq 0$ 
        \begin{align}

            \E\Bigl[|P_t^{1}|^2\Bigr] \leq 
            \begin{dcases} C_1 \bigl(\eps +  e^{-\frac{C_2}{\eps}t} |P_0^{1}|^2\bigr) \  &\text{if $\alpha=0$}, \\
            C_3 \left(\eps +\eps |Q^1_0|^2  + (e^{-\frac{C_4}{\eps}t} + \eps)  |P^1_0|^2    \right) &\text{if $\alpha>0$},
             \end{dcases}
        \end{align}
        where the constants $C_1, C_2, C_3, C_4>0$ are independent of $\eps$ and $t$.

        \item Let $(\hat q_t,q_t,p_t)\in \R^{k}\times \R^{d-k} \times \R^{d-k}$ with initial data $(\hat q_0,q_0,p_0)=(Q^1_0,Q^2_0,P^2_0)$  evolve according to~\eqref{eq:0Mass-q1} and~\eqref{eq:limit-gen}. 
        We have for any $t\leq 0$
        \begin{align}
        \E\biggl[\Bigl|(Q^{1}_t,Q^{2}_t,P^{2}_t)^\top - (\hat q_t,q_t,p_t)^\top\Bigr|^2\biggr] \leq \begin{dcases}C_5 e^{C_6 t^2}\Bigl(\eps + 
        \bigl|P_0^{1}\bigr|^2  \Bigr) \ &\text{if $\alpha=0$}, \\
        C_7 e^{C_8 t^2}\Bigl(\eps t^2+\eps^2 t^2 \bigl|Q_0^{1}\bigr|^2 + |P^1_0|^2\Bigr)  &\text{if $\alpha>0$},
        \end{dcases}
        \end{align}
        where the constants $C_5,C_6, C_7,C_8>0$ are independent of $\eps>0$ and $t>0$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.757842+00:00","domain":"probability theory","id":"claim_cc9c54e892fd8bc42e5ebd4657fa126261c5a0bc1b4b8845b1934e98ba4ef4d0","kind":"lemma","schema_version":1,"statement":"[Lemma lem:frostman-green-smoothing of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $\mu$ be a finite positive Radon measure on $D$ satisfying, for some
$C_\mu<\infty$ and $\alpha>0$,
\begin{equation}
 \mu(B_D(z,r))\le C_\mu r^\alpha,
 \qquad z\in D,
 \quad 0<r\le1.
\end{equation}
Then $\mu(\{z\})=0$ for every $z\in D$.  For every $p>0$,
\begin{equation}
 L_p(\mu)
 :=\sup_{z\in D}\int_D
 \left(1+\log^+\frac1{|z-w|}\right)^p\mu(dw)<\infty.
\end{equation}
Moreover, for every compact $K\Subset D$,
\begin{equation}
 \sup_{\substack{z,z'\in K\\|z-z'|\le\delta}}
 \int_D|G_D(z,w)-G_D(z',w)|^2\,\mu(dw)
 \xrightarrow[\delta\downarrow0]{}0.
\end{equation}
In particular,
\begin{equation}
 \sup_{z\in D}\int_DG_D(z,w)^2\,\mu(dw)
 \le C_D^2L_2(\mu)<\infty.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:13:22.519513+00:00","domain":"probability theory","id":"claim_cc9f00138c07a4f67f9a4f1f2851e30f2b7831416db2cfeede6a577ebbd48a44","kind":"definition","schema_version":1,"statement":"[Definition eq:defomration-area-change of arXiv:2505.16585, 'Expanded regimes of area law for lattice Yang--Mills theories'] Let $s \in \mc{S}_\Lambda$ be a string, and suppose that $s$ is non-null. Let $\mbf{e}$ be an edge of $s$. Let $K : \mc{P}_\Lambda \ra \N$ be a plaquette count. Let $\mbb{D}_{\pm}(s, \mbf{e}, K)$ be the set of pairs $(s', K')$ such that $s'$ is a positive/negative deformation of $s$ at $\mbf{e}$, and such that $K'$ satisfies the following constraint. First, let $p_0 \in \mc{P}_\Lambda^+$ be the positively oriented plaquette such that $s'$ is a deformation of $s$ using either $p_0$ or $p_0^{-1}$. Then we assume that $K(p_0) \geq 1$, and we impose that $K'$ is given by
\begin{equs}
K'(p) = \begin{cases} K(p) & p \neq p_0, \\
K(p) - 1 & p = p_0 .\end{cases}
\end{equs}
Note by definition that for all $(s', K') \in \mbb{D}_{\pm}(s, \mbf{e}, K)$, 
\begin{equs}
\sum_{p \in \mc{P}_\Lambda^+} K'(p) = -1 + \sum_{p \in \mc{P}_\Lambda^+} K(p).
\end{equs}
In the case where $K(p_0) = 0$ for all plaquettes $p_0$ such that either $p_0$ or $p_0^{-1}$ contain the edge $\mbf{e}$, then we define $\mbb{D}_{\pm}(s, \mbf{e}, K) := \varnothing$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:29:08.520285+00:00","domain":"probability theory","id":"claim_cca280fbe179e0b4234741f35e1313eed15e360d4a3bf444a3f2723610d7f8c3","kind":"concept","schema_version":1,"statement":"[Proposition prop:Markov of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $D\subset \mathbb{C}$ be a domain with $\partial D =  \partial^D\cup\partial^F$, $\partial^D\cap\partial^F=\emptyset$, and $U\subset D$ open. Let $h$ be the GFF on $D$ with  \textit{Dirichlet} (resp. free) \textit{boundary conditions} on $\partial^D$ (resp. $\partial^F$). Then we can write $h=h_1+h_2$ where: 
		\begin{enumerate}
			\item $h_1$ and $h_2$ are independent;
			\item $h_1$ is a GFF on $U$ with Dirichlet boundary condition on $\partial U\backslash \partial^F$ and free on $\partial U\cap \partial^F$;
			\item $h_2$ is the same as $h$ outside $U$ and harmonic inside $U$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:10.033985+00:00","domain":"probability theory","id":"claim_cca52748fee41d222c1cdf0d7ef4929ea8eed2d6f83d1bbd05b2a579d57cf9f4","kind":"concept","schema_version":1,"statement":"[Lemma 26 of arXiv:2506.09609, 'Schramm-Loewner evolution contains a topological Sierpi\'nski carpet when $\kappa$ is clos'] Fix $N \geq 100$. For all sufficiently large $M$ (which may depend on $N$ and $\varrho$), with probability $1 - o_R(1)$ as $R \to \infty$, the set $\mathscr{U}$ is $N$-separated in the following sense. Let $\mathsf{m} = \mathsf{m}(N, R, \varrho)$ be the largest integer $m$ such that $N^m \leq \varrho^{-1} 10^{-4} R$. There exists a sequence of vertex sets $\{\mathcal{A}_m\}_{0 \leq m \leq \mathsf m - 1}$ satisfying:
    \begin{enumerate}[i.]
        \item $\mathcal{A}_m \subset \varrho N^m \mathbb{Z}^2 \cap \mathscr{L}_R$ for $0 \leq m \leq \mathsf m - 1$; 
        \item For $0 \leq m \leq \mathsf m - 1$, each vertex in $\mathcal{A}_m$ has $|\cdot|_\infty$-distance at least $\frac{1}{10} \varrho N^{m+1}$ away from each other; 
        \item We have $\mathscr{U} \subset \cup_{m=0}^{\mathsf{m} - 1} \cup_{y \in \mathcal{A}_m} B(y, 10 \varrho N^m)$. 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:31:49.846588+00:00","domain":"probability theory","id":"claim_cca75cb5081d0bb7faeeee7c18d3357dfa02f92e11bca9c9797facb8badcc2bd","kind":"theorem","schema_version":1,"statement":"[Theorem the: relative compactness of measured-valued processes of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] The sequences
	\begin{equation*}
