{"assumptions":[],"created_at":"2026-10-27T12:40:22.329091+00:00","domain":"probability theory","id":"claim_cd313c090350e8e432e2ee615310c4a88d6c1028f9f0d9f3bd88e7627feb3002","kind":"lemma","schema_version":1,"statement":"[Lemma lem: separate outer of arXiv:2609.03755, 'The Scramble Number of Outerplanar Graphs'] Let $G$ be a maximal outerplanar graph. Under the isomorphism that maps $G[N(v)\cup\{v\}]$ to $F_{\deg(v)}$, let $x,y\in N(v)$ map to non adjacent path vertices $u_i$ and $u_j$ such that $i<j$. We may produce a cut $C$ such that
    \begin{enumerate}
        \item $C$ disconnects at least two non-empty vertex sets,
        \item the vertices $u_{i+1}, \ldots, u_{j-1}$ lie in the same component, and $v$ lies in another component,
        \item $|C|\leq \deg(x)+\deg(y)+(j-i)$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.221389+00:00","domain":"probability theory","id":"claim_cd31c1ea153844d2aed386453ed4feb8979e72c0c47872b31117417e97f257a3","kind":"concept","schema_version":1,"statement":"[Proposition prop: 478 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] Let $E_{0}$ and $\epsilon_{0}$ be as in Theorem (thm: 96 of the paper).
Let $\beta_{*}$ be as in Lemma (lem: 523 of the paper).
Consider a (small) constant $\hat{\epsilon}\in(0,\beta_{*}/3)$ such that $[E_{0}-\hat{\epsilon},E_{0}+\hat{\epsilon}]\subset\mathcal{I}(\epsilon_{0}/2)$.
Choose a small constant $\delta\in(0,1)$.
For $x,y\in[E_{0}-\hat{\epsilon},E_{0}+\hat{\epsilon}]$ with $|x-y|\ge N^{\delta}\eta_{*}$,
\begin{equation*}
	\partial_{w}\Tr(M'(x\pm\mathrm{i}\eta_{*})M^{-1}(x\pm\mathrm{i}\eta_{*})V(x\pm\mathrm{i}\eta_{*},y\mp\mathrm{i}\eta_{*}))
	= -\frac{1}{(x-y)^{2}} \Big( 1 + O(\hat{\epsilon}) \Big),
\end{equation*}
where the implicit constant in $O(\hat{\epsilon})$ is independent of $x$ and $y$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:53.156722+00:00","domain":"probability theory","id":"claim_cd332ebabdaf21e997d540fea655bc489c5793c15f4641d1cdbe0f5555c3ef95","kind":"theorem","schema_version":1,"statement":"[Theorem 7 (Markov property) of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] For every $\mu$ in the support of the marginal distribution,
\begin{equation}
        \sum_{\lambda\in\SP}K_X^Y(\mu,\lambda)=1.
\end{equation}
Moreover,
\begin{equation}
        \Prob_q^{X,Y}(\mu,\lambda)
        =\pi_{qX,Y}(\mu)K_X^Y(\mu,\lambda),
\end{equation}
where
\begin{equation}
        \pi_{qX,Y}(\mu)=\frac{Q_\mu(qX)P_\mu(Y)}{\Ht(qX;Y)}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:05:57.813344+00:00","domain":"probability theory","id":"claim_cd3376ab331b5ddd62cf760ce485358cd7be6f402088b3c654837ddeac56c50b","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2608.30570, '2608.30570'] Let $\Sigma\subset \mathbb{R}^n$ be a  properly  immersed  surface with
\begin{enumerate}
\item ${\rm {Area}}(\Sigma\cap B_R)\le \Lambda R^2$ for all $R>0$,
\item the genus of $\Sigma$ is finite,
\item there exists $R_k\to \infty$ such that $\lim_{k\to \infty}\int_{(A_{\frac{R_k}{2},4R_k})\cap \Sigma}|{\bf A}|^2d\mu=0$. Here $A_{\frac{R_k}{2},4R_k}=B_{4R_k}(0)\backslash B_{\frac{R_k}{2}}(0)$.
\end{enumerate}
Then the number of ends of  $\Sigma$ is no more  than $2\Lambda$ and they are all annular. More precisely, there exists a large number $R_0>0$ such that $\Sigma\backslash B_{R_0}(0)$ contains finite many  non-compact connected   components
$\{\Sigma_j\}_{j=1}^{N\le 2\Lambda}$, which are all homeomorphic  to $\mathbb{D}^c=\{z\in \mathbb{C}||z|\ge 1\}$.
Moreover, for each $j\in \{1,2,\ldots, N\}$ and $k$ large, if $x_k\in \Sigma_j\cap \partial B_{\frac{3R_k}{2}}$, then,  there exist a positive integer $d= d_{j,k}\le \frac{\Lambda}{3\pi}$ and   a conformal parameterization $f: D_{(2R_k)^{\frac{1}{d}}}\backslash D_{R_k^{\frac{1}{d}}}\to \Omega_{R_k}$ for some domain $\Omega_{R_k}\subset \Sigma_j$  containing $x_k$ and satisfying
\begin{align*}
d_{H}(\left(\Sigma_j\cap (B_{2R_k}\backslash B_{R_k})\right)_{x},\Omega_{R_k})\le \psi(\epsilon_k)R_k
\end{align*}
such that  $df\otimes df=e^{2u}g_{\mathbb{R}^2}$ and  for any $ z\in D_{(2R_k)^{\frac{1}{d}}}\backslash D_{(R_k)^{\frac{1}{d}}}$, there holds
\begin{align} 
C^{-1}\le \frac{e^{2u}}{d^2|z|^{2d-2}}\le C
\end{align}
\begin{align}
1-\psi(\epsilon_k)\le \frac{|f(z)|}{|z|^d}\le 1+\psi(\epsilon_k).
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:25.278259+00:00","domain":"probability theory","id":"claim_cd37c8a4e5ed16804e19886b0ce8e35a6ad3d5f11df60a7398ca850d187ff149","kind":"theorem","schema_version":1,"statement":"[Prop 15 of arXiv:2606.21433, 'Central limit theorem for\\ the averaged Adam optimizer'] We assume the setting of \cref{thm-1}.
Let $n^*\in\N$ and consider the stopping time
\bas{ T_{n^*}'=\inf\{n\ge n^*: \theta_n\not \in V \}.
}
Moreover, let for all $k\in\N$, $r(k)=\lfloor k-(\log k)^2\rfloor$, $v^*$  as in \cref{def:v_star},
\bas{

  \cE'_k=\{\forall i\in\{1,\dots,d\}\exists \text{distinct }&\ell_1,\ell_2\in\{n^*+1,\dots, k-1\}\text{ with }
\\&
  (X^{(i)}(\theta_{\ell_1-1},U_{ \ell_1}))^2\wedge (X^{(i)}(\theta_{\ell_2-1},U_{ \ell_2}))^2\ge \delta\} ,
}
\bas{

  \tilde \cE'_k=\{\forall i\in\{1,\dots,d\}\exists \text{distinct }&\ell_1,\ell_2\in\{r(k),\dots, k-1\}\text{ with }
\\
&
  (X^{(i)}(\theta^*,U_{ \ell_1}))^2\wedge (X^{(i)}(\theta^*,U_{\ell_2}))^2\ge \delta\}
}
and
\bas{

  \tilde \cE''_k=\bigl\{\bigl\|(\1_{\{k+\ell<r(k)\}}\,X(\theta^*,U_{k+\ell}))_{\ell\in-\N_0}\bigr\|_{\ell_\varrho^d}\le 1\bigr\} .
}
One has
\bas{

  \lim_{ k \to \infty }
  \gamma_{ r( k ) }
  (\log k)^2/\sqrt{\gamma_{k-1}}=0
}
and there exists $ \kappa \in (0,\infty) $ such that the following is true:
\begin{enumerate}[label=(\roman*)]
\item

Almost surely, on $\{T_{n^*}'=\infty\}$, all but finitely of the events $(\cE'_k)_{k\in\N}$ occur and  for all $k\in\N$ with $k>n^*$ and all  $i\in\{1,\dots,d\}$
\bas{
\E\bigl[\1_{\{T_{n^*}'=\infty\}}\1_{\cE'_k}v^*(\bX^{(i)}(k))^{-1}\bigr]\le \kappa.
}
\item

Almost surely,  all but finitely many of the events $(\tilde \cE'_k)_{k\in\N}$ and $(\tilde \cE''_k)_{k\in\N}$ occur and there exists  $\kappa\in(0,\infty)$ such that for all $k\in\N$ with $r(k)\ge1$ and all  $i\in\{1,\dots,d\}$
\bas{
\E\bigl[\1_{\tilde \cE_k'}v^*(\tilde \bX^{(i)}(k-1))^{-1}\big|\cF_{r(k)-1}\bigr]\le \kappa,}
where $\tilde \bX(k)=(X(\theta^*,U_{k+\ell}))_{\ell\in-\N_0}$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.073750+00:00","domain":"probability theory","id":"claim_cd37e47d9fbfaf67218ac6fa1178928dca96c33108e67bfb10290bcb2099b2bb","kind":"theorem","schema_version":1,"statement":"[Proposition 11 of arXiv:2606.01881, '2606.01881'] For every $\eps>0$,
