{"assumptions":[],"created_at":"2026-10-27T23:48:35.812540+00:00","domain":"probability theory","id":"claim_cd88d4f127fbd7aa9cf58437030cd5f2f0d2450e62cc4d67d0e80489513cb12a","kind":"concept","schema_version":1,"statement":"[Proposition eq:bd_It of arXiv:2411.09482, 'Anomalous Regularization in Kazantsev-Kraichnan Model'] Take $s\in (0,d/2)$ and $\alpha\in (0,1)$. Then we have, as $|n|\to\infty$,
\begin{align}
    \mathcal{I}_{tra}(n) = c_{tra}|n|^{-2s+2-2\alpha}  +O(|n|^{-2s}),
\end{align}
where\footnote{The constant $c_{tra}$ comes exactly from [galeati2024anomalous], as one can check using $\Gamma(z+1)=z\Gamma(z)$; mind that, unlike in [galeati2024anomalous], here the integral $\mathcal{I}_{tra}(n)$ is not multiplied by $(2\pi)^{-d/2}$.}
\begin{align*}
    c_{tra}= -(d-1)(s+\alpha-1)(d+2-2s-2\alpha)C_{d,s,\alpha}
\end{align*}
and
\begin{align}
    C_{d,s,\alpha} = -\frac{\pi^{d/2}\Gamma(s+\alpha-1)\Gamma\left(\frac{d-2s+2}{2}\right)\Gamma(-\alpha)}{4\Gamma(s)\Gamma\left(\frac{d+2+2\alpha}{2}\right)\Gamma\left(\frac{d+4-2s-2\alpha}{2}\right)}>0.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.426689+00:00","domain":"probability theory","id":"claim_cd896aaeff84aaec92c25e28058d95be97aa74feba729fe6b3e953e3f388238d","kind":"concept","schema_version":1,"statement":"[Theorem thm:multCol of arXiv:2508.03577, 'Phase Transitions in a Particle Model\\ for the Self-Adaptive Response to Cancer Dynamics'] \begin{enumerate}
    \item(PAI off, $\lambda_m=0$)
    Let $(A_t)_{t\ge 0}$ be the evolution of the model according to Definition (def:mutlCol of the paper). Let $\tau$ be the first time a column is equal to $\1=(1,\ldots,1)$. Denote $b=\tfrac{pM}{qN}$ and assume that this remains constant. We then have that for $\varepsilon_M\to 0$ sufficiently slowly\footnote{here, $\varepsilon_M>\log^{-1/2}(M)$ is sufficient}
    \begin{equation}
        \lim_{\mycom{M\to\infty}{b={pM}/\left(qN\right)}}\mathbb{P}\rk{\abs{\tau-\frac{M\log(M)}{q}}\le \varepsilon_M M\log(M)\mid A_0\equiv 0}=1\, .
    \end{equation}
    Furthermore, as $M\to\infty $ and $b=\tfrac{pM}{qN}$ constant, we have that
    \begin{equation}
        \mathbb{E}_\pi\ek{\#\gk{\text{columns }c\text{ with }c\equiv 1}}\sim N\frac{\Gamma(b+1)}{ (M/q)^{b}}\, ,
    \end{equation}
    where $\pi$ is the stationary distribution (on the space of matrices). Furthermore, after time $\tau(1+\varepsilon)$, the number of columns equal to 1 agrees with the stationary distribution. This implies that the model has a cut-off phenomenon on the $\log$-scale.
    \item(PAI on) Introduce now the new parameter $\widetilde{q}=q+\lambda_m$. Denote $\widetilde{b}=\tfrac{{p}M}{\widetilde{q}N}$ and assume that it remains constant. We then have that under the same conditions on $\varepsilon_M$ as before
    \begin{equation}
         \lim_{\mycom{M\to\infty}{\widetilde{b}={pM}/\left(qN\right)}}\mathbb{P}\rk{\abs{\tau-\frac{M\log(M)}{\widetilde{q}}}\le \varepsilon_M M\log(M)\mid A_0\equiv 0}=1\, ,
    \end{equation}
    as well as
    \begin{equation}
        \mathbb{E}_\pi\ek{\#\gk{\text{columns }c\text{ with }c\equiv 1}}\sim N\frac{\Gamma\rk{\widetilde{b}+1}}{ (M/\widetilde{q})^{\widetilde{b}}}\, .
    \end{equation}
    Hence, PAI can be achieved by a change of parameters.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:43:45.393688+00:00","domain":"probability theory","id":"claim_cd8ae22044ec0adcc82118eaa95de1d7d9a2daff2d478152cca29c5a7bbc3b09","kind":"concept","schema_version":1,"statement":"[Proposition 31 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] Let $\Gamma_{\BD}$ be a non-nested CLE$_4$ in $\BD$. Let $\delta > 0$. Then for each $x, y, z \in {\BD}$ with $\lvert x - z\rvert \wedge \lvert y - z\rvert \ge \delta$, 
	\begin{equation}
		\BP\!\left\lbrack\SCB^{B_\varepsilon(z)}(\SCL(x); D_{\Gamma_{\BD}}^{\BD}) \cap \SCB^{B_\varepsilon(z)}(\SCL(y); D_{\Gamma_{\BD}}^{\BD}) = \emptyset\right\rbrack \le \varepsilon^{2 + o(1)} \quad \text{as } \varepsilon \to 0, 
	\end{equation}
	at a rate depending only on $\delta$, where $\SCB^{B_\varepsilon(z)}(\SCL; D_{\Gamma_{\BD}}^{\BD}) \defeq \SCB_{D_{\Gamma_{\BD}}^{\BD}(\SCL, B_\varepsilon(z))}(\SCL; D_{\Gamma_{\BD}}^{\BD})$. The same is true with two deterministic and disjoint connected arcs of $\partial\BD$ in place of $\SCL(x)$ and $\SCL(y)$. (In this case, the rate of~\eqref{eq:hitting-two-metric-balls} depends only on the deterministic arcs and is uniform over all $z \in \BD$.) (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

