	\begin{align*}
			&\lim_{\varepsilon\to0}\lim_{\sigma\to0}\PP\left(\dist\bigg( L^{i }_{\varepsilon,N}(\sigma),\mathcal M_0\times\mathcal M_0\bigg)\leq\delta\right)\\
