{"assumptions":[],"created_at":"2026-10-27T21:41:19.327698+00:00","domain":"probability theory","id":"claim_cdfe90f5ad2cf8011284e88ecbda83bb6dfd6cba69bd7fe897b2496ae545ccc8","kind":"definition","schema_version":1,"statement":"[Definition eq:sub-Laplacian of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\{X_1,\ldots,X_{m}\}$ be an orthonormal frame for $\mathcal{D}$. Define the \emph{horizontal gradient} of $f$, denoted by
$\nabla_{\mathcal{H}}f$, as the horizontal section
\begin{equation*}
\nabla_{\mathcal{H}}f:=\sum_{i=1}^{m}(X_if)X_i,
\end{equation*}
for any function $f:{\mathbb G}\longrightarrow {\mathbb R}$ for which the partial derivatives
$X_if$ exist. The second-order differential operator 
\begin{equation}
\Delta_{\mathcal{H}}:=-\sum_{i=1}^{m} X_i^2
\end{equation}
defined on $C^{\infty}(\mathbb{G})$ is called a \emph{sub-Laplacian}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:36:16.003708+00:00","domain":"probability theory","id":"claim_ce098fca1a3b7d6d46678ff5ac72a55da0c687c430bfa0de9ebebb711a8073ed","kind":"theorem","schema_version":1,"statement":"[Proposition second_moment_bounded_degree of arXiv:2606.27357, '\textbf{Typical distances in high-genus triangulations}'] Let $n, g \ge 1$ such that $n \ge 2g-1$ and let $\mathbf{p} = (p_1,\cdots,p_{\ell}) \in (\mathbb{N}^{*})^{\ell}$. Denoting by $e_1$ the root edge on $\partial_1 T_{n,g,\mathbf{p}}$ and by $\rho_1$ its starting point, we have 
\begin{align*}
\mathbb{E}[\deg_{T_{n,g,\mathbf{p}}}(\rho_1)^2] \le 4 + 5 \frac{\tau_{\mathbf{p}}(n+1,g)}{\tau_{\mathbf{p}}(n,g)}+ 16\frac{\tau_{\mathbf{p}}(n+2,g)}{\tau_{\mathbf{p}}(n,g)}.
\end{align*}

Moreover, for any $\theta \in [0,\frac{1}{2})$, there exists $C_{\theta} > 0$ such that  for any $\frac{g_n}{n} \to \theta \in [0,\frac{1}{2})$ and $\mathbf{p}^n = (p_1^n,\cdots,p_{\ell_n}^n) \in (\mathbb{N}^{*})^{\ell_n}$ such that $|\mathbf{p}^n| = o(n)$, for $n$ large enough
\begin{align*}
\forall x \in \partial T_{n,g_n,\mathbf{p}^n}, \qquad \mathbb{E}[(D_x^n)^2] \le C_{\theta}.
\end{align*}
Therefore by (equation bound of the paper), for $n$ large enough,
\begin{align*}
\mathbb{E}\big[|\partial^{*}B^{\bullet}(n)|^2\big]
\le \mathbb{E}\big[|B^{+}(n)|^2\big]
\le 4C_{\theta}|\mathbf{p}^{n}|^2.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:22:46.468642+00:00","domain":"probability theory","id":"claim_ce0c940cfe337ed561b9874947de078748fbaefe55535f6ef89cbb9d06501aa3","kind":"definition","schema_version":1,"statement":"[Definition 67 (Level sets of $\newuL \upmu$ and the $\newuL \upmu$-adapted tori) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Given a non-negative number $\ubar' \le 0$, we define:
