{"assumptions":[],"created_at":"2026-10-27T22:46:36.164696+00:00","domain":"probability theory","id":"claim_ced1eaa73f1a030f39f115b0bcd4d2da5257cf8dce8ca03519d0e8db296cc7a1","kind":"definition","schema_version":1,"statement":"[Definition Def_OneFormAndSelfDualTwoFormDirichletResidueCondition of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] {BeraWalpuski2025}}]

