    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:57:28.240312+00:00","domain":"probability theory","id":"claim_cf07902b530d4b032c4fca653f6f4b32384e36d069880cdf9ddc3d2f49d24122","kind":"concept","schema_version":1,"statement":"[Proposition 59 of arXiv:2607.18104, '2607.18104'] Let $C>0$, $\theta \in \R$, $N\in \N$ and $\mathfrak{a}\in (0,1)$. Let $\rho \in [\mathfrak{a},1-\mathfrak{a}]$ and consider ASEPs $(\eta_t)_{t \geq 0}$ and $(\bar{\eta}^{\per}_t)_{t \geq 0}$ evolving according to the extended $(\rho,\theta,1,N)$-reference frame basic coupling. Consider (random) data $\eta^{N} \in \{0,1\}^{N}$ with 
\begin{equation}
 \textup{Ber}_{\rho+CN^{-1/2}}^{N} \succeq \P( \eta^{N} \in \, \cdot \, ) \succeq  \textup{Ber}_{\rho-CN^{-1/2}}^{N} ,  
\end{equation} where $\textup{Ber}_{\rho}^{N}$ denotes the Bernoulli-$\rho$-product measure on $\{0,1\}^{N}$. Define initial data $\eta_0\in \{0,1\}^{\mathbb{Z}}$
\begin{equation}
\eta_0(x):=\eta^N(x- \lfloor \theta N \rfloor )
\end{equation} for all $x \in \lbr \theta N+1, (1+\theta)N \rbr$. For all
$x \notin \lbr \theta N+1, (1+\theta)N\rbr$, let $\eta_0(x)$ be occupied independently with probability $\rho$. For initial data $\tilde{\eta}_0$, assume that \eqref{eq:AgreeLocally} holds, but extend the configuration outside of $\lbr \theta N+1, (1+\theta)N \rbr$ periodically. Then there exist some $\tilde{c},\tilde{C}>0$, depending only on $\mathfrak{a}$, $q$ and $C$, and not $\theta,N,\rho$, such that the extended colored ASEP  $(\xi_t)_{t \geq 0}$ from Definition~\ref{def:ExtendedCouplingASEP} and  
\begin{equation*}
    \mathcal{A}^{\theta}_{\delta,N} := \left\{ \xi_t(x) \in \{\zero,\one \}  \, \forall (x,t) \in \mathcal{I}^{\rho}_{\delta,N}\Big(\frac{1}{8}+\theta,\frac{7}{8}+\theta\Big)  \right\}
\end{equation*} satisfy for all $\delta>0$ 
\begin{equation}
\liminf_{N \rightarrow \infty}\Pex\big( \mathcal{A}^{\theta}_{\delta,N} \big)   \geq 1- \tilde{C} \exp(-\tilde{c} \delta^{-1} ) . 
\end{equation} 
Furthermore,  \eqref{eq:GoodControlASEP} continues to hold when $(\xi_t)_{t\geq 0}$ is defined the as a full-space extended colored ASEP with reference frame $\mathcal{I}^{\rho}_{N}\big(\theta,1+\theta\big)$ for two full-space ASEPs, i.e., we obtain $(\xi_t)_{t\geq 0}$ as in Definition~\ref{def:ExtendedCouplingASEP} with respect to two ASEPs on the integers, which evolve under the (extended) basic coupling along edges in $\mathcal{I}^{\rho}_{N}\big(\theta,1+\theta\big)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:28:53.622129+00:00","domain":"probability theory","id":"claim_cf0b17f8a26e2da99e3092ca0ab957528daaba334c024a0b0b70819006636635","kind":"concept","schema_version":1,"statement":"[Proposition 18 (Laplace asymptotics in the bulk regime) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] Fix $1<p<\infty$, an integer $r\ge 1$, and complex parameters
\begin{equation}
\lambda_1,\dots,\lambda_r\in\mathbb C,
\qquad
\Re \lambda_j>\max\{-1,1-p\},\quad j=1,\dots,r.
\end{equation}
Put $\Lambda:=\lambda_1+\cdots+\lambda_r$.
For every integer $n\geq 2$ let  $j(n)\in \{0,\ldots, n-1\}$ and suppose that
\[
\alpha(n) := \frac{j(n)}{n}\to \alpha\in(0,1).
\]
For $\beta\in(0,1)$, let $\Psi_{p,\beta}: (0,\infty)\to\R$ and its unique global maximizer $\theta_{p,\beta}$  be defined as in Proposition~\ref{prop:maximizer_Phi_p_beta}. Then $\theta_{p,\alpha(n)}\to \theta_{p,\alpha}$ as $n\to\infty$, and the following assertions hold:

\vspace{2mm}
\noindent
(i) Absolute asymptotic: As $n\to\infty$, one has
\[
\begin{aligned}
I_{n,j(n)}&(\lambda_1,\dots,\lambda_r)
\sim
\frac{p(p-1)^{n-j(n)-1}\,n\binom{n-1}{j(n)}}{2\pi^{(n-j(n))/2}\,
\Gamma\!\left(\frac{j(n)+\Lambda+p}{p}\right)}
\,
\sqrt{\frac{2\pi}{n\,|\Psi_{p,\alpha(n)}''(\theta_{p,\alpha(n)})|}}
\,
\frac{\mathcal{K}_p(\theta_{p,\alpha(n)})}
{\theta_{p,\alpha(n)}\,\mathcal{J}_p(\theta_{p,\alpha(n)})}
\\
&\times
\,e^{\,n\Psi_{p,\alpha(n)}(\theta_{p,\alpha(n)})}
\prod_{j=1}^r
\left(
\alpha(n)\frac{\mathcal F_p(\theta_{p,\alpha(n)};\lambda_j)}{\mathcal F_p(\theta_{p,\alpha(n)};0)}
+
(1-\alpha(n)) \frac{\mathcal F_p(\theta_{p,\alpha(n)};\lambda_j+p-2)}{\mathcal F_p(\theta_{p,\alpha(n)};p-2)}
\right).
\end{aligned}
\]
In particular, for $\lambda_1= \ldots = \lambda_r = 0$ this formula takes the form
\begin{equation}
I_{n,j(n)}(0,\dots,0)
\sim
\frac{p(p-1)^{n-j(n)-1}\,n\binom{n-1}{j(n)}}{2\pi^{(n-j(n))/2}\,
\Gamma\!\left(\frac{j(n)+p}{p}\right)}
\,
\frac{\mathcal K_p(\theta_{p,\alpha(n)})}{\theta_{p,\alpha(n)}\,\mathcal J_p(\theta_{p,\alpha(n)})}
\,
e^{\,n\Psi_{p,\alpha(n)}(\theta_{p,\alpha(n)})}
\sqrt{\frac{2\pi}{n\,|\Psi_{p,\alpha(n)}''(\theta_{p,\alpha(n)})|}}.
\end{equation}

\vspace{2mm}
\noindent
(ii) Relative asymptotic: As $n\to\infty$, one has
\[
\frac{I_{n,j(n)}(\lambda_1,\dots,\lambda_r)}{I_{n,j(n)}(0,\ldots, 0)}
\sim
\left(\frac{p}{\alpha \, n}\right)^{\Lambda/p}
\prod_{j=1}^r
\left(
\alpha\frac{\mathcal F_p(\theta_{p,\alpha};\lambda_j)}{\mathcal F_p(\theta_{p,\alpha};0)}
+
(1-\alpha)\frac{\mathcal F_p(\theta_{p,\alpha};\lambda_j+p-2)}{\mathcal F_p(\theta_{p,\alpha};p-2)}
\right).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:56:00.655309+00:00","domain":"probability theory","id":"claim_cf0bb69504cf8ad1b513890e33c589963639ff0c2247be61dd02b6cafe14bd20","kind":"concept","schema_version":1,"statement":"[Proposition prop_exit_exp of arXiv:2603.29442, 'A compact support property for infinite-dimensional SDEs with Hölder continuous coefficien'] There are constants $C_1 \geq 1$ and $c_2> 0$ such that for sufficiently small $\zeta$, for all $\delta \in (0,1]$ and $\mathbb{P} \in \mathscr{M}_{\gamma,\delta}((0,2\zeta))$,
