{"assumptions":[],"created_at":"2026-10-27T11:15:34.488694+00:00","domain":"probability theory","id":"claim_cf4c7f02c2b10f2590f403231386b97000b90bf8171fc12b10fe45c9eb0479aa","kind":"concept","schema_version":1,"statement":"[Proposition 11 (Ricci and scalar curvature) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] For the metric \eqref{eq:ansatz-metric}, with $X, Y \in \mathcal{H}$ basic horizontal (block decomposition $X = \sum_i X_i$), $\xi^* = \xi/H$ the unit Reeb field, $\nu = \partial_s$, 

	\emph{(i) Vertical components.}
	\begin{align}

		\operatorname{Ric}(\nu, \nu) &\;=\; -\frac{H''}{H} \;-\; \sum_{i=1}^r n_i \left( \frac{q_i H' + \kappa_i'}{F_i^2} \;-\; \frac{(q_i H + \kappa_i)^2}{2 F_i^4} \right),\\

		\operatorname{Ric}(\xi^*, \xi^*) &\;=\; -\frac{H''}{H} \;+\; \sum_{i=1}^r n_i \left( \frac{q_i^2 H^2}{2 F_i^4} \;-\; \frac{H'}{H}\, \frac{q_i H + \kappa_i}{F_i^2} \right).
	\end{align}

	\emph{(ii) Mixed components vanish:} $\operatorname{Ric}(\nu, \xi^*) = 0$ and $\operatorname{Ric}(X, \nu) = \operatorname{Ric}(X, \xi^*) = 0$.

	\emph{(iii) Horizontal components.} $\operatorname{Ric}(X, Y) = \sum_{i=1}^r \mathcal{R}_i\; \pi^*g_i(X_i, Y_i)$, where
	\begin{equation}
		\mathcal{R}_i \;=\; p_i \;-\; \frac{q_i H' + \kappa_i'}{2} \;-\; \frac{H'}{2H}\,(q_i H + \kappa_i) \;+\; \frac{\kappa_i\,(2 q_i H + \kappa_i)}{2 F_i^2} \;-\; \frac{q_i H + \kappa_i}{2} \sum_{j=1}^r \frac{n_j\,(q_j H + \kappa_j)}{F_j^2} \,.
	\end{equation}

	\emph{(iv) Scalar curvature.}
		\begin{equation}
		\begin{aligned}
			&\mathrm{R}_g \;=\; -\frac{2H''}{H} \;+\; \sum_{i=1}^r n_i \left( \frac{2 p_i}{F_i^2} \;-\; \frac{q_i^2 H^2}{2 F_i^4} \;-\; \frac{2\,(q_i H' + \kappa_i')}{F_i^2} \;-\; \frac{2H'}{H}\, \frac{q_i H + \kappa_i}{F_i^2} \;+\; \frac{3\,(q_i H + \kappa_i)^2}{2 F_i^4} \right) \\
			&\qquad \;-\; \left( \sum_{i=1}^r \frac{n_i\,(q_i H + \kappa_i)}{F_i^2} \right)^{2} .
		\end{aligned}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:44:17.190833+00:00","domain":"probability theory","id":"claim_cf4cf6a909c2139a560a54ac85b3d2c99650ec13d92655cffe26cd14022214aa","kind":"definition","schema_version":1,"statement":"[Definition 25 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] The $H$-algebra $A$ (of class $\mathcal{C}^{\infty}$) on $\mathbb{R}^{d}_{y}$ is said to be stochastic $\Phi$-proper (resp. stochastic $\Phi$-pseudoproper) if the following two conditions are satisfied: 
