\begin{equation}
    |\det M - \det L|\leq k^{k/2}\left(\max_{1\leq i\leq k} (\|M_i\|_\infty, \|L_i\|_\infty) \right)^{k-1}\max_{1\leq i\leq k} \|M_i-L_i\|_\infty
\end{equation}

    hold true.","status":"unverified"}

