{"assumptions":[],"created_at":"2026-10-26T19:46:12.276487+00:00","domain":"probability theory","id":"claim_cf813ce959a11306b86e7cdf4923e67a9c510158d89d747631f0f90147d68925","kind":"theorem","schema_version":1,"statement":"[Theorem 36 (Adapted Brenier distance) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $\bX=\bX^{a,L}$ and $\bY=\bX^{b,M}$ be elements of $\cFG$.
The minimal transport cost over all Gaussian adapted Brenier couplings is given by
\begin{equation}
\inf_{\pi \in \mathrm{Cpl}_{\mathrm{AB}}(\bX, \bY)} \E_{\pi}\big[\|X-Y\|_2^2\big]
= \mathcal{D}_{\mathrm{AB}}^2(L,M)
\end{equation}
where 
$$
\mathcal{D}_{\mathrm{AB}}^2(L,M):=\|a-b\|_2^2+\|L\|_F^2+\|M\|_F^2
-2\sum_{t=1}^N \Gamma_t(L,M),
$$
and $\Gamma_t(L,M)$ represents the maximum alignment value for the $t$-th step:
\begin{equation}
\Gamma_t(L,M)
:=
\max_{P_t\in\mathscr{P}(L_{t,t}^{\intercal} M_{t,t})}\ \tr\big((L^{\intercal} M)_{t,t}P_t\big).
\end{equation}
Explicitly, let $L_{t,t}^{\intercal} M_{t,t}$ have the singular value decomposition $U_t\Sigma_tV_t^{\intercal}$, where we partition the singular vectors $U_t=[U_{t,1}\ U_{t,0}]$ and $V_t=[V_{t,1}\ V_{t,0}]$ such that $U_{t,1}, V_{t,1}$ correspond to the non-zero singular values and $U_{t,0}, V_{t,0}$ correspond to the zero singular values. Then
\begin{equation}
\Gamma_t(L,M)
=
\tr\Big(U_{t,1}^{\intercal} (L^{\intercal} M)_{t,t} V_{t,1}\Big)
\;+\;
\Big\|\,U_{t,0}^{\intercal} (L^{\intercal} M)_{t,t} V_{t,0}\,\Big\|_*.
\end{equation}
Furthermore, the infimum in \eqref{eqn:AB.opt.cost} is attained by a Gaussian coupling $\pi^{Q}$ where $Q\in \mathscr{O}(N,d)$. In other words, $\dist_\mathrm{AB}$ is an objective function of a corresponding Procrustes problem: 
$$
\mathcal{D}_{\mathrm{AB}}(L,M)=\min_{Q\in\mathscr{O}(N,d), Q_t\in\mathscr{P}(L_{t,t}^\intercal M_{t,t})}\|L-MQ\|_\mathrm{F}
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:56:36.581010+00:00","domain":"probability theory","id":"claim_cf8142fe36a3e790ea60d41f9531b1f2bbab2898a517a0bc7ebc31446defa1fb","kind":"lemma","schema_version":1,"statement":"[Lemma Pdefmj of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Let $j\ge 0$ and 
\begin{equation}

M_j(u)=(K+j+\nu_b+2)(-1)^{j}w_{\gamma-1,\nu_b+1}(K-1+j)\mathcal T(bu^{K+j}),
\end{equation}
then we have the following convergent series representation for $|u|<1$:
\begin{equation}

M_j(u)=\sum_{m=j+1}^{+\infty}(-1)^{m}w_{\gamma-1,\nu_b+1}(K-1+m)u^{K-1+m}.
\end{equation}
Moreover, let $1\le j\le {5}$, then there exist universal constants {$0<c_{\nu,1}<c_{\nu,2}$} such that:\\ \noindent\underline{behavior for small u}:  for $0\le u\le  b$,
\begin{equation}

{c_{\nu,1}}\le \frac{M_j(u)}{\Gamma(\alpha_\gamma)\Gamma(1-\alpha_\gamma)K^{\nu_b+j+4-\alpha_\gamma}u^{K+j}}\le {c_{\nu,2}}\end{equation}
\noindent\underline{behavior for large u}: for $b\le u< \frac 12$:
\begin{equation}

{c_{\nu,1}}\le \frac{M_j(u)}{\Gamma(\alpha_\gamma)\Gamma(1-\alpha_\gamma)K^{\nu_b+3}\left(\frac{u}{1-u}\right)^{K-1}u^{\alpha_\gamma}}\leq {c_{\nu,2}}.
\end{equation}
\noindent\underline{control of the iterate}:  let $1\le j\le 5$, then
\begin{equation}

\left\|\frac{\mathcal T (u^jM_0)}{M_0}\right\|_{L^\infty(u\leq \frac 12)}\le \frac{c_\nu}{b}.
\end{equation}

\noindent\underline{control of the derivative}: 
\begin{equation}

\forall 0\le u\le \frac 12, \ \ \frac{|uM_0'|}{M_0}\leq \frac{c_\nu}b. 
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:45:05.547052+00:00","domain":"probability theory","id":"claim_cf8275f4b2731b04d26fa56a323c3a7e968c9d52965c460d802997b6c371612f","kind":"lemma","schema_version":1,"statement":"[Lemma 2 of arXiv:2608.05514, 'It\^{o}'s formula for L\'evy-It\^{o} processes taking values in the dual of nuclear space'] Let $M$ be a cylindrical martingale-valued measure on $\R_{+} \times \mathcal{R}$. There exists two  cylindrical martingale-valued measures $M^{c}$ and $M^{d}$ on $\R_{+} \times \mathcal{R}$ with the following properties:
\begin{enumerate}
\item $M(t,A)=M^{c}(t,A)+M^{d}(t,A)$ $\forall t\geq 0$, $A \in \mathcal{R}$.  
\item For every $A \in \mathcal{R}$ and $\phi \in \Phi$, $(M^{c}(t,A)(\phi): t \geq 0)$ has continuous paths and $(M^{d}(t,A)(\phi): t \geq 0)$ has purely discontinuous paths. 
\item For every $A \in \mathcal{R}$ and $\phi \in \Phi$, the square integrable martingales $(M^{c}(t,A)(\phi): t \geq 0)$ and $(M^{d}(t,A)(\phi): t \geq 0)$ are orthogonal.   
\end{enumerate}","status":"unverified"}

