{"assumptions":[],"created_at":"2026-10-26T20:58:53.182693+00:00","domain":"probability theory","id":"claim_d21c1a588a1ddd7baa23a0ce3259a1e016adc6f3bface18b6d200bc40c48923d","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2606.30080, 'Ergodicity of reflected stochastic reaction-diffusion equations driven by space-time white'] A pair $(u, L)$ is said to be a solution of equation \eqref{1.1} if
\begin{itemize}
  \item [(i)] $u$ is a continuous process on $[0,\infty)\times[0,1]$. For any $t\geq 0$ and $x\in [0,1]$, $u(t,x)$ is $\mathcal{F}_t$-measurable, $u(t,x)\geq 0$ and $u(t,0) = u(t,1) = 0$, $\mathbb{P}$-a.s.  
  \item [(ii)] $L$ is a random measure on $[0,\infty)\times (0,1)$ such that
  \begin{itemize}
    \item [(a)] $L(\{t\}\times(0,1))=0$ for any $t\geq 0$.
    \item [(b)] $\int_0^t\int_0^1 x(1-x)L(ds,dx) <\infty$ for any $t\geq 0$.
    \item [(c)] $L$ is $\mathcal{F}_t$ adapted in the sense that for any measurable mapping $\psi$, 
        \[
        \int_0^t\int_0^1 \psi(s,x) L(ds,dx) \text{ is } \mathcal{F}_t \text{-measurable.}
        \]
  \end{itemize}
  \item [(iii)] $(u,L)$ solves \eqref{1.1} in the following sense: for any $t\geq 0$, $\phi\in C^2([0,1])$ with $\phi(0) = \phi(1) = 0$, 

      \begin{align*}
& (u(t),\phi)-\int_0^t(u(s),\phi'')ds+\int_0^t(b(u(s)),\phi)ds\\
=&(u_0, \phi)+\int_0^t\int_{0}^1\sigma(u(s,x))\phi(x)W(ds,dx)+\int_0^t\int_{0}^1\phi(x)L(ds,dx), \quad \mathbb{P}\text{-a.s.},
\end{align*} 
where $(\cdot,\cdot)$ denotes the scalar product in $L^2([0,1])$, and $u(t):=u(t, \cdot)$.
  \item [(iv)] The support of $L$ is contained in the set $\{(t,x)\in [0,\infty)\times(0,1): u(t,x)=0\}$, that is
  \[
  \int_0^{\infty}\int_{0}^{1} u(t,x) L(dt,dx) = 0,\quad \mathbb{P}\text{-a.s.}
  \]
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:53.157407+00:00","domain":"probability theory","id":"claim_d21e29e258310f327d70b49bad5da682bf8adcc5bfee837ab431651c6b154771","kind":"theorem","schema_version":1,"statement":"[Proposition 15 of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] In the rectangular specialization,
\begin{equation}
