and
\begin{equation}
    \Prob{T_{k,n}^x \ge \tau, \abs{\mathfs{C}_x\left( T_k^x \right)} \ge v} \le \Prob{v^\alpha \Tilde{T}_{k,n}^x \ge \tau}
