{"assumptions":[],"created_at":"2026-10-27T18:40:26.993208+00:00","domain":"probability theory","id":"claim_d3547ab1015c20ad85c1395bad9f7edea54742529b1cf46cdc068b373271ed4a","kind":"concept","schema_version":1,"statement":"[Cor cor-LDP of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Fix $R\in\mathbb{N}$ and $W=W_R=[-R,R]^d$ and a function $F\colon{\mathcal M }_1({\mathcal L }_W\times{\mathcal S }_W)\to\mathbb{R}$ and a measurable set $B\subset{\mathcal M }_1({\mathcal L }_W\times{\mathcal S }_W)$.

\begin{enumerate}
\item If $F$ is lower semi-continuous and bounded from below and $B$ closed and $B'\subset {\mathcal M }_1({\mathcal T }_W)$ compact, then
$$
\begin{aligned}
\limsup_{N\to\infty}\frac 1{|\Lambda_N|}\log {\tt Q}^{\ssup{\Lambda_N,{ \rm bc }}}&\Big[{\operatorname e }^{-|\Lambda_N| F(\Xi_{N,R})}\1\{\Xi_{N,R}\in B\}\{\partial\Xi_{N,R}^{{{\scriptscriptstyle{({\mathcal S }})}}}\in B'\}\Big]\\
&\leq -\inf_{\xi\in B\cap\bigcap_{k\in \mathbb{N}}{\mathcal M }_1^{{{\scriptscriptstyle{({k}})}}}({\mathcal L }_W\times  {\mathcal S }_W)\colon \partial\Pi_W^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)\in B'}\big(F(\xi)+J_{W}(\xi)\big).
\end{aligned}
$$
\item Fix all the parameters $M,L,K,\mathfrak r,T,\vartheta,S\in(0,\infty]$ and put $\Theta=(M,L,K,\mathfrak r,T,\vartheta, S)$. Then, for any $W$-admissible $\psi\in{\mathcal M }_1({\mathcal T }_W)$ and for any sequence $\psi_N\to\psi$ such that ${\tt Q}^{\ssup{\Lambda_N,{ \rm bc }}}_{W;\Theta}(\partial\Pi_W^{{{\scriptscriptstyle{({\mathcal S }})}}}(\Xi_{N,R})=\psi_N)>0$ for any $N$, if $F$ is upper semi-continuous and $B$ is subset of and open in $A_{W;\Theta}$,
$$
\begin{aligned}
\liminf_{N\to\infty}\frac 1{|\Lambda_N|}&\log {\tt Q}^{\ssup{\Lambda_N,{ \rm bc }}}_{W;\Theta}\Big[{\operatorname e }^{-|\Lambda_N| F(\Xi_{N,R})}\1\{\Xi_{N,R}\in B\}\,\Big|\,\partial\Pi_W^{{{\scriptscriptstyle{({\mathcal S }})}}}(\Xi_{N,R})=\psi_N\Big]\\
&\geq -\inf_{\xi\in B\colon \partial\Pi_W^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)=\psi}\big(F(\xi)+J_{W;\Theta}(\xi)\big),
\end{aligned}
$$
where  
\begin{equation}
J_{W;\Theta}(\xi)=\frac 1{|W|} H_{{\mathcal L }_W\times{\mathcal S }_W}\big(\xi\,\big|\,\Pi_W^{{{\scriptscriptstyle{({\mathcal L }})}}}({\tt Q}_{M})_{L,K}\otimes [\partial \Pi_W^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)\otimes {\tt K}^{{{\scriptscriptstyle{({M,\mathfrak r, T,\vartheta,S}})}}}_{W}]\big)
,\qquad \xi\in{\mathcal M }_1({\mathcal L }_W\times {\mathcal S }_W),
\end{equation}
where $\Pi_W^{{{\scriptscriptstyle{({\mathcal L }})}}}({\tt Q}_{M})_{L,K}$ is the conditional version of $\Pi_W^{{{\scriptscriptstyle{({\mathcal L }})}}}({\tt Q}_M)$ given $A_{W; M,L,K}^{{{\scriptscriptstyle{({\mathcal L }})}}}$, and  ${\tt K}^{{{\scriptscriptstyle{({M,\mathfrak r, T,\vartheta,S}})}}}_{W}(\mu,\cdot)$ is the conditional version of ${\tt K}_{W}(\mu,\cdot)$ given $A_{W;M,\mathfrak r, T}^{{{\scriptscriptstyle{({\mathcal S }})}}}\cap{\mathcal S }_W^{{{\scriptscriptstyle{({M,\vartheta,S}})}}}$. (In particular, $J_{W;\Theta}(\xi)=\infty$ if $\xi(A_{W;\Theta})<1$.)
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:09:43.676433+00:00","domain":"probability theory","id":"claim_d3556e7f06ca7d014de3ac38be1dc12b992e90bffda7d9261c60e9567e5d19ab","kind":"lemma","schema_version":1,"statement":"[Lemma order-S^N of arXiv:2605.28194, 'Delayed Blow-up in 3D Fluids via Pseudo-Transport Noise'] Fix $a\in [-1,0)$. For every $\delta\in (0,1)$, there exists a constant $C_\delta$ depending only on $\delta$ and $a$, such that
