        \displaystyle a + \frac{1}{ad_0 + \sqrt{a^2d_0^2 + 2d_0}}, & a \ge a_0.
    \end{cases}

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.162143+00:00","domain":"probability theory","id":"claim_d369aaeb36086b8feb3ac07dba40f76738e3b2bd10bb52d69560447a2799c8fb","kind":"definition","schema_version":1,"statement":"[Definition Def_LinearUniformlyFredholm of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let
  $E$ and $F$ be tame Fréchet space bundles over a tame Fréchet manifold $B$.
  A map of tame Fréchet space bundles $L \mskip0.5mu\colon\thinspace E \to F$ is \defined{uniformly Fredholm}
  if
  for every $b \in B$
  there exist an open neighbourhood $b \in \mathscr{U} \subseteq B$,
  finite-rank vector bundles $\mathrm{Def}$ and $\mathrm{Ob}$ over $\mathscr{U}$,
  and maps of tame Fréchet space bundles $\pi \mskip0.5mu\colon\thinspace E|_\mathscr{U} \twoheadrightarrow \mathrm{Def}$ and $\iota \mskip0.5mu\colon\thinspace \mathrm{Ob} \hookrightarrow F|_\mathscr{U}$ such that the \defined{thickening}
  \begin{equation*}
    \begin{pmatrix}
      L & \iota \\
      \pi & 0
    \end{pmatrix}
    \mskip0.5mu\colon\thinspace E|_\mathscr{U} \oplus \mathrm{Ob} \to F|_\mathscr{U} \oplus \mathrm{Def}
  \end{equation*}
  is an isomorphism of tame Fréchet space bundles.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:13:22.505672+00:00","domain":"probability theory","id":"claim_d36bec1c342e39d59dd454f4ad115918fdfdbb5715797aaf2153c8adb76beb8b","kind":"lemma","schema_version":1,"statement":"[Lemma l.1point-minimizer of arXiv:2505.15283, 'Quantization of Probability Distributions via Divide-and-Conquer: Convergence and Error Pr'] Let $\mu \in {\mathcal{M}}_1$ then for any $x\in {\mathbb{R}}$ we have
\begin{equation}
    W_1(\mu,\delta_x) = \int_{\mathbb{R}} |t-x| \mathrm{d} \mu(t).
\end{equation}
Moreover, if $f$ is a split function and letting 
\begin{equation}
    \bar{\mu}_{+} = {\mathbb{E}}_\mu[X | X > f(\mu)], \quad
    \bar{\mu}_{-} = {\mathbb{E}}_\mu[X | X \leq f(\mu)],
\end{equation} 
then
\begin{equation}
    \begin{split}        
    W_1( \mu,\delta_{\mathrm{med}(\mu)})  
    & = \frac{1}{2} 
    \left(
        \bar{\mu}_+-\bar{\mu}_-
    \right)\\
    W_1( \mu,\delta_{\bar{\mu}})
    &= 2 \mu(\Omega_-) \left(\bar{\mu} - \bar{\mu}_-\right)  
    = 2 \mu(\Omega_+) \left(\bar{\mu}_+ - \bar{\mu}\right).
    \end{split}    
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.358524+00:00","domain":"probability theory","id":"claim_d36c52b372621d39633c27ae057f051f60b6c26068edbbc729fe8084115f55b2","kind":"definition","schema_version":1,"statement":"[Definition 10 (Piecewise Kingman's coalescent) of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] For real numbers $x_1 > x_2 > \cdots > x_k >0$, the piecewise Kingman's coalescent $\big(Z^{(k)}_s=Z^{(k)}_s(x_1,\ldots, x_k):s > 0\big)$ with rate $\frac{4}{\ell(s)}$ is defined as:
\begin{itemize}
\item For \(s > x_1\), we set \(Z^{(k)}_s = 0\).
\item Recursively, for each \(i = 1,\ldots,k\), conditionally on \(\big(Z^{(k)}_s : s > x_i\big)\), the process \(Z^{(k)}_s\) on the interval \(s \in (x_{i+1}, x_i]\) (with $x_{k+1}:=0$) evolves as a Kingman's coalescent started with \(\lim_{s \downarrow x_i} Z^{(k)}_s + 1\) lineages, where each pair of lineages coalesces at rate \(\frac{4}{\ell(s)}\).
Here the height parameter \(s\) is interpreted as backward time, so the coalescent runs as \(s\) decreases.
\end{itemize}","status":"unverified"}

