			\mathcal{A}f(x) = h(x-z) + \frac{\gamma}{p} \int^{xp}_{u} W^{(q)}(x - yp^{-1}) f(y) \dd y,  
		\end{equation}
		for a chosen $h \in  C_{[0,a]}$, and for which we shall denote $\mathcal{A}^0f(x) = f(x)$ and  $\mathcal{A}^{n+1}f(x) = \mathcal{A}[\mathcal{A}^{n}f(x)]$ for $n \geq 0$.  Then, the unique fixed point of $\mathcal{A}$ is $\mathcal{G}^{(q,p)}_\gamma h(x;u,z)$.","status":"unverified"}

