{"assumptions":[],"created_at":"2026-10-26T19:16:49.558369+00:00","domain":"probability theory","id":"claim_d4ca32d3e1307cbbb8160e8cf3fcb1b475a6065c42b3a476ea97239938a6fded","kind":"definition","schema_version":1,"statement":"[Defs 23 (Monotone limit form) of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] Suppose~\ref{ass:CE} and~\ref{ass:ConditionalClos}. Define

\begin{align*} 
\dom{\vvE^{\U, \QP}}&:=\{u \in \cap_{r>0} \dom{\E^{\U, \QP}_r}: \lim_{r \to \infty}\E^{\U, \QP}_r(u) <+\infty\} \comma
\\
\vvE^{\U, \QP}(u)&:=\lim_{r \to \infty}\E^{\U, \QP}_r(u) \cquad 
\vvE^{\U, \QP}(u,v):=\frac{1}{4}\Bigl(\vvE^{\U, \QP}(u+v)- \vvE^{\U, \QP}(u-v)\Bigr) \notag \fstop
\end{align*} 
The form $(\vvE^{\U, \QP}, \dom{\vvE^{\U, \QP}})$ is a strongly local conservative $\QP$-symmetric Dirichlet form on~$L^2(\U, \QP)$.

The square field~$\cdc^\U$ is defined as the monotone limit of~$\cdc^\U_r$ as well:
\begin{align} 
\cdc^\U(u):=\lim_{r \to \infty}\cdc^\U_r(u) \cquad \cdc^\U(u, v):= \frac{1}{4}\Bigl( \cdc^\U(u+v)- \cdc^\U(u-v)\Bigr)\cquad u, v \in \dom{\vvE^{\U, \QP}}\fstop 
\end{align}
Furthermore,  $(\vvE^{\U, \QP}, \dom{\vvE^{\U, \QP}})$ satisfies the Rademacher-type property:
\begin{align}
\Lip(\U, {\mssd}_\U, \QP) \subset \dom{\vvE^{\U, \QP}}\comma \quad \cdc^\U(u) \le \Lip_{{\mssd}_\U}(u)^2 \qquad  u \in \Lip(\U, {\mssd}_\U, \QP) \fstop
\end{align}","status":"unverified"}

