{"assumptions":[],"created_at":"2026-10-27T23:01:54.385969+00:00","domain":"probability theory","id":"claim_d4ead1d68abc39cb01f002b5b2fa7b462aa73e4c5cc5a132a07f91ee21ed2e12","kind":"lemma","schema_version":1,"statement":"[Lemma lem_hops of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] Let~$\gamma = (x_0,\ldots, x_n)$ be a path in~$\mathcal G^t$. Assume that~$x_0$ and~$x_n$ belong to~$\mathcal H$ (the infinite cluster of~$\mathcal G$), and~$x_1,\ldots,x_{n-1}$ do not belong to~$\mathcal H$ (so that each of them is either in~$t\Z^d$ or in some finite cluster of~$\mathcal G$). Let
	\[b:= \max\left\{\|y-x\|_\infty:\; \begin{array}{l} x, y \in V,\; x \text{ and } y \text{ are in the same finite} \\ \text{cluster of }\mathcal G, \text{ and this cluster is visited by } \gamma \end{array}\right\},\]
		that is,~$b$ is the maximum~$\ell_\infty$-diameter of all finite clusters of~$\mathcal G$ intersected by~$\gamma$. Then,
	\begin{equation*}
		\sum_{e \in \gamma} \tau^t_e \ge \frac{\K t}{2t+b}\cdot \|x_n -x_0\|_\infty.
	\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:49:17.491333+00:00","domain":"probability theory","id":"claim_d4f1f4156e4d315843ac53fbad695c42ba4ef42e8b4cc8a24f0eebd4fe03e324","kind":"theorem","schema_version":1,"statement":"[Proposition 15 (Algebraic argument I, Step 1) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $[\beta]\geq0$ and assume that for all populated $ \beta' \prec \beta$ 
\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \left|
\pi^{(\n)}_{xy\, \beta'}
\right|^{ p} \lesssim \ve^{|\beta'|-\langle\beta'\rangle} |x-y|^{\langle \beta' \rangle - |\n|}\,.
\end{aligned}
\end{equation}
Then for all \(\gamma\) populated and not purely polynomial, we have
\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \left|
(\Gamma_{xy})_{ \beta}^{\gamma}
\right|^{ p} \lesssim \ve^{|\beta|-\langle\beta\rangle-|\gamma|+\langle\gamma\rangle} |x-y|^{\langle\beta \rangle - \langle\gamma\rangle}\,,
\end{aligned}
\end{equation}
with the implicit understanding that the exponents on the right-hand side in
\eqref{est_Gamma} are non-negative, unless the left-hand side is zero.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.576276+00:00","domain":"probability theory","id":"claim_d4f3f29795b0b009716154c708e3a5a1ae55a729f483d4a47eb50c0d799dd7ea","kind":"concept","schema_version":1,"statement":"[Theorem T:PDE of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] For $\alpha\in (0,\infty)$, $\beta\in (0,2]$, and $\gamma\ge 0$, the solution
  to
  \begin{align*} 
    \begin{cases}
      \left(\partial_t^\beta + \dfrac{\nu}{2} (-\Delta)^{\alpha/2}\right) u(t,x) = I_t^\gamma\left[f(t,x)\right], & \qquad t>0,\: x\in\mathbb{R}^d,                         \\[1em]
      \left.\dfrac{\partial^k}{\partial t^k} u(t,x)\right|_{t = 0} = u_k(x),                                      & \qquad 0\le k\le \left\lceil \beta \right\rceil-1, \:\: x\in\mathbb{R}^d,
    \end{cases}
  \end{align*}
  with $f$ and $u_k$ being smooth functions with compact support (i.e., $f\in
    C_c^\infty(\mathbb{R}_+\times\mathbb{R}^d)$ and $u_k\in C_c^\infty(\mathbb{R}^d)$) is
  \begin{align*} 
    u(t,x) = J_0(t,x) + \int_0^t \ensuremath{\mathrm{d} } s \int_{\mathbb{R}^d} \ensuremath{\mathrm{d} } y\: f(s,y) \: \DRL{0+}{\left\lceil \beta \right\rceil-\beta-\gamma} Z(t-s,x-y),
  \end{align*}
  where $\DRL{0+}{\left\lceil \beta \right\rceil-\beta-\gamma}$ denotes the
  \textit{Riemann-Liouville derivative}\index{Riemann-Liouville integral} $D_{0+}^{\left\lceil \beta \right\rceil-\beta-\gamma}$
  acting on the time variable,
  \begin{align*} 
    J_0(t,x)\coloneqq \sum_{k = 0}^{\left\lceil \beta \right\rceil-1}\int_{\mathbb{R}^d} u_{k}(y) \partial_t^{\left\lceil \beta \right\rceil-1-k} Z(t,x-y) \ensuremath{\mathrm{d} } y
  \end{align*}
  is the solution to the homogeneous equation and $Z(t,x) \coloneqq
    Z_{\alpha,\beta,d}(t,x)$ is the corresponding fundamental solution. Denote
  \begin{gather*}
    Y(t,x) \coloneqq Y_{\alpha,\beta,\gamma,d}(t,x) = \DRL{0+}{\left\lceil \beta \right\rceil-\beta-\gamma}
    Z_{\alpha,\beta,d}(t,x), \\
    Z^* (t,x) \coloneqq Z^{*}_{\alpha,\beta,d}(t,x) = \frac{\partial}{\partial t} Z_{\alpha,\beta,d}(t,x),
    \quad \text{if $\beta\in(1,2]$.}
  \end{gather*}
  Then, we have the following Fourier transforms:
  \begin{align}
    \mathcal{F} Z_{\alpha,\beta,d}(t,\cdot)(\xi)        & = t^{\left\lceil \beta \right\rceil-1} E_{\beta,\left\lceil \beta \right\rceil}(-\tfrac12 \nu t^\beta |\xi|^\alpha),              \\
    \mathcal{F} Y_{\alpha,\beta,\gamma,d}(t,\cdot)(\xi) & = t^{\beta+\gamma-1} E_{\beta,\beta+\gamma}(-\tfrac12 \nu t^\beta |\xi|^\alpha),  \\
    \mathcal{F} Z^*_{\alpha,\beta,d}(t,\cdot)(\xi)      & = t^{k} E_{\beta,k+1}(-\tfrac12\nu t^\beta |\xi|^\alpha), \quad \text{if $\beta\in (1,2]$}.

  \end{align}
  Moreover, when $\beta\in (0,2)$, we have the following explicit expressions:
  \begin{align}
    Z(t,x) = \pi^{-\frac d2} t^{\left\lceil \beta \right\rceil-1} |x|^{-d}
    \FoxH{2,1}{2,3}{\frac{|x|^\alpha}{2^{\alpha-1}\nu t^\beta}}{(1,1),\:(\left\lceil \beta \right\rceil,\beta)}
    {(d/2,\alpha/2),\:(1,1),\:(1,\alpha/2)},
  \end{align}
  \begin{align}
    \begin{aligned}
      Y(t,x) = \pi^{-\frac d2} |x|^{-d}t^{\beta+\gamma-1}
      \FoxH{2,1}{2,3}{\frac{|x|^\alpha}{2^{\alpha-1}\nu t^\beta}}
      {(1,1),\:(\beta+\gamma,\beta)}{(d/2,\alpha/2),\:(1,1),\:(1,\alpha/2)},
    \end{aligned}
  \end{align}
  and, if $\beta\in (1,2)$,
  \begin{align}
    Z^{*}(t,x)=
    \pi^{-\frac d2} |x|^{-d}
    \FoxH{2,1}{2,3}{\frac{|x|^\alpha}{2^{\alpha-1}\nu t^\beta}}{(1,1),\:(1,\beta)}
    {(d/2,\alpha/2),\:(1,1),\:(1,\alpha/2)},
  \end{align}
  where $H_{2,3}^{2,1}$ 
  refers to the Fox $H$-function defined as in~(equation E:Fox-H of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:24:25.935717+00:00","domain":"probability theory","id":"claim_d4f7776d7e045a087e4f8354d05fd8d086ea94f745c85ed2006778fa2ca32c58","kind":"concept","schema_version":1,"statement":"[Lemma 31 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $F$ be a set of edges in $(G, \omega)$ with $\omega_e \leq a_1$ for all $e \in F$, and fix $D > 0$. Then there exists a connected weighted graph $(G', \omega')$, such that an edge $e \in F$ is either contracted in $G'$ (without contracting a loop) or has $\omega'_e = a_1$, and 
    \begin{equation} 
        \bP( \diam(\cT) \leq D) \geq \tilde{\bP}^{(G', \omega')}( \diam(\cT) \leq D).
    \end{equation}
    If instead $a_2 \leq \omega_e$ for each $e \in F$, then an edge $e$ is either not contained in $G'$ or has $\omega'_e = a_2$ and \eqref{eq:bump_F} holds. The same conclusion (for a different $(G', \omega')$) also holds for the event that the diameter is larger than some $D'$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:47:21.706497+00:00","domain":"probability theory","id":"claim_d4f97ca25c02b4778b6db503702870c5dffc1a0ae216b2a61bc46468be714639","kind":"lemma","schema_version":1,"statement":"[Lemma lem_der_under_integral_sign of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Assume $c(x,\cdot)$ to be $\mathcal{C}^1(\mathcal{Y})$ and $c(x,\cdot)+\psi^{\nu}_\varepsilon(\cdot)$ $\Lambda$-semiconcave uniformly in $x\in\mathcal{X}$.
If for all $\delta>0$ and all open balls $B\subseteq \mathcal{Y}$ we have
\begin{equation*}
\int (1+\sup_{y\in B}|\nabla_2c(x,y)|)\exp\biggl(\delta\sup_{y\in B}|\nabla_2c(x,y)|\biggr)\rho(\mathrm{d}x)<+\infty,
\end{equation*}
then the differentiation formula 
\begin{equation*}
\nabla\psi^{\nu}_\varepsilon(y)=-\int_\mathcal{X}\nabla_2 c(x,y)\,\pi_\varepsilon^{\rho\nu}(\mathrm{d} x|y)\,,
\end{equation*}
holds in the sense of weak derivatives.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.369015+00:00","domain":"probability theory","id":"claim_d4fbe3923d5a55130a93e5e797c4090ce3fcaa7218ca2216c9a94af00ed60a0f","kind":"lemma","schema_version":1,"statement":"[Lemma lem:C2 of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] For any $p \geq 1$ and $i \in \{1,\dots , d\}$ we have
