    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:38:17.787572+00:00","domain":"probability theory","id":"claim_d524350205a7f9b367d5aff6e29f339646409c984928abf41665310e0ccd49cc","kind":"concept","schema_version":1,"statement":"[Thm permuton_conv of arXiv:2509.07729, 'Permuton and local limits for the Luce model'] Set $f_n(y):=\theta_{\lfloor yn \rfloor}$ for all $y\in[0,1]$ and assume that $f_n\to f$ almost everywhere for some positive, finite, measurable function $f$ on $[0,1]$.
	Let also $\mu$ be the law of the pair
	\begin{equation}
            (X,Y):=\Big(U,F\big(E/f(U)\big)\Big),
        \end{equation}
	where $U$ is a uniform random variable on $[0,1]$, $E$ is an independent exponential random variable of parameter 1, and
	\begin{equation}
		F(x):=1-\int_0^1\mathrm{e}^{-x f(y)}\,\text{d} y,\quad \text{for all $x\geq 0$.}
	\end{equation}
	If $\sigma_n\sim \Luce(\theta_1,\dots,\theta_n)$, then the sequence $(\sigma_n)_n$ converges in probability in the permuton sense to the deterministic permuton $\mu$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.358707+00:00","domain":"probability theory","id":"claim_d524d4de31b2ae30f7b490f568a3b60610245f5f4e20f935cb321297cf3fbe89","kind":"concept","schema_version":1,"statement":"[Lemma lem:orthogonal_density of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $(e_i)_{i=1}^\infty, (q_k)_{k=1}^\infty$ be  orthonormal basis of $\mathcal{H}, V$, respectively.  The collection  
    \begin{equs}
        \mathcal{S}_{ON}(V \otimes \mathcal{H})= \left\{ \sum_{i,k= 1}^n f_{ik}(B(e_1), \dots, B(e_n)) q_k \otimes e_i: n \in \mathbb{N}, f_{ik} \in \mathcal{C}_{\mathrm{pol}}^\infty({\mathbb{R}}^n) \right\} 
    \end{equs}
    is dense in $\mathbb{D}^{k, p}(V \otimes \mathcal{H})$ for any $k \geq 0$, $p \geq 2$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:19:00.857903+00:00","domain":"probability theory","id":"claim_d525e2d0a9d750747b8cd3538cc1d0cc83ae028ee9c06f636b47921fcd2de982","kind":"concept","schema_version":1,"statement":"[Theorem 12 (Entropic martingale identity) of arXiv:2608.20337, 'Information on trajectories:\\ martingales and random times'] For $\Psi_t$ the running conditional log-CGF~\eqref{eq:exact-cgf}, the exponential martingale~\eqref{eq:doleans} has $\log \E_P[\cE_t(\lambda)] = 0$ for every $t \geq 0$, and for every $Q \ll P|_{\cF_t}$,
\begin{equation}
  \lambda\,\E_Q[Y_t] - \E_Q[\Psi_t(\lambda)]
    + \KL(Q\|Q^\star_t)
  = \KL(Q\|P|_{\cF_t}),
\end{equation}
where $\dd Q^\star_t/\dd P \propto \cE_t(\lambda)$ is the Gibbs tilt.
Dropping the nonnegative residual $\KL(Q\|Q^\star_t)$ gives the variational form $\sup_{Q\ll P|_{\cF_t}}\bigl\{\lambda\,\E_Q[Y_t] -
\E_Q[\Psi_t(\lambda)] - \KL(Q\|P|_{\cF_t})\bigr\} = 0$, attained at $Q^\star_t$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:55:37.871241+00:00","domain":"probability theory","id":"claim_d5274a5f3932b43a82273e3086481fbd2390583fa9b54e3494607522470e42ac","kind":"lemma","schema_version":1,"statement":"[Lemma lem:imp of arXiv:2605.07591, 'Nonnegativity of the second largest eigenvalue of \(4 \times 4\) tridiagonal stochastic ma'] The following statements hold:
\begin{enumerate}
\item If \(\Delta_2 \le 0\), then \(\Delta_3 \le 0\).
\item If \(\Delta_3 \le 0\) and \(\Delta_2 \ge 0\), then \(\Delta_4 \le 0\).
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:25:40.180492+00:00","domain":"probability theory","id":"claim_d528bf8843ce111e77cc701cd1964256b6938c7bf5ae123ade96ac7c7b552891","kind":"theorem","schema_version":1,"statement":"[Theorem thm:R0 of arXiv:2609.01562, 'Points of maximal traffic on a grid with obstruction'] Let $B=(c,c)\in\mathcal{R}_0(n)$ with $n\ge 5$. For every $A\in\mathcal{G}(n)\backslash\{(0,0),(n,n)\}$, we have
\begin{equation*}
 f_B(A) \le 
 \begin{cases}
 f_B(1,1) & \text{if $c<n\le 2c$}, \\
 f_B(n-1,n-1) & \text{if $2c \le n$.}
