\item $\forall (x_1,...,x_n) \in \mathbb{R}^n, \ g(x_1,...,x_n) \leq g(|x_1|,....,|x_n|)$
\end{enumerate}
Let $f \in \mathcal{B}^n$ \eqref{absolutetails} be an $n$-tuple of absolute tail bounds. Then, 
\begin{equation}
   \sup_{X \in \mathcal{T}(f)} P(g(X) \geq t) = P(g(\widetilde{X}) \geq t), \ \forall t \in \mathbb{R}.
