{"assumptions":[],"created_at":"2026-10-26T19:45:38.359173+00:00","domain":"probability theory","id":"claim_d5b18a2d60f77c2674ae9db59c442bbc66ac5d7d4490acb57c1e9551a9b386fb","kind":"lemma","schema_version":1,"statement":"[Lemma 12 (Monotonicity of the corrector energy) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] Let~$U \subset V$ be bounded Lipschitz domains in~$\Rd$, and let~$\eps \in (0,1)$.
		For every~$p \in \Rd$, the correctors~$\phi_U$ and~$\phi_V$ defined by~\eqref{eq:elleqdefnu} on~$U^\eps$ and~$V^\eps$ satisfy
		\begin{equation}

			D_\a^\eps(\phi_U) \le D_\a^\eps(\phi_V)\,.
		\end{equation}
		Consequently,
		\begin{equation}

			\|\phi_U\|_{H^1_{\mathrm{crit}}(U^\eps)}^2 + \|\phi_U\|_{L^2(U^\eps)}^2
			\le C\bigl(\|\phi_V\|_{H^1_{\mathrm{crit}}(V^\eps)}^2 + \|\phi_V\|_{L^2(V^\eps)}^2\bigr)\,,
		\end{equation}
		where~$C$ depends only on~$d$,~$\lambda$, and~$\operatorname{diam}(U)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:38:11.840087+00:00","domain":"probability theory","id":"claim_d5b2419acb2d8f8fbd4ed74fcb8c24df30e9d1e6e58bd0225fdcac3c1b0f4627","kind":"concept","schema_version":1,"statement":"[Proposition MvN-Frechet of arXiv:2504.04860, 'Stochastic differential equations driven by fractional Brownian motion: dependence on the '] Let $H\in (0,1)$ and choose $a,b \in (0,1)$ such that $a\leq H \leq b$ and $\frac{1}{2} \in [a,b]$. Define  \begin{align*}
		\widehat{B}_t^H = B_t^{\frac{1}{2}} +  \int_{\frac{1}{2}}^H \partial_h B_t^{h}\,\mathrm{d} h , \qquad H \in [a,b], \,\, t \in [0,T].
		\end{align*} 
	Then, we have
	\begin{itemize}
		\item[(1)]  that for fixed $H \in [a,b]$ the processes $\widehat{B}^H$ and $B^H$  are indistinguishable and 
		\item[(2)]  for all $\omega \in \Omega$ the map $ [a,b] \ni H \mapsto \widehat{B}^H(\omega) \in C([0,T];\mathbb{R})$ is  Fr\'echet differentiable  with derivative $\partial_H B^H$, that is,
		\begin{align*}
			& \lim_{\delta \rightarrow 0} \frac{\sup_{t \in [0,T]} |\widehat{B}^{H+\delta}_t(\omega) - \widehat{B}^H_t(\omega) - \partial_H {B}^{H}_t(\omega)\delta |}{|\delta|}=0.
		\end{align*}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

