{"assumptions":[],"created_at":"2026-10-26T19:44:17.163111+00:00","domain":"probability theory","id":"claim_d5b6d425871747bb0eb091670c42fdd9d906c3661e779008ec3c2cdd442aba7c","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Let $\mathcal{A}$, and $\mathcal{A}_{n}\subset \mathcal{A}$ for each $n\in\mathbb{N}$, be compact subsets of $\mathbb{R}^{d}$. Let $Q$, taking values in $\mathcal{A}$, and $Q_{n}$, taking values in $\mathcal{A}_{n}$, for each $n\in\mathbb{N}$, be random variables, such that $\{Q_{n}\}$ converges almost surely to $Q$. Let $f_{n}:\mathcal{A}_{n}\rightarrow\mathbb{R}$ for each $n$, and $f:\mathcal{A}\rightarrow\mathbb{R}$ with $f\in\mathcal{C}^{(0)}(\mathcal{A})$. Let $\beta_{n}>0$ for each $n$ be such that 
\begin{equation}
\sup\left\{\left|f_{n}(x)-f(x)\right|:x\in \mathcal{A}_{n}\right\}\leqslant \beta_{n} \text{ for each } n\in\mathbb{N} \quad \text{and} \quad \beta_{n}\rightarrow 0 \text{ as } n\rightarrow\infty. 
\end{equation}
Then the Cesaro average
\begin{equation}
\frac{1}{n}\sum_{i=1}^{n}f_{i}(Q_{i}) \convas f(Q) \text{ as }n\rightarrow\infty.
\end{equation} 

Alternatively, let $Q$ as well as $Q_{n}$, for each $n\in\mathbb{N}$, take values in $\mathcal{A}$, and let $Q_{n}\convas Q$. Let $f_{n}:\mathcal{A}\rightarrow\mathbb{R}$ and $f_{n}\in\mathcal{C}^{(0)}(\mathcal{A})$ for each $n\in\mathbb{N}$, and $f:\mathcal{A}\rightarrow\mathbb{R}$, such that $\{f_{n}\}$ converges uniformly to $f$ on $\mathcal{A}$. Then, once again, the conclusion of \eqref{Cesaro_convergence} holds. A special case of this scenario is where $f_{n}\equiv f$ for each $n\in\mathbb{N}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:33:17.673553+00:00","domain":"probability theory","id":"claim_d5b99df44e4f497c5dbe8fa02a5054de2d0c7feb067651e8012ba32722a1f13a","kind":"concept","schema_version":1,"statement":"[Corollary 4 (Gaussian Brunn--Minkowski with barycenter terms) of arXiv:2607.10769, '\fontsize{14}{17}\selectfont\bfseries Sharp Poincar\'e interpolation along Wasserstein geo'] Let $K_0,K_1\subset\R^n$ be convex Borel sets with
$\gamma(K_i)>0$. For every $t\in[0,1]$, set
$K_t=(1-t)K_0+tK_1$ and
$b_t=(1-t)b_{K_0}+tb_{K_1}$.  Then
\begin{equation}
 e^{|b_t|^2/(2n)}\gamma(K_t)^{1/n}
 \geq
 (1-t)e^{|b_{K_0}|^2/(2n)}\gamma(K_0)^{1/n}
 +t e^{|b_{K_1}|^2/(2n)}\gamma(K_1)^{1/n}.
\end{equation}
Moreover, equality in \eqref{eq:intro-barycenter-BM} at some
$t\in(0,1)$ holds if and only if
$\bar K_0=\bar K_1$. In this case, equality holds for every
$t\in[0,1]$. 

In particular, if $b_{K_0}=b_{K_1}$, then
\[
 \gamma(K_t)^{1/n}
 \geq(1-t)\gamma(K_0)^{1/n}+t\gamma(K_1)^{1/n}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:57:28.239020+00:00","domain":"probability theory","id":"claim_d5b9b13e397bd060049d09c8f9b8ff6217a8d787a266b1477db2b89c5e224852","kind":"definition","schema_version":1,"statement":"[Definition 47 of arXiv:2607.18104, '2607.18104'] The \textbf{asymmetric simple exclusion process (ASEP)} on $\Z$ with parameter $q\in [0,1)$ is a continuous-time Markov chain $(\eta_t)_{t \geq 0}$ on $\{0,1\}^{\Z}$ with generator
\begin{equation}
L_{\Z}f(\eta) = \sum_{x \in \Z} \big(\eta(x)(1-\eta(x+1)) + q \eta(x+1)(1-\eta(x))\big)\big[ f(\eta^{x,x+1})- f(\eta) \big] 
\end{equation} acting on the core of cylinder functions $f \colon \{0,1\}^{\Z} \rightarrow \R$. 
Here, $\eta^{x,x+1}$ denotes the configuration, where we swap the values of $x$ and $x+1$, and leave all other values in $\eta$ unchanged, i.e.,
\begin{equation}
    \eta^{x,x+1}(y) := \begin{cases}
        \eta(x+1) & \text{ if } y=x \\
        \eta(x) & \text{ if } y=x+1 \\
        \eta(y) & \text{ otherwise. }
    \end{cases}
\end{equation}
 We define the \textbf{wrapped periodic asymmetric simple exclusion process (periodic ASEP)} as the continuous-time Markov chain $(\eta^{\per}_t)_{t \geq 0}$ on $\{0,1\}^{\Z/N\Z}$ with respect to the generator
\begin{equation}
L_{\per}f(\eta) = \sum_{x \in \Z/N\Z} \big(\eta(x)(1-\eta(x+1)) + q \eta(x+1)(1-\eta(x))\big)\big[ f(\eta^{x,x+1})- f(\eta) \big] 
\end{equation} for all cylinder functions $f \colon \{0,1\}^{\Z/N\Z} \rightarrow \R$. We extend the wrapped periodic ASEP $(\eta^{\per}_t)_{t \geq 0}$ to the \textbf{unwrapped periodic ASEP} $(\epb_t)_{t \geq 0}$ on $\{0,1\}^{\Z}$ by setting for all $t\geq 0$
\begin{equation}
    \epb_t(x) := \eta_t( x \textup{ mod } N) . 
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:32:56.073493+00:00","domain":"probability theory","id":"claim_d5baa98a9f9ac23582ff025cee91756e553deb710743c0deaead5dc32cafc929","kind":"lemma","schema_version":1,"statement":"[Lemma le:sLND-U of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Assume the condition  (equation e:DL of the paper) holds and
\begin{equation}
  \begin{cases}
    \theta_1<1,  \\
    \theta_2<1,  \\
    \gamma<1-H_0.
  \end{cases}
\end{equation}
\begin{enumerate}
  \item The Gaussian random field $U=\{U(t,x),(t,x)\in\mathbb{R}\times\mathbb{R}^d\}$ has stationary increments with spectral measure
  \begin{equation}
  F_U(\ensuremath{ \mathrm{d}} \tau,\ensuremath{ \mathrm{d}} \xi)=\frac{C_{H_0}|\tau|^{1-2\gamma-2H_0}}{|\tau|^{2\beta}+2|\xi|^\alpha|\tau|^\beta\cos\left(\frac{\pi\beta}{2}\right)
  +|\xi|^{2\alpha}} \mu(\ensuremath{ \mathrm{d}} \xi) \ensuremath{ \mathrm{d}}  \tau.
  \end{equation}
  \item The Gaussian random field $U$ satisfies the strong local nondeterminism property: there exists
  a constant $C>0$ such that for all $n\in\mathbb{N}$ and $(t,x),(t^1,x^1),\dots,(t^n,x^n)\in\mathbb{R}\times\mathbb{R}^d$,
  \begin{equation}
    \mathrm{Var}\big(U(t,x)|U(t^1,x^1),\dots,U(t^n,x^n)  \big)\ge C\min_{k=0,1,\dots,n}\bigg( |t-t^k|^{\theta_1}+\sum_{i=1}^d|x_i-x^{k}_i|^{\theta_2} \bigg)^2,
  \end{equation}
  where $t^0=x^0_i=0$, $i=1,\dots, d$.
  \item 
  There exist constants $c, C>0$ such that
  \begin{equation}
    c\left(|t-s|^{2\theta_1}+|x-y|^{2\theta_2}\right) \le \mathbb E\left[ |U(t,x)-U(s,y)|^2 \right]\le C\left(|t-s|^{2\theta_1}+|x-y|^{2\theta_2}\right)
  \end{equation}
  for all $(t,x),(s,y)\in\mathbb{R}\times\mathbb{R}^d$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:41:03.294292+00:00","domain":"probability theory","id":"claim_d5badda1256e0dc0a5ceea923b6781a301b4216b529e61e6ad5b767db5acc2ba","kind":"concept","schema_version":1,"statement":"[Lemma lem_sticky_refl_principle of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] Let $X$ be the sticky Brownian motion of stickiness parameter $\rho>0$ defined on the filtered probability space $ \mathcal P_x = (\Omega, \bF, (\bF_t)_{t\ge 0},\Prob_x) $ such that $\Prob_x$-a.s., $X_0 = x$ (in particular, $X$ is $(\mathcal F_t)_{t\ge 0}$-adapted). 
Let $X' $ be the process defined for all $t\ge 0 $ by
\begin{equation}

	X'_t = 
	\begin{dcases}
		X_t & t< \tau^{X}_{0},\\
		-X_t & t\ge \tau^{X}_{0}.\\
	\end{dcases}
\end{equation}
The process $X'$ defined this way is a sticky Brownian motion of stickiness parameter $\rho$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:19:46.233938+00:00","domain":"probability theory","id":"claim_d5bb0aea145a06c3430fd646227ffe69ca2910037176aad63ebf47f5a819bfdd","kind":"concept","schema_version":1,"statement":"[Prop 66 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Assume that $\tr_{d_n}\circ \pi_n\to \tau$, and let $\l$ be the GNS representation of $\tau$. Let $k$ be a positive integer and let $\phi \in \B(\A,\rmM_k)_+$.
\begin{enumerate}
\item[a.] If $\phi$ is approximately associated to $\l^{\oplus \infty}$, then $\phi$ is asymptotically associated to $\bspi$.
\item[b.] If $\phi_{\rm{sing}}$ is asymptotically associated to $\bspi$, then so is the whole of $\phi$.
\end{enumerate} \qed (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.580244+00:00","domain":"probability theory","id":"claim_d5bb18514ace5e3734b9106a164bae778ccba22b82b5d6eaeaf25b246e05dcaa","kind":"definition","schema_version":1,"statement":"[Definition def:nSD[a,b] of arXiv:2411.15401, 'The reference interval in higher-order stochastic dominance'] [{\color{black}[J80]}]
Let $a,b\in[-\infty,\infty]$ with $a<b$ and $n\in\mathbb{N}$. For $X,Y\in\mathcal X_{[a,b]}$, we say that $X$ dominates $Y$ in the sense of $n$th-order stochastic dominance on $[a,b]$ ($n{\rm SD}_{[a,b]}$), denoted by $X\ge_{n}^{[a,b]} Y$ or $F_X\ge_{n}^{[a,b]} F_Y$ if 
\begin{align*}
F_X^{[n]}(\eta)\le F_Y^{[n]}(\eta),~\forall \eta\in[a,b]~{\rm and}~F_X^{[k]}(b)\le F_Y^{[k]}(b)~{\rm for}~ k\in[n]
\end{align*}
or equivalently,
\begin{align*}
\mathbb{E}[(\eta-X)_+^{n-1}]\le \mathbb{E}[(\eta-Y)_+^{n-1}],~\forall \eta\in[a,b]~{\rm and}~\mathbb{E}[(b-X)^{k-1}]\le \mathbb{E}[(b-Y)^{k-1}]~{\rm for}~ k\in[n].
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:18:27.573585+00:00","domain":"probability theory","id":"claim_d5be73f4a2839ac2d20ef27d19338ffeb14d0c5f6dc47019d061c73bc52f38ac","kind":"concept","schema_version":1,"statement":"[Thm 30 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 4$. There exists $C_{\textup{mag}}=C_{\textup{mag}}(d)\geq 1$ such that, for every $h\geq0$,
