{"assumptions":[],"created_at":"2026-10-27T09:01:15.319076+00:00","domain":"probability theory","id":"claim_d5c54b198ec587f14bbfdc494fbfb7aa26444983ea6c8696987cd2fb9d470358","kind":"concept","schema_version":1,"statement":"[Corollary 14 (Two-layer mean-field risk curves) of arXiv:2608.30261, 'Estimating Population-Risk Curves Along Nonconvex Gradient Flows from the Training Sample'] \label[corollary]{cor:mean-field-width-oracle}
For the two-layer model in \eqref{eq:mean-field-network} and the deterministic
finite width family $\mathcal W_n$, for $N\geq1$ write
$\mathsf s_N\sim\mathsf s_N'$ when
$\mathsf s_N,\mathsf s_N'\in\mathsf Z_0^N$ differ in at most one coordinate.
For $m\in\mathcal W_n$ and $N\geq1$, define
\begin{align*}
 \beta_{N,m}
 &=\sup_{\substack{(t,\lambda)\in\cH_m,\
                    \mathsf s_N,\mathsf s_N'\in\mathsf Z_0^N,\
                    \mathsf s_N\sim\mathsf s_N'\\ z\in\mathsf Z_0}}
 \big|L_{N,(m,t,\lambda)}(\mathsf s_N,z)
       -L_{N,(m,t,\lambda)}(\mathsf s_N',z)\big|,\\
 \beta_{N,m}^{\rm mix}
 &=\sup_{\substack{(t,\lambda),(t',\lambda')\in\cH_m,\
                    (t,\lambda)\ne(t',\lambda')\\
                    \mathsf s_N,\mathsf s_N'\in\mathsf Z_0^N,\
                    \mathsf s_N\sim\mathsf s_N',\ z\in\mathsf Z_0}}
 \frac{1}{d_1((t,\lambda),(t',\lambda'))}\\[-2pt]
 &\quad{}\times
 \left|\begin{aligned}
  &L_{N,(m,t,\lambda)}(\mathsf s_N,z)
   -L_{N,(m,t,\lambda)}(\mathsf s_N',z)\\
  &\quad-L_{N,(m,t',\lambda')}(\mathsf s_N,z)
   +L_{N,(m,t',\lambda')}(\mathsf s_N',z)
 \end{aligned}\right|.
\end{align*}
When $\cH_m$ is a singleton, define $\beta_{N,m}^{\rm mix}=0$.
There are finite nonnegative deterministic constants
$B_T,C_{\beta,T},C_{{\rm hyp},T}$ and $C_{\Delta,T},C_{PP,T}$, depending only
on $Q_0,X,T,\lambda_{\max},L_0$, $(\mathsf S_j)_{j=0}^3$, and
$(\mathsf L_j)_{j=1}^3$, such that
$L_{N,(m,t,\lambda)}(\mathsf s_N,z)$ lies in one deterministic interval of
length $B_T$, uniformly over $m\in\mathcal W_n$, $N\geq1$,
$(t,\lambda)\in\cH_m$, $\mathsf s_N\in\mathsf Z_0^N$, and $z\in\mathsf Z_0$.
Uniformly over $m\in\mathcal W_n$ and $N\geq1$, the bounds
$\beta_{N,m}\leq C_{\beta,T}/N$ and
$\beta_{N,m}^{\rm mix}\leq C_{\Delta,T}/N$ hold,
\eqref{eq:hyper-modulus} holds on
$(\mathcal U,\rho)=(\cH_m,d_1)$ with
$\omega_{n-1}(r)=C_{{\rm hyp},T}r$, and the
deletion-chord hypotheses of \cref{thm:jackknife-cancellation} hold with
curvature $C_{PP,T}$.  Define the finite deterministic
simultaneous concentration radius
$s_{n,\mathcal W}^{\rm mf,ch}:(0,1)\to[0,\infty)$ by
\begin{equation}
 s_{n,\mathcal W}^{\rm mf,ch}(\delta)
 =\frac{B_T+2C_{\beta,T}}{\sqrt{2n}}
       \sqrt{\mathfrak L_{n,\mathcal W,\delta}}
 +\frac{C_{\rm ch}(C_{{\rm hyp},T}+C_{\Delta,T})}{\sqrt n}
  \left\{\mathfrak E_{\mathcal W}
           +D_{\mathcal W}\sqrt{\mathfrak L_{n,\mathcal W,\delta}}\right\}.
\end{equation}
For every $\delta\in(0,1)$, with probability at least $1-\delta$,
\begin{multline}
 \max_{m\in\mathcal W_n}\sup_{(t,\lambda)\in\cH_m}
 |\widetilde\Score_{n,m}(t,\lambda)-\Risk_{S,m}(t,\lambda)|\leq\frac{2T\mathsf L_1^2C_{{\rm ker},T}}{n(n-1)}
 +\frac{2C_{PP,T}}{(n-1)^2}
 +s_{n,\mathcal W}^{\rm mf,ch}(\delta).
\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

