\item For every $\omega \in \widetilde{\Omega}$, $f \in \Lc$, and $s, t \in \R$ such that $s \leq t$, one has $L^{s,t}_{\omega} f \in \Lc$;
\item For every $\omega \in \widetilde{\Omega}$, 
$$
\lim_{s \to -\infty} Z_s^{y,0}(\omega) = Z_{-\infty}^{y,0}(\omega) > 0, \qquad \forall y \in \Z^d;
$$
\item For every $\omega \in \widetilde{\Omega}$, the function 
$$
\mathcal{Y}(\omega): \Z^d \to (0, \infty), \ y \mapsto Z_{-\infty}^{y,0}(\omega)/Z_{-\infty}^{0,0}(\omega)
$$
is an element of $\Lc$. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.333773+00:00","domain":"probability theory","id":"claim_d63b194f32ff3754334a0b3b115267fd8edafb9c71bcf19db2546d6e4ab0cd8a","kind":"lemma","schema_version":1,"statement":"[Lemma 7 of arXiv:2511.06196, 'Central limit theorem for high temperature spin models via martingale embedding'] Let $p_d$, $d=0,1,2,\dots$, denote the probability mass function of $D_\infty$. We have, for some $d_1$ depending only on $\alpha$ and any $d_2\geq 1$,
