{"assumptions":[],"created_at":"2026-10-26T19:47:01.662335+00:00","domain":"probability theory","id":"claim_d644a087149af1131b64de13a2a42adf405d0cb6c148ce3cfbfbb3cca3c77772","kind":"concept","schema_version":1,"statement":"[Theorem 5 of arXiv:2604.23610, 'Scaling limits of Lévy walks with random velocities'] Let $\{U_V\left(t\right)\}_{t\ge0}$ and $\{O_V\left(t\right)\}_{t\ge0}$ be the wait-first LW with
 random velocities and jump-first LW with random velocities, respectively, that are generated by the sequence $\left\{V_i, \, T_i, \, \mathbf{J}_i\right\}_{i\in \mathbb{N}}$. Then,
 \begin{enumerate}
     \item 
     if $\alpha<\beta$, we have
     \begin{equation}
         \begin{aligned}
             n^{-1/\alpha}U_V\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \left(\mathbf{L}_{\alpha}^-\left(S_{\alpha}^{-1}\left(t\right)\right)\right)^+,\\
             n^{-1/\alpha}O_V\left(n^{1/\alpha}t\right) \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \mathbf{L}_{\alpha}\left(S_{\alpha}^{-1}\left(t\right)\right),
         \end{aligned}
     \end{equation}
