{"assumptions":[],"created_at":"2026-10-26T20:46:26.257562+00:00","domain":"probability theory","id":"claim_d645d93ed36a8452c9bde011aa698f5dc28755b4757e9a73fd478444a5d31138","kind":"concept","schema_version":1,"statement":"[Thm 65 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Suppose that \cref{ncptas} is satisfied. 
  We regard $F$ and $F_n$ as subsets of a common $\bcm$ space $(M,d)$.
  Let $x\in F$ and $x_n\in F_n$. Take $r_{\infty}\ge r_0$ satisfying 
  $x\in B(\rho,r_{\infty})$ and $x_n\in B(\rho_n,r_{\infty})$.
  Then, for any $f\in\BL^{\kappa}(M),\kappa\in [1/2,1]$ and $t>0$
  \begin{align*}
    |P_{t}f(x)-P^n_tf(x_n)|
    \lesssim\|f\|_{\BL^{\kappa}}
    \inf\Bigl\{  \Psi_1(n,r)+C_n(r)\Psi_2(n,r)^E : r\in [r_{\infty},\infty), \Psi_2(n,r)\le \frac{1}{2}\Bigr\},
  \end{align*}
  where
  \begin{equation*}
    \Psi_1(n,r)=P_{x}^n(\sigma_{B(\rho,r)^c}\le t)\vee P_{x_n}^n(\sigma^n_{B(\rho_n,r)^c}\le t),
  \end{equation*}
  \begin{equation*}
    \Psi_2(n,r)=d_{\rm{H}}(F^{(r)},F_n^{(r)})^{\kappa}+d_{\BL^{\kappa}}(\mu^{(r)},\mu^{(r)}_n)+d(x,x_n),
  \end{equation*}
  \begin{equation*}
    \begin{aligned}
      C_n(r)=&(D_n^{(r)})^{4+2(1+\frac{s}{2(1+s)\theta})(2\kappa-1)}\\
    &\quad\times \left[(\diam K_n^{(r)}+\mu_n(F_n^{(r)}))\diam K_n^{(r)}\mu_n(F_n^{(r)})\mu(F^{(r)})^{3/2}\diam F^{(r)}(\mu(F^{(r)})^{1/2}+\mu_n(F_n^{(r)}))\right]\\
    \lesssim& r^{6+\frac{3}{2}s+2(1+\frac{s}{2(1+s)\theta})(2\kappa-1)}(r+\mu_n(F^{(r)}))(r^{s/2}+\mu_n(F^{(r)}))(r^s+\mu_n(F^{(r)}))^{4+2(1+\frac{s}{2(1+s)\theta})(2\kappa-1)},
    \end{aligned}
  \end{equation*}
  \begin{equation*}
    K_n^{(r)}=F^{(r)}\cup F_n^{(r)},\qquad D_n^{(r)}=\mu(F^{(r)})\diam F^{(r)}\vee \mu_n(F^{(r)}_n)\diam F^{(r)}_n,
  \end{equation*}
  and
  \begin{equation*}
    E=\frac{\kappa}{\kappa+(1+s)(2+\kappa)(\kappa+\theta)}.
  \end{equation*}
  Moreover, the time-dependence of the constant in $\lesssim$ is $t^{[\kappa-\frac{s}{2(1+s)\theta}(2\kappa-1)]},\;t\in (0,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:52.231839+00:00","domain":"probability theory","id":"claim_d647f5cbb36f19adab794bf5a5cd99d2d6d1d66ff01f08154f3c34c2105d1ba3","kind":"definition","schema_version":1,"statement":"[Df 3 of arXiv:2512.10199, 'Explicit correlation functions for the six-vertex model in the free-fermion regime'] A \emph{generalised snake configuration on $\midedge_n$} is a permutation $\orho:\midedge_n \to \midedge_n$ with the additional property that, for all $x \in \midedge_n$,
\begin{equation*}
    \orho(x) \in \begin{cases}
        \{x,x+ \tfrac{1}{2}(e^1 + e^2), x + e^1\} &\text{ if } x \text{ black,}\\
        \{x,x+ \tfrac{1}{2}(e^1 + e^2), x + e^2\} &\text{ if } x \text{ white.}
    \end{cases}
\end{equation*}
Let $\gen_n$ be the set of generalised snake configurations on $\midedge_n$.

A \emph{crossing} in a generalised snake configuration $\orho$ is a vertex $v \in \mathbb{T}_n$ for which
\begin{align*}
\orho(v - \tfrac{1}{2}e^1) = v+\tfrac{1}{2}e^1 \quad \text{and} \quad \orho(v - \tfrac{1}{2}e^2) = v+\tfrac{1}{2}e^2.
\end{align*}
A \emph{pure snake configuration} (which we will often denote by $\rho$) is a generalised snake configuration with no crossings. Denote $\pure_n$ to be the set of pure snake configurations on $\midedge_n$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.235133+00:00","domain":"probability theory","id":"claim_d64827a5f0fe080627e9a9a8dd127a3f5dff01fb68a17eb4c96e87b93b26481a","kind":"theorem","schema_version":1,"statement":"[Theorem of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] The  functional type law of large numbers holds for the multi-scale ensemble Kalman sampler model $((ex2:systema of the paper))$-$((ex2:systemb of the paper))$, i.e.,
