{"assumptions":[],"created_at":"2026-10-27T07:19:00.896660+00:00","domain":"probability theory","id":"claim_d69c481cbfb8ef6cfeb4b3d1752d92971bffeb29b56589b8113eb85e6412402e","kind":"theorem","schema_version":1,"statement":"[Cor 13 of arXiv:2608.20552, 'One-point fluctuations for exponential last passage percolation under upper-tail condition'] Let $n_1,n_2\in\N$ and $0\le i,j\le n_2$. Define\footnote{The superscript and subscript indicate whether the $1$- and $2$-blocks in the left and right lists, respectively, are ordered as $12$ or $21$.} 
\beqq
\begin{aligned}
	\J^{12}_{12}(a,b,n_1,n_2)&:=\J^{1^{n_1-a}(12)^a2^{n_2-a}}_{1^{n_1-b}(12)^b2^{n_2-b}},
	&\qquad
	\J^{12}_{21}(a,b,n_1,n_2)&:=\J^{1^{n_1-a}(12)^a2^{n_2-a}}_{2^{n_2-b}(12)^b1^{n_1-b}},\\
	\J^{21}_{12}(a,b,n_1,n_2)&:=\J^{2^{n_2-a}(12)^a1^{n_1-a}}_{1^{n_1-b}(12)^b2^{n_2-b}},
	&\qquad 
	\J^{21}_{21}(a,b,n_1,n_2)&:=\J^{2^{n_2-a}(12)^a1^{n_1-a}}_{2^{n_2-b}(12)^b1^{n_1-b}}.
\end{aligned}
\eeqq
Then
\beqq
	\left| \J^{2^{n_2-i}1^{n_1}2^i}_{2^{n_2-j}1^{n_1}2^j} \right| \le 2^{2(n_1+n_2)} S^{\alpha}_{\beta}
	\qquad
	\text{for each } \alpha,\beta \in\{12,21\},
\eeqq
where
\beqq
\begin{alignedat}{2}
	S^{12}_{12}
	&:=
	\sum_{a=0}^{n_1\wedge(n_2-i)}
	\sum_{b=0}^{n_1\wedge(n_2-j)}
	a!b!\,|\J^{12}_{12}(a,b,n_1,n_2)|,
	\qquad&
	S^{12}_{21}
	&:=
	\sum_{a=0}^{n_1\wedge(n_2-i)}
	\sum_{b=0}^{n_1\wedge j}
	a!b!\,|\J^{12}_{21}(a,b,n_1,n_2)|,\\
	S^{21}_{12}
	&:=
	\sum_{a=0}^{n_1\wedge i}
	\sum_{b=0}^{n_1\wedge(n_2-j)}
	a!b!\,|\J^{21}_{12}(a,b,n_1,n_2)|,
	\qquad&
	S^{21}_{21}
	&:=
	\sum_{a=0}^{n_1\wedge i}
	\sum_{b=0}^{n_1\wedge j}
	a!b!\,|\J^{21}_{21}(a,b,n_1,n_2)|.
\end{alignedat}
\eeqq","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.218374+00:00","domain":"probability theory","id":"claim_d69d27f77e1bfa6cf22e29b58ad25539f17fc12054d1eb3fa9309e9ddcf1452e","kind":"concept","schema_version":1,"statement":"[Theorem thm:LIL of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] Let $\beta \in \mathcal{C}^2\big([0, \infty); \mathbb{R}\big)$ satisfy $t \dot{\beta}_t \to 0$ as $t \to \infty$.
