\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.685085+00:00","domain":"probability theory","id":"claim_d6fdfc59764c13fe54af4c34f3000a7751f08188616755b7a4bed3d5eee26009","kind":"lemma","schema_version":1,"statement":"[Lemma 7 (Analytic evaluation lemma) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $\gamma:[0,T]\to V$ be continuous and of bounded variation, and put $g=S(\gamma)$ and $l=\log g$.
Assume $R(l)=\infty$.
Define
\[
A_{\Phi}(z)=\sum_{n\geq 1}z^n\Phi^{(n)}(l_n),
\qquad
G_{\Phi}(z)=\sum_{n\geq 0}z^n\Phi^{(n)}(S_n(\gamma)).
\]
Then both functions are entire and
\begin{equation}
G_{\Phi}(z)=\e^{A_{\Phi}(z)}
\qquad (z\in\C).
\end{equation}
Moreover,
\begin{equation}
\norm{G_{\Phi}(z)}
 \leq \exp\!\bigl(\abs{z}\,\norm{\Phi}\,L(\gamma)\bigr).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:06:18.027361+00:00","domain":"probability theory","id":"claim_d6fe55f173b8d448f8b36ce8722548be2e080f5d414360c2ec9c53c9eab43f3e","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2608.15616, '\textbf{Compact Support Property of Super-Brownian Motion with Irregular Drift}'] Let $r >0$, $m >0$, and 
		\begin{equation}
			\psi^{m,r}(x) =
			\begin{cases}
				0, & |x| \leq r, \\
				m(|x|/r - 1), & r \leq |x| \leq 2r, \\
				m, & 2r \leq |x|.
			\end{cases}
		\end{equation}
		Then there exists a unique mild nonnegative solution $u^m$ to 
		\begin{equation}
			 \frac{1}{2}\Delta u^m(x) -\frac{1}{2}(u^m(x))^2 + \psi^{m,r}(x ) = 0, \quad x \in \R. 
		\end{equation}
		Furthermore, $u^m(x)$ is monotonically increasing in $m$ for all $x\in R$ and there exists a constant $\constFromEq{c}{eq:est_u_infty}>0$ such that for $|x| < r$ we have
		\begin{equation}
			\lim_{m \rightarrow \infty} u^m(x) \leq \constFromEq{c}{eq:est_u_infty}(r-|x|)^{-2}.
		\end{equation}
    Furthermore, the monotone pointwise limit $u$ of $u^m$ is the unique, nonnegative solution to
    \begin{equation}
        \begin{cases}
            \Delta u(x) = \big( u(x) \big)^2, \quad x\in (-r,r), \\
            u(x) \rightarrow \infty, \text{ as } x\rightarrow r \text{ or } x\rightarrow -r.

        \end{cases}
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:12:19.484214+00:00","domain":"probability theory","id":"claim_d6ff1a223581fac0f6eff4dba71fc0fdcc2ec7fc381f1436c587c8ab475fbdf6","kind":"theorem","schema_version":1,"statement":"[Theorem 17 (Lamperti reduction) of arXiv:2608.17927, 'Near-unit-root persistence of symmetric stable \\ autoregressive sequences'] For every $h > 0$, the sequence $(R_{jh})_{j \geq 0}$ is the stationary symmetric stable AR($1$) chain
\begin{equation}

R_{(j+1)h} = e^{-h/\alpha}R_{jh}+\zeta_{j},
\end{equation}
where the innovations are independent symmetric $\alpha$-stable variables with scale $(1-e^{-h})^{1/\alpha}$. Setting $h = \alpha\log{(1/a)}$ yields
\begin{equation}

\Lambda(a,\alpha) = \lambda_{\alpha}(h)
\end{equation}
and
\begin{equation}

0 < \frac{G_{\alpha}^{*}}{\alpha} = \lim_{h \downarrow 0}\frac{\lambda_{\alpha}(h)}{h} = \sup_{h > 0}\frac{\lambda_{\alpha}(h)}{h} \leq \frac{1}{2}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:24:45.935902+00:00","domain":"probability theory","id":"claim_d7013340aa5c29e3e16205e9b3115dd201436fb89ffe3ba1cbe1f667a69bbcac","kind":"concept","schema_version":1,"statement":"[Proposition prp:initial_trace_prop of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] Let $(A,\nu) \in \mathcal{T}$. Then there exists a unique solution to (equation eq:initial_trace of the paper). Furthermore, the following holds:
	\begin{enumerate}
		\item Let $(A,\nu), (\hat{A},\hat{\eta})\in \mathcal{T}$ such that $(A,\nu) \preceq(\hat{A},\hat{\eta})$. Then 
		\begin{equation*}
			\mathcal{W}_t(A,\nu)(x) \leq 	\mathcal{W}_t(\hat{A},\hat{\eta})(x), \quad \forall t>0, x\in \mathbb{R}. 
		\end{equation*}
		\item Let $((A_n,\nu_n))_{n\geq 1} \subset \mathcal{T}$ such that $\eta^{A_n,\nu_n}$ converges $m$-weakly to $\eta^{(A,\nu)}$, then it follows that $\mathcal{W}(A_n,\nu_n)$ converges to $\mathcal{W}(A,\nu)$ uniformly on compacts of $(\mathbb{R}_+\backslash \{0\})\times \mathbb{R}$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

