    for every increasing events $A_1$ and $A_2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:49.286263+00:00","domain":"probability theory","id":"claim_d728c1f67ffc1c9971114f9873c59cc8755628985df0b9d9f510c531a3772380","kind":"definition","schema_version":1,"statement":"[Definition 9 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $(p,\alpha)\in(1,\infty)\times(0,1)$ with $p\alpha<1$. We define $C^{\alpha,p}_o([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^k))$ as the set of continuous paths $\mathbf{x}:[0,T]\rightarrow G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^k)$ such that $\mathbf{x}_0=(1,0,\dots,0)$ and
    \begin{equation*}
        \begin{aligned}
            &\lVert \mathbf{x} \rVert_{\textup{hom $p$-var};[0,T]} + \lVert \mathbf{x} \rVert_{\textup{hom $\alpha$-H\"{o}l};[0,T]} < \infty\\(\textit{equiv.}\; &\lVert \mathbf{x} \rVert_{\textup{inhom $p$-var}} + \lVert \mathbf{x} \rVert_{\textup{inhom $\alpha$-H\"{o}l};[0,T]} < \infty).
        \end{aligned}
    \end{equation*}
    Moreover, we define
    \begin{equation*}
        \begin{aligned}
            &\widehat{C}^{\alpha,p}_o=\widehat{C}^{\alpha,p}_o([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^{k+1})) :=\\
            &:= \Big\{\widehat{\mathbf{x}}\in C_o^{\alpha,p}([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^{k+1})) \,:\, \widehat{\mathbf{x}}^{(1)}=\left(t,\mathbf{x}^{(1)}\right)\;\forall\,t\in[0,T],\,\mathbf{x}\in C^{\alpha,p}_o([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^k))\Big\}.
        \end{aligned}
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:03:39.758394+00:00","domain":"probability theory","id":"claim_d729cc7100cacae557b0f9657b02606d9825afb56acc1f836212a280a216ac50","kind":"lemma","schema_version":1,"statement":"[Lemma lem:moment-bound:H^0_epsilon of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] Assume the hypotheses of~Theorem (thm:well-posed of the paper) and let $U_0=(u_0,\eta_0)\in \mathcal{H}^0_\mu$. Then

\begin{enumerate}[noitemsep,topsep=0pt,wide=0pt,label=\arabic*.,ref=\theassumption.\arabic*]
\item For all $\beta$ sufficiently small independent of $\mu\in\mathcal{M}_\delta$,
\begin{equation}
\mathbb{E} \exp\left({\beta\Psi_0(U(t))}\right)\le e^{-c_0t}\exp\left({\beta\Psi_0(U_0)}\right)+C_0,\quad t\ge 0,
\end{equation}
where $\Psi_0$ is as in (equation form:Psi_0 of the paper) and $c_0=c_0(\beta)>0$, $C_0=C_0(\beta)>0$ do not depend on $U_0\in\mathcal{H}^0_\mu$, $t\ge 0$ and $\mu\in\mathcal{M}_\delta$.

\item For all $n\ge 1$, there exist positive constants $c_{0,n},\tilde{c}_{0,n}$ and $C_{0,n}$ independent of $U_0\in\mathcal{H}^0_\mu$, $t\ge 0$ and $\mu\in\mathcal{M}_\delta$ such that
\begin{equation}  
\emph{d} \Psi_0(U(t))^n\le -c_{0,n} \Psi_0(U(t))^n\emph{d} t+\tilde{c}_{0,n}\emph{d} t+\emph{d} M_{0,n}(t),
\end{equation}
where $M_{0,n}(t)$ is the semi-martingale given by
\begin{equation} 
M_{0,n}(t)=\int_0^t n\Psi_0(U(r))^{n-1}\langle u(t),Q\emph{d} w(r)\rangle_H.
\end{equation}
Furthermore,
\begin{equation} 
\mathbb{E}\Psi_0(U(t))^n \le e^{-c_{0,n}t}\Psi_0(U_0)^n+C_{0,n},\quad t\ge 0.
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:28:33.705575+00:00","domain":"probability theory","id":"claim_d72b363a693fa79bab596dbb5f2af14d141be265b67e87d509d03b2b7cd9ce59","kind":"concept","schema_version":1,"statement":"[Thm t:P0 of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] Let assumptions $\mathbf{H}^\mathrm{diss}_A$, $\mathbf{H}_{a,b,c}^{\mathrm{Lip}_b}$,
