	\item [\rm{iii.}] For any $i=0,\dots,T-1$, $j=i,\dots,T-1$ and $\theta >0$, conditional on $\sqrt{\widetilde{L}_{(v)}(T-i)}=\theta$, 
\begin{equation}
T_{\widetilde{v}_k}(T-j) \sim \Poigeo\left(\frac{\widetilde{\theta}_k}{j-i+1};\frac{1}{j-i+1}\right).
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:20:07.912391+00:00","domain":"probability theory","id":"claim_d74d7896c494e507149ca1be58060936019196489088063fadef1d0c9b4149c1","kind":"concept","schema_version":1,"statement":"[Thm BS2 of arXiv:2608.29914, 'Fixed points in abstract provability structures'] {beklemishev2016some}}]
