{"assumptions":[],"created_at":"2026-10-27T05:57:28.226118+00:00","domain":"probability theory","id":"claim_d75e8891e42881505271c33ff55dd8c1da940a21b7fe5c192f99e716fef3ba61","kind":"concept","schema_version":1,"statement":"[Lemma 8 (PDE and diffusion facts) of arXiv:2607.18032, 'FRSB in the SK spin glass: convergence to full-interval support at zero temperature'] Let $u:=u^{|\cdot|,\gamma}$ be the solution of \eqref{eq:zt-general-PDE}. For every $T<1$, the function $u$ is continuous in $(t,x)$ and smooth in $x$ on $[0,T]\times\R$.  It is even, convex, and one-Lipschitz in $x$, with
\begin{equation*}
 -1<u_x(t,x)<1,\qquad u_{xx}(t,x)>0
 \quad\text{and}\quad \lim_{x\to\pm\infty}u_x(t,x)=\pm1.
\end{equation*}
The stochastic differential equation
\begin{equation}
 \dd X_t=\gamma(t)u_x(t,X_t)\dd t+\dd W_t
 \quad\text{and}\quad X_0=0,

\end{equation}
has a unique weak solution. For every fixed $t>0$, $X_t$ has a smooth, positive, and even density, denoted by
\begin{equation}
 \rho_t(x):=\frac{\mathrm d\mathcal L(X_t)}{\mathrm d x}(x),
 \qquad \forall x\in\R.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:24:20.957392+00:00","domain":"probability theory","id":"claim_d75f68df1e8ff9e752e81b694e55f39f780c891703220df2adc15b7aaf7f7a7f","kind":"concept","schema_version":1,"statement":"[Lemma main:proof:lem2 of arXiv:2508.12464, 'On the Fitness Landscape in the $\NK$ Model'] Let $(g_k)_{1\leq k\leq M}$ be a sequence of centered Gaussian r.v. with $\mathbb{E} g_k^2\leq T^2$ for all $1\leq k\leq M.$ Then
	\begin{align*}
		\mathbb{E}\ln \sum_{k=1}^Me^{\beta g_k}\leq \left\{\begin{array}{ll}
			\ln M+\frac{\beta T^2}{2},&\mbox{if $0<\beta<\frac{\sqrt{2\ln M}}{T}$},\\
			\\
			\beta T\sqrt{2\ln M},&\mbox{if $\beta \geq \frac{\sqrt{2\ln M}}{T}$}.
		\end{array}
		\right.
	\end{align*}
	and
	$$
	\mathbb{E}\max_{1\leq k\leq M}g_k\leq T\sqrt{2\ln M}.
	$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:30:36.755346+00:00","domain":"probability theory","id":"claim_d7601ac3f5decf1b888aca0ce7981ebf747068314f50a00ed8254436b55ff145","kind":"lemma","schema_version":1,"statement":"[Lemma 5 of arXiv:2607.09246, 'Scaling limit of 1+1 dimensional directed polymer with power-law tail and spatial correlat'] Let \(h=h_N\) be a positive sequence with \(h_N\to\infty\); Assume that $ \mathfrak d_N(h)\le1 $ and, for all large \(N\),
\[
        2\beta_N k_N\Psi_h(y)\le1,
        \qquad(|y|>2h).
\]
Then, we have, uniformly over all paths \(S\in\mathcal B(h)\),
\begin{equation}
        \frac{
        \mathbb E_{\mathbb Q}\!\left[
        e^{\beta_NH_N^{\bar\omega}(S)}
        \left(
        e^{\beta_N\Delta H_N^{\mathrm{far},h}(S)}-1
        \right)^2;
        D_h^c
        \right]
        }
        {
        \mathbb E_{\mathbb Q}
        [e^{\beta_NH_N^{\bar\omega}(S)}]
        }
        \le C\mathfrak d_N(h),
\end{equation}
\begin{equation}
        \frac{
        \mathbb E_{\mathbb Q}\!\left[
        e^{\beta_NH_N^{\bar\omega}(S)}
        \left|
        e^{\beta_N\Delta H_N^{\mathrm{far},h}(S)}-1
        \right|;
        D_h^c
        \right]
        }
        {
        \mathbb E_{\mathbb Q}
        [e^{\beta_NH_N^{\bar\omega}(S)}]
        }
        \le C\sqrt{\mathfrak d_N(h)},
\end{equation}
and
\begin{equation}
        \frac{
        \mathbb E_{\mathbb Q}\!\left[
        e^{\beta_NH_N^{\bar\omega}(S)}
        e^{\beta_N\Delta H_N^{\mathrm{far},h}(S)};
        D_h^c
        \right]
        }
        {
        \mathbb E_{\mathbb Q}
        [e^{\beta_NH_N^{\bar\omega}(S)}]
        }
        \le 1+C\mathfrak d_N(h).
\end{equation}
Consequently, for every \(A\subseteq\mathcal B(h)\),
\begin{equation}
\begin{aligned}
&\mathbb E_{\mathbb Q}\left[
\left|
Z_N(\beta_N;\bar\omega+\Delta\omega^{\mathrm{far},h};A)
-
Z_N(\beta_N;\bar\omega;A)
\right|;
D_h^c
\right]                                                      \\
&\qquad\le
C\sqrt{\mathfrak d_N(h)}\,
\mathbb E_{\mathbb Q}[Z_N(\beta_N;\bar\omega;A)]
\end{aligned}
\end{equation}
and
\begin{equation}
        \mathbb E_{\mathbb Q}\left[
        Z_N(\beta_N;\bar\omega+\Delta\omega^{\mathrm{far},h};A);
        D_h^c
        \right]
        \le
        (1+C\mathfrak d_N(h))\,
        \mathbb E_{\mathbb Q}[Z_N(\beta_N;\bar\omega;A)] .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:02:08.142224+00:00","domain":"probability theory","id":"claim_d76129fa8633655ddac1f246958a502d696202e44d86afde8a63ec73d9b91edb","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] Let $k\in\bN$ and let $\cG_k$ be the set of  maps in $\cG$ with $k$ edges on the outer boundary.  Then 
\begin{enumerate}
    \item For each $k\geq 1$, there exists a   bijection between $\mathcal G_k$ and $\mathcal H_k$ which sends an oriented annular map to the associated pair of height functions and preserves the weights~\eqref{eq: planar map weight} and~\eqref{eq: lattice path weight}.
    \item Fix $b>0$. Let $G$ be sampled from $\mathcal G_{\lfloor b\sqrt{N}\rfloor} $ according to the weights~\eqref{eq: planar map weight} with associated height function $(\sfZ_j)_{0\leq j\leq n}$. Then as $N\to \infty$, the law of $(\frac{1}{\sqrt N}\sfZ_{\lfloor Nt \rfloor })_{0\leq \lfloor Nt \rfloor\leq n}$ converges in distribution to $\int_0^\infty \d a B^{\gamma, \bH}_{0, -a+ib}$ with respect to the metric~\eqref{eq:curve-metric}. The   parameter $\gamma$ is given by
    \begin{equation}

        \cos \ab(\frac{\pi\gamma^2}{4}) = \frac{2b_e + 2\sum_{i,j \in \bZ_{\ge 0}} ijb_{i,j}}{2b_e + \sum_{i,j\in \bZ_{\ge 0}}(i^2+j^2) b_{i,j}}
    \end{equation}
    and by choosing  numbers $\{b_e,b_{i,j}:i,j\in\bZ_{\geq0}\}$ properly, $\gamma$ may take every value in $(0,\sqrt{2})$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.877221+00:00","domain":"probability theory","id":"claim_d764991e8b15e3575deba6bdb2578a218bf247cda82bc712d8332e8e22195bbb","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] Fix any $\gamma>0$ and put $\ms_n:=\exp(-n^{1+\gamma})$ for integer $n\geq 2$. Let $N_1$ and $N_2$ be integer-valued, possibly dependent on $\gamma$, functions defined on some (not necessarily the same) right vicinities of $0$ and satisfying $\lim_{s\to 0+}(N_1(s))^s=1$ and $\lim_{s\to 0+}(N_2(s))^s=+\infty$. Then
\begin{equation}
\lim_{n\to\infty} g(\ms_n)\sum_{k=1}^{N_1(\ms_n)}\frac {a_k}{k^{1/2+\ms_n}} \tilde{\eta}_{k,1}(\ms_n)=0\quad\text{{\rm a.s.}}
\end{equation}
and
