{"assumptions":[],"created_at":"2026-10-27T16:50:26.914191+00:00","domain":"probability theory","id":"claim_d84eed1799766f72f84d9983445963500bd6da273e00703ca2615e8d5ef758f0","kind":"definition","schema_version":1,"statement":"[Definition def:set_hitting_animals of arXiv:2505.07145, 'Nonamenable Poisson zoo'] For any $K \subset \subset V(G)$, let us introduce the notation
	\begin{equation}

		Z(K) := 
		\left\{
			(x, H) \in Z \, : \, H \cap K \neq \emptyset
		\right\},
	\end{equation}
	the subset of animals that hit the set $K$.
	Analogously, let us also define, for any $k \in \mathbb{N}_{>0}$,
	\begin{equation}

		Z_k(K) := 
		\left\{
			(x, H) \in Z \, : \, H \cap K \neq \emptyset, \, \mathrm{Vol}((x,H)) = k
		\right\},
	\end{equation}
	and denote the finite union of such sets, for $R \in \mathbb{N}$, as
	\begin{equation}

		Z^R(K) :=
		\bigcup_{k = 0}^{R} Z_k(K) =
		\left\{
			(x, H) \in Z \, : \, H \cap K \neq \emptyset, \, \mathrm{Vol}((x,H)) \leq R
		\right\}.
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.257266+00:00","domain":"probability theory","id":"claim_d84f0e57b326c3edb616ddf59502b8f64eaf358fcb2637c72d2738c8ae47aa24","kind":"concept","schema_version":1,"statement":"[Thm 61 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Fix $t>0,\;x,y\in F,$ and $x_n,y_n\in F_n$.
Suppose that $(F,R,\mu)$ satisfies $\rm{(A1)}$
for $s_0,s_1>0$ with $s_0<s_1+1$,
and that
\begin{align*}
  h:=d_{\rm{H}}(F,F_n)^{\kappa}+d_{\BL^{\kappa}}(\mu,\mu_n)+d(x,x_n)+d(y,y_n)
\end{align*}
is less than $1/2$.
\begin{itemize}
  \item [$\mathrm{(i)}$]For each $\kappa\in [1/2,2/3)$, it holds that
\begin{align*}
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim h^E,
\end{align*}
where
\begin{align*}
  E=\frac{2(s_1-s_0+1)}{\left\{ (2\kappa+5)s_0+2\kappa+4 \right\}(s_1+2)+2(s_1-s_0+1)}.
\end{align*}
Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-2},\;t\in (0,1]$.
\item[$\mathrm{(ii)}$]If $(F,R,\mu)$ satisfies the assumption $\mathrm{(A2)}$, then it holds for $\kappa\in [1/2,1]$ that
\begin{align*}
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim h^E,
\end{align*}
where
\begin{align*}
  E=\frac{s_1-s_0+1}{(\kappa+2)(1+s_0)(s_1+2)+\frac{s_0}{2}+(s_1-s_0+1)}.
\end{align*}
Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-2},\;t\in (0,1]$.
\item[$\rm{(iii)}$]If $(F,R,\mu)$ satisfies the assumption $\mathrm{(A3)}$, then it holds for $\kappa\in [1/2,1]$ that
\begin{align*}
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim  h^{E_1}(\log(1/h))^{E_2},
\end{align*}
where
\begin{align*}
  E_1=\frac{s_1-s_0+1}{(2+\kappa)(1+s_0)\Theta+\frac{s_0}{2}+(s_1-s_0+1)},
  \quad E_2=\frac{(2+\kappa)\{s_1+2(2+s_0)(s_0-s_1)\}}{1-(2+s_0)(s_0-s_1)},
\end{align*}
and $\Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)}$.
Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-2},\;t\in (0,1]$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:25:06.181815+00:00","domain":"probability theory","id":"claim_d8500d79f074e9c8f9df50705b054018f8751bfc5e38042f222b24063a599e2a","kind":"lemma","schema_version":1,"statement":"[Lemma 7 (Exponential stability) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] For $\theta\in\Theta$, there exists a unique solution $\vartheta_{\mrm U}(t;\theta)\in\Theta$ for all $t\ge 0$ to 
