{"assumptions":[],"created_at":"2026-10-26T19:46:12.275477+00:00","domain":"probability theory","id":"claim_d86b9e3dc2da0e639761dfa9599aa1be98de749bc88a852fd4d109c15dc14062","kind":"concept","schema_version":1,"statement":"[Proposition 24 of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $\bG^{a, L} \in \cFG$, where $a \in \bR^{Nd}$ and $L \in \mathscr{L}(N, d)$.
\begin{itemize}
\item[(i)] $\bG^{a,L} \in \cFG_{\mgle}$ if and only if $a_1 = \cdots = a_N$ and
\[
L_{t, t} = L_{t+1, t} = \cdots = L_{N, t}, \quad t \in [N].
\]
That is,
\begin{equation*}
X_{t+1} = X_t + L_{t+1,t+1}\epsilon_{t+1}, \quad t \in [N-1].
\end{equation*}
\item[(ii)] $\bG^{a,L} \in \cFG_{\Markov}$ if and only if for each $t \in [N-1]$ there exists $\Phi_t \in \bR^{d \times d}$ such that 
\begin{equation} 
\begin{bmatrix}
L_{t+1,1} & \cdots & L_{t+1,t}
\end{bmatrix} = \Phi_t \begin{bmatrix} L_{t,1} & \cdots & L_{t,t} \end{bmatrix}.
\end{equation}
That is,
\[
X_{t+1} = (a_{t+1} - \Phi_t a_t) + \Phi_t X_t  + L_{t+1,t+1} \epsilon_{t+1}, \quad t \in [N-1].
\]
\end{itemize}
In particular, we have $\cFG_{\mgle} \subset \cFG_{\Markov}$. We let
\begin{equation*}
\mathscr{L}_{\mgle}(N, d) := \{L \in \mathscr{L}(N, d)
: \bG^{L} \in \cFG_{\mgle}\}
\end{equation*}
be the set of Cholesky factors of Gaussian martingales. Similarly, we let
\[
\mathscr{L}_{\mathrm{Markov}}(N, d) := \{L \in \mathscr{L}(N, d)
: \bG^{L} \in \cFG_{\mathrm{Markov}}\}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.113228+00:00","domain":"probability theory","id":"claim_d86cedc17ad5431087784e395941b3c6c40e04464db9da299e2f8c319c87e99b","kind":"lemma","schema_version":1,"statement":"[Lemma lem:weight-removal-interface-match of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Put $\chi_{\rm rad}=50r^2/29$ and define
\begin{equation}
 \begin{aligned}
 \varphi_-(r)&=\sum_{n=0}^\infty a_n\chi_{\rm rad}^n,
 &a_0&=1,
 &a_n&=-\frac{3}{n!(2n-1)(2n+1)(2n+3)}\quad(n\geq1),\\
 \varphi_+(r)&=r-\frac{39}{25r}-\frac{507}{625r^3}
                 -\frac{6591}{15625r^5},
 &&& &r>0.
 \end{aligned}

\end{equation}
The two profiles solve
\begin{equation}
 \frac{29}{200}\varphi_-''
 +\left(\frac{29}{50r}-\frac r2\right)\varphi_-'
 +\frac12\varphi_-=0,
 \qquad
 \frac{13}{50}\varphi_+''
 +\left(\frac{39}{25r}-\frac r2\right)\varphi_+'
 +\frac12\varphi_+=0.

\end{equation}
There exist matching parameters
\begin{equation*}
 R_{\mathrm{int}}\in
 \left(\sqrt{\frac{29}{15}},\frac{\sqrt{203}}{10}\right),
 \qquad \mathfrak s_{\mathrm{match}}\ne0,
\end{equation*}
For these parameters, the matched profile
\begin{equation}
 \varphi_{\rm dw}(r)=
 \begin{cases}
  \varphi_-(r),&0\leq r\leq R_{\mathrm{int}},\\
  \mathfrak s_{\mathrm{match}}\varphi_+(r),&r\geq R_{\mathrm{int}}
 \end{cases}

\end{equation}
is $C^1$ and piecewise smooth.","status":"unverified"}

