{"assumptions":[],"created_at":"2026-10-28T02:31:45.389532+00:00","domain":"probability theory","id":"claim_d897772fa28bfe6ac01531801d794ac8f9c064bc095967e5391550a2bf06f61d","kind":"concept","schema_version":1,"statement":"[Thm cltn of arXiv:2412.06480, 'A SIR epidemic model on a refining spatial grid \\ II-Central limit theorem'] ~\\
	Assume that $\sqrt{\mathbf{N}}\big( Z_{\mathbf{N},\varepsilon}(0)- Z_{\varepsilon}(0)\big) \longrightarrow 0 $, as $ \mathbf{N}\to \infty $.\\ Then, as $ \mathbf{N} \rightarrow + \infty$ , $\big\{\begin{array}{rl}  \Psi_{\mathbf{N},\varepsilon} (t) ,  \; t\geq 0   \end{array} \big\} \Longrightarrow \big\{\begin{array}{rl} \Psi_{\varepsilon}(t) , \; t\geq 0  \end{array}\big\} ,  $ for the topology of locally uniform convergence, where  the limit process
	$ \Psi_{\varepsilon}(t) := \left( \begin{array}{cl}
	U_{\varepsilon}(t)\\
	V_{\varepsilon}(t)\\
	W_{\varepsilon}(t)
	\end{array}
	\right) $ satisfies
	\begin{equation}
	\Psi_{\varepsilon}(t) = \int_0^t \nabla_{\!\!z} b_{\varepsilon}\big(r,Z_{\varepsilon}(r)\big) \Psi_{\varepsilon}(r)dr + \sum_{j=1}^{K}\int_0^t \sqrt{\beta_j\big(r,Z_{\varepsilon}(r)}\big)dB_j(r) , \quad t \geq 0, 
	\end{equation}
	and $ \displaystyle \{ B_1(t), B_2(t), \cdots, B_K(t) \}$ are mutually independent standard Brownian motions. \\
	More precisely, by setting $ A_{\varepsilon}=S_{\varepsilon} +I_{\varepsilon}+R_{\varepsilon}$, for any site $x_i$, the limit $(U_{\varepsilon}, V_{\varepsilon}, W_{\varepsilon})^{\mathtt{T}}$ satisfies the following system
	\begin{eqnarray}
	\hspace{-0.5cm}U_{\varepsilon}(t,x_i)
	&  = & \mu_{S} \int_0^t \Delta_{\varepsilon}U_{\varepsilon}(r,x_i)dr -  \int_0^t \beta(x_i) \dfrac{I_{\varepsilon}(r,x_i)\big(I_{\varepsilon}(r,x_i)+R_{\varepsilon}(r,x_i)\big)V_{\varepsilon}(r,x_i)}{A_{\varepsilon}^2(r,x_i)} dr\nonumber  \\
	&- & \int_0^t\beta(x_i) \dfrac{S_{\varepsilon}(r,x_i)\big(S_{\varepsilon}(r,x_i)+R_{\varepsilon}(r,x_i)\big)U_{\varepsilon}(r,x_i)}{A_{\varepsilon}^2(r,x_i)}  dr
	+\int_0^t \sqrt{\beta(x_i)\dfrac{S_{\varepsilon}(r,x_i)I_{\varepsilon}(r,x_i)}{A_{\varepsilon}(r,x_i)}}\; \; dB_{x_i}^{inf}(r)\nonumber  \\
	&- &\sum_{y_i \sim x_i}\int_0^t\sqrt{\dfrac{\mu_{S}}{\varepsilon ^2} S_{\varepsilon}(r,x_i)}\; \; dB_{x_iy_i}^S(r) 
	+\sum_{y_i \sim x_i}\int_0^t\sqrt{\dfrac{\mu_{S}}{\varepsilon ^2} S_{\varepsilon}(r,y_i)}\; \; dB_{y_ix_i}^S(r) \nonumber
	\end{eqnarray}
\begin{eqnarray}
V_{\varepsilon}(t,x_i)
&=& \mu_{I} \int_0^t \Delta_{\varepsilon}V_{\varepsilon}(r,x_i)dr +\int_0^t \beta(x_i) \dfrac{I_{\varepsilon}(r,x_i)\big(I_{\varepsilon}(r,x_i)+R_{\varepsilon}(r,x_i)\big)V_{\varepsilon}(r,x_i)}{A_{\varepsilon}^2(r,x_i)} dr\nonumber  \\
&+&\int_0^t\beta(x_i) \dfrac{S_{\varepsilon}(r,x_i)\big(S_{\varepsilon}(r,x_i)+R_{\varepsilon}(r,x_i)\big)U_{\varepsilon}(r,x_i)}{A_{\varepsilon}^2(r,x_i)}dr-\int_0^t \alpha(x_i)V_{\varepsilon}(r,x_i)dr\nonumber\\
&-&\int_0^t\sqrt{\beta(x_i)\dfrac{S_{\varepsilon}(r,x_i)I_{\varepsilon}(r,x_i)}{A_{\varepsilon}^2(r,x_i)}}\; \; dB_{x_i}^{inf}(r)+\int_0^t\sqrt{\alpha(x_i) I_{\varepsilon}(r,x_i)}\; \; dB_{x_i}^{rec}(r) \nonumber\\
&-& \sum_{y_i \sim x_i}\int_0^t\sqrt{\dfrac{\mu_{I}}{\varepsilon ^2} I_{\varepsilon}(r,x_i)}dB_{x_iy_i}^I(r)+ \sum_{y_i \sim x_i}\int_0^t\sqrt{\dfrac{\mu_{I}}{\varepsilon ^2} I_{\varepsilon}(r,y_i)}\; \; dB_{y_ix_i}^I(r)  \nonumber 
\end{eqnarray}
\begin{eqnarray}
W_{\varepsilon}(t,x_i) 
& =& \mu_{R} \int_0^t \Delta_{\varepsilon}W_{\varepsilon}(r,x_i)dr+ \int_0^t \alpha(x_i) V_{\varepsilon}(r,x_i)dr-\int_0^t\sqrt{\alpha(x_i) I_{\varepsilon}(r,x_i)}\; \; dB_{x_i}^{rec}(r) \nonumber
\\[2mm]
&-& \sum_{y_i \sim x_i}\int_0^t\sqrt{\dfrac{\mu_{R}}{\varepsilon ^2} R_{\varepsilon}(r,x_i)}\; \;dB_{x_iy_i}^R(r)+ \sum_{y_i \sim x_i}\int_0^t\sqrt{\dfrac{\mu_{R}}{\varepsilon ^2} R_{\varepsilon}(r,y_i)}\; \; dB_{y_ix_i}^R(r), \nonumber 
\end{eqnarray} 
where $\{ B_{x_i}^{inf}: x_i\in \mathrm{D}_\varepsilon \}$ , $\{ B_{x_i}^{rec} : x_i\in \mathrm{D}_\varepsilon \}$ , $\{ B_{x_i y_i}^S   : y_i \sim x_i\in \mathrm{D}_\varepsilon \}$ , $\{ B_{x_i y_i}^I   : y_i \sim x_i\in \mathrm{D}_\varepsilon \}$ and $\{ B_{x_i y_i}^R   : y_i \sim x_i\in \mathrm{D}_\varepsilon \}$ are  families of independent Brownian motions. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:41:33.836026+00:00","domain":"probability theory","id":"claim_d898114342d890944bc4d5e12e0c1779b12ebb1f04c4d3029c4b9fe668566295","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.11385, 'Quantitative large population limit for non exchangeable diffusions in Fisher information'] We let $\displaystyle \delta_{N}=\max_{(i,j) \in v^{2}} \xi_{i,j}^{N}$ and
\[H_{t}^{v}=H \left( P_{t}^{v,N}|Q_{t}^{v,N} \right), \qquad \quad I_{t}^{v}=I\left(P_{t}^{v,N}|Q_{t}^{v,N} \right).\]
Fix a $T>0$ and suppose that there exists a constant $C$ such that
\begin{equation*}
\forall v \subset [N], \
    H_{0}^{v}+I_{0}^{v} \leq C \left(\delta_{N} |v|+1\right)\left( \sum_{(i,j)\in v^{2}} \left(\xi_{i,j}^{N} \right)^{2}+\delta_{N} \sum_{(i,j) \in v} \left(\xi^{T} \xi+\xi \xi^{T} \right)_{i,j}+\delta_{N}^{2} |v| \right).
\end{equation*}
Suppose moreover that $\left(P_{0}^{[N],N}, Q_{0}^{[N],N}\right)$ satisfies Hypothesis \ref{hyp-princ}.
We distinguish two set of assumptions:
\begin{itemize}
    \item Torus Case. Suppose that $b$ is smooth and assume that that  $\nabla^2 \log Q_{0}^{u,N}$ is bounded with constants that do not depend on $u$ or $N$.
    \item $\mathbb{R}^d$ case. Suppose that $b$ is smooth bounded, with bounded derivatives and assume that there exists $C>0$ such that 
    \begin{equation*}
   \forall u \in [0,1], \ \sup_{t\in [0,T]}\Vert \nabla^2 \log Q_{t}^{u,N}\Vert \leq C.
\end{equation*}

\end{itemize}
Then, there exists a constant $M_{T}$ (that does not depend on v,N) such that 
\begin{equation*}
\forall v \subset [N], \
    H_{T}^{v}+I_{T}^{v} \leq M_{T} \left(\delta_{N} |v|+1\right)\left( \sum_{(i,j)\in v^{2}} \left(\xi_{i,j}^{N} \right)^{2}+\delta_{N} \sum_{(i,j) \in v} \left(\xi^{T} \xi+\xi \xi^{T} \right)_{i,j}+\delta_{N}^{2} |v| \right).
\end{equation*}
In particular, if $\xi_{i,j}^{N}=G_{N} \left( \frac{i}{N}, \frac{j}{N} \right)$ with $G_{N}$ a graphon with values in $[0,1]$, we have 
\begin{equation*}
\forall v \subset [N], \
    H_{T}^{v}+I_{T}^{v} \leq M_{T} \frac{\left|v \right|^{2}}{N^{2}}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:19:06.724220+00:00","domain":"probability theory","id":"claim_d8993e8433e3a953a4bf40f2097d7ecf2bddae45c9d54d81d2921e7543eb50db","kind":"concept","schema_version":1,"statement":"[Proposition prop:H01r of arXiv:2606.02340, 'Transitivity in Inhomogeneous Random Tournaments'] Suppose $\hat \sigma^2_{T_n}$ be as defined in 
