{"assumptions":[],"created_at":"2026-10-27T23:11:09.268796+00:00","domain":"probability theory","id":"claim_d9aa8adc22690d3ecdb6a5a9ebe04064d8c83e94937b714f59db81a15f5e6e5f","kind":"definition","schema_version":1,"statement":"[Definition def: solution of arXiv:2411.05924, 'Non-negative Martingale Solutions to the Stochastic Porous Medium Equation with Sticky Beh'] A tuple $((\Omega, \mathcal F, \mathbb F, \mathbb P), u, W)$, where $(\Omega, \mathcal F, \mathbb F, \mathbb P)$ is a stochastic basis supporting a $U$-valued $\mathbb F$-adapted $Q$--Wiener process $W$ and an $\mathbb F$-adapted process $u$, is called a \emph{non-negative martingale solution to the stochastic porous medium equation} (equation eq: intro1 of the paper)--(equation eq: intro3 of the paper) if
    \begin{enumerate}[label=(\roman*)]
        \item $u \in \bigcap_{\delta\in(0,1)} \Xi_{\mathfrak u}^\delta$;
        \item $u(t,x) \geq 0$ $\mathbb P \otimes \mathrm d t \otimes \mathrm d x$-a.s.;
        \item for all $\varphi \in C^3_c([0,1],\mathbb R)$, $\mathbb P \otimes \mathrm d t$-a.s.~we have that 
        \begin{align}
            \nonumber
            &\langle \varphi, u(t) \rangle = \left\langle \varphi, u_0 \right\rangle + \int_0^t \left\langle \partial_x^2 \varphi, u^\alpha(r) \right\rangle \mathrm d r \\

            &\qquad+ \int_0^t \langle \varphi, \1_{u(r)>0} B(u(r)) \mathrm d W(r) \rangle + \int_0^t \langle \varphi, \1_{u(r)=0} R(u(r)) \rangle \mathrm d r.
        \end{align}
    \end{enumerate}
    Furthermore, let $\mathcal S: L^2(\mathcal Q_T) \rightarrow \mathbb R$ be a functional given by
    \begin{equation}

        \mathcal S(u) := \iint_{\mathcal Q_T} \1_{u(t,x)=0} \mathrm d t \mathrm d x.
    \end{equation}
    We say that the system (equation eq: intro1 of the paper)--(equation eq: intro3 of the paper) exhibits \textit{sticky behavior} if
    \begin{equation}

        \mathbb P\left( \mathcal S( u) > 0 \right) > 0.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:25:55.318255+00:00","domain":"probability theory","id":"claim_d9ab9629c8f2d7ea99c0810aaceaffb2103f0d8a1a8bb11c2c93d81ecde89421","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] \begin{itemize}
\item The functions $\Theta_1$ and $\Theta_3$ satisfy the following heat equations:
\begin{equation}
	\partial_r \Theta_1(r; z) = \partial_z^2 \Theta_1(r; z), \quad 
	\partial_r \Theta_3(r; z) = \partial_z^2 \Theta_3(r; z).
\end{equation}
\item The function $\Theta_1(r; \cdot)$ has period $2\pi$ while the function $\Theta_3(r; \cdot)$ has anti-period $2\pi$:
\begin{equation} 
	\Theta_1(r; z)=-\Theta_1(r; z+2\pi), \quad \Theta_3(r; z)=\Theta_3(r; z+2\pi).
\end{equation}
\item The functions $\Theta_1$ and $\Theta_3$ satisfy the following imaginary shift identities:
\begin{equation}
	\Theta_1(r; z + \ii r) = \ii \ee^{\frac{r}{4} - \frac{\ii z}{2}} \Theta_3(r; z), \quad 
	\Theta_3(r; z + \ii r) = \ii \ee^{\frac{r}{4} - \frac{\ii z}{2}} \Theta_1(r; z).
\end{equation}
\item The functions $\Theta_1$ and $\Theta_3$ have the following asymptotics as $r\to \infty$: for $x\in \R$, we have

\begin{align} 
	\Theta_1(r; x)= 2 \ee^{-r/4} \sin\left(\frac{x}{2}\right) (1+O(1)\ee^{-2r}),\quad
	\Theta_3(r; x)= 1 + O(1)\ee^{-r},
\end{align}
where the $O(1)$ terms have upper bounds independent of $x$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:56:37.647960+00:00","domain":"probability theory","id":"claim_d9ac2d6c8f2aab3f88e9197458f031040baddb24b054001bd225379f27b37d5b","kind":"lemma","schema_version":1,"statement":"[Lem surface tension expression of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $L,M\geq 1$ and $\beta>0$. One has
