		f_{X_1-X_2}(x)&=\frac{\mathrm{e}^{-2\lambda}}{2^{\alpha_1+\alpha_2}\beta\sqrt{\pi}}\bigg(\frac{\lambda}{2}\bigg)^{(1-\alpha_1-\alpha_2)/2}\bigg(\frac{|x|}{\beta}\bigg)^{\alpha_1+\alpha_2}\nonumber\\
		&\quad\times\int_{0}^{\infty}t^{-(\alpha_1+\alpha_2+2)/2}\exp\bigg(-t-\frac{x^2}{4\beta^2t}\bigg)I_{\alpha_1+\alpha_2-1}\bigg(\frac{|x|}{\beta}\sqrt{\frac{2\lambda}{t}}\bigg)\,\mathrm{d}t.
