{"assumptions":[],"created_at":"2026-10-27T19:48:47.286363+00:00","domain":"probability theory","id":"claim_da9e824d4a19e7e69c885cea755f9ed3e1c62a15bb0f2ca9f59840d29373b513","kind":"lemma","schema_version":1,"statement":"[Lemma opt2prefix of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $f\in \mathbb{R}$, $q\in (0,1)$ and $u\in (0,1)$. Let $\zeta\in \mathrm{Prefix}_2(u,q)$ satisfy the assumptions of Proposition (prop:annealed 0 of the paper). Let $(X_t)_{t\in [0,1]}$ be the Auffinger--Chen process
		\begin{equation*}
			\begin{cases}
				\mathrm{d} X_t=\xi''(t)\zeta([0,t])\partial_x \Phi_\zeta(t,X_t)\mathrm{d} t+\sqrt{\xi''(t)} \mathrm{d} B_t\\
				X_0=0.
			\end{cases}
		\end{equation*}
		For every $s\in [0,1]$, set
		\begin{equation*}
			H_\zeta(s):=\frac{1}{2}\int_s^1 \xi''(r)\Bigl(\mathbb{E}[(\partial_x\Phi_\zeta(r,X_r))^2]-r\Bigr)\mathrm{d} r.
		\end{equation*}
		Then, the following hold:
		\begin{enumerate}[label=(\roman*)]
			\item \begin{equation}
				-\mathbb{E}[\Phi_\zeta(q,X_q)]+\int_0^q t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_q^1 t\xi''(t)\zeta([0,t])\mathrm{d} t=-f,
			\end{equation}
			\item \begin{equation}
				\mathbb{E}[(\partial_x\Phi_\zeta(q,X_q))^2]=q,
			\end{equation}
			\item  \begin{equation}
				\mathrm{supp}(\zeta)\cap [q,1]\subset \underset{[q,1]}{\mathrm{arg\,min}}(H_\zeta).
			\end{equation}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.617077+00:00","domain":"probability theory","id":"claim_daa0fee468b67143da89c61fb9edc7613159c8bd0322a8eb8f256d8dbde1f976","kind":"concept","schema_version":1,"statement":"[Lem 21 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $d\ge 2$ and for $\lambda:=(\lambda_1,\lambda_2)\in\a^\ast_{\Q_{d-1},\C}$ let $\varphi_\lambda\in\1_{d-1}\cdot|\det|^{\lambda_1}\boxplus\1_1\cdot|\cdot|^{\lambda_2}$ be a normalized factorizable vector. If $\varphi_\lambda$ is holomorphic in a sufficiently small neighbourhood of the hyperplane $\lambda_1-\lambda_2=\tfrac{d}{2}$ then $\Eis(\varphi_\lambda)$ has at most a simple polar divisor along the same hyperplane, where the residue is given by
		\begin{equation*}
