\end{equation}
and further,
\begin{equation}
    \max_{\kappa\in \Nbb^n:|\kappa|=k}\left\|\Dop^\kappa f\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-iso-Gaussian}}}(p)^k\, \frac{\Wop^{\geq k}(f)}{\binom{n+k-1}{k}} \left[1+ \frac{1}{2k} \ln\left(\frac{\binom{n+k-1}{k}}{\Wop^{\geq k}(f)}\right)\right]^{\frac{kp}{2}},
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-iso-Gaussian}}}(p) = C^{\text{\rm\ref{thm:high-order-Tal-isoper-Boolean}}}(p) \gtrsim 2-p$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

