{"assumptions":[],"created_at":"2026-10-26T19:43:44.249413+00:00","domain":"probability theory","id":"claim_db540f530954774e8c2e49fa86d4e5fd9f4ea8612aba46b26356443641f5b744","kind":"concept","schema_version":1,"statement":"[Lemma 30 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Let $u_{t_j, k}, v_{t_j, k}$  be given as in \eqref{eqn: eot_cost_expand} with $t= t_{j-1}$ and $\varepsilon=t_j-t_{j-1}$.

Recall the negative self-entropy functional $\m H(\rho)\coloneqq \int_{\mb T^d}\rho(x)\log\rho(x)\,\dd x$ for $\rho\in\ms P_{ac}(\mb T^d)$.
Define
\begin{align*}
S_j&\coloneqq\frac{1}{\varepsilon_j}\bigg[\W_2^2(\rho_{t_{j-1}}^\nu, \rho_{t_j}^\nu) - \frac{\varepsilon_j}{2}\big[\m H(\rho_{t_{j-1}}^\nu) + \m H(\rho_{t_j}^\nu)\big] + \frac{\varepsilon_j}{8}\int_{t_{j-1}}^{t_j}\!\int_{\mb T^d}\|\nabla\log\bar\rho_{t}^\nu\|^2\bar\rho_t^\nu\,\dd x\dd t\bigg]\\
&\qquad - \bigg[\int_{\mb T^d}\left(\log u_{t_{j-1},0} + \varepsilon_j\frac{u_{t_{j-1},1}}{u_{t_{j-1},0}}\right)\,\dd\rho_{t_{j-1}}^\nu + \int_{\mb T^d}
\left(\log v_{t_{j-1},0} + \varepsilon_j\frac{v_{t_{j-1},1}}{v_{t_{j-1},0}}\right)\,\dd\rho_{t_j}^\nu\bigg].
\end{align*}
Then, there are remainder terms $\delta_{1,j}$ and $\delta_{2,j}$ (c.f. Appendix~\ref{app: simplification} for explicit expressions) such that
\begin{align*}
S_j &= \frac{1}{2}\int_{t_{j-1}}^{t_j}\!\int_{\mb T^d}\Big\|\nabla\Phi_{t_{j-1}}^\mu - \nabla\bar \Phi_t^\nu - \frac{1}{2}\nabla\log\frac{\rho_{t_{j-1}}^\mu}{\bar\rho_t^\nu}\Big\|^2\,\dd\bar\rho_t^\nu\dd t 
- \KL(\rho_{t_{j-1}}^\nu\,\|\,\rho_{t_{j-1}}^\mu) - (\varepsilon_j\delta_{1,j} + \delta_{2,j}).
\end{align*}
Moreover, these remainder terms satisfy
\begin{align*}
\sum_{j=1}^m \varepsilon_j \delta_{1,j} &\leq \sup_{j\in[m]}\Lip\big(v_{t_{j-1}, 1}v_{t_{j-1}, 0}^\dagger\big)\cdot \sqrt{\sum_{j=1}^m\frac{\W_2^2(\rho_{t_{j-1}}^\nu, \rho_{t_j}^\nu)}{\varepsilon_j}}\cdot \max_{j\in[m]}\varepsilon_j\\
\sum_{j=1}^m \delta_{2,j} &\leq \frac{1}{4} \left[\sup_{t\in[0,1]} \Big\|\frac{\partial}{\partial t}v_{t,0}\Delta v_{t,0}^\dagger\Big\|_{\m C^0} + \sup_{j\in[m]}\Lip\big(v_{t_{j-1},0}\Delta v_{t_{j-1},0}^\dagger\big)\sqrt{\sum_{j=1}^m \frac{\W_2^2(\rho_{t_{j-1}}^\nu, \rho_{t_j}^\nu)}{\varepsilon_j}}\right]\cdot\max_{j\in[m]} \varepsilon_j.
\end{align*}
