{"assumptions":[],"created_at":"2026-10-27T11:15:34.474321+00:00","domain":"probability theory","id":"claim_dbcba3e8bc5e92ac632b0e3935d7d78ebe4ee24f4f323d8c9dfd4f8cd9c03847","kind":"concept","schema_version":1,"statement":"[Proposition 3 (Calabi symmetry = the ansatz over $\mathbb{CP}^{n-1}$) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Calabi symmetry is precisely the circle-bundle ansatz \eqref{eq:ansatz-metric} satisfying the Kähler condition \eqref{eq:kahler-condition} with the following data:

	\begin{itemize}
		\item \textbf{Number of factors and base:} $r = 1$, $N = N_1 = \mathbb{CP}^{n-1}$ (so $n_1 = n - 1$), with $g_1 = 2\, g_{FS}$, $p_1 = n$;
		\item \textbf{Circle bundle:} $P = S^{2n-1} \subset \mathbb{C}^n$ the unit sphere, with the $\mathrm{U}(1)$-action $z \mapsto e^{\sqrt{-1}\varphi} z$ and $\pi : S^{2n-1} \to \mathbb{CP}^{n-1}$ the Hopf fibration, i.e. $e(P) = a_1$ and $q_1 = 1$;
		\item \textbf{Vertical field:} $\xi = \sqrt{-1} \sum_{j=1}^n \big( z_j \partial_{z_j} - \bar{z}_j \partial_{\bar{z}_j} \big)$, the generator of the scalar rotation;
		\item \textbf{Connection form:} $\theta = \frac{\sqrt{-1}}{2} \big( \bar{\partial}\rho - \partial\rho \big)$ (the form denoted $\eta$ in parts of the literature);
		\item \textbf{Identification of the manifold:} $I \times S^{2n-1} \xrightarrow{\;\cong\;} \mathbb{C}^n \setminus \{0\}$ (or an annulus), $(s, p) \mapsto e^{\rho(s)/2}\, p$, where $s$ and $\rho$ are related by $ds = \sqrt{u_{\rho\rho}/2}\; d\rho$;
		\item \textbf{Warping functions:}
	\end{itemize}

	\begin{equation}
		H \;=\; \sqrt{2\, u_{\rho\rho}}, \qquad F_1 \;=\; \sqrt{u_{\rho}} \qquad (\text{composed with } \rho = \rho(s)).
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:14:37.646785+00:00","domain":"probability theory","id":"claim_dbcbbbca9dc4dd629c49bfb63cd52bd97a82c901ed4253834be648295ea7a3b8","kind":"theorem","schema_version":1,"statement":"[Theorem 3 of arXiv:2608.19560, '\textbf{Computing transient probabilities in Markovian queues with balking conditional on '] The PGF $\pi_{k,\ell,s}^*(z,t \mid K)$ conditional on exactly $K$ customers
