{"assumptions":[],"created_at":"2026-10-28T00:52:17.577895+00:00","domain":"probability theory","id":"claim_dbcc8a5b2cfbdf909370d5f2afdc011cb7b828615c864fd529f5addea4dde2fd","kind":"theorem","schema_version":1,"statement":"[Theorem t:Girsanov of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Fix~$\pi\in\msP(\mbfT_\circ)$ and suppose that Assumption~(ass:Girsanov of the paper) is satisfied.
Then, the quadratic form~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ defined by
\begin{equation}
\begin{gathered}
\msD(\widehat\mcE_\pi^\phi)\eqdef \set{u\in \msD(\widehat\mcE_\pi)^\bullet_{\loc} \cap L^2(\mcQ_\pi^\phi) : \int_\msP \widehat\mcG_\pi(u)\, \mathop{}\!\mathrm{d}\mcQ_\pi^\phi<\infty }\,\mathrm{,}\;\,
\\
\widehat\mcE_\pi^\phi(u,v)\eqdef \int_\msP \widehat\mcG_\pi(u,v)\, \mathop{}\!\mathrm{d}\mcQ_\pi^\phi \,\mathrm{,}\;\, \qquad u,v\in \msD(\widehat\mcE_\pi^\phi) \,\mathrm{,}\;\, 
\end{gathered}
\end{equation}
is a $\tau_\mrma$- and $\tau_\mrmn$-quasi-regular local Dirichlet form on~$L^2(\mcQ_\pi^\phi)$.

If, additionally,
\begin{equation}
\phi\in L^2(\mcQ_\pi) \qquad \text{and} \qquad\int \widehat\mcG_\pi(\phi) \mathop{}\!\mathrm{d} \mcQ_\pi <\infty \,\mathrm{.}
\end{equation}
Then, 
\begin{enumerate}[$(i)$]
\item the form~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ is additionally strongly local and recurrent;
\item for the generator~$\big({\widehat\mcL_\pi^\phi,\msD(\widehat\mcL_\pi^\phi)}\big)$ of~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ we have~$\hCylP{}{0}\subset \msD(\widehat\mcL_\pi^\phi)$ and
\[
\widehat\mcL_\pi^\phi u= \widehat\mcL^\phi u\eqdef \widehat\mcL u+\phi^{-1}\,\widehat\mcG_\pi(\phi, u) \quad \text{on}\quad \hCylP{}{0} \,\mathrm{.}
\]

\item $\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ is properly associated with the $\mcQ_\pi^\phi$-symmetric process~$\widehat\mcW_\pi^\phi$, which is thus recurrent (in particular: conservative) and a right Borel process for both~$\tau_\mrma$ and~$\tau_\mrmn$;

\item a $\mcQ_\pi^\phi$-measurable set~$\mbfA\subset \msP$ is $\widehat\mcE_\pi^\phi$-invariant if and only if it is $\widehat\mcE_\pi$-invariant;

\item 
$\widehat\mcW^\phi_\pi$ is a solution to the martingale problem for~$\ttparen{\widehat\mcL^\phi,\hCylP{}{0}}$. 
In particular, for every~$u\in\hCylP{}{0}$ ($\subset \mcC_b(\tau_\mrma)$), the process
\begin{equation}
M^{\class{u}}_t\eqdef u(\widehat\mcX^{\pi,\phi}_t)- u(\widehat\mcX^{\pi,\phi}_0)-\int_0^t (\widehat\mcL^\phi u)(\widehat\mcX^{\pi,\phi}_s)\mathop{}\!\mathrm{d} s
\end{equation}
is an adapted square-integrable martingale with quadratic variation
\begin{equation}
\tquadvar{M^{\class{u}}}_t = \int_0^t \widehat\mcG(u)(\widehat\mcX^{\pi,\phi}_s)\mathop{}\!\mathrm{d} s \,\mathrm{.}
\end{equation}
\end{enumerate}

Finally, suppose, in addition to~(equation eq:t:Girsanov:00 of the paper), that
\begin{equation}
\phi^2\in L^2(\mcQ_\pi) \qquad \text{and}\qquad \int \phi^2\, \widehat\mcG_\pi(\phi)\mathop{}\!\mathrm{d}\mcQ_\pi <\infty\,\mathrm{.}
\end{equation}
Then, additionally,
\begin{enumerate}[$(i)$, resume]
\item
$\hCylP{}{0}$ is a form core for~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$.

\item 
$\widehat \mcL^\phi \hCylP{}{0}\subset L^1(\mcQ_\pi^\phi)$ and there exists a unique strongly continuous semigroup on~$L^1(\mcQ_\pi^\phi)$ the generator of which extends~$\tparen{\widehat\mcL^\phi,\hCylP{}{0}}$.
In particular, the self-adjoint operator $\big({\widehat\mcL_\pi^\phi,\msD(\widehat\mcL_\pi^\phi)}\big)$ is the unique Markovian extension of $\tparen{\widehat\mcL_\pi^\phi,\hCylP{}{0}}$, and~$\big({\widehat\mcE_\pi^\phi,\msD(\widehat\mcE_\pi^\phi)}\big)$ is the unique Dirichlet form extending~$\tparen{\widehat\mcE_\pi^\phi,\hCylP{}{0}}$;

\item 
$\widehat\mcW_\pi^\phi$ is the unique ---up to~$\mcQ_\pi^\phi$-equivalence--- $\mcQ_\pi^\phi$-sub-stationary $\mcQ_\pi^\phi$-special standard process solving the martingale problem~(equation eq:t:Girsanov:1 of the paper).
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.562580+00:00","domain":"probability theory","id":"claim_dbd0a335f497bfe1f08ef21b67c8e1bbc5b0d3bd98fbbccec3ede27dacc1f9ea","kind":"lemma","schema_version":1,"statement":"[Lemma Generic Morse property of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:Morse}
For fixed \(N,p\), the set of coefficient tensors for which the restriction of \(H_N\) to \(\mathbb S_N\) is not Morse is contained in a proper real algebraic subset of \(\mathbb R^{N^p}\).  Consequently, if the joint coefficient law is absolutely continuous, the field is almost surely Morse.
The same conclusion holds when the coefficient law is absolutely
continuous with respect to Lebesgue measure on the space of symmetric
degree-\(p\) tensors.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:28:53.622049+00:00","domain":"probability theory","id":"claim_dbd2524b736197e8e6e208c35f91c41efd458e8191367d0523056ecb52ea2b3e","kind":"theorem","schema_version":1,"statement":"[Proposition 17 (Mixed moments of the surface measure) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] For $1<p<\infty$ and $n\geq 2$ consider the weighted $\ell_p$-ball $\mathbb B_p^n(a)$ with weights $a_1,\ldots, a_n >0$.
Let $\lambda_1,\dots,\lambda_n\in\mathbb C$ satisfy $\Re \lambda_k>-1$ for all $k=1,\dots,n$. Then
\begin{equation}
\int_{\partial \mathbb B_p^n(a)}
\prod_{k=1}^n |x_k|^{\lambda_k}\,d\mathcal H^{n-1}(x)
=
\frac{
p\, \prod_{k=1}^n a_k^{-\lambda_k-1}
}{
2\,\Gamma\!\left(\dfrac{n+\Lambda+p-1}{p}\right)\sqrt\pi
}
\int_0^\infty
\frac{G_\lambda(0)-G_\lambda(\theta)}{\theta^{3/2}}\,d\theta,
\end{equation}
where $\Lambda=\sum_{k=1}^n \lambda_k$ and
$$
G_\lambda(\theta):=\prod_{k=1}^n \mathcal F_p(\theta a_k^2;\lambda_k), \qquad \theta \geq 0,
\qquad
G_\lambda(0)
=
\left(\frac{2}{p}\right)^n
\prod_{k=1}^n
\Gamma\!\left(\frac{\lambda_k+1}{p}\right).
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:49:06.302128+00:00","domain":"probability theory","id":"claim_dbd3aafe2c536c6aca69d93c9d18fb817b91a4eb3e627fd1451a91fe231cb3ba","kind":"concept","schema_version":1,"statement":"[Conjecture conj:threshold of arXiv:2601.05361, 'Noise sensitivity in last-passage percolation'] Consider planar last-passage percolation with geometric weights. The transition from stability to noise sensitivity occurs at $t\asymp n^{-1/3}$ in the sense that, as $n\to\infty$,
