{"assumptions":[],"created_at":"2026-10-27T10:25:49.836671+00:00","domain":"probability theory","id":"claim_de131f69147d7b02ed6dd88ba43df3b55c627778440d62a5a1c65b0439da2ffe","kind":"lemma","schema_version":1,"statement":"[Lemma 10 of arXiv:2609.01965, 'A logarithmic Bogomolov--Sommese vanishing theorem on compact K\"ahler manifolds'] Let $(X,\omega)$ be a compact K\"ahler manifold of dimension $n$ and $L$ a pseudo-effective line bundle over $X$ with $\nd(L)=k>p$.
    Let $D$ be a reduced simple normal crossing divisor on $X$.
    There exist constants $c_0,C_0>0$ such that for every $\varepsilon$ sufficiently small, we have the following properties.
    \begin{enumerate}
        \item There exists a log resolution 
        $$\pi_\varepsilon:\widetilde{X}_\varepsilon\longrightarrow X$$
        and a reduced simple normal crossing divisor $B_\varepsilon$ such that $B_\varepsilon$ contains the total transform of $D$ and the exceptional divisor.
        Moreover, $\pi_\varepsilon$ induces a natural morphism from $\Omega^p_X(\log D)$ to $\Omega^p_{\widetilde{X}_\varepsilon}(\log B_\varepsilon)$.
        \item There exists a singular Hermitian metric $\widetilde{h}_\varepsilon$ on line bundle $\pi^*_\varepsilon L$ 
        with divisorial singularities supported on $B_\varepsilon$ and smooth on $$Y_\varepsilon:=\widetilde{X}_\varepsilon\setminus B_\varepsilon.$$
        \item There exist K\"ahler forms $\gamma_\varepsilon$ and $\Omega_\varepsilon$ on $\widetilde{X}_\varepsilon$ such that, on $Y_\varepsilon$,
        \begin{equation}
            \image\Theta_{\pi^*_\varepsilon L,\widetilde{h}_\varepsilon}=\gamma_\varepsilon-3\varepsilon\pi^*_\varepsilon\omega 
            \quad \text{and} \quad \Omega_\varepsilon\geq \pi^*_\varepsilon\omega.
        \end{equation}
        \item The following uniform estimates hold:
        \begin{equation}
            V_\varepsilon:=\int_{\widetilde{X}_\varepsilon}\gamma_\varepsilon^n\geq c_0\varepsilon^{n-k} 
            \quad \text{and} \quad
            \int_{\widetilde{X}_\varepsilon}\gamma_\varepsilon^{p}\wedge\Omega_\varepsilon^{n-p}\leq C_0.
        \end{equation}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.220430+00:00","domain":"probability theory","id":"claim_de1389e3a267ca83edf26aaebc55fc1553fd5196c621c3b0565f9f8e500b1faf","kind":"concept","schema_version":1,"statement":"[Lemma lem: 792 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] {EHR26+}}]
Suppose the same setting as in Theorem (thm: 369 of the paper).
Consider $z=E_{1}+\mathrm{i}\eta_{1}$ and $w=E_{2}+\mathrm{i}\eta_{2}$ with $E_{1},E_{2}\in\mathcal{I}(\epsilon_{0}/2)$ and $|\eta_{1}|,|\eta_{2}|\in(0,100)$.
Let $\mathcal{B}_{z,w}$ be as in (equation eq: 535 of the paper).
Then,
\begin{equation}
	\lVert \mathcal{B}_{z,w}^{-1} \rVert_{\lVert\cdot\rVert\to\lVert\cdot\rVert} + \lVert \mathcal{B}_{z,w}^{-1} \rVert_{\lVert\cdot\rVert_{\textnormal{hs}}\to\lVert\cdot\rVert_{\textnormal{hs}}}
	\lesssim
	\begin{cases}
		1, & \eta_{1}\eta_{2} > 0, \\
		\max\{1,|z-w|^{-1}\}, & \eta_{1}\eta_{2} < 0.
	\end{cases}
\end{equation}
Specifically, for the case $z=w$,
\begin{equation}
	\lVert \mathcal{B}_{z}^{-1} \rVert_{\lVert\cdot\rVert\to\lVert\cdot\rVert} + \lVert \mathcal{B}_{z}^{-1} \rVert_{\lVert\cdot\rVert_{\textnormal{hs}}\to\lVert\cdot\rVert_{\textnormal{hs}}}
	\lesssim 1.
\end{equation}
Moreover, there exist (small) positive thresholds $\beta_{*},\epsilon_{*}\sim 1$, $\epsilon_{*}<1/3$, such that, if $|z-w|\le\beta_{*}$ and $\eta_{1}\eta_{2}<0$, then
\begin{equation}
	\lVert (\zeta-\mathcal{B}_{z,w})^{-1} \rVert_{\lVert\cdot\rVert\to\lVert\cdot\rVert} + \lVert (\zeta-\mathcal{B}_{z,w})^{-1} \rVert_{\lVert\cdot\rVert_{\textnormal{hs}}\to\lVert\cdot\rVert_{\textnormal{hs}}}
	\lesssim 1,
\end{equation}
for all $\zeta\in\mathbb{C}$ satisfying $|\zeta|\ge\epsilon_{*}$ and $|1-\zeta|\ge 1-2\epsilon_{*}$,
and the disk of radius $\epsilon_{*}$ around the origin contains a single eigenvalue $\beta_{z,w}$ of $\mathcal{B}_{z,w}$ with algebraic multiplicity one, that is,
\begin{equation}
	\textnormal{rank}\,\Pi_{z,w} = 1, \quad\;\; \Pi_{z,w}\coloneqq \frac{1}{2\pi\mathrm{i}}\oint_{|\zeta|=\epsilon_{*}} (\zeta-\mathcal{B}_{z,w})^{-1} \mathrm{d}\zeta,
\end{equation}
where $\Pi_{z,w}$ is the spectral projection corresponding to $\beta_{z,w}$.
Furthermore, the eigenvalue $\beta_{z,w}$ of $\mathcal{B}_{z,w}$ satisfies
\begin{equation}
	|\beta_{z,w}| \sim 
	\begin{cases}
		1, & \eta_{1}\eta_{2} > 0, \\
		\min\{1,|z-w|\}, & \eta_{1}\eta_{2} < 0.
	\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

