{"assumptions":[],"created_at":"2026-10-26T19:28:04.858403+00:00","domain":"probability theory","id":"claim_de6a913a927e2c07eb59f005dba8e4336d04764565ba4ab862ba3f73ce442703","kind":"theorem","schema_version":1,"statement":"[Thm 11 of arXiv:2511.20875, 'Double $q$-Wigner Chaos and the Fourth Moment'] Let $0\le q<1$ and $m,n \in \mathbb{N}$ have opposite parities. Let $\{ f_k\}_{k\in \mathbb{N}} \subset H^{\otimes m}, \{ g_k\}_{k\in \mathbb{N}} \subset H^{\otimes n}$ be fully symmetric, and let $X_k=I_q( f_k)$ and $Y_k=I_q( g_k)$ be the $q$-Wigner integrals. Assume $\|f_k\|_{\mathcal{F}_q(H)}$ and $\|g_k\|_{\mathcal{F}_q(H)}$ converge and define 
      \[ \sigma_X=\lim_{k \to \infty}\| f_k\|_{\mathcal{F}_q(H)} \quad \& \quad  \sigma_Y=\lim_{k \to \infty}\| g_k\|_{\mathcal{F}_q(H)}.\]
      Then the following are equivalent
      \begin{enumerate}
          \item $\lim_{k \to \infty}\tau_q[(X_k+Y_k)^4]=(2+q^{m^2})\sigma_X^4+(2+q^{n^2})\sigma_Y^4 +(4+2q^{mn})\sigma_X^2\sigma_Y^2$.
           \item $\displaystyle{\lim_{k\to\infty} f_k \overset{p}{\frown} f_k = 0}$ in $H^{\otimes 2(m-p)}$ for $p=1,\ldots,m-1$ and $\displaystyle{\lim_{k\to\infty} g_k \overset{p}{\frown} g_k = 0}$ in $H^{\otimes 2(n-p)}$ for $p=1,\ldots,n-1$.
          \item $X_k+Y_k $ converges in distribution toward the mixed $Q$-Gaussian with respect to $\begin{pmatrix}
              \sigma_X\\ \sigma_Y
          \end{pmatrix}$
          where 
          \[Q=\begin{pmatrix}
              q^{m^2} & q^{mn} \\
              q^{mn} & q^{n^2}
          \end{pmatrix}.\]
       \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.329947+00:00","domain":"probability theory","id":"claim_de6ec7325cdc9be15196f2312207668ef1db250cf79c49ea1dcfe5a60ca341c8","kind":"definition","schema_version":1,"statement":"[Definition qshprod of arXiv:2411.06827, 'The Exponential Lie Series and a Chen--Strichartz Formula for L{\'e}vy Processes'] The commutative quasi-shuffle product $\star$ on ${\mathbb R}{\langle}{\mathbb A}{\rangle}$  is  inductively defined by
\begin{align}

\begin{aligned}
	u\,& \star\, {\mathbf 1}
	= {\mathbf 1}\,\star\, u
	=u, \\
	ua \star vb & 
	=(u \star vb)a + (ua \star v)b + (u \star v)[a,b],
\end{aligned}
\end{align}
where $u$ and $v$ are words and $a$ and $b$ are letters, and where
 `$ {\mathbf 1}$' is the empty word.","status":"unverified"}

