			t^{- \frac 12}\log(1+t)\mbox{\bf 1}_{\{ \frac pq<\frac 12\}}+t^{-(1- \frac{p}{q})}\mbox{\bf 1}_{\{\frac 12 < \frac pq<1\}}&  \mbox{ if $p=\frac d2$},\\
 			t^{-\frac 12}\mbox{\bf 1}_{\{ \frac pq<\frac 12\}}+t^{-(1- \frac{p}{q})}\mbox{\bf 1}_{\{\frac 1 2< \frac pq<1\}}  & \mbox{ if $p>\frac d2$}.\\








