{"assumptions":[],"created_at":"2026-10-28T00:32:56.076981+00:00","domain":"probability theory","id":"claim_e0c6654b9c95216323067e5de3a371af7d81606cbd15402bd1b0e2e10fae39d0","kind":"theorem","schema_version":1,"statement":"[Theorem th:small-ball of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Let $\{u(t,x), t \ge 0, x \in \mathbb{R}^d\} $ be the solution of (equation e:fde of the paper) and recall that $\theta_1$ and $\theta_2$  are given in (equation e:theta12 of the paper).
  \begin{enumerate}[(1)]
    \item (Small ball probability in time). Assume the conditions (equation e:DL of the paper) and (equation e:tilde-U-exist of the paper) hold. Assume additionally
    either $\beta+\gamma-2\le0$ or
    \begin{equation*}
      \begin{cases}
        \beta+\gamma-2>0, \\
        -H_0+\frac{\beta}{\alpha}(d-H)<1.
      \end{cases}
    \end{equation*}
        Then,
    \begin{equation*}
      \lim_{\varepsilon\to0} \varepsilon^{1/\theta_1}\log\mathbb P\bigg\{\max_{t\in[0,1]}|u(t,x)|\le\varepsilon\bigg\} = -C_1^{1/2\theta_1}\kappa ,
    \end{equation*}
    where $C_1$ is defined in (equation e:de-C1 of the paper) and $\kappa$ is the small ball constant of a fractional Brownian motion
    with index $\theta_1$ (e.g. [Li2001Gaussian]).
    \item (Small ball probability in space). Assume the conditions (equation e:DL of the paper) and (equation e:hat-U-exist of the paper) hold. There exist
    positive constants $c$ and $C$ independent of $t>0$ such that for sufficiently small $\varepsilon>0$,
    \begin{equation*}
      \exp\left(-\frac{c}{\varepsilon^{d/\theta_2}}\right)\le \mathbb P\bigg\{\max_{x\in[-1,1]^d}|u(t,x)-u(t,0)|\le\varepsilon\bigg\}\le \exp\left(-\frac{C}{\varepsilon^{d/\theta_2}}\right).
    \end{equation*}
    \item (Space-time joint small ball probability). Assume the conditions (equation e:DL of the paper) and (equation e:U-exist of the paper) hold. Assume additionally
    either $\beta+\gamma-2\le0$ or
    \begin{equation*}
      \begin{cases}
        \beta+\gamma-2>0, \\
        -H_0+\frac{\beta}{\alpha}(d-H)<1.
      \end{cases}
    \end{equation*}
    Then, there exist positive constants $c$ and $C$ such that for sufficiently small $\varepsilon>0$,
    \begin{equation*}
      \exp\left(-\frac{c}{\varepsilon^{Q}}\right)\le \mathbb P\left\{\max_{(t,x)\in [0,1]\times[-1,1]^d}|u(t,x)|\le\varepsilon\right\}\le \exp\left(-\frac{C}{\varepsilon^{Q}}\right),
    \end{equation*}
  where $Q=\frac{1}{\theta_1}+\frac{d}{\theta_2}$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:49:15.470918+00:00","domain":"probability theory","id":"claim_e0c6af90fbf8ae37b8fdd38494ec6673b37764ca573e98f38261a5f00e2c0fd2","kind":"concept","schema_version":1,"statement":"[Corollary reduction corank 2 of arXiv:2608.28278, 'Reduction of symmetric time-dependent Hamiltonian systems I: presymplectic principal $\R$-'] Let $(T^*Q, \omega_h, T^*\phi, J)$ be the symmetric presymplectic Hamiltonian system given in Proposition (prop:J momentum map of the paper). Moreover, let $\nu\in \mathfrak{g}^*$ such that $J^{-1}(\nu) \neq \emptyset$ and suppose that $\phi$ is free and the space of orbits $(T^*Q)_\nu := J^{-1}(\nu)/G_\nu$ is a manifold such that the canonical projection $\pi_\nu: J^{-1}(\nu) \to J^{-1}(\nu)/G_\nu$ is a submersion. Then, there is a presymplectic closed $2$-form $\omega_h^\nu$ on $(T^*Q)_\nu$ such that
    \begin{equation}
        \pi_\nu^*(\omega_h^\nu)=\iota_\nu^*(\omega_h),
    \end{equation}
    where $\iota_\nu: J^{-1}(\nu) \hookrightarrow T^*Q$ is the canonical inclusion. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:38:13.627369+00:00","domain":"probability theory","id":"claim_e0c8ad396d135ca4f6db696f8cd7c490b844da0f0b1cc5032867959a0510232a","kind":"lemma","schema_version":1,"statement":"[Lem 5 of arXiv:2609.00598, 'Supercritical mean--field limit for magnetized Hamiltonian dynamics'] Let $v$ be a smooth vector field on $\mathbb{T}^{2}$, 
