    \item $\exists \theta^* > 0$ such that $\theta^* \kappa'(\theta^*)=\kappa(\theta^*)$
    \item $\mathbb{E}\left(|\max_{m\in M}m|^2\right)<\infty$
    \item $\mathbb{E}\left(\sum_{m\in M}e^{\theta^* m}\left(\log \sum_{m\in M}e^{\theta^* m}\right)^2\right)<\infty$
