\begin{equation}
\begin{aligned}
        \Delta_m
        &\le
        e^{-g\tau(m_r,m)}\Delta_{m_r}
        +
        K_1\sqrt{\frac{H_{m_r}}{m_r+n_0}}
        +
        \frac{K_2}{m_r+n_0}
\end{aligned}

