{"assumptions":[],"created_at":"2026-10-27T23:03:39.761851+00:00","domain":"probability theory","id":"claim_e444203f1cd8c9f370576ded0507066a9bbd2d720ca41ea710bfd91b4737f20a","kind":"lemma","schema_version":1,"statement":"[Lemma lem:moment-boud:H^1_epsilon of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] Assume the hypotheses of~(thm:well-posed of the paper) and let $U_0=(u_0,\eta_0)\in \mathcal{H}^1_\mu$. Then
\begin{enumerate}
[noitemsep,topsep=0pt,wide=0pt,label=\arabic*.,ref=\theassumption.\arabic*]
\item For all $\beta$ sufficiently small independent of $\mu\in\mathcal{M}_\delta$, 
\begin{equation}
\mathbb{E} \exp\left({\beta\Psi_1(U(t))}\right)\le  e^{-c_{1,0}t}\exp\left({\beta C_{1,0}\Psi_1(U_0)}\right)+C_{1,0},\quad t\ge 0,
\end{equation}
where $\Psi_1(u,\eta)$ is as in (equation form:Psi_1 of the paper) and $c_{1,0}=c_{1,0}(\beta)>0$, $C_{1,0}=C_{1,0}(\beta)>0$ do not depend on $U_0$, $\mu\in\mathcal{M}_\delta$ and $t\ge 0$. 

\item For all $n\ge 1$, there exist positive constants $c_{1,n}$, $C_{1,n}$ independent of $U_0$, $\mu\in\mathcal{M}_\delta$ and $t\ge 0$ such that
\begin{equation}  
\emph{d} \Psi_1(U(t))^n\le -c_{1,n} \Psi_1(U(t))^n\emph{d} t+C_{1,n}\emph{d} t+C_{1,n}\Psi_0(U(t))^{n}\emph{d} t+\emph{d} M_{1,n}(t),
\end{equation} 
where $M_{1,n}(t)$ is the semi-martingale given by
\begin{equation} 
M_{1,n}(t)=\int_0^t n\Psi_1(U(r))^{n-1}\langle A^{1/2}u(t),A^{1/2}Q\emph{d} w(r)\rangle_H. 
\end{equation}
Furthermore,
\begin{equation} 
\mathbb{E}\Psi_1(U(t))^n \le C_{1,n}e^{-c_{1,n}t}\Psi_1(U_0)^n+C_{1,n},\quad t\ge 0.
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:45.022975+00:00","domain":"probability theory","id":"claim_e4446431a1135b409b9d9c0e79f285b25af2ea667197c536f46faa1d19a135ee","kind":"lemma","schema_version":1,"statement":"[Lemma 5 of arXiv:2606.06231, 'Sensitivity of SDE Solutions to Perturbations of the Diffusion and Drift'] Suppose we have $a_n,b_n\in[0,\infty)$, $T,\tau\in(0,\infty)$, and measurable $f_n:[0,T]\to[0,\infty)$, $n\in\mathbb{Z}^+$ that satisfy
    \begin{align}
        f_n(t)\leq   b_n+a_n\int_0^t e^{\tau s}f_{n-1}(s)ds
    \end{align}
    for all $n\in\mathbb{Z}^+$, $t\in[0,T]$, where $f_0\coloneqq 1$.  Then for all $t\in[0,T]$, and defining $b_0\coloneqq 1$, we have
\begin{align}
    f_n(t)\leq \sum_{j=0}^n \frac{\prod_{k=j+1}^n a_k}{(n-j)! \tau^{n-j}} b_j  e^{(n-j)\tau t} \,.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:45.023720+00:00","domain":"probability theory","id":"claim_e44ba747f3debe0934bcc08b1d053c9f8374047f84be764016f64ff1c0ab9a28","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.06489, 'The Missing Central Limit Theorems for Local Functionals of Berry's Random Wave Model'] For any order $q\geq 2$ and space dimension $d\geq 2$, the random variable $\frac{h(q,R)}{\sqrt{\var h(q,R)}}$ converges in total variation and 1-Wasserstein distance
    to a standard Gaussian random variable as $R\to\infty$.

    Moreover, if $F(R)=\int_{B_R}f(u_1(x))dx$ is given by a nontrivial local observable with Hermite decomposition
    \begin{equation*}
        f(x)=\sum_{q\geq 2}\frac{a_q}{q!}H_q(x),
        \qquad
        a_q=\frac1{\sqrt{2\pi}}\int_\R f(z)H_q(z) e^{-z^2/2}dz,
    \end{equation*}
    such that either $d=2$ and $a_4\neq 0$ or $\sum_{q\geq 3}\frac{a_q^2C_{q,d}}{(q!)^2}<\infty$,
    then $\frac{F(R)}{\sqrt{\var F(R)}}$ converges in 1-Wasserstein distance to a standard Gaussian random variable as $R\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.658209+00:00","domain":"probability theory","id":"claim_e44db5aeb47ef0de395c487d040c15db23c8edae8570e346375151fee071768d","kind":"concept","schema_version":1,"statement":"[Theorem 11 (Scaling limit of Sinkhorn-rescaled random matrices) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $(\r_k, \c_k)$ and $\bLambda_k$ satisfy Assumption \ref{assumption: limit_theory}, and for each $k$ let $\X_k$ be a random matrix satisfying Assumption \ref{assump:random_matrix} with mean $\bLambda_k$ and target margin $(\r_k, \c_k)$. Let $\varphi_{\X_k^{\r_k,\c_k}}$ denote the piecewise constant extension of $\X_k^{\r_k,\c_k}$ to $[0,1]^2$ as in Theorem \ref{thm:bound_X^rs-Z}, and let $W^{\r,\c;\bLambda} := d\pi^{\r,\c;\bLambda}/(dx\,dy)$ be the Lebesgue density of the limiting SSB from Theorem \ref{thm:SSB_deterministic_limit}. Assume
		\begin{enumerate}[label=\textup{(\roman*)}]
			\item $\sup_k \sigma_k \le \sigma < \infty$ and $\sup_k R_k \le R < \infty$;
			\item $\liminf_k (m_k/n_k) \wedge (n_k/m_k) \ge \gamma > 0$;
			\item $(m_k \vee n_k)^{3/2} \sqrt{\log(m_k \vee n_k)} = o_{K,\delta,\gamma,\sigma,R}(\|\bLambda_k\|_1)$.
		\end{enumerate}
		Fix $D > 0$. Then for any $g \in L^{\infty}([0,1]^2)$,
		\begin{align}
			&\left|\int_{[0,1]^2} g\!\left(\varphi_{\X_k^{\r_k,\c_k}} - W^{\r,\c;\bLambda}\right) dx\, dy\right| \nonumber \\
			&\qquad = O_{K, \delta, \|g\|_{\infty}, \sigma, R}\!\left( \frac{(m_k \vee n_k)^{3/2} \sqrt{D\log(m_k \vee n_k)}}{\|\bLambda_k\|_1} + \sqrt{\norm{\rho_{\r} - \rho_{\r_k}}_{L^1} + \norm{\rho_{\c} - \rho_{\c_k}}_{L^1}} + d_H(\varphi_{\bLambda_k}, \varphi_{\bLambda}) \right)
		\end{align}
		with probability at least 
		\begin{align}
			1 - 2(m_k \vee n_k)^{-D} - m_k^2 \exp(-c\,\Phi_{\bLambda_k}) - 2\exp\left(-\frac{\|\bLambda_k\|_1^2}{2(m_k n_k \sigma^2 + R\|\bLambda_k\|_1)}\right)
		\end{align}
		for an absolute constant $c > 0$, where $\Phi_{\bLambda_k}$ is the row-alignment rate in \eqref{eq:Phi_def}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:34:45.593655+00:00","domain":"probability theory","id":"claim_e451f79aaaa84563fb2ca6fe4a95172b1ebd59a0ffb3ac237d3a351755afae82","kind":"lemma","schema_version":1,"statement":"[Lemma lem:flags of arXiv:2609.01776, 'On the Cuspidal Cohomology of Iwahori Congruence Subgroups of $\mathrm{SL}(3, \mathbb{Z})$'] Let $\mathbb{F}_p = \mathbb{Z}/p\mathbb{Z}$.  Further, let $\overline{B}$ denote the Borel subgroup of upper triangular matrices in $\overline{G} = \mathrm{SL}(n, \mathbb{F}_p)$.  Let $V = \{v_1, \ldots, v_m\}$ and $W = \{w_1, \ldots, w_m\}$ be two saturated lists in $\mathbb{Z}^n$.  Let $V_i$ and $W_i$ denote the subspaces of $\mathbb{Q}^n$ generated by $\{v_1, \ldots, v_i\}$ and  $\{w_1, \ldots, w_i \}$ respectively. 

    Fix $i_1 < i_2 < \cdots < i_k$ from $\{1, \ldots, m\}$.  Consider the flags $F^V$ and $F^W$, which correspond to a nested sequence of subspaces
    \begin{gather*}
        0 \subsetneq V_{i_1} \subsetneq V_{i_2} \subsetneq \cdots \subsetneq V_{i_k} \subseteq \mathbb{Q}^n, \\
        0 \subsetneq W_{i_1} \subsetneq W_{i_2} \subsetneq \cdots \subsetneq W_{i_k} \subseteq \mathbb{Q}^n.
    \end{gather*}

    Let $\overline{F}^V$ and $\overline{F}^W$ denote the flags 
    \begin{gather*}
        0 \subsetneq \overline{V}_{i_1} \subsetneq \overline{V}_{i_2} \subsetneq \cdots \subsetneq \overline{V}_{i_k} \subseteq \mathbb{F}_p^n, \\
        0 \subsetneq \overline{W}_{i_1} \subsetneq \overline{W}_{i_2} \subsetneq \cdots \subsetneq  \overline{W}_{i_k} \subseteq \mathbb{F}_p^n,
    \end{gather*}
    where $\overline{V}_i = \langle \bar{v}_1, \ldots, \bar{v}_i \rangle$ and $\overline{W}_i = \langle \bar{w}_1, \ldots, \bar{w}_i \rangle$ with 
    $v_j \equiv \bar{v}_j \pmod p$ and $w_j \equiv \bar{w}_j \pmod p$.  Suppose there exists $B_0 \in \overline{B}$ that sends $\overline{F}^V$ to $\overline{F}^W$.  Then, there exists some $\mathcal{I}_0 \in \mathcal{I}(n, p)$ such that $\mathcal{I}_0 \equiv B_0 \pmod p$ and $\mathcal{I}_0$ sends $F^V$ to $F^W$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:32:19.920949+00:00","domain":"probability theory","id":"claim_e453396662df33c4483aefcf7a2e594254a4bc98f9aeb3fbf4e77da5dabee36d","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Fix $T>0.$ Let $X$ be a random variable whose density $f : \N \rightarrow (0, \infty) $ with respect to $\pi_{T}$ is ultra log-concave, then we have
    \begin{displaymath}
        \delta_{\mathrm{Thinn}}(f) \ge a(1-a) \frac{T^{2}}{2} \Theta_{\frac{f(0)}{f(1)}} \Bigg( \frac{\E X}{T} \Bigg)
    \end{displaymath}
    where, for $c>0,$ we denote
    \begin{displaymath}
        \Theta_{c}(z):= \frac{z^{2}}{1+cz} \log \Big( \frac{1}{1+cz} \Big) - \frac{z^{2}}{1+cz} + z^{2}= z^{2} \phi \Bigg( \frac{1}{1 + cz} \Bigg), \quad z\ge 0.
