			\end{align*}
			If $\frac{t_0}{2}< s < t$, then
			\begin{align*}
				\|\nabla \rho (s)\|_{L^2}^2 \leq A,
			\end{align*}
			$A$ is given in lemma (lem6 of the paper), provided $t_0$ $\leq$ $t_3(E)$ for some chosen $t_3(E)$ $\leq -1$. \newline			 
			For $t_0 \leq t_3(E)$, $t \in  [-1,0]$,
			\begin{align*}
				I_1 \leq \sqrt A{R_0}^3\int_{-\infty}^{0} {z}^{2}(s,w) {e}^{\nu s} ds = r_1(\omega),
			\end{align*}
			$r_1(\omega)$ is a random variable being independent of $E$. Since $\frac{w(t)}{t}$ $\to 0$ as $t \to$ $\pm$ $\infty$, the ergodic property implies that $s \mapsto$ ${z}^{2}(s,w) {e}^{\nu s}$ is pathwise integrable on $(-\infty,0]$.\newline
			To estimate $I_2$, we choose $t_4(E) \leq -1$ such that 
			\begin{align*}
				8\sqrt A E^3e^{\frac{\nu}{2}t_4} \leq 1.
			\end{align*}
			By Lemma (lem5 of the paper), we deduce
			\begin{equation*}
				\|\rho(s)\|_{L^2}\ \leq 2E, 
			\end{equation*}
			for all s $\in [t_0,\frac{t_0}{2}]$. If $\frac{t_0}{2} \leq t_4(E)$, then we derive
			\begin{align*}
				I_2&=\int_{t_0}^{\frac{t_0}{2}} {z}^{2}(s,w)\|\rho(s)\|_{L^2}^{3}\|\nabla \rho(s)\|_{L^2} {e}^{\nu s}ds \\	&\leq \int_{t_0}^{\frac{t_0}{2}} [8\sqrt A E^3{e}^{\frac{\nu}{2} s}]{z}^{2}(s,w) {e}^{\frac{\nu}{2} s}ds \\
