{"assumptions":[],"created_at":"2026-10-27T11:36:12.192623+00:00","domain":"probability theory","id":"claim_e578ab1ff9d4e032c30b8cb576fd7caef950491bb52e01c71165b4c7065b2c27","kind":"concept","schema_version":1,"statement":"[Proposition 7 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Assume the set-up \eqref{eq:OU_flow}--\eqref{eq:char_flow}. The following results hold uniformly in $t\in [0,T]$ and $z=z_T\in\mathcal{D}$.

\noindent \emph{(i)} For any fixed $n_1,n_2\in\N$ and multi-indices $\bm{k}\in \N^{n_1},\bm{l}\in\N^{n_2}$ we have
\begin{equation}
\left(\E^{(W)}-\E^{(G)}\right)\left[\eta_t^{|\bm{k}|+|\bm{l}|}\Delta_t(\bm{k}) \overline{\Delta_t(\bm{l})}\right] =\mathcal{O}(\eta_t).

\end{equation}

\noindent \emph{(ii)} For $\beta=2$ and any fixed $p,q\in\N\cup\{0\}$ with $p+q\ge 3$ it further holds that
\begin{equation}
