& \int_{M_{T}}|\nabla^{3}H|^{2}+\int_{\frac{15}{32}T}^{T}(\int_{M_{t}} |\nabla^{4} H|^{2}) dt\\ 
     \leq &C(E_2^{\frac{4}{3}}+E_1^4+T^{-1})||H||_{L^{p_0}(M_0)}^2\{(||H||_{L^{p_0}(M_0)} E^{\frac{1}{2}}_1E^{\frac{1}{2}}_2{T^{-\frac{3}{2p_0}}}+T^{-1} + E_1^4) \\
&\times( E_1^2T^{1-\frac{3}{p_0}}+ T^{\frac{1}{2}-\frac{3}{p_0}})+ E_1^3E_2 T^{1-\frac{3}{p_0}}\}+C E_1E_2^3||H||_{L^{p_0}(M_0)}^2T^{1-\frac{3}{p_0}}\\
&+C(E_1^2E_2^2+E_2^{\frac{8}{3}})||H||_{L^{p_0}(M_0)}^2( E_1^2T^{1-\frac{3}{p_0}}+T^{\frac{1}{2}-\frac{3}{p_0}}).
    \end{split}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:35:10.787517+00:00","domain":"probability theory","id":"claim_e74a11a3b8ff8b4040dc4dd213bf7e9c331285c6cf8b6234a98b3c1ff2fec83d","kind":"lemma","schema_version":1,"statement":"[Lemma 14 (Survival along a sequence of stars) of arXiv:2604.00630, 'The contact process on a bipartite spatial network'] Let~$G$ be a bipartite graph. Let~$(x_k)_{k\ge 0}$ and~$(y_k)_{k \ge 1}$ be sequences of vertices of~$G$ such that:
	\begin{itemize}
		\item $(x_k)_{k \ge 0}$ have type 1 and~$(y_k)_{k \ge 1}$ have type~2, with
	\[
x_0 \sim y_1 \sim x_1 \sim y_2 \sim x_2 \sim \cdots;
	\]
\item the sequence~$(x_k)_{k\ge 0}$ has infinitely many distinct elements.
	\end{itemize}
	Then, the contact process on~$G$ with rates~$\lambda_1,\lambda_2$ and~$x_0$ initially infected survives forever with probability at least
	\begin{equation*}
		1-\sum_{k=0}^\infty ((\varepsilon \lambda_1 \lambda_2 \deg(x_k))^{-1/2} + \exp\{-c\lambda_1 \lambda_2^2 \lfloor \exp(\varepsilon \lambda_1 \lambda_2 \cdot \deg(x_k)) \rfloor \}),
	\end{equation*}
	where~$\varepsilon > 0$ is the constant of Lemma~\ref{lem_main_star} and~$c > 0$ is a constant not depending on~$\lambda_1,\lambda_2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:48:24.290855+00:00","domain":"probability theory","id":"claim_e74a45e3fac23816dcfd28c86111597a68c1a8cb5686cb481451497d648ff8cb","kind":"definition","schema_version":1,"statement":"[Definition fixptfun of arXiv:2605.06887, 'Law of large numbers for activated random walk on villages'] Define the function $\phi:\mathbb{R}_+^{V} \rightarrow{\mathbb{R}^{V}}$ as follows: for $m \in \mathbb{R}_+^{V}$ and $x \in V$, set
\begin{equation} 
     \phi(m)_x = (\sigma_x - \frac{\lambda_x}{1+\lambda_x})\left( 1-e^{-\beta(m)_x}\right) + \beta(m)_x
\end{equation}
We call $\phi$ the fixed point function of the VARW model.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:57:16.061833+00:00","domain":"probability theory","id":"claim_e74e0010fb2bd03aa40a2186e09bcd4739f185e62ec90f528c3b0da343f7be1b","kind":"concept","schema_version":1,"statement":"[Lem branching_rate_upper_bound of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] There exists $\sigma,L > 0$ such that, for any $0 \leq s_0 \leq t$,  on the event $\{ \forall s \in [s_0,t], X_s \leq \sqrt{2} s \text{ and } \mathopen{}\mathclose\bgroup\originalleft\lvert\theta_s\aftergroup\egroup\originalright\rvert < \sigma \}$ as well as on the event $\{ \forall s \in [s_0,t], X_s \leq \sqrt{2} s \text{ and } \mathopen{}\mathclose\bgroup\originalleft\lvertY_s\aftergroup\egroup\originalright\rvert < \sigma s \}$, we have

	\begin{equation*}
	\forall s \in [s_0,t], \quad b(\theta_s) \leq 1 - \beta \abs{\frac{Y_s}{\sqrt{2} s}}^\alpha (1+f(Y_s,s)),
	\end{equation*}
    where $f = f^-_{L,2-\alpha,1} = - \bigl( \bigl[ L \bigl( \abs{\frac{y}{s}}^{2-\alpha} + s^{-1} \bigr) \bigr] \wedge \zeta \bigr)$ where $\zeta \in (0,1/2]$ is chosen in (equation eq:def_f_-_+ of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:14:57.636999+00:00","domain":"probability theory","id":"claim_e74ee58e80c00bc34694bd69628c7df5e3433067287a21e1463eae77d29dde17","kind":"theorem","schema_version":1,"statement":"[Proposition prop: general approximation bound for numerics of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $n\geq 3$ and $t\geq 0$. Then
    \begin{equation}
         \left| \textup{d}^{(n)}(t) - \frac{(n-1)}{e}\left( \frac{n-3}{n-1} \right)^t\right| \leq \varepsilon^{(n)}(t),
    \end{equation}
where 
\begin{equation}
     \varepsilon^{(n)}(t) = \left( \sum_{r=2}^{\left\lfloor (n-1)/2\right\rfloor} n^r \left( 1 - \frac{2r(n-r+1)}{n(n-1)}\right)^{t}\right)+ \frac{\sqrt{p(n)n!}}{2^{t+1}} + \frac{1}{(n-2)!}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:49:15.411673+00:00","domain":"probability theory","id":"claim_e7506a5298f8e5900458b8416327ed71d12520fa97d6591e673ea55e37fad1ad","kind":"lemma","schema_version":1,"statement":"[Lemma lem:pathwise_boundedness of arXiv:2608.27313, 'A Finite Sample Analysis for Quantile Temporal Difference Learning in Distributional Reinf'] Let
\begin{equation*}
    B\coloneq\frac1{1-\gamma},
    \qquad
    \Delta\coloneq\frac{c}{1-\gamma}.
\end{equation*}
If $\bm\theta^{(0)}\in[0,B]^{{\mathcal{S}}\times[m]}$, then, almost surely,
\begin{equation}
    \bm\theta^{(t)}\in[-\Delta,B+\Delta]^{{\mathcal{S}}\times[m]}
    \qquad\text{for every }t\ge0.
\end{equation}
Consequently,
\begin{equation}
    \norm{\bm\theta^{(t)}-\bm\theta_m}_\infty
    \le\frac{1+c}{1-\gamma}
    \qquad\text{for every }t\ge0.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:18:13.238749+00:00","domain":"probability theory","id":"claim_e753e024a9a4784c2c1725b2c3a48d70294369b5ad4af74137f893943d32e312","kind":"lemma","schema_version":1,"statement":"[Lemma le:chineq of arXiv:2506.17168, '{\bf Scaling limits for sample autocovariance operators of Hilbert space-valued linear pro'] The function $c(r,s)$ in (equation equality_beta of the paper) can be bounded from above as
