{"assumptions":[],"created_at":"2026-10-27T20:06:06.358426+00:00","domain":"probability theory","id":"claim_e769d6f208f715676d1e1242401fc280d85d040be23e12034397e107ef8dcadd","kind":"concept","schema_version":1,"statement":"[Lemma lem:quadratic-generator of arXiv:2605.26652, 'Pathological Large Deviations of the KMP Process in Dimension $d\ge 2$'] Define
