\begin{equation}

\| G_{ \cA}\|_{L_{p/(p-1)}(C)}\leq N \rho^{-(d+2) /p }
\| G_{\cA}\|_{L_{1}(2C )} , 
\end{equation}
which is equivalently rewritten as
$$
\Big(\dashint_{C}G^{p/(p-1)}_{\cA}\,dxdt\Big)^{(p-1)/p}
\leq N\dashint_{2C}G_{\cA}\,dxdt.
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.332307+00:00","domain":"probability theory","id":"claim_e7701b72c6e75fc96138e0a60776f6900eb0f669bd72d7145fe4df693f287c7a","kind":"concept","schema_version":1,"statement":"[Theorem t:asymptotic variance test function of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d,\infty)$. Suppose that $\Phi$ is a locally square-integrable invariant random complex measure. Further, suppose that $f\in L^1$ is Fourier-smooth with exponent $p+\vartheta$ for some $\vartheta>0$. Then
\begin{equation}
    \frac{\BV[\Phi(f_r)]}{r^d} = O(r^{-p})\quad \text{as } r\to\infty.
\end{equation}
if $\Phi$ is $p$-uniform. The converse holds under the additional assumption that $\lambda_d(f)\neq0$. In both cases, the same holds for beyond $p$-uniformity with $o$ instead of $O$.
\begin{proof}
    Remark~(r: f_r formulas of the paper) and~(equation e: spectral covariance formula of the paper) yield that
    \begin{align}
        \frac{\BV[\Phi(f_r)]}{r^{d-p}} &= (2\pi)^{-d}r^{-d+p} \int |\hat{f}_r(k)|^2 \, \hat\beta_\Phi(dk) \nonumber\\
        &= (2\pi)^{-d}r^{d+p} \int |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk) \nonumber\\
        &= (2\pi)^{-d}r^{d+p} \int_{B_2} |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk) + (2\pi)^{-d}r^{d+p} \int_{B_2^c} |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk)
    \end{align}
    for $r>0$. Since $\hat\beta_\Phi$ is translation-boundeds, see (equation e: translation-bounded of the paper), and since $f$ is Fourier-smooth, we can apply (equation e: fourier smooth 2 of the paper). Hence, there is a $c_1>0$ such that, as $r\to\infty$,
    \begin{equation}
        r^{d+p} \int_{B_2^c} |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk) \leq c_1r^{d+p} \int_{B_2^c}\sup_{s\in B_1} |\hat{f}(r(k+s))|^2 \, dk = O(r^{-\vartheta}).
    \end{equation}
    Therefore, it only remains to treat the fist summand in (equation e:linear statistic bound 1 of the paper). We can apply the other Fourier-smoothness property~(equation e: fourier smooth 1 of the paper) of $f$ to obtain that there is a $c_2>0$ such that
    \begin{align*}
        r^{d+p} \int_{B_2} |\hat{f}(rk)|^2 \, \hat\beta_\Phi(dk) &\leq c_2 r^{d+p} \int_{B_2} (1 + r \|k\|)^{-(d+p+\vartheta)} \, \hat\beta_\Phi(dk) \\
