        \frac{
            f_h^{(\kappa)}(a)
        }{
            f_0^{(\kappa)}(a)
        } .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:15:34.488821+00:00","domain":"probability theory","id":"claim_e79b4f911bf210284a9b5b0ef786cbf13beff1f5915976f6c21a80194ea290b9","kind":"concept","schema_version":1,"statement":"[Corollary 12 (The Kähler case) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] If $\kappa_i \equiv 0$ for all $i$ (the Kähler condition \eqref{eq:kahler-condition}), then

	\begin{equation}
		\begin{gathered}
			\operatorname{Ric}(\nu, \nu) \;=\; \operatorname{Ric}(\xi^*, \xi^*) \;=\; -\frac{H''}{H} \;+\; \sum_{i=1}^r n_i \left( \frac{q_i^2 H^2}{2 F_i^4} \;-\; \frac{q_i H'}{F_i^2} \right), \\
			\mathcal{R}_i \;=\; p_i \;-\; q_i H' \;-\; \frac{q_i H^2}{2} \sum_{j=1}^r \frac{n_j\, q_j}{F_j^2} \,,
		\end{gathered}
	\end{equation}

	and the scalar curvature becomes

	\[
	\mathrm{R}_g \;=\; -\frac{2H''}{H} \;+\; \sum_{i=1}^r n_i \left( \frac{2 p_i}{F_i^2} \;-\; \frac{4\, q_i H'}{F_i^2} \;+\; \frac{q_i^2 H^2}{F_i^4} \right) \;-\; \left( \sum_{i=1}^r \frac{n_i\, q_i H}{F_i^2} \right)^{2} .
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:33.748044+00:00","domain":"probability theory","id":"claim_e7a1bb916e0b96ef2ce1794c0963435a3e3e6499f0d300dd63c81ea74801e880","kind":"lemma","schema_version":1,"statement":"[Lem 12 of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Let $\rho_1<\rho_2$ be consecutive pivot nodes and set $j:=\rho_2-\rho_1$.
The following statements hold.
\begin{enumeratei}
