    \end{align}
    with probability $1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:26:47.177933+00:00","domain":"probability theory","id":"claim_e83ce607c774ce79a213fbfbb661975d010b9f30505de52e1dbe9567196eefa1","kind":"concept","schema_version":1,"statement":"[Ppn 80 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] On the time interval $[q_0,\gamma(1)]$,
for $\tilde{w}_t$ as defined by Lemma~\ref{l:time.change}, we have
    \[
        \int_{q_0}^{\gamma(1)}
        \Big(
            \bbE w_{\lambda(s)} - \bbE \tilde w_s
        \Big)_+ \,ds
        \le 2\epsilon^{1/4}
    \]
for all $\epsilon>0$ small enough.

\begin{proof} By Lemma~\ref{l:generalized.inverse.fn}, for bounding the integral we can ignore the measure-zero set of times $s$ for which $\gamma'(\lambda(s))=0$. Therefore, without loss, we restrict our attention to times $s$ for which
$\gamma'(\lambda(s))>0$. In this case, we have $\gamma'(\lambda(s)) \lambda'(s) = 1$, so the definition of $\tilde w_s$ for $s\in[q_0,\gamma(1)]$ 
can be written as $\tilde w_s = \lambda'(s)^{1/2} w_{\lambda(s)} \ind\{\lambda(s) \le \tau\}$. We therefore have
    \begin{align*}
        \int_{q_0}^{\gamma(1)}\lt(
            \bbE w_{\lambda(s)} - \bbE\tilde w_s
        \rt)_+ \,ds
        &\le
        \int_{q_0}^{\gamma(1)}
        \bbE\Big[
        w_{\lambda(s)} - \lambda'(s)^{1/2}
            w_{\lambda(s)} \ind\{ \lambda(s) \le \tau\}
    \Big]_+\,ds\\
        &\le
        \int_{q_0}^{\gamma(1)}
        \bbE\Big[ \lambda'(s)^{1/2} w_{\lambda(s)} \ind\{
        \lambda(s) > \tau\}\Big]\,ds\,,
    \end{align*}
    where the last inequality uses $\lambda' \ge 1$, as a consequence of \eqref{e:gamma.prime}. We then apply the Cauchy--Schwarz inequality to bound the above by
    \begin{align*}
      &  \bigg(
            \int_{q_0}^{\gamma(1)}
            \bbP(\lambda(s) > \tau)\,ds\bigg)^{1/2}
            \cdot\bigg(
            \int_{q_0}^{\gamma(1)}
            \lambda'(s)
            \bbE\Big[
            (w_{\lambda(s)})^2 \ind\{ \lambda(s) > \tau\}\Big]
            \,ds
        \bigg)^{1/2}\\
  &\quad      \le \bigg(
            \int_{q_0}^{\gamma(1)}
            \lambda'(s)
            \bbE\Big[
            (w_{\lambda(s)})^2 \ind\{
             \lambda(s) > \tau\}\Big]
            \,ds
        \bigg)^{1/2}.
    \end{align*}
Changing variables to $u = \lambda(s)$, we bound the last integral above by
    \begin{align*}
        \int_{q_0}^1
        \bbE[(w_u)^2 \ind\{u > \tau\}]\,du
        &= \bbE
            \int_\tau^1 (w_u)^2 \,du
       = \bbE[Y(1)^2 -\hat Y(1)^2]
        = 1 - \gamma(1)
        \le 4\epsilon^{1/2}\,,    \end{align*}
where the last step again uses
Proposition~\ref{p:gamma-1}. This proves the claim.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:34.577790+00:00","domain":"probability theory","id":"claim_e842b726d5c7009d60d0bc476b7afe806eb0a804d181aa8f7f55b6c89f5ccc4f","kind":"concept","schema_version":1,"statement":"[Lemma 20 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $X_{N}= I_{p} (f_{N})$ with $ f_{N} \in H ^ {\odot p}$ for all $N\geq 1$. Assume that $(X_{N}, N\geq 1)$ satisfies (\ref{c1}). Let $Y_{N}= I_{q} (g_{N}) $ with $p<q<2p$ and $(Y_{N}, N\geq 1)$ bounded in $ L^ {2}(\Omega)$. Then
		\begin{enumerate}
			\item For $N\geq 1$, 
			\begin{equation*}
				Y_{1, N}= \frac{ p(q-1)!}{(q-p)!} I_{q-p} (f_{N}\otimes _{p}g_{N}) + R_{1,N},
			\end{equation*}
			where $R_{1, N}\to _{N \to \infty } 0 $ in $ L ^ {2}(\Omega)$.
			\item $X_{N}$ and $Y_{1, N}$ are asymptotically independent, i.e. 
			\begin{equation*}
				\langle DX_{N}, DY_{1, N} \rangle _{H} \to _{N\to \infty}0 \mbox{ in } L^ {2}(\Omega).
			\end{equation*} 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:19:46.239659+00:00","domain":"probability theory","id":"claim_e842c854b90236d00175add458fd2cd5639fc428e895437e4db716c5a1f854e7","kind":"definition","schema_version":1,"statement":"[Defi 1 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $0\leq s< T<\infty$. 
\begin{enumerate}
    \item[(i)] A family $\left(\mu_t\right)_{t\in (s,T)}\subset \mathcal{M}(\mathbb{R}^d)$ is called a (weak, or distributional) solution on $(s,T)$ to the linear Fokker-Planck equation  
    \begin{equation}
        \frac{d}{dt} \mu_t = {\sf L}^\ast_t \mu_t, \quad t\in (s,T),
    \end{equation}
    if $\left(\mu_t\right)_{ t\in (s,T)}$ is a Borel curve in $\mathcal{M}(\mathbb{R}^d)$ endowed with the Borel $\sigma$-algebra $\mathcal{B}\left(\mathcal{M}(\mathbb{R}^d)\right)$ associated to the topology of weak convergence,
    \begin{equation}
        \int_s^T\int_{B(0,R)} \|b(t,x)\|+\|a(t,x)\| \; \mu_t(dx) dt <\infty, \quad R>0,
    \end{equation}
    and
    \begin{equation}
        \int_s^T\int_{\mathbb{R}^d} \left[\frac{d}{dt}f(t,x)+ {\sf L}_t f(t,x)  \right] \;\mu_t(dx) dt = 0, \quad f\in C_c^\infty \left((s,T)\times \mathbb{R}^d\right).
    \end{equation} 
\item[(ii)] We say that $\left(\mu_t\right)_{t\in [s,T)}\subset \mathcal{M}(\mathbb{R}^d)$ is a solution to the linear Fokker-Planck equation \eqref{eq:LFPshort} (with initial condition $\mu_s$) if $\left(\mu_t\right)_{t\in (s,T)}$ is a solution on $(s,T)$ as in (i), and $\lim\limits_{t\searrow s} \mu_t=\mu_s$ weakly.
\item[(iii)] We say that $\left(\mu_t\right)_{t\in [s,T)}\subset \mathcal{M}(\mathbb{R}^d)$ is a weakly (resp. vaguely) continuous solution to the linear Fokker-Planck equation \eqref{eq:LFPshort} if it is a solution on $(s,T)$ in the sense of (i), and the curve of measures $[s,T)\ni t\mapsto \mu_t\in \mathcal{M}(\mathbb{R}^d)$ is (resp. vaguely) continuous; this definition is obviously extended when $(\mu_t)_{t\in [s,T)]}$ is merely right-continuous. 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:56:14.309094+00:00","domain":"probability theory","id":"claim_e84a93b98088e449b22bce0605ecd1d4a71ed5b6ac40e17f0e60454b3ca46ccb","kind":"lemma","schema_version":1,"statement":"[Lemma L:2.4 of arXiv:2412.09850, 'Averaging principles for time-inhomogeneous multi-scale SDEs via nonautonomous Poisson equ'] Suppose that Assumption {\rm(A1 of the paper)} holds. Let $Y^{s,x,y}:=\{Y_{t}^{s,x,y}\}_{t\ge s}$ be the unique strong solution to the SDE (equation FrozenE of the paper). Then, for any $t\in \mathbb{R}$ and $x\in \mathbb{R}^n$, there exists $\eta^x_{t} \in L^{2} (\Omega ,\mathscr{F},\mathbb{P} )$ such that for all $t\ge s$, $x\in \mathbb{R}^n$ and $y\in \mathbb{R}^m$,
\begin{equation}
\mathbb{E}|Y_{t}^{s,x,y}-\eta^x_{t}|^{2} \le C (1+|x|^2+|y|^{2} )e^{-2\int_{s}^{t}\alpha(u)\,du},\quad \sup_{t\in\mathbb{R}}\mathbb{E}|\eta^x_{t}|^2\leqslant C(1+|x|^2),
