    \end{align*}
    defines a symmetric homogeneous norm on $\mathbb G$. In particular, the unit metric ball $\{x\in\mathbb G: \rho(x)<1\}$ coincides with the Euclidean ball $B_{\mathbb{R}^n}(0,\kappa)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:26:20.538253+00:00","domain":"probability theory","id":"claim_e979ebb05ff28d82c19f9486734372664fe752b0a294621e0bd3bc6084916759","kind":"concept","schema_version":1,"statement":"[Cor cor1:sig:gam of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] If Assumptions \mbox{\normalfont  (asum:ic of the paper)}, \mbox{\normalfont  (asum:lip of the paper)} and \mbox{\normalfont  (asump:super of the paper)} to \mbox{\normalfont  (asum:derv:liningam of the paper)}  hold, then for   $ 2\leq p_0\leq \min\{{\bar p}/((\eta+1)
  (\eta/8+1)),\bar p/2\}$
		\begin{align*}
			\sum_{\mathfrak q=1}^{2}E\big|(\widehat\sigma_{\mathfrak{q}})_{tam}^{\displaystyle{n}}\big(\kappa_n(s),s,x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}\big)\big|^{p_0} 
			+ \sum_{\mathfrak q=1}^{2}\int_Z E\big|(\widehat\gamma_{\mathfrak{q}})_{tam}^{\displaystyle{n}}\big(\kappa_n(s),s,x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)},\bar z\big)\big|^{p_0}\nu(d\bar z)
			\leq &  
