{"assumptions":[],"created_at":"2026-10-27T08:26:47.149686+00:00","domain":"probability theory","id":"claim_e9d42c624c189484810d26e4ae31d484642b41de7ad84beafcd4e174d4794c35","kind":"concept","schema_version":1,"statement":"[Lemma 22 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Fix a bounded open set $U \subseteq \CC$ and let $\varepsilon \in (0,1), \alpha \in (0,1/4), A \in (2,\infty)$ be such that $\alpha (1+2/A) < 1/4$. Suppose that the functions $b,M$ are chosen such that $b(\xi) \sqrt{M(\xi)} > 20 A$. Then, there exists a constant $C \in (0,\infty)$ depending only on $\varepsilon,\alpha,A$, and $U$, such that the following hold with probability at least $1-\varepsilon$. For all $z \in U$, we have that
\begin{enumerate}
    \item 
    \begin{equation*}
        h_{e^{-t}}(z) \leq 2t - \alpha \log t + C\,\,\text{for all} \,\, t \geq 0.
    \end{equation*}
    \item 
    For all $n,m \in \NN$ with $m<n$, we have
    \begin{align*}
        &\widetilde{D}_h^{\xi}(\partial B_{e^{-n-50}}(z),\partial B_{e^{-m}}(z)) \\
        &\leq C^{\xi +1} e^{C(\xi+1) / A} e^{2\xi Q(\xi)} \sum_{k=m}^{n-1} \min_{t \in [k,k+1]}\left(\exp\left(\xi h_{e^{-t}}(z) - \xi Q(\xi) t + \frac{(2+2\xi) (2t - h_{e^{-t}}(z))}{A}\right)\right).
    \end{align*}
    \item 
    For all $n \in \NN$, we have
    \begin{align*}
        &\widetilde{D}_h^{\xi}(\text{around}\,\, \mathbb{A}_{e^{-n-1},e^{-n}}(z))\\
        &\leq C^{\xi+1} e^{C(\xi+1)/A} e^{2\xi Q(\xi)} \min_{t \in [n+1,n+2]} \exp\left(\xi h_{e^{-t}}(z) - \xi Q(\xi) t + \frac{(2+2\xi) (2t - h_{e^{-t}}(z))}{A}\right).
    \end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:13:22.533571+00:00","domain":"probability theory","id":"claim_e9d86f4221df308e54c5b1cdf2c29f0924c75d7fdb3774abd478f9d7442ca82d","kind":"concept","schema_version":1,"statement":"[Prop weighted_L2_NEW of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given $\alpha \geqslant 0$ and $N \in \mathbb{N}$, then for all integers $h,k$ satisfying 
