{"assumptions":[],"created_at":"2026-10-28T00:52:17.578625+00:00","domain":"probability theory","id":"claim_eb76b6e2c0049270884064f47843df20949efb71962913f5bccddeeb809af2a1","kind":"concept","schema_version":1,"statement":"[Proposition p:BLocSpW of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Let~$\sigma$ be a regular pair potential.
Under Assumption~(ass:Girsanov of the paper), then
\begin{enumerate}[$(i)$]
\item $W_\sigma\in \msD(\widehat\boldsymbol\mssE_\pi)^\bullet_{\loc}$ for every~$\pi\in\msP_*(\mbfT)$.
\end{enumerate}
If furthermore, there exists~$d\geq 0$ such that
\begin{gather}

\sup_{x\in M}\nu\big({B_r(x)}\big) \in O(r^d) \quad \text{as } r\downarrow 0\,\mathrm{,}\;\,
\\

\int_0^1 \sigma(r)\, r^{d-1} \mathop{}\!\mathrm{d} r <\infty \quad \text{and} \quad -\int_0^1 \sigma'(r)\, r^{d-1}\mathop{}\!\mathrm{d} r<\infty\,\mathrm{,}\;\,
\end{gather}
then
\begin{enumerate}[$(i)$, resume]
\item $W_\sigma\in\msD(\widehat\boldsymbol\mssE_\pi)$ for every~$\pi\in\msP(\mbfT)$.
\end{enumerate}

\begin{proof}
We divide the proof into several parts.

\paragraph{Proof of~(i:p:BLocSpW:1 of the paper)}
Let~$\tau$ as in Definition~(d:OnePlusMoment of the paper) be witnessing that~$\pi\in \msP_*(\mbfT)$, and let~$\varepsilon$ be given by Lemma~(l:NestPhi of the paper).
Define functions~$f_{i,j}\eqdef f_{i,j,n}\colon \mbfx\mapsto \mssd(x_i,x_j)\wedge \varepsilon(ijn)$ and
\[
\mbfu_n\colon (\mbfs,\mbfx)\longmapsto \tfrac{1}{2}\sum_{\substack{i,j\\i\neq j}} s_i\, s_j \, \sigma\tparen{f_{i,j}(\mbfx)} \,\mathrm{.}
\]
Further let~$\widehat\mbfF_n\eqdef \widehat\mbfF_n$ be the $\widehat\boldsymbol\mssE_\pi$-nest constructed in Proposition~(p:AndiHatPolar of the paper)(i:p:AndiHatPolar:1 of the paper) for~$\varepsilon$ chosen above, and note that~$\mbfu_n\equiv W_\sigma$ on~$\widehat\mbfF_n$.
In particular,~$\mbfu_n\equiv W_\sigma$ on the $\widehat\boldsymbol\mssE_\pi$-quasi-open set~$\widehat\mbfG_n\eqdef \mathrm{int}_{\widehat\boldsymbol\mssE_\pi}\widehat\mbfF_n$.
Since~${\big(\widehat\mbfF_n\big)}_n$ is an $\widehat\boldsymbol\mssE_\pi$-nest,~$\widehat\mbfG_n\nearrow_n \widehat\mbfM$ up to $\widehat\boldsymbol\mssE_\pi$-polar sets by~[Kuw98].
Thus, by definition of broad local space, it suffices to show that~$\mbfu_n\in\msD(\widehat\boldsymbol\mssE_\pi)$ for every~$n\in{\mathbb N}$.

\medskip\emph{$L^2$-bound}.\quad For the $L^2$-norm of~$\mbfu_n$, respectively:
by~(equation eq:AssSmallScaleInt of the paper) for~$\sigma$;
since~$\mbfs\in\mbfT$ implies~$i<s_i^{-1}$, and by~(equation eq:NestPhi of the paper) and~(equation eq:AssSmallScaleInt of the paper) for~$\sigma$;
by Lemma~(l:NestPhi of the paper) and the properties of~$\tau$;
by Jensen's inequality and since~$\sum_i s_i=1$,
we have
\begin{align*}
\left\lvert\mbfu_n\right\rvert^2 \lesssim& \abs{\sum_{i,j} s_i\, s_j\, \sigma\big({\varepsilon(ijn)}\big)}^2 \leq \abs{\sum_{i,j} s_i\, s_j\, \sigma\tparen{\varepsilon(s_i^{-1}s_j^{-1}n)}}^2 
\\
\leq&\ \sqrt{\tau(n)} \sum_{i,j,h,k} s_i\, s_j\, s_h\, s_k \sqrt[4]{\tau(s_i^{-1})\, \tau(s_j^{-1})\, \tau(s_h^{-1}) \tau(s_k^{-1}) }
\\
=&\ \sqrt{\tau(n)} \paren{\sum_i s_i \sqrt[4]{\tau(s_i^{-1})}}^4 \leq \sqrt{\tau(n)} \sum_i s_i\, \tau(s_i^{-1}) \,\mathrm{.}
\end{align*}
Integrating the above inequality w.r.t.~$\widehat\boldsymbol\nu_\pi$ shows that~$\mbfu_n\in L^2(\widehat\boldsymbol\nu_\pi)$ by definition of~$\tau$.

\medskip\emph{Energy bound}.\quad As for the $\widehat\boldsymbol\mssE_\pi$-energy of~$\mbfu_n$, we have
\begin{align}
\nonumber
4\,\widehat\boldsymbol{\mathsf{\Gamma}}_\pi(\mbfu_n)_{\mbfs,{\,\cdot\,}}=&\ \widehat\boldsymbol{\mathsf{\Gamma}}_\pi\paren{\sum_{\substack{i,j\\i\neq j}} s_i\, s_j\, \sigma\circ f_{i,j}}
\\
\nonumber
=&\ \sum_{\substack{i,j\\i\neq j}} \sum_{\substack{h,k\\h\neq k}} s_i\, s_j\, s_h\, s_k\, \tparen{\sigma'\circ f_{i,j}} \tparen{\sigma'\circ f_{h,k}} \, \boldsymbol{\mathsf{\Gamma}} (f_{i,j},f_{h,k})
\\
\nonumber
=&\ \sum_{\substack{i,j\\i\neq j}} \sum_{\substack{h,k\\h\neq k}} s_i\, s_j\, s_h\, s_k\, \tparen{\sigma'\circ f_{i,j}} \tparen{\sigma'\circ f_{h,k}} \, \sum_{a\in\left\{i,j,h,k\right\}} s_a^{-1}\mathsf{\Gamma}(f_{i,j},f_{h,k})
\\

=&\ 8 \sum_k\sum_{\substack{i,j\\i,j \neq k}} s_i\, s_j\, s_k \tparen{\sigma'\circ f_{i,k}} \tparen{\sigma'\circ f_{j,k}} \, \mathsf{\Gamma}(f_{i,k},f_{j,k}) \,\ma (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

