{"assumptions":[],"created_at":"2026-10-27T07:04:39.220227+00:00","domain":"probability theory","id":"claim_ebabe64d7995e36ca67ca380a9b0248fd8ebd8c353bccd6dfafe3bc604a5f5d6","kind":"definition","schema_version":1,"statement":"[Defn 7 of arXiv:2608.13976, 'Boundary Harnack principle for diffusion with jumps on metric measure spaces'] \begin{enumerate}
\item [\rm (i)]
 We say condition  ${\rm \bf (Jt)}_{\leq, \bar r, \gamma}$ holds
 with some $\bar r>0$ and $\gamma>0$ if  there is a constant $C=C(\bar r, \gamma)>0$ such that for $r\in (0, \bar r],$
\begin{equation}
J(x,  \sX \setminus B(x,r))\leq Cr^{-\gamma}   \quad\hbox{ for every }x\in\sX.
\end{equation}

\item [\rm (ii)]
 We say  condition  ${\rm \bf ({\wh{Jt}})}_{\leq,  \bar r,  \gamma}$ holds
   with $ \bar r>0$ and $\gamma >0$ if there is a constant $C= C(\bar r, \gamma)>0$ such that for every ball $B$ with radius
 $\bar r$ and  $\overline B\subsetneq \sX$ and   every  $r\in (0, \bar r/4],$
\begin{equation}
\wh J^B(x, (2^{-1}B)\setminus B(x,r))\leq Cr^{-\gamma}   \quad\hbox{ for every }x\in 2^{-1}B.
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:31:45.221392+00:00","domain":"probability theory","id":"claim_ebad8e7b68b1ee5ab8663b699485d38e681241b9d04c4c3559aff882e4fc6ff9","kind":"theorem","schema_version":1,"statement":"[Theorem formal of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] $F(x,t;q)$ admits a formal expansion
\begin{align*}
F(x,(s-\log\varepsilon)/\varepsilon;\exp(-\varepsilon))\sim e^{-xe^{-s}}\Big(1+\sum_{l=1}^\infty G_l(x,\log\varepsilon,s)\Big),
\end{align*}
where
\begin{align*}
G_l(x,\log\varepsilon,s)=\sum\limits_{m=1}^{2l}x^me^{-ms}g_{l,m}(\log\varepsilon,s)
