{"assumptions":[],"created_at":"2026-10-26T19:39:41.405591+00:00","domain":"probability theory","id":"claim_ec10dced39543db8aab25b2a9c7c578e13438566eef9909615582da714fc31d1","kind":"theorem","schema_version":1,"statement":"[Prop 7 of arXiv:2604.06516, 'From stochastic individual-based models to free-boundary Hamilton-Jacobi equations'] Let $x\in\R$. We consider the birth-death-mutation process $(Z^K_t,t\ge 0)$ defined as before but started from a unique individual with trait $x$, i.e.\ $Z^K_0=\delta_{x}$, and we denote the corresponding expectation by $\mathbb{E}_{\delta_x}$.\\ 
(i) Let $\varphi:\R\to\R$ be bounded and measurable. Then, for any $t>0$, we have
		\begin{equation}

			\mathbb{E}_{\delta_{x}}\left[\langle {Z}^K_{t}, \varphi\rangle \right]=\mathbb{E}_{x}\left[\exp\left(\int_{0}^{t} R(X^K_s)\ ds \right)\varphi(X^K_{t}) \right],
		\end{equation}
		where $X^K$ is the  process defined in  \eqref{marchealeatoire}.\\
(ii) For $t>0$, $x\in \R$ and for a bounded measurable function $\Phi:\mathbb{D}[0,t]\to\mathbb{R}$,
		\begin{equation}

			\mathbb{E}_{\delta_x}\left[\langle {\Theta}^K_t,\Phi\rangle\right]=\mathbb{E}_{\delta_{x}}\left[\sum_{u\in {V}^K_{t}}\Phi({X}^{K,u}_{s},\ s\leq t) \right]
            =\mathbb{E}_{x}\left[\exp\left(\int_{0}^{t} R(X^K_{s})\ ds \right)\Phi(X^K_{s},\ s\leq t) \right].   
		\end{equation}
(iii) For all $t>0$ and $A\subset\mathbb{D}[0,t]$,
\begin{align*}
        \E (N^{K,A}_{t})  & =\int_\R K^{\beta^K_0(x)}\E_{\mu^K_{x,T}}\Big[\exp\Big(\log K\int_0^{t} R(Y_s^K) ds \Big)\mathbbm{1}_{(Y^K_{s})_{s\in[0,t]}\in A}\Big]dx.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:53:54.936007+00:00","domain":"probability theory","id":"claim_ec12f9ea36b373909b228dd31784b56d2663e9637ab9bf5089522e3d173e2c0e","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2607.17396, '2607.17396'] Let $\left\{X_{k}, k \geq 0 \right\}$ be a critical branching process with immigration with $\lambda \in \left(0, \infty\right)$, $b^{2}\in \left(0, \infty\right)$ and $\sigma^{2}\in \left(0,\infty\right)$.
Assume that the immigration sequence $\left\{{{\varepsilon_k},k\geq 1} \right\}$ is a strictly stationary and ergodic sequence adapted to a stationary non-decreasing filtration $\left\{\mathcal{H}_{i}, i \in \mathbb{Z}\right\}$ such that $\delta_{n,2}=o\left(\sqrt{n}\right)$ as $n \to \infty$.

Then
\begin{equation}
 Y_{n} \mathop{\to}\limits^{\mathcal{D}} Y, \qquad n\to \infty,
\end{equation}
where the limit process $Y=\left\{Y\left(t\right), t \geq 0 \right\}$ is the pathwise unique strong solution of the stochastic differential equation (SDE)
\begin{equation}
 \mathrm{d} Y\left(t\right) = \lambda \mathrm{d}t+\sigma \sqrt{Y\left(t\right)^{+}} \mathrm{d} W\left(t\right)
\end{equation}
with initial condition $Y(0)=0$, where $\left\{W\left(t\right), t \geq 0 \right\}$ is a standard Wiener process. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:38:17.820026+00:00","domain":"probability theory","id":"claim_ec1742210d0035fef19a2c729ddd5594907d16a3b9cd836246944830a246494d","kind":"concept","schema_version":1,"statement":"[Lemma l.smallkappa.phi of arXiv:2510.07682, 'From tug-of-war to Brownian Boost: \\ explicit ODE solutions for player-funded stochastic-'] Let $(\rho,\beta) \in (0,\infty)^2$ and suppose that $\kappa > 0$ is less than $\min \big\{ \rho^{-2} , (1+\rho)^{-1}/2  \big\}$.
\begin{enumerate}
\item
We have that
\begin{eqnarray*}
  \phi_0(\kappa,\rho,\beta) &= & \beta \;+\; 
     \frac{4\rho\,\beta^{1+\rho}}{(1+\beta^\rho)^2}\,\kappa \;+\; \beta \, \Theta_1(\kappa,\rho,\beta) \kappa^2   \qquad \textrm{and} \\
  \phi_1(\kappa,\rho,\beta) &= & \beta \;-\; 
     \frac{4\rho\,\beta^{1+\rho}}{(1+\beta^\rho)^2}\,\kappa \;+\; \beta \, \Theta_2(\kappa,\rho,\beta) \kappa^2 \, ,
\end{eqnarray*}
where  $\vert \Theta_i(\kappa,\rho,\beta) \vert \, \leq \, 2\rho(1+\rho)$ for $i \in \{1,2\}$.
\item 

We also have that
$$
 s(x) \, = \, x - \frac{8\rho\, x^{1+\rho}}{(1+x^\rho)^2}\,\kappa  \, + \,  x \,  \Theta_3(\kappa,\rho,x) \kappa^2 
$$
with $\vert \Theta_3(\kappa,\rho,x) \vert \leq 52 \rho (1+\rho)^3$. 
\end{enumerate}
Now suppose only that $(\rho,\beta) \in (0,\infty)^2$. 
\begin{enumerate}
    \setcounter{enumi}{2} 
\item For $\xi \in (0,\infty)$ and $\kappa > 0$,
\[
 S_\rho(\xi,\kappa) \,=\, \xi - \frac{8\rho\,\xi^{1+\rho}}{(1+\xi^\rho)^2}\,\kappa \,+\, \xi\,\Theta_4(\kappa,\rho,\xi)\,\kappa^2
\]
with $\vert \Theta_4(\kappa,\rho,\xi)\vert \leq 64 \rho^2 (1+\rho)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:45.025992+00:00","domain":"probability theory","id":"claim_ec18aaad4806b6694b1b940d8180f60f51fd3f39728ccb6501b97d37d69f28a1","kind":"theorem","schema_version":1,"statement":"[Proposition 16 of arXiv:2606.06757, 'Path-Dependent Ergodic Optimal Control \\ and Backward Stochastic Differential Equations'] There exists a unique solution $(Y^{\tau,T,\xi}, Z^{\tau,T,\xi})$ to the backward SDE \eqref{BSDE_finite_horizon} and:
    \begin{equation*}
    \begin{array}{cc}
         \displaystyle (Y_t^{\tau, T,\xi}, Z_t^{\tau, T, \xi}) = (v^{T}, \zeta^T)(t, \mathcal{X}^{\tau, \xi}_t) \, , & \text{for all } \,  \tau\leq t\leq T \, ,
    \end{array}
    \end{equation*}
    for some measurable functions $v^{T} :(-\infty,T]\times \mathcal{C}_{\theta} \rightarrow \R$ and $\zeta^T : (-\infty,T] \times \mathcal{C}_{\theta} \rightarrow \mathbb{R}^d$. Moreover, the functions $v^T$ are Lipschitz continuous in $\xi$ and uniformly continuous in $t$ (uniformly in $T$), \textit{i.e.}, there exists a constant $C>0$, depending on $\eta_1$, $\eta_2$, $\theta_0$, $\theta$, and $L_H$, such that for all $t,t'\leq T$, and $\xi,\xi'\in \mathcal{C}_{\theta}$,
    \begin{eqnarray}
        \big|v^{T}(t,\xi)-v^{T}(t,\xi')\big|
        &\le&
        C\,|\xi-\xi'|_{\theta},

    \\
        \big|v^T(t',\xi)-v^T(t,\xi)\big|
        &\le&
        C \big[\,(1+|\xi|_{\theta})\,|t'-t|^{1/2}+|t-t'|+\omega_{\theta,\xi}(|t'-t|) \big].

    \end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:00.763910+00:00","domain":"probability theory","id":"claim_ec1c6ad36fa9f5335ed879a7fc3095bc6793190571e5b8fc86571fc45150d3d2","kind":"theorem","schema_version":1,"statement":"[Proposition 10 (Milstein scheme) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] Under the assumptions of Theorem~\ref{thm:rde}, let
$\{t_k = kT/n\}_{k=0}^n$ be a uniform partition of $[0,T]$ and
