{"assumptions":[],"created_at":"2026-10-27T21:59:24.050890+00:00","domain":"probability theory","id":"claim_ec3617b789f335e9d72b66549d5ba5ddd6f9860daf60dfacc1d6ddea432d3a58","kind":"theorem","schema_version":1,"statement":"[Proposition prop:coordinate-crossing of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] For $N\ge3$, the first three Ritz levels are
\begin{equation}
 \Lambda_1(N)=2N,
 \qquad
 \Lambda_2(N)=3N-\sqrt{N^2+8N-8}.
\end{equation}
Set
\begin{equation}
 R_N:=\sqrt{N^2+11N-20},
 \qquad
 \phi_N:=\frac13\arccos\!\left(
 \frac{3\sqrt3\,N(7N-16)}{2R_N^3}\right).
\end{equation}
Then
\begin{equation}
 \Lambda_3(N)
 =4N+\frac{4R_N}{\sqrt3}
 \cos\!\left(\phi_N+\frac{2\pi}{3}\right).
\end{equation}
Equivalently, $\Lambda_3(N)$ is the smallest zero of
\begin{equation}
 \lambda^3-12N\lambda^2
 +(44N^2-44N+80)\lambda
 -48N^3+120N^2-192N=0.
\end{equation}
Moreover,
\begin{equation}
 \Lambda_2(N)<2N\qquad(N\ge3),
\end{equation}
and the first crossings of the continuum coefficient along this ladder are
\begin{align}
 \Lambda_1(N)&<A_N &&(N\ge12),\\
 \Lambda_2(10)&>A_{10},\qquad
 \Lambda_2(N)<A_N &&(N\ge11),\\
 \Lambda_3(10)&<A_{10}.
\end{align}
Consequently,
\begin{equation}
 C(N)\le\Lambda_2(N)<\min\{A_N,2N\}
 \qquad(N\ge11),
\end{equation}
and $C(10)<A_{10}$ follows from the third level.  Finally,
\begin{equation}
 \Lambda_3(N)
 =2N-4-\frac6N+\frac{51}{N^2}+O(N^{-3})
 \qquad(N\to\infty).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:11.634857+00:00","domain":"probability theory","id":"claim_ec3840dbfcb5709fb0a163b4c74d8216babd0648b99accb04bdfe58d933da931","kind":"concept","schema_version":1,"statement":"[Theorem 21 of arXiv:2605.31088, 'On couplings for kinetic Langevin diffusions'] Assume that $\gamma^2>4\alpha\geq 0$ and assume $  \lambda_{-} \Delta x - \Delta v =0$ and $\Delta x \neq 0$. 
Then there exists a constant $C>0$ such that for all $h>0$, $k\in \N$ one has
\begin{equation}
    \dTV{\law(Z_k^h),\law(\tilde Z_k^h)} \leq C e^{\lambda_{-} hk} |\Delta z|.
\end{equation}
On the other hand, for all choices of $\Delta x,\Delta v\in\R^{d}$, every $h>0$ and every Markovian coupling $\mu_h$ of $(Z_k^h,\tilde{Z}_k^h)_{k\in \N}$ there exist constants $k_{\mu_h}\in\N$, $c_{\mu_h} >0$ and $c>0$ (with $c$ independent of $\mu_h$) such that for all $k\geq k_{\mu_h}$ one has
\begin{equation}
    \mu_h(Z_k^h\neq \tilde{Z}_k^h) \geq c\min\big( c_{\mu_h}(hk+1)^{-\nicefrac{1}{2}}, c_{\mu_h} e^{\lambda_{+} hk},  h^{-1} e^{\lambda_{-} hk} \big).
\end{equation}
If moreover $\mu_h$ satisfies the now-equals-forever property, then \eqref{eq:lb_couplingprob_disc} holds true for all $k\in\N$. 
Notably, if $\lambda_{-} \Delta x - \Delta v =0$ and $\Delta x \neq 0$, then one has for every $h>0$ and every Markovian coupling $\mu_h$ of $(Z_k^h,\tilde{Z}_k^h)_{k\in \N}$ that
\begin{equation}
    \liminf_{k\rightarrow \infty} 
    \frac{\mu_h(Z_k^h\neq \tilde{Z}_k^h)}{\dTV{\law(Z_k^h),\law(\tilde Z_k^h)}}
    \geq \frac{c}{C h},
\end{equation}
where $c,C>0$ are constants independent of $h$ and $\mu_h$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:32:56.074588+00:00","domain":"probability theory","id":"claim_ec3a04580f50a86044ce1cc3410bf9e1cea291905b07217a884f835c2addebed","kind":"theorem","schema_version":1,"statement":"[Theorem th:modulus-time of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Assume the conditions of Lemma (le:sLND-tilde-U of the paper) hold  and recall that $\theta_1$ and $C_1$ are given in  (equation e:theta12 of the paper) and
   (equation e:de-C1 of the paper), respectively. For any  fixed $x\in\mathbb{R}^d$, we have the following temporal regularity results:
  \begin{enumerate}
    \item (Uniform modulus of continuity). For any $0<a<b$,
    \begin{equation*}
      \lim_{\varepsilon\to0^+}\sup_{\substack{s,t\in[a,b];\\ |t-s|\le\varepsilon}}\dfrac{|u(t,x)-u(s,x)|}{|t-s|^{\theta_1}\sqrt{\log\left(1+|t-s|^{-1}\right)}}=\sqrt{2C_1},
