{"assumptions":[],"created_at":"2026-10-26T19:46:12.282083+00:00","domain":"probability theory","id":"claim_ec3eb6152e18b22a5f15b888851eb87f8cd5aba824969eb44ed86cc86496849f","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2604.22567, 'Sign-balance of random Laplace eigenfunctions'] $\, $

