{"assumptions":[],"created_at":"2026-10-27T09:43:00.038115+00:00","domain":"probability theory","id":"claim_ec6386de063d99d9de3e8ed25075c8ead7c7e87e71737454eb7a23cfe39b804c","kind":"concept","schema_version":1,"statement":"[Lem 20 of arXiv:2609.00739, '2609.00739'] Let
\[
 Z(r):=\zetastar^a(B_r),
 \quad F(r):=\frac{Z(r)}{r},
 \quad H(r):=\int_{B_r}x\cdot\dd h(x).
\]
For almost every $0<r_0<r_1<\rho$,
\begin{equation}
 F(r_1)-F(r_0)
 =\int_{B_{r_1}\backslash B_{r_0}}
 \frac{1}{4\abs{x}}\dd\mathcal N(x)
 +\int_{r_0}^{r_1}\frac{H(s)}{2s^2}\dd s.
\end{equation}
Define the right-continuous representative
\[
