	where $ \hat{C}_t= C_t\int_{0}^{t}\phi(t,r)C_r\mathrm{d}r$,
	$\mathrm{d}W$ indicates the usual It\^o integral and $\diamond\mathrm{d}B^H$ denotes the FWIS integral.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:04.860517+00:00","domain":"probability theory","id":"claim_ecbf2b9b74171a6a22e3dc23db2936c74ebcfda7260dac20e377096483bb1469","kind":"lemma","schema_version":1,"statement":"[Lem 26 (\textit{cf.} {\cite[THEOREM 5.4) of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] {Shigekawa}}]
Let $n \in \N$ and $F$ be a random variable. 
Suppose that, for every $m \in \{1, \ldots, n\}$, there exists $K_m \in L^p(\Omega)$ with $p > 1$ such that for all $\varphi \in C^{\infty}_{\mathrm{c}}(\R)$, 
\begin{equation}
    \E[\varphi^{(m)}(F)] = \E[\varphi(F)K_m]. 
\end{equation}
Then, the law of $F$ has a density function $\rho_F \in C_{\mathrm{b}}^{n-1}(\R)$ that satisfies
\begin{align}
    \norm{\rho_F}_{C_{\mathrm{b}}^{n-1}(\R)} \lesssim_{n,p} 
    \begin{cases}
        \norm{K_1}_{L^p(\Omega)}, &\text{when $n = 1$},\\
        \left( 1 + \sum_{m=1}^{n} \norm{K_m}_{L^p(\Omega)} \right)\norm{K_1}_{L^p(\Omega)}^{1-\frac{1}{p}}, &\text{when $n \geq 2$}.
    \end{cases}

\end{align}
Moreover, $\rho^{(j)}_{F} \in \bigcap_{r \in [1,\infty)}L^r(\R)$ holds for every $j \in \{0, \ldots, n-1\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:48:24.522489+00:00","domain":"probability theory","id":"claim_ecc092b2653ca9b8f8a2bc28f047bc84f424ad652e3ef3552a8ad2598ebd480c","kind":"lemma","schema_version":1,"statement":"[Lemma L5.9 of arXiv:2512.18990, '\bf Hybrid Stochastic Functional Differential Equations with Infinite Delay: Approximation'] Suppose that all conditions  of Lemma (TH5.8 of the paper) hold. Then for any $\Delta\in(0, 1]$,
