{"assumptions":[],"created_at":"2026-10-27T13:41:28.180837+00:00","domain":"probability theory","id":"claim_ed6a291630c71cdcb5b3b8cca82d15ae7679972a0b28690ec842a64cc78b9beb","kind":"concept","schema_version":1,"statement":"[Proposition pro:CheegerPoincareBounds of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $D \geqslant 2$ be an integer and $U$ be a doubly stochastic irreducible $D \times D$ transition matrix. Let $U^+$ be the additive symmetrisation of $U$. Then
    \begin{enumerate}[label=(\alph*)]
        \item The Cheeger constant $\Phi_{\ast}(U)$ of $U$ is equal to that of $U^T$ as well as to that of $U^+$.

        \item The spectral gap $\gamma^+$ of $U^+$, also known as the \emph{Poincar\'e constant} of $U$, satisfies $\gamma^+ \asymp \Phi_{\ast}(U)$.

        \item The following \emph{Poincar\'e inequality} holds: For any distribution $\nu$ on $[D]$, writing $\pi$ for the uniform distribution on $[D]$, we have that for all $t \geqslant 0$,
        \begin{equation*}
            \normtp{\nu \mathrm{e}^{t(U-I)} - \pi} \leqslant \mathrm{e}^{-\gamma^+ t} \left\lVert\nu - \pi\right\rVert_{2, \pi} = \mathrm{e}^{-\gamma^+ t} \Big( \sum_{x \in [D]} \Big( \frac{\nu(x)}{\pi(x)}-1\Big)^2 \pi(x)\Big)^{\frac{1}{2}}.
        \end{equation*}

        \item In the notation of (c), uniformly in $t \geqslant D$, we have that
        \begin{equation*}
            \normtp{\nu \mathrm{e}^{t(U-I)} - \pi} \lesssim (1+t^D)  \mathrm{e}^{-\gamma (t-D)} \left\lVert\nu - \pi\right\rVert_{2, \pi}.
        \end{equation*}

        \item The worst-case total variation distance from $\pi$ at time $t$, defined as
        \begin{equation*}
            \mathrm{d}_{\mathrm{TV}}(t) \coloneqq \max_{x \in [D]} \normTV{\delta_x \mathrm{e}^{t(U-I)} - \pi},
        \end{equation*}
        where $\delta_x$ is the Dirac measure on $x$, satisfies uniformly in $t \geqslant D$ that
        \begin{equation*}
            \frac 12 \mathrm{e}^{-\gamma t} \leqslant \mathrm{d}_{\mathrm{TV}}(t) \lesssim (1+t^D)  \mathrm{e}^{-\gamma (t-D)}.
        \end{equation*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:31:14.335607+00:00","domain":"probability theory","id":"claim_ed6abbdff0ce6134a5ae01f277d5468a419c5744b4603ee0e8121ae9a134818d","kind":"definition","schema_version":1,"statement":"[Definition general_term of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] The terms we consider are defined by the data $\#_{\mathcal{I}} \in \mathbb{Z}_{\geq 1}$, a positive integer $\#_{\beta}$, a time factor $g : \mathbb{R}_{\geq 0} \to \mathbb{R}$, a bounded sequence, $\kappa = \kappa_N : [[1, N]]^{\#_{\mathcal{I}}} \to \mathbb{R}$, a constant $d_N \in \mathbb{R}$, and a tuple of positive integers $(r_k)_{k=1}^{\#_{\beta}}$. We define $\mathcal{I}$ as a multi-index of free summation indices $i_1, \dots, i_{\#_{\mathcal{I}}}$ that are iterated from $1$ to $N$. The above data defines a sequence of functions ${\mathbb R}^+ \to {\mathbb R}$ by, 
		\begin{equation}
			\begin{split}
			& t \mapsto g(t) \frac{N^{d_N}}{N^{\#_{\mathcal{I}}}} \sum_{\mathcal{I}} \kappa(\mathcal{I}) \sum_{\beta \in [[1, K]]^{\#_{\beta}}}\EX\Bigg[(\partial_\beta F) (\widetilde{\mathcal{L}}_\tau (X(t))) \prod_{k=1}^{\#_{\beta}} \Bigg(\sum_{\mathcal{J} \in J^{r_k}} \partial_{\mathcal{J}} \mathcal{L}_{\tau}^{\beta_k} (X(t)) \prod_{s=1}^{r_k} \Big( \mathrm{IF}(k, s, \mathcal{I}, \mathcal{J})\Big)\Bigg)\Bigg],
			\end{split}

		\end{equation} where $\mathrm{IF}(k, s, \mathcal{I}, \mathcal{J})$ denotes an \textit{inner factor}. Denote $\mathcal{J}(s) = (\alpha(\mathcal{J}(s)), i(\mathcal{J}(s)), j(\mathcal{J}(s)))$, let $q_i$ and $q_j$ be the basis vectors $q_{i(\mathcal{J}(s))}$ and $q_{j(\mathcal{J}(s))}$ respectively and $\alpha = \alpha(\mathcal{J}(s))$. Each inner factor is defined by the following ($k$ and $s$ dependent) data: 
		\begin{itemize}
			\item Integers $n_1 \in \mathbb{Z}_{\geq 1}$, $n_2 \in \mathbb{Z}_{\geq 0}$, and the tuple $(\hat{n}_l)_{l=1}^{n_2} \in \mathbb{Z}_{\geq 1}^{n_2}$. 
			\item $\mathcal{I} \cup \{q_i, q_j\}$-valued indices $u_i, v_i$, $1 \leq i \leq n_1$. We assume that $q_{i}$ and $q_{j}$ occur exactly once in $(u_i, v_i)_{i=1}^{n_1}$. 
			\item For $1 \leq l \leq n_2$: $\mathcal{I}$-valued indices $\hat{u}_{j}, \hat{v}_{j}$, $1 \leq j \leq \hat{n}_l$.
		\end{itemize}
		The above data uniquely defines the inner factor, \begin{equation}
			\mathrm{IF}(k, s, \mathcal{I}, \mathcal{J}) := \frac{N}{\pi} \int_{I} \im \prod_{i=1}^{n_1} G_{u_i v_i} \varrho^{(n_2)}_{\alpha} \prod_{l=1}^{n_2} \Big(\Delta \im \Big(\prod_{j=1}^{\hat{n}_l} G_{\hat{u}_j \hat{v}_j}\Big) \Big)\mathop{}\!{d} E.

		\end{equation} A term of the form (equation general_term of the paper) shall usually be called $T$, and we shall write \emph{e.g., } $r_k(T)$, $\mathcal{I}(T)$, $n_1(k, s)(T)$, $g(t)(T)$, etc., to denote the defining data of $T$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.495477+00:00","domain":"probability theory","id":"claim_ed6c9c8a3ee53d6b13a67f26f88362d08ae9bd39b18776d99f0e46860ac9c9cd","kind":"theorem","schema_version":1,"statement":"[Cor gamma 1 gamma2 capacity change of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Let $\gamma$, $\tilde{\gamma}$ be two hulls starting at $e^{ix} \in \partial \mathbb{D}$ and $e^{iy} \in \partial \mathbb{D}$ with capacity $\varepsilon$ and $c \varepsilon$ , let $g_{\varepsilon}$ be the normalized map removing $\gamma$ and $\tilde{\varepsilon}= \operatorname{hcap}(g_{\varepsilon}\circ \gamma(t))$, then we have:

\begin{equation}
\tilde{\varepsilon}=
c \varepsilon\left(1-\frac{\varepsilon}{\sin^2(\frac{x-y}{2})}\right)+o\left(\varepsilon^2\right).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.428985+00:00","domain":"probability theory","id":"claim_ed6d64bce453108fc01aa7fe3b6760a683ba478d0661560902a91074a9524dbf","kind":"concept","schema_version":1,"statement":"[Lemma LemPAIon of arXiv:2508.03577, 'Phase Transitions in a Particle Model\\ for the Self-Adaptive Response to Cancer Dynamics'] The following algorithm samples the steady-state distribution of the (jump-chain) of the model with PAI switched on: start with the zero matrix. Evolve time in discrete steps. At each step, 
    \begin{enumerate}
        \item with probability $p/(1+N\lambda_m)$, select a uniformly chosen column to the list of forbidden columns,
        \item with probability $q/(1+N\lambda_m)$, turn the entries of a uniformly selected row into ones, given that the entry is not located in a forbidden row,
        \item with probability $\lambda_m N/(1+N\lambda_m)$, turn a uniformly selected entry of the matrix into a one, given that the entry is not a forbidden column.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:02:34.832548+00:00","domain":"probability theory","id":"claim_ed6f008d4f039adc102e22697b33fd4174452b00921c2faad1e45c776ea2a053","kind":"concept","schema_version":1,"statement":"[Theorem 1 (Gaussian permanent anticoncentration) of arXiv:2607.20329, '2607.20329'] For every $\mathbb K\in\{\R,\C,\Hh\}$ and $n\ge1$,
		$W_n^{\mathbb K}$ has a radial density $p_n^{\mathbb K}$ satisfying
		\begin{equation}
			\|p_n^{\mathbb K}\|_\infty
			=p_n^{\mathbb K}(0)
			\lesssim_\beta n^{(\beta+2)/4}.
		\end{equation}
		Consequently, for every $\varepsilon>0$,
		\begin{equation}
			\sup_{z\in\mathbb K}
			\Pp(|W_n^{\mathbb K}-z|\le\varepsilon)
			\lesssim_\beta n^{(\beta+2)/4}\varepsilon^\beta.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:51:33.318239+00:00","domain":"probability theory","id":"claim_ed7085b56940fdbbc0033a876e8b0afff1f21b8725ee802ac2a1420fb1941790","kind":"concept","schema_version":1,"statement":"[Prop pb-surj-glo of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let
    \begin{equation}
        \begin{tikzcd}
            A\arrow[r,"g"]\arrow[d,"q"']\arrow[dr,pullback] & B\arrow[d,"p"]\\
            C\arrow[r,"f"'] & D
        \end{tikzcd}
    \end{equation}
    be any pullback square in the 1-category of compact Lie groups such that the homomorphism $p$ is \emph{surjective}. Then the corresponding square in $\textup{Glo}$ is a pullback.

