\displaystyle{\int_{\mathcal{O}^*(\Lambda)}}\mathcal{E}_{\leq K}(\Omega)dm_{\mathrm{KKS}}(\Omega) & = \dfrac{\|\Lambda\|^2}{2c_N(N^2-1)}\cdot \sum\limits_{0<|k|\leq K} \dfrac{1}{|k|^2} \ ,
\\
\displaystyle{\int_{\mathcal{O}^*(\Lambda)}}\mathcal{Z}_{\leq K}(\Omega)dm_{\mathrm{KKS}}(\Omega) & = \dfrac{\|\Lambda\|^2}{2c_N(N^2-1)}\cdot \left|\{k: 0<|k|\leq K\}\right| \ .
