						\lim_{|\pi|\rightarrow 0} \left|\varphi^{\pi}(\bold{x}(t_0),\cdots,\bold{x}(t_n)) - \Phi(\bold{x})   \right| = 0.
					\end{equation}
				\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:43:43.440566+00:00","domain":"probability theory","id":"claim_ee9b89db5f1a77166060e264bc1d98273387289247f42ed1f7620aea209e9925","kind":"lemma","schema_version":1,"statement":"[Lemma Lebesguept of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] Let $1 \leq p \leq q$, $\Theta$ be a scale function and $(\mathcal{F}_p,\Gamma_p,\Psi)$ be a $p$-energy structure.
    Let $\nu$ be a Borel measure on $X$ for which there are constants $K \geq 1$ and $R > 0$ such that
        \begin{equation}
            \nu(B(x,r))^{\frac{1}{q}} \leq K \Theta(x,r) \left( \frac{\mu(B(x,r))}{\Psi(x,r)} \right)^{\frac{1}{p}}
        \end{equation}
    for all $x \in X$ and $0 < r \leq R$.
    Then for every $f \in \mathcal{F}_p$ the following holds for $\nu$-almost every $x \in X$. Given any pair of sequences $y_i\in X$ and $r_i > 0$ such that $x \in B(y_i,r_i)$ for all $i \in \mathbb{N}$ and $r_i \to 0^+$ as $i \to \infty$, the limit
    \begin{equation}
        \lim_{i \to \infty} \vint_{B(y_i,r_i)} f\, d\mu
    \end{equation}
    exists and is independent of the choices of the sequences.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:23:27.793481+00:00","domain":"probability theory","id":"claim_eea24fa2ff5c2e516e98464f45bb50628af2a29a840c6b7df73af7719894d80b","kind":"lemma","schema_version":1,"statement":"[Lemma covougff of arXiv:2606.11043, 'Thick points under Gaussian free field dynamics'] Take $(e_n)_{n\in \mathbb N}$ an orthonormal basis of $H_0^1(D)$ with the inner product of (equation eq.h01-ip of the paper) to define the OU-GFF $\varphi$. Then, the collection $(\langle \varphi(t), f\rangle_\nabla)_{t\in \mathbb R, f\in H_0^1(D)}$ is a centered Gaussian process with covariance given by
    \begin{equation}
        \mathbb E[\ipn{\varPhi(t)}{f} \ipn{\varPhi(s)}{g}] 
        = e^{-\frac{1}{2}|s-t|}\ipp{f}{g}_{\nabla}, \ \ \ \text{ for any $s,t \in R$ and $f,g \in H_0^1(D)$.} 
    \end{equation}
    As a consequence, for $f,g\in H_0^{-1}(D)$  and $s,t\in \mathbb R$
    \begin{equation*}
        \mathbb E[\ipp{\varPhi(t)}{f}\ipp{\varPhi(s)}{g}] = 
        \frac{1 }{2\pi } e^{-\frac{1}{2}|t-s|}\ipp{f}{(-\Delta)^{-1}g},
    \end{equation*}
     thus the law of $\varPhi$ does not depend on the choice of the basis $(e_n)_{n\in \mathbb N}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:15:16.649947+00:00","domain":"probability theory","id":"claim_eea4cbeeb13c5940e7a2ec27c93523a1bac896887a7f6caa1655458d5cf406f4","kind":"definition","schema_version":1,"statement":"[Defi 13 (\cite{KT25}, Definition 2.1.8) of arXiv:2608.30743, 'Perspectives on the Bott spectral sequence for Lie groupoids'] The groupoid $J^E G$ is the fat groupoid associated to the VB-groupoid

