{"assumptions":[],"created_at":"2026-10-26T20:52:17.371763+00:00","domain":"probability theory","id":"claim_ef67a1075007519ca5500391f506d9657dc24402d1fea21086069beb4a9a5b54","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.03973, 'A remark on the \\ majorizing measures theorem for general processes'] Suppose that $X \sim \mu$ is a centered random vector in $\R^n$ such that
  \begin{equation}

  \klconst(\mu) = \sup_{\substack{\theta, \eta \in \R^n \\ \theta \neq \eta}} 
\frac{\kl{\mu_\theta}{\mu_\eta}}{\|\theta - \eta\|_2^2} < \infty,
  \end{equation}
  where $\mu_\theta$ denotes the law of the translate $\theta + X$.
  Then, for any nonempty, bounded $T \subset \R^n$,
  \[
  \E_\mu \Big[\sup_{t \in T} \, \langle X, t \rangle \Big] \gtrsim \frac{1}{\sqrt{\klconst(\mu)}} \, \gamma_2(T).
  \] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:13:31.955602+00:00","domain":"probability theory","id":"claim_ef6b75bf3dde4f1588b234f3eb2ae8459a3aae2ce0f3ee38100a7dd1a04eb61c","kind":"lemma","schema_version":1,"statement":"[Lemma lem:intermediate_recursion of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] For all ${n < N-1}$,
    \begin{align*}
        (\mathtt d^\mathsf{sh}_{n+1})^2
        &\leqslant L_n^2 \,(\mathtt d^\mathsf{sh}_n)^2 + O\bigl((\mathtt E^{\rm w}_n + \zeta_n \mathtt E^{\rm s}_n)\,\mathtt d^\mathsf{sh}_n + (\mathtt E^{\rm s}_n)^2\bigr)\,,
    \end{align*}
    where:
    \begin{itemize}
        \item $L_n$ is the effective contraction constant at iteration $n$ for the ``diffuse then shift'' process given in Lemma~(lem:discrete_contraction of the paper), i.e.,
            \begin{align*}
                L_n = \exp\Bigl(-c\int_{nh}^{(n+1)h} (\omega_+ + \eta_t^\mathsf{p})\,\mathrm{d} t\Bigr)\,.
            \end{align*}
        \item $\mathtt E$ denotes the local errors in the twisted coordinates. Namely, introducing a third process $\tilde\psi$ which starts at $\psi_n^\mathsf{alg}$ and evolves by the diffusion $\boldsymbol{P}$, we define
            \begin{align*}
                \mathtt E_n^{\rm w} \coloneqq \sqrt{\mathbb{E}[\norm{\mathbb{E}[\uppsi^\mathsf{alg}_{n+1} - \tilde \uppsi_{n+1} \mid \mathscr{F}_n]}^2]}\,, \qquad
                \mathtt E_n^{\rm s} \coloneqq \sqrt{\mathbb{E}[\norm{\uppsi^\mathsf{alg}_{n+1}- \tilde \uppsi_{n+1}}^2]}\,,
            \end{align*} 
            where the inner expectations are conditional on the filtration $\mathscr{F}_n$ at iteration $n$.
        \item $\zeta_n$ is the ``coupling constant'', defined in~(equation eq:zeta of the paper) below.
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:05:57.792962+00:00","domain":"probability theory","id":"claim_ef6c92ed60112aca6e22763c7044346d2d2da28ccb23be0b30c874a45049ff0c","kind":"lemma","schema_version":1,"statement":"[Lemma 54 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $\SC$ be as defined at the start of \cref{sec:example_lmd<umd} and
    consider $\SC$ as a subset of $\ell^{\infty}(\NN)$.
    Then for every $\eps \in (0,1)$ we have
    \begin{equation*}
        \prod_{i=1}^{n(\eps)} \frac{a_i}{\eps}
        \le \cn(\SC,\eps) 
        \le \prod_{i=1}^{n(\eps)} \Bigl(\frac{a_i}{\eps} +1\Bigr)  .
 \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:57:07.194129+00:00","domain":"probability theory","id":"claim_ef72118a733311d28fc6af53315454b42ce51fd1d8c0b5c3e7462ca144b10eae","kind":"theorem","schema_version":1,"statement":"[Theorem th:main of arXiv:2508.21055, 'Modern aspects of Markov chains:\\entropy, curvature and the cutoff phenomenon'] We have
\begin{eqnarray*}
\forall f\in\mathcal {F}_1^+,\quad\forall \varepsilon\in(0,1/2),\quad {\rm w}_{\textsc{mix}}(f,\varepsilon) & \le & \frac{2}{\gamma \varepsilon^2}\left(1+\sqrt{V_{f,\varepsilon}}\right),
\end{eqnarray*}
where $V_{f,\varepsilon}:=\mathrm{Varent}(P_t^\star f)$ is the varentropy at time $t={\rm t}_{\textsc{mix}}(f,1-\varepsilon)$. Similarly,
\begin{eqnarray*}
{\rm w}_{\textsc{mix}}(\varepsilon) & \le & \frac{2}{\gamma \varepsilon^2}\left(1+\sqrt{V_{\varepsilon}}\right),
\end{eqnarray*}
where $V_\varepsilon:=\max_{x\in\mathbb{X}}\sqrt{\mathrm{Varent}(P_t^\star f^x)}$ is the worst-case varentropy at time $t = {\rm t}_{\textsc{mix}}(1-\varepsilon)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.197827+00:00","domain":"probability theory","id":"claim_ef72586f2c6a69aec737b411d8405abd03270c04df6297247bd33c91ad641774","kind":"concept","schema_version":1,"statement":"[Lem 44 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For any $K \geq (\widetilde C_{\mu}+\varepsilon) \log N$ and $i\in \{\iota(p),\ldots,\tau(p)-2\}$, and any $\xi>0$, there exists an event $F_i=F_i(\xi) \in \sigma(\mathbf a_i)$ and $\zeta=\zeta(\mu,\xi)$, such that the following holds.
        \begin{enumerate}[label=(\alph*)]
            \item 

            We have
            \begin{equation} 
                \mathbb P(F_{i}) \geq 1- \exp(-N^{\zeta}).
            \end{equation}
            \item 

            There exists $C(\mu,\chi)>0$ such that if $s_i \in \mathsf S^\p _{\for}$, we have that for all $x \in \mathsf S^\p_{\for}$ and $x>_{\lex} s_i$, 
            \begin{equation}

                \mathbb E\left[\left|\cI(B_x) \right|\big\vert \mathbf a_i\right] \leq C(\mu,\chi)N(\lambda_{x})^{1-o_{\chi}(1)}\cdot N^{O(\chi)}.
            \end{equation}
            on the event $F_i$.
            \item 

            There exists $C(\mu,\chi)>0$ such that if $s_i \in \mathsf S^\p _{\for}$, we have
            \begin{equation}

                \mathbb E\left[\left|\{j>i:s_j=s_i \}\right|\big\vert \mathbf a_i\right] \leq C(\mu,\chi)N(\lambda_{s_i})^{1-o_{\chi}(1)}\cdot N^{O(\chi)}.
            \end{equation}
            on the event $F_i$.
            \item

            There exists $C(\mu,\chi)>0$ such that if $s_i \in \mathsf S^\p _{\for}$, we have that for all $x \in \mathsf S^\p_{\for}$ and $x>_{\lex} s_i$, 
            \begin{equation} 
                \mathbb E\left[\left|E(G_{B_x}) \right|\big\vert \mathbf a_i\right] 
                \leq C(\mu,\chi)N^{2-\frac{K-M}{\log N}\sum_{1 \leq i \leq z} h_i\psi_{\bp^{(i)}}(2)+o_\chi(1)} \cdot(\lambda_{x})^{2-o_\chi(1)} 
            \end{equation}
            on the event $F_i$,
            where $M$ is the length of prefix $x$.
            \item 
             For any prefix $x$ such that $\lambda_x \geq N^{-1+\xi}$, we have 
            \begin{equation}
                \P \lt( \big|\,|\cI(B_x)|-N \lambda_x \big| \leq (N \lambda_x)^{\frac{4}{5}} \big|\mathbf a_i \rt)\geq 1-\exp(-N^{\xi/2})
            \end{equation}
            on the event $F_i$.
            \item 

            For any prefix $x$ such that $\lambda_x \geq N^{-1+\xi}$, we have 
            \begin{equation}
                \P \Big(\Big|n^{(t),x}_{ l}-N \lambda_x \cdot \frac{n^{(t)}_{ l}}{N}\Big| \leq (N \lambda_x)^{\frac{4}{5}} \mbox{  for all $(t,l) \in \mathsf{P}$ and $ M<t\leq K$}\big|\mathbf a_i \Big)\geq 1-\exp(-N^{\xi/2})
            \end{equation}
            on the event $F_i$, where $M$ is the length of prefix $x$.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

