{"assumptions":[],"created_at":"2026-10-27T08:18:19.227092+00:00","domain":"probability theory","id":"claim_efa24b0b6af855861193c8c95ad0825fd1cf10cb811334baac3a81365b896105","kind":"definition","schema_version":1,"statement":"[Definition 27 of arXiv:2608.29086, '2608.29086'] [$Part(m)$]
Given $P, m \in Obj(Mol)$. $P$ is called a \textit{partition} of $m$ if
\begin{enumerate}
\item $P \rightarrow_M m$, and
\item $|P|=|m|$. 
\end{enumerate} 
Given $m \in Obj(Mol)$. $Part(m)$ denotes the collection of all partitions of $m$, i.e,
\begin{equation*} 
Part(m):=\{P \in Obj(Mol)\ |\  P \text{ is a partition of } m\} \quad \subset Obj(Mol).
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:19:00.857313+00:00","domain":"probability theory","id":"claim_efa3dda482ef25e56d7e66e3e9f241bfa96c78aa97c6bbe48db64166fb86c8cb","kind":"concept","schema_version":1,"statement":"[Corollary 7 (Conditional form) of arXiv:2608.20337, 'Information on trajectories:\\ martingales and random times'] \begin{equation}
  \log Z_T(\alpha)
  = \max_{\widetilde Q \ll P}
    \left\{
      \sum_{t=1}^T \E_{\widetilde Q}\!\left[
        \alpha_t \log R_t - \KL(\widetilde Q_t \| P_t)
      \right]
    \right\}
\end{equation}
where $\widetilde Q_t = \widetilde Q_t(\cdot \mid X_{1:t-1})$ and $P_t = P_t(\cdot \mid X_{1:t-1})$.
The maximizer $R^*_\alpha$ has one-step conditional densities
\begin{equation}
  r^*_{\alpha,t}(x_t \mid x_{1:t-1})
