{"assumptions":[],"created_at":"2026-10-27T13:47:12.039427+00:00","domain":"probability theory","id":"claim_efe03d29911e14bc5de913712ce0b9ab187c90d73ada51f989c15dd5f1854c3b","kind":"theorem","schema_version":1,"statement":"[Proposition comu-prop-1 of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Let $\phi$ be a $C^{1}$-diffeomorphism of $\mathbb{R}^{d}$.  Assume that there exist $\beta \in(0,1)$ and $p\geq 1$ such that 
 \begin{trivlist}
\item[(i)] $v \in C_{\mathrm{loc }}^{\beta}(\mathbb{R}^{d}, \mathbb{R}^{d})$,
\item[(ii)]
$\operatorname{div} v \in L_{\mathrm{loc}}^{1}(\mathbb{R}^{d})$,
\item[(iii)]
$g \in L_{\mathrm{loc}}^{\infty}(\mathbb{R}^{d})$ and 
\item[(iv)]
$J \phi^{-1} \in W_{\mathrm{loc}}^{1-\beta,p}\left(\mathbb{R}^{d}\right)$.
  \end{trivlist}
 Then for  all $r>0$ and any $R>0$, 
 there exist  constants $C_R>0$ and $C_{R,p}>0$ such that if 
 $\rho \in C_{r}^{\infty}$  such that $\operatorname{supp}\left(\rho \circ \phi^{-1}\right) \subseteq B_R$, then 
\begin{align}
&\quad\left|\int_{\mathbb R^d} \mathcal{R}_{\ensuremath{\varepsilon}}[ v,g](\phi(x)) \rho(x) d x\right|\\
&\leq C_{R}\Vert g\Vert_{L_{R+1}^{\infty}}\Vert\rho\Vert_{L_{r}^{\infty}}
\Vert\operatorname{div} v\Vert_{L_{R+1}^{1}}\Vert J \phi^{-1}\Vert_{L_{R}^{\infty}}\\
&\quad+C_{R,p}\Vert g\Vert_{L_{R+1}^{\infty}}[v]_{C_{R+1}^{\beta}}\left(\Vert D \rho\Vert_{L_{r}^{p}}\left\Vert D \phi^{-1}\right\Vert_{L_{R}^{\infty}}\left\Vert J \phi^{-1}\right\Vert_{L_{R}^{\infty}}+\left[J \phi^{-1}\right]_{W_{R}^{1-\beta, p}}\Vert\rho\Vert_{L_{r}^{\infty}}\right).
\end{align}
Moreover, 
\begin{equation}
\lim _{\ensuremath{\varepsilon} \to  0} \int_{\mathbb R^d} \mathcal{R}_{\ensuremath{\varepsilon}}[v, g](\phi(x)) \rho(x) d x=0.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:10:05.759224+00:00","domain":"probability theory","id":"claim_efe399c65998594ae3b81183cab087b46588d65cbdd47b2dda41c4c2ea1bf0a6","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2608.17493, 'Integrals of some compound processes'] Let $\lambda>0$, $f$ be a Bernstein function as in \eqref{definizioneFunzioneBernstein} with $ \bar \nu_f\not=0$ and
	\begin{equation}
		a_k = a_{\lambda,f,k} = \frac{1}{f(\lambda)} \frac{\lambda^k}{k!}\int_0^\infty e^{-\lambda w} w^k \bar \nu_f(\dif w),\ \ \ k\ge1.
	\end{equation}
	\begin{itemize}
		\item[($i$)] $\displaystyle \sum_{k\ge1} a_k = 1-(a+b\lambda)/f(\lambda)$.
		\item[($ii$)] $ \displaystyle f\big(\lambda(1-x)\big) = f(\lambda) \Bigg(1- \sum_{k\ge 1}a_k x^k\Bigg) - b\lambda x ,\ \ \ x\le1. $
		\item[($iii$)] Let  $a'_1 = a_1 + b\lambda/f(\lambda)$ and $a'_k = a_k,\ k\ge2$. Let $F$ be a distribution function and $p$ be a suitable function. $f$ has $a=0$ if and only if
		\begin{equation}
			f\Big(\lambda\big(I-C_F\big)\Big) p= f(\lambda)\big(I-C_{ F_f}\big) p
		\end{equation}
		with $F_f$ being the distribution
		\begin{equation}

		F_f = \sum_{k\ge1} a'_k F^{(k)} = \sum_{k\ge1} a'_k\, \conv_{h=1}^k F, \ \ \ x\in \mathbb{R}.
		\end{equation}
	\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:25:55.462549+00:00","domain":"probability theory","id":"claim_efe48ed41920297f3a57a7aba69844e7b7763b0b95f31d2dacfc628f5f7d3b67","kind":"concept","schema_version":1,"statement":"[Thm 20 of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] If $\{\mathcal{G}^{\varepsilon}\}$ satisfies {Condition A}, then $X^{\varepsilon}$ satisfies the large deviation principle on $\mathcal{E}$ with the
