        \mathcal{E}(f,g)\ &\leq\ C\norm{f}\norm{{\mathcal{C}}g}&&\kern-2em\text{for all }f\in\dom(\mathcal{E})\cap\mathbb{H}^h,\, g\in\dom({\mathcal{S}})\,.\tag{C}
