x^n \rightarrow_{\text{l.u.}} x\quad\text{on} \quad \mathbb{I}:=[0,T]\!\setminus\!D(\tau)
	\end{equation}
with $x^n(T)\rightarrow x(T)$. In particular, $x^n(t)\rightarrow x(t)$ for all $t \notin  D(\tau)$ and $t=T$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:45:17.697291+00:00","domain":"probability theory","id":"claim_f060ea999548ff6ef757761d785097941a6a17099ffe74e758cb6ea5e8ef57c8","kind":"concept","schema_version":1,"statement":"[Lemma lem: GT-truncation of arXiv:2604.08462, 'Convergence of $k$-point functions in\\ high dimensional percolation'] Let $R>0$. Suppose that $(x_0, \dots, x_k, \underline{g}) \in G(\epsilon^R, n)$. Let $x_I, x_J$ be chosen as at Proposition (prop: tree-reduct of the paper). We have, uniformly in $n$ and in $T \in \mathfrak{T}_{k}$, that
 \begin{align}
        &\mathbb{P}\left(\begin{array}{c}\Gamma(x_{\phi(0)}, \dots, x_{\phi(k)}, \underline{g}), \mathcal{T}(x_{\phi(0)}, \dots, x_{\phi(k)}, \underline{g}) = \phi(T), \\
        \{x_I \leftrightarrow \overline{g} \text{ off }\,\mathfrak{C}(\underline{g})\} \circ \{x_J \leftrightarrow \overline{g} \text{ off }\,\mathfrak{C}(\underline{g})\}
