{"assumptions":[],"created_at":"2026-10-27T17:27:32.350267+00:00","domain":"probability theory","id":"claim_f15a9e576464c79c44e11409530865bd40ad2343bac9e5cb17678c77379084b9","kind":"theorem","schema_version":1,"statement":"[Proposition prop_densityrepfortarget of arXiv:2509.18045, 'Density convergence on Markov diffusion chaos via Stein's method'] Assume $F$ is a random variable that admits a density function $p$ with support on an interval $(\ell,u), -\infty\leq \ell<u\leq \infty$. 
\begin{enumerate}[label=\roman*)]
	\item   If $p(x)$ is continuously differentiable on $(\ell,u)$,  then for every $x\in (\ell,u)$
\begin{equation}
	p(x)=\mathbb{E} \left[ \mathds{1}_{\{ F>x\}} h(F) \right]\,,\quad \hbox{where}\quad  
	h(x)=h_0(x)=-\frac{d}{dx} \log (p(x))\,.  
	\end{equation}  
\item Let $k\in \mathbb{N}$.  If $p(x)$ has continuous derivative up to order $k+1$ and moreover $\lim_{x\to u^{-}} p^{(k)}(x)=0$,  then for every $x\in (\ell,u)$    
\begin{equation}
	p^{(k)}(x)=\mathbb{E} \left[ \mathds{1}_{\{ F>x\}} h_k(F) \right]\,,\quad \hbox{where}\quad 
	h_k(x)=-\frac{  p^{(k+1)} (x)}{p(x)} \,.   
\end{equation} 
\item The sequence $h_k$'s  satisfy  the following recursive formula:
\begin{equation}
	h_{k+1}(x)=h_k'(x)+h_k(x)\frac{d}{dx} \log p(x) =h_k'(x)-h_k(x) h_0(x)\,. 

\end{equation}
\end{enumerate}","status":"unverified"}

