  \end{equation*}
  over \(W(k)\) with Frobenius lift given on the standard coordinates by
  \begin{equation*}
    t_i  \mapsto  t_i^p, \qquad u_i  \mapsto  u_i^p.
  \end{equation*}
  Then, for every integer \(r \geq 1\), there exists a morphism
  \begin{equation*}
    s'_r \colon W_rS_{\setF_p} \to S
  \end{equation*}
  and a commutative diagram
  \begin{equation*}
    \begin{tikzcd}
    W_rS_{\setF_p} \arrow[d, "s'_r"'] \arrow[rd, "\sigma_{S,r}"] &         \\
    S \arrow[r, "\pi_S"']                                  & S^{\dR}
    \end{tikzcd}
  \end{equation*}
  of \(\setF_p\)-stacks, where \(\pi_S \colon S \to S^{\dR}\) is the natural morphism given in \Cref{DefdeRhamStack} and \(\sigma_{S,r} \colon W_rS_{\setF_p} \to S^{\dR}\) is the morphism obtained by \cite{petrov2025Decomposition}*{Corollary~4.4} (\Cref{ConstPetrov}).","status":"unverified"}

