{"assumptions":[],"created_at":"2026-10-26T19:34:09.910700+00:00","domain":"probability theory","id":"claim_f31e8a498faa763a9e1ab66eb71d82a9a8c92bc36794b21b66faa1efc6ffb43b","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2603.26319, 'Regularity of Gibbs measures for unbounded spin systems on general graphs'] Assume $\rho$ is an even measure satisfying \eqref{eq: single-site assumption}.
Suppose $J, J'$ are interactions on $V$ satisfying  \eqref{C1}, \eqref{C2} and $0 \leq J_{x, y} \leq J'_{x,y}$ for all $x, y \in V$. Suppose also that  $\xi, \xi'$ are boundary conditions on $\Lambda$ such that $0 \leq \xi_x \leq \xi'_x$ for all $x \in V$ and $\sum_{y \in V} J'_{x, y} |\xi'_y| < \infty$ for all $x \in \Lambda$. Let $u\geq 0$ and $x \in \Lambda$.
Then 
\begin{equation*}
    \nu_{\Lambda, \beta, \rho, J}^{\xi}[\varphi_x \geq u] \leq \nu_{\Lambda, \beta, \rho, J'}^{\xi'}[\varphi_x \geq u].
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:25.282486+00:00","domain":"probability theory","id":"claim_f3208dfe977b9ab477d67023e13a8cd57d887ae01c1b8f1f2ccb61d79e875ec2","kind":"theorem","schema_version":1,"statement":"[Cor 9 of arXiv:2606.21778, 'Pontryagin Maximum Principle in Free Probability Theory'] Let $0<T<\infty$. Consider the fSDE
	\begin{equation}
		dX_t=a(X_t)dt + \sum_{i=1}^{d}b^i(X_t)dW_tc^i(X_t)
	\end{equation}
	Assume that $a$, and the products $b^ic^i, i=1,\dots d$ are globally operator Lipschitz. Then \eqref{eq:h54} has a unique global solution on $[0,T]$, uniformly bounded in operator norm.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:23:05.284801+00:00","domain":"probability theory","id":"claim_f320cbaa7ef1975dc112ba0a1d0ba99e57a682e0f880eb8f995b6d02e73de768","kind":"theorem","schema_version":1,"statement":"[Proposition 4 (Posterior expectations of the complete-data sufficient statistics) of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] At iteration $t$, define
\begin{align*}
  \widetilde{\Sigmab}^{(t)}
  =
  \tilde{\Lambdab}^{(t)}
  \Gammab^{(t)}
  \tilde{\Lambdab}^{(t)\star}
  +
  \Psib^{(t)},\quad
  \widetilde{\Ab}^{(t)}
  =
  \Gammab^{(t)}
  \tilde{\Lambdab}^{(t)\star}
  \left(\widetilde{\Sigmab}^{(t)}\right)^{-1},\quad
  \widetilde{\Cb}^{(t)}
  =
  \Gammab^{(t)}
  -
  \widetilde{\Ab}^{(t)}
  \tilde{\Lambdab}^{(t)}
  \Gammab^{(t)}.
\end{align*}
Then, the conditional distribution of the latent factor matrix is
\begin{align*}
  \tilde{\Zb}\mid\Xb,\tilde{\thetab}^{(t)}
  \sim
  \mathbb{C}\Ncal_{k\times n}
  \left(
    \widetilde{\Ab}^{(t)}\Xb,
    \widetilde{\Cb}^{(t)},
    \Ib_n
  \right),
\end{align*}
and the posterior expectations of the complete-data sufficient statistics in \eqref{eq:sufficient_stat_defs} are
\begin{align}

  \tilde{\Zb}^{(t)}
  =
  \widetilde{\Ab}^{(t)}\Xb, \qquad
  \widetilde{\Sbb}_{zz}^{(t)}
  =
  n\widetilde{\Cb}^{(t)}
  +
  \tilde{\Zb}^{(t)}
  \tilde{\Zb}^{(t)\star}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:30.013846+00:00","domain":"probability theory","id":"claim_f3280a7d9ec6f5c47598653789789a69be7214870af8514cea36066a8a055d22","kind":"definition","schema_version":1,"statement":"[Definition 2 of arXiv:2605.04684, 'Ergodicity of stochastic functional differential equation with jumps and finite delay'] A distance-like function $d$ bounded by $1$ is called contracting for $P_{t}$ if there exists $\alpha<1$ such that for any $\xi,\eta \in \mathscr{D}$ with $ d(\xi,\eta)<1$, we have
\begin{equation*}
    W_{d}\left(P_{t}(\xi, \cdot), P_{t}(\eta, \cdot)\right) \leq \alpha d(\xi, \eta),
\end{equation*}
where $P_t(\xi,\cdot)$ and $P_t(\eta,\cdot)$ are the transition functions of the process $(X_{t}^{\xi})_{t \geq 0}$ and $(X_{t}^{\eta})_{t \geq 0}$, respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:34:45.765951+00:00","domain":"probability theory","id":"claim_f32927491f45323a9eeae965a911a308895bcbf2d1bef440c4c4ba0b7de0db15","kind":"lemma","schema_version":1,"statement":"[Lemma Hlfsn of arXiv:2609.01990, 'Jacquet-Zagier treatment of the beyond endoscopy trace formula for \(\GL_2\)'] We can write \[
    H_{l,f}^s(0,n) = J_{l,f}(0,n) + \left(\frac{\sqrt{\pi} lf^2}{2 \sqrt{n}}\right)^{2s-1} I_{l,f}(0,n) 
    \] as 
    \begin{equation}
        H_{l,f}^s(0,n) = \frac{1}{2\pi i } \int_{(2)} \frac{(2w - \frac{3}{2})}{(w+\frac{s}{2}-1)(w-\frac{s+1}{2}) } \Gamma(w) \mathcal{F}(w,s) \left(\frac{\sqrt{\pi}lf^2}{2\sqrt{n}} \right)^{-2w+s+1} dw 
    \end{equation}
    with 
    \begin{equation}
        \mathcal{F}(w,s) = \int_{-1}^{1} F_s(y) (1-y^2)^{w - \frac{s+1}{2}} dy 
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:34:45.636331+00:00","domain":"probability theory","id":"claim_f32bea0847fb8fc2f1911f51777764d275618996df01c2d75ababa36d83918ea","kind":"lemma","schema_version":1,"statement":"[Lemma eq:N(B/eta) of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] If $B_d>1$ and $\eta_d\ge 1$, then
 \begin{equation}
	N_d\!\left(\frac{B_d}{\eta_d}\right) = 
	c_d\left(\frac{B_d}{\eta_d}\right)^{a_d} (1+\log B_d)^{-\Delta_d} (1 + O((1+ \log \eta_d)(1+\log B_d)^{-\delta})).
 \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.653127+00:00","domain":"probability theory","id":"claim_f32c6b1a0d1c2d90aebf1338e57eb919cf25957449ce21c69540611ad90ee37f","kind":"lemma","schema_version":1,"statement":"[Lem 38 of arXiv:2609.01389, 'K-stability and birational rigidity of Fano 3-fold weighted complete intersections'] The defining polynomials of $X$ can be written as
\[
\begin{split}
\msF_1 &= z w + s t + t f_4 + f_8, \\
\msF_2 &= z^2 s + z (t g_3 + g_7) + t^2 y + t g_6 + g_{10},
