      \delta_R( y ,F_n(\zeta,U))\in[\xi_n^-(y),\xi^+_n(y)].
    \end{equation}

    \item For every $\zeta, \zeta' \in G_{\mathrm{loc}}^\eta(0)$
    \begin{equation}

      F_{T_\mathrm{bl}}(\zeta,U)(x)
      =F_{T_\mathrm{bl}}(\zeta',U)(x)
      \quad \text{for every }
      x \in B_{2L_\mathrm{bl}}(z'),\ z' \in \{-L_\mathrm{bl}, 0, L_\mathrm{bl}\}.
    \end{equation}

    \item  If $\zeta(x)=\zeta'(x)$ for every $x \in B_{2L_\mathrm{bl}}(0)$, then
    \begin{equation}
      F_{n}(\zeta,U)(x)
      = F_{n}(\zeta',U)(x) \quad\text{for every } x \in B_{L_\mathrm{bl}/2}(0),
      \ n=1,\dots,T_\mathrm{bl}.
    \end{equation}
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:25:44.992327+00:00","domain":"probability theory","id":"claim_f541360b8e6078439b65a474ffa0cee660acd05c2a3dec40fbae99c8839656e3","kind":"concept","schema_version":1,"statement":"[Lemma 4 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] Let $\g\in\R$ then there exists $c>0$ such that 
