{"assumptions":[],"created_at":"2026-10-26T19:28:04.857894+00:00","domain":"probability theory","id":"claim_f565764fd6a4dcef6d599ef1f335acb36a8cae467e6e4ba197c565f9ab6d25b0","kind":"concept","schema_version":1,"statement":"[Thm 5 of arXiv:2511.20875, 'Double $q$-Wigner Chaos and the Fourth Moment'] Let $m,n\in\N$ have opposite parities.  For each $k\in\N$, let $f_k \in L^2(\mathbb{R}^m_+)$ and $g_k \in L^2(\mathbb{R}^n_+)$ be mirror symmetric functions, and let $X_k = I_0(f_k)$ and $Y_k=I_0(g_k)$ be the free Wigner integrals in $\Gamma_0(H)$ where $H=L^2(\mathbb{R}_+)$.  Assume $\tau_0[X_k^2] + \tau_0[Y_k^2] \to \sigma^2$ as $k\to\infty$.  Then the following three conditions are equivalent.
\begin{enumerate}
    \item $\displaystyle{\lim_{k\to\infty} \kappa_4[X_k+Y_k] = 0}$.
    \item $\displaystyle{\lim_{k\to\infty} f_k \overset{p}{\frown} f_k = 0}$ in $L^2(\mathbb{R}_+^{2(m-p)})$ for $p=1,\ldots,m-1$ and $\displaystyle{\lim_{k\to\infty} g_k \overset{p}{\frown} g_k = 0}$ in $L^2(\mathbb{R}_+^{2(n-p)})$ for $p=1,\ldots,n-1$.
    \item The sequence $(X_k+Y_k)_{k\in\N}$ converges in distribution to a centered semicircular random variable with variance $\sigma^2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:42:57.243179+00:00","domain":"probability theory","id":"claim_f565be3e1d99e2d3250287f1da5f9442fb22287ef2c970316d5bda0c1d043997","kind":"theorem","schema_version":1,"statement":"[Proposition prop:aligned-late-asymptotics of arXiv:2608.21561, '\textbf{Loss-Parameterized Fisher Width Along Learning Trajectories}'] As $r\to\infty$,
\begin{align}
    L_\star(r)
    &\sim
    \frac{\pi^2}{6\sqrt{2\pi}}\frac1r,
    \\
    b(r)
    &\sim
    \frac{1}{\sqrt{2\pi}}\frac1r,
    \\
    a(r)
    &\sim
    \frac{\pi^2}{3\sqrt{2\pi}}\frac1{r^3}.

\end{align}
Consequently,
\begin{equation}
    \kappa(r)
    \sim
    \frac{\pi^2}{3r^2},
    \qquad
    \frac{b(r)}{L_\star(r)}
    \longrightarrow
    \frac6{\pi^2}.

\end{equation}
For $d\geq2$,
\begin{equation}
    w_F(B_2^d;ru_\star)
    \sim
    (2\pi)^{-1/4}
    \mathbb E[\chi_{d-1}]
    r^{-1/2},

\end{equation}
where $\chi_{d-1}$ denotes a chi random variable with $d-1$ degrees of
freedom. Therefore
\begin{equation}
    \frac{
        w_F(B_2^d;ru_\star)
    }{
        \sqrt{L_\star(r)}
    }
    \longrightarrow
    \frac{\sqrt6}{\pi}
