{"assumptions":[],"created_at":"2026-10-27T13:28:33.794458+00:00","domain":"probability theory","id":"claim_f58db97b9ef7f3fb457c648ede8c93ee441dea073cc5c57b70e406fb0dd140a9","kind":"concept","schema_version":1,"statement":"[Proposition prop:40 of arXiv:2504.12293, 'Near-existence of bigeodesics in dynamical exponential last passage percolation'] {BBB23}}]

