{"assumptions":[],"created_at":"2026-10-27T19:22:08.368069+00:00","domain":"probability theory","id":"claim_f5c7701a7fc54e0bf57912332b56f04bcd607386eed6c87854ef52d5e7ca3fd7","kind":"concept","schema_version":1,"statement":"[Thm coupling of arXiv:2607.28817, 'Limiting spectral distribution for the adjacency matrix of the Watts--Strogatz random grap'] With the same notation as in Theorem~(thm:mainresult of the paper), define the distributions on $Z_n$ and $U_n$ as follows:
\begin{enumerate}
    \item $Z_n$ is an $n\times n$ symmetric random matrix whose upper-triangular entries are independent, and for every $i \le j$,
    \[
        (Z_n)_{ij} =
        \begin{cases}
            \bernoulli(1 - p_n) & \mbox{if }\quad 0 < \min\big(|i-j|,\, n - |i-j|\big) \le \frac{K_n}{2}, \\
            0 & \mbox{otherwise.}
        \end{cases}
    \]

    \item $U_n$ is the adjacency matrix of an Erd\H{o}s--R\'enyi random graph of size $n$ with parameter $\frac{p_n K_n}{n}$, independent of $Z_n$. In other words, $U_n$ is an $n\times n$ symmetric random matrix independent of $Z_n$ and whose upper-triangular entries are independent and satisfy, for every $i \le j$,
    \[
        (U_n)_{ij} =
        \begin{cases}
            \bernoulli\left(\frac{p_nK_n}{n}\right) & \mbox{if }\quad i < j, \\
            0 & \mbox{if } i = j.
        \end{cases}
    \]
\end{enumerate}
Let $A_n$ denote the adjacency matrix of $WS_n(K_n, p_n)$. 
Then, under the same assumptions as in Theorem~(thm:mainresult of the paper), namely~(equation eq:assumption1 of the paper) and~(equation eq:assumption2 of the paper), there is a coupling of $A_n$ and $(Z_n, U_n)$ so that $Z_n$ and $U_n$ are independent and
\begin{equation} 
    \mu_{\frac{A_n}{\sqrt{p_nK_n}}} - \mu_{\frac{Z_n}{\sqrt{p_nK_n}} + \frac{U_n}{\sqrt{p_nK_n}}}\;\xrightarrow[n\to\infty]{}\; 0\qquad\mbox{ weakly in probability}. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:31:02.807747+00:00","domain":"probability theory","id":"claim_f5c889fac1568cde94f6d40e77fbc362b2c18c6375166b74d91b447a67016a5c","kind":"lemma","schema_version":1,"statement":"[Lemma priori-2026-5-6-1 of arXiv:2609.01488, 'Stabilization by a background magnetic field: global well-posedness of the full compressib'] Assume that all the conditions of Lemma (priori-25-6-27-2 of the paper) hold and that $N>M+2(r+1)$. Then there are two positive constants $\epsilon_2,\epsilon_3<1$, depending only on $\mathbb T^3$, $r$, $c$, $|\mathbf n|$, $M$, $N$, $\mu$, $\lambda$, $\gamma$, $\bar P$, $\underline{\rho}^{-1}$, $\bar\rho$ and $M_0$, if
\begin{align}
&(1+\|\rho_0\|_M)\left(M_\rho\|(\mathbf u_0,p_0,\mathbf h_0)\|^2_M\right)^{\frac{N-M-2r-2}{N-M}}\leq\eta_2,
\end{align}
and
\begin{align}
M_\rho\big(1+\|\rho_0\|^{2(N-1)}_{M}\big)&\|(\mathbf u_0,p_0,\mathbf h_0)\|^2_M+\big(1+\|\rho_0\|^{2(N-1)}_{M}\big)\|(\mathbf u_0,p_0,\mathbf h_0)\|^2_N\nonumber\\
&\quad+M_\rho\|\rho_0\|^2_N\|(\mathbf u_0,p_0,\mathbf h_0)\|_M^{\frac{2(N-M-r-1)}{N-M}}\leq\eta_3,
\end{align}
hold for some $\eta_2\in(0,\epsilon_2]$ and $\eta_3\in(0,\epsilon_3]$, then the following estimate holds:
\begin{align}
\sup_{t\in[0,T]}\|(\mathbf u,p,\mathbf h)\|^2_N+\int_0^T\|\mathbf u_t\|^2_{N-1}dt+\int_0^T\|\mathbf u\|_{N+1}^2dt\leq B_6\eta_3,
\end{align}
where the positive constant $B_6$ depends only on $\mathbb T^3,|\mathbf n|,M,\mu,\lambda,\gamma,\bar P,\underline{\rho}^{-1},\bar\rho,M_0,r,c.$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.593864+00:00","domain":"probability theory","id":"claim_f5ceec921f323308de0ffb679b6f9b01c2424351045d9e85360e9621a1cf0da3","kind":"concept","schema_version":1,"statement":"[Lemma Lem:Tail of arXiv:2411.15681, 'Strassen's local law of the iterated logarithm for the generalized fractional Brownian mot'] ([Tal95])
Let $\mathcal X = \{\mathcal X(t), t \in \mathbb R\}$ be a centered real-valued Gaussian process, 
and let $S \subset \mathbb R$ be a closed set equipped with the canonical metric  
$$d_{\mathcal X}(s, t) = \left[\mathbb E\big(\mathcal X(s) -\mathcal  X(t)\big)^2\right]^{1/2}.$$
Then there exists a  constant  $c_{3,3}>0$ such that for every $u >0$, 
\begin{equation*}
\mathbb P\Biggl\{ \sup_{s, t \in S} |\mathcal X(s) - \mathcal X(t)| \ge c_{3,3}\,
\bigg(u + \int_0^D \sqrt{\log N(d_{\mathcal X}, S, \varepsilon)}\, d\varepsilon \bigg)\Bigg\}
\le \exp\bigg( - \frac{u^2} {D^2}\bigg),
\end{equation*}
where $N(d_{\mathcal X}, S, \varepsilon)$ denotes the minimal number of open $d_{\mathcal X}$-balls
of radius $\varepsilon$ needed to cover $S$, and   $D= \sup\{ d_{\mathcal X}(s,t):\,
s,\, t \in S\}$ is the diameter of $S$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.744463+00:00","domain":"probability theory","id":"claim_f5d0f59aa61730e34dcf4ed3d72297651db3ca5bb6749dd3d283853813574553","kind":"definition","schema_version":1,"statement":"[Defn of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] For $\mathfrak{s}>-1/2$ and $\nu>-1$ define the Hua-Pickrell $\mathbb{HP}_\mathfrak{s}$ and Bessel $\mathbb{B}_\nu$ stochastic zeta functions by:
\begin{align*}
    \mathbb{HP}_\mathfrak{s}(z)=\lim_{k\to \infty}\prod_{\substack{\mathrm{x}\in \mathcal{HP}_\mathfrak{s}\\|\mathrm{x}|>k^{-2}}}\left(1-z\mathrm{x}\right), \ \  \
    \mathbb{B}_{\nu}(z)=\prod_{\mathrm{x}\in \mathcal{IB}_{\nu}}(1-z\mathrm{x}), \ \ \forall z \in \mathbb{C}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:36:23.124713+00:00","domain":"probability theory","id":"claim_f5d30f44cf3e5167523cbb2ead31b2d3bd0bc453c4eee19a9d5069db45c19800","kind":"concept","schema_version":1,"statement":"[Thm GenLineInt of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Under the assumptions of Theorem (thm:LineInt of the paper),
