{"assumptions":[],"created_at":"2026-10-26T19:32:15.344702+00:00","domain":"probability theory","id":"claim_f65dc5ce2d265164f7ff338c3a65c97fdaecfec34c6e0ef5fe9b035803a6ec9d","kind":"concept","schema_version":1,"statement":"[Theorem 26 of arXiv:2506.15044, '2506.15044'] Let $M,N\in(\mathcal{M}_{\mathrm{loc}})^\mathbb{B}$.
\begin{itemize}
  \item [$(1)$] If $(T_n,M^{(n)})$ and $(T_n,N^{(n)})$ are FCSs for $M\in(\mathcal{M}_{\mathrm{loc}})^\mathbb{B}$ and $N\in(\mathcal{M}_{\mathrm{loc}})^\mathbb{B}$ respectively, then $(T_n,[M^{(n)},N^{(n)}])$ is an FCS for $[M,N]\in \mathcal{V}^\mathbb{B}$, and $(T_n,[M^{(n)}])$ is an FCS for $[M]\in (\mathcal{V}^+)^\mathbb{B}$, and $(T_n,\sqrt{[M^{(n)}]})$ is an FCS for $\sqrt{[M]}\in (\mathcal{A}^+_{\mathrm{loc}})^\mathbb{B}$.

  \item [$(2)$] For $\widetilde{M}\in(\mathcal{M}_{\mathrm{loc}})^\mathbb{B}$ and $a,b\in \mathbf{R}$,
      \[
       [M,N]=[N,M],\quad [aM+b\widetilde{M},N]=a[M,N]+b[\widetilde{M},N].
      \]

  \item [$(3)$]  If $\tau$ is a $\mathbb{B}$-inner stopping time, then
      \begin{equation}
       [M^{\tau},N^{\tau}]=[M,N]^{\tau}
      \end{equation}
       and
      \begin{equation}
      [M^{\tau}\mathfrak{I}_\mathbb{B},N^{\tau}\mathfrak{I}_\mathbb{B}]
      =[M^{\tau},N^{\tau}]\mathfrak{I}_\mathbb{B}
      =[M,N]^{\tau}\mathfrak{I}_\mathbb{B}=[M^{\tau}\mathfrak{I}_\mathbb{B},N].
      \end{equation}

  \item [$(4)$] Further suppose $M,N\in(\mathcal{M}_{\mathrm{loc}})^{i,\mathbb{B}}$. Then $[M,N]$ is the unique $\mathbb{B}$-adapted process with finite variation such that $MN-[M,N]\in (\mathcal{M}_{\mathrm{loc,0}})^{i,\mathbb{B}}$ and $\Delta [M,N]=\Delta M\Delta N$.

  \item [$(5)$] Further suppose $M\in(\mathcal{M}_{\mathrm{loc}})^{i,\mathbb{B}}$. Then $[M]=0\mathfrak{I}_\mathbb{B}$ if and only of $M=0\mathfrak{I}_\mathbb{B}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.469670+00:00","domain":"probability theory","id":"claim_f664ee9ac533e4b7edebbab3ccf4a88d53b0601fedc98c2f6d3adaa30f0d4efd","kind":"lemma","schema_version":1,"statement":"[Lemma 23 (Last-leg flattening identities) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let
\[
  K\in\cA_1\otimes\cdots\otimes\cA_m\otimes\conj{\cC}\otimes\cE.
\]
Regard the same tensor, after canonical permutations, as either
\begin{align*}
  K^+&\in
  \cA_1\otimes\cdots\otimes\cA_{m-1}
  \otimes\conj{(\conj{\cA_m}\otimes\cC)}\otimes\cE,\\
  K^-&\in
  \cA_1\otimes\cdots\otimes\cA_{m-1}
  \otimes\conj{\cC}\otimes(\cA_m\otimes\cE).
\end{align*}
Thus $K^+$ has input space $\conj{\cA_m}\otimes\cC$ and $K^-$ has output
space $\cA_m\otimes\cE$.  In coordinates,
\[
  K^+_{i_1\cdots i_{m-1}}(\conj{a_j^{(m)}}\otimes c)
  =K_{i_1\cdots i_{m-1}j}c,
\]
\[
  K^-_{i_1\cdots i_{m-1}}c
  =\sum_j a_j^{(m)}\otimes K_{i_1\cdots i_{m-1}j}c.
\]
Then, for every $S\subset[m-1]$ and $2\le r\le\infty$,
\begin{equation*}
  \norm{\Flat_S(K^+)}_{\Sch_r}
  =\norm{\Flat_{S\cup\{m\}}(K)}_{\Sch_r},
\end{equation*}
\begin{equation*}
  \norm{\Flat_S(K^-)}_{\Sch_r}
  =\norm{\Flat_S(K)}_{\Sch_r}.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.364834+00:00","domain":"probability theory","id":"claim_f666098c23e7d7aaf4f08925c460678c549b0db51d7502b86de0c2a250902a57","kind":"lemma","schema_version":1,"statement":"[Lemma lem:TV-llr of arXiv:2601.07045, 'From Continuous to Discrete: \\ a No-U-Turn Sampler for Permutations'] Let $p$ and $q$ be probability mass functions on a finite set $\mathcal{I}$ such that
