{"assumptions":[],"created_at":"2026-10-26T20:58:09.069822+00:00","domain":"probability theory","id":"claim_f6c32150183ddcb96f5df604de9db81f6fb52ff591e3df872a95b273cb04dc7b","kind":"lemma","schema_version":1,"statement":"[Lem 3 of arXiv:2606.27839, '2606.27839'] For
