q(\tau)=\frac{1}{21n}\sqrt[2n]{\frac{\tau}{S^2}}.
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:41:33.832180+00:00","domain":"probability theory","id":"claim_f79a51959fd2a0ea16c7d0ffe1e2e91e052987fa496a1e93fc5cd10cf7c31cf0","kind":"theorem","schema_version":1,"statement":"[Proposition 22 (Exact rank computation) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] In the setting of \cref{ex:branching}, with parameter block $(\eta_1,\eta_2)\in(0,1)^2$:
\begin{enumerate}[label=\textup{(\alph*)}]
\item the depth-two chain on $\cS_2=\{ba,ad,db,ae,ec,ca\}$ is irreducible and has stationary distribution
\begin{equation*}
\pi(\eta_1,\eta_2)=\frac{1}{3(\eta_2+1-\eta_1)}(\eta_2,\eta_2,\eta_2,1-\eta_1,1-\eta_1,1-\eta_1),
\end{equation*}
\item in the reduced chart given by the free coordinates $\mu(d\mid ba)$ and $\mu(d\mid ca)$,
\begin{equation*}
\bar q_{\cQ}^{(2)}(\eta_1,\eta_2)=(\eta_1,\eta_2),
\end{equation*}
\item in the reduced depth-one chart with free coordinate $q_{a,d}^{(1)}$,
\begin{equation*}
\bar q_{\cQ}^{(1)}(\eta_1,\eta_2)=\frac{\eta_2}{\eta_2+1-\eta_1},
\end{equation*}
\item for every interior point $\theta_0=(\eta_1^0,\eta_2^0)$,
\begin{equation}
\rank D\bar q_{\cQ}^{(2)}(\theta_0)=2, \qquad \rank D\bar q_{\cQ}^{(1)}(\theta_0)=1.
\end{equation}
\end{enumerate}
