{"assumptions":[],"created_at":"2026-10-26T19:25:12.189904+00:00","domain":"probability theory","id":"claim_fa32b9d4d0305b6674eb1b00f68caf7bdb9d34cc75dc87b0527ba9747f799a10","kind":"lemma","schema_version":1,"statement":"[Lemma 35 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, $v,w\in \widetilde{\mathbb{Z}}^d$ with $|v-w|\ge d$, and $0\le a,b\le |v-w|^{d-2}$, 
  	\begin{equation}
  	\Big| 	\frac{\mathfrak{p}_{v\leftrightarrow w,a,b}  }{\bar{\mathfrak{p}}_{v\leftrightarrow w,a,b}}   -1 \Big| \lesssim (ab+1) \cdot |v-w|^{2-d}, 
    	\end{equation}
    	where $\bar{\mathfrak{p}}_{v\leftrightarrow w,a,b}:=\mathbb{K}_{\{v,w\}}(v,w)\cdot \mathfrak{q}_v(a)\cdot \mathfrak{q}_w(b)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:46:00.367125+00:00","domain":"probability theory","id":"claim_fa3a26553d5f795ea75d3fc6e8f25170e4e7115aa883fb024f67ab2bf63af81e","kind":"concept","schema_version":1,"statement":"[Proposition prop:loc of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Suppose (equation alphaH=3/2 of the paper), and set
    \begin{align*}
        \delta = h^{\rho\alpha} \quad \text{and} \quad
        \varepsilon= \delta^{\frac{2H+2}{3+2\alpha}}

        = h^{\rho}.
    \end{align*}
    Fix $0<t_1<t_2$. Then, there exists $K > 0$ such that for any $\rho \in (0\,,1)$, there exists $r_\rho \in (0\,,1)$ such that
    \begin{align*}
        \|\Delta^h_B u(t\,,x)\|_2^2 \le K \rho\, h^2 \log(1/h)
    \end{align*}
    uniformly for all $t \in [t_1\,,t_2]$, $x \in \mathbb{R}$ and $h \in (0\,,r_\rho]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:10.010643+00:00","domain":"probability theory","id":"claim_fa3f2c3fecba2c50b59d41acbeb2d953507c9e83119b396c149de5384171c0e7","kind":"concept","schema_version":1,"statement":"[Conjecture 7 (Ellipsoid fitting) of arXiv:2504.20539, 'Randomstrasse101: Open Problems of 2024'] Let $n, d \geq 1$ and $x_1, \cdots, x_n \sim \mathcal{N}(0,\mathrm{I}_d/d)$. For any $\varepsilon > 0$: 
    \begin{align}

        \limsup_{d \to \infty} \frac{n}{d^2} \leq \frac{1-\varepsilon}{4} \Rightarrow \lim_{d \to \infty} \mathbb{P}[\exists \mathcal{E} \textrm{ an ellipsoid fit to } (x_i)_{i=1}^n] = 1, \\

        \liminf_{d \to \infty} \frac{n}{d^2} \geq \frac{1+\varepsilon}{4} \Rightarrow \lim_{d \to \infty} \mathbb{P}[\exists \mathcal{E} \textrm{ an ellipsoid fit to } (x_i)_{i=1}^n] = 0.
    \end{align} (Stated as a conjecture by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:28:08.642468+00:00","domain":"probability theory","id":"claim_fa40d9fd5082a8437d5ae7c20627bebbd3399067f4aa97893b7804c8a1503ac5","kind":"theorem","schema_version":1,"statement":"[Corollary 4 of arXiv:2607.28992, 'Minimal inversion of a permuton sample'] Let $\mu$ be a permuton decomposed into $\mu_1,\ldots,\mu_k$ with respect to the tiling $\rect=\{S_1,\ldots,S_k\}$ with side lengths $\delta_1,\ldots,\delta_k$ and bottom-left corners $(x_1,y_1),\ldots,(x_k,y_k)$.
    Assume that each measure $\mu_\ell$ admits a piece-wise continuous, strictly positive density $f_\ell$ on $S_\ell$ which is also top-right continuous at $(x_\ell,y_\ell)$ and bottom-left continuous at $(x_\ell+\delta_\ell,y_\ell+\delta_\ell)$.
    Let $\minv_n^\mu$ be the minimal inversion of $n$ points distributed according to $\mu$, as defined in~\eqref{eq:main}.
    Then, the random variable $\minv_n^\mu$ satisfies one of the following two cases, as $n\rightarrow\infty$.
    \begin{itemize}
        \item If the set of splittings $\diag_\rect$ is non empty, then
        \begin{align*}
            n^{-1/2}\minv_n^\mu
            \dconv\ray[2,\sum_{\ell\in\diag_\rect}\frac{f_\ell(x_\ell,y_\ell)+f_\ell(x_\ell+\delta_\ell,y_\ell+\delta_\ell)}{2}]
        \end{align*}
        \item If the set of splittings $\diag_\rect$ is empty, then
        \begin{align*}
            n^{-1}\minv_n^\mu
            \dconv\mass_\rect
            =\min\left\{\sum_{m\in\inv_{\sigma_\rect}(\ell)}s_m:\ell\in[k]\right\}\,.
        \end{align*}
    \end{itemize}
    Both convergence occur in distribution, although the second one also occurs in probability.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.583369+00:00","domain":"probability theory","id":"claim_fa49fb911bbd27f079d7d7aaca368619b379618590cd107b7c21c9520d302acb","kind":"concept","schema_version":1,"statement":"[Lemma 434 of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] Assume that $G(t,y)=F(t)\cdot y$ for some locally bounded function $F$ on $\mathbb{R}_+$. 
 If  
 \begin{eqnarray}
   \int_0^\infty \frac{y^2}{n^2}\, \mu_n(dy) \to \sigma^2  \in (0,\infty)
 \quad \mbox{and}\quad 
 X^{(n)} \to X^* \in C(\mathbb{R}_+;\mathbb{R}_+) \mbox{ weakly in $D(\mathbb{R}_+;\mathbb{R}_+)$},
 \end{eqnarray} 
 as $n\to\infty$,   we have $Z^{(n)}  \overset{\rm f.d.d.}\longrightarrow Z^*$ with the limit process $Z^* $ given by
 \begin{eqnarray*}
 Z^*(t):= \int_0^t \int_0^{X^* (s)} F(t-s) B^* (ds,dz), \quad t\geq 0,
 \end{eqnarray*}  
 where $B^* (ds,dz)$ is Gaussian white noise with intensity $ \sigma^2\cdot ds\, dz$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:05.000884+00:00","domain":"probability theory","id":"claim_fa4b8b71cefce09034a05940dbcdadc3150758a585e88c3ac800e0a2c6208a92","kind":"theorem","schema_version":1,"statement":"[Theorem 99 (Projective/inverse limits) of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] Let $F$ be a set on which is defined a partial (reflexive, transitive, antisymmetric) order $\leq$, directed upwards in the sense that for arbitrary $\{\alpha,\beta\}\subset F$ there is $\gamma\in F$ such that $\gamma\geq\alpha$ and $\gamma\geq\beta$. For each $\alpha\in F$ let there be given a probability space $(\Omega_\alpha,\FF_\alpha,\mu_\alpha)$, $\Omega_\alpha$ being a Hausdorff\footnote{or, more generally, one in which every compact subset is closed} topological space, $\FF_\alpha$ including all the compact sets of $\Omega_\alpha$, $\mu_\alpha$ being inner regular w.r.t. the compact sets in the sense that $$\mu_\alpha(A)=\sup\{\mu(K):K\text{ a compact subset of }A\},\quad A\in \FF_\alpha.$$

Let maps $\pr_{\beta\downarrow \alpha}$ as $(\alpha,\beta)$ runs over $\leq$ verify the following properties:
\begin{enumerate}[(a)]
 \item  $\pr_{\alpha\downarrow \alpha}=\mathrm{id}_{\Omega_\alpha}$ for all $\alpha\in F$;
 \item $\pr_{\beta\downarrow \alpha}\circ \pr_{\gamma\downarrow \beta}=\pr_{\gamma\downarrow \alpha}$ for all $\alpha\leq\beta\leq \gamma$ from $F$;
 \item $\pr_{\beta\downarrow \alpha}:\Omega_\beta\to \Omega_\alpha$ is continuous, also measurable in the sense that $\pr_{\beta\downarrow \alpha}\in \FF_\beta/\FF_\alpha$ for all $\alpha\leq \beta$ from $F$;
 \item $\pr_{\beta\downarrow \alpha}$ maps onto $\Omega_\alpha$ for all $\alpha\leq \beta$ from $F$.
 \end{enumerate}
 Suppose furthermore the consistency condition
\begin{enumerate}[(e)]
\item  $(\pr_{\beta\downarrow \alpha})_\star \mu_\beta=\mu_\alpha\text{ for all $\alpha\leq \beta$ from $F$}$
\end{enumerate} holds true. 

Next, set $$\Omega:=\left\{\omega\in \prod_{\gamma\in F}\Omega_\gamma: \pr_{\beta\downarrow \alpha}\omega_\beta=\omega_\alpha\text{ for all }\alpha\leq \beta\text{ from }F\right\},$$ introduce $\pr_\alpha:=(\Omega\ni\omega\mapsto \omega_\alpha)$ for $ \alpha\in F$, and assume 
\begin{enumerate}[(f)]
\item $\pr_\alpha$ maps $\Omega$ onto $\Omega_\alpha$ for each $\alpha\in F $. 
\end{enumerate}
Suppose finally that 
 \begin{enumerate}[(g)]
 \item for each non-empty countable $F'\subset F$ that is not bounded above (no $\gamma\in F$ such that $\alpha\leq\gamma$ for all $\alpha\in F'$) admitting an enumeration in increasing order (there is a $\uparrow$ map from $\mathbb{N}$ onto $F'$): if $\omega'\in \prod_{\alpha\in F'}\Omega_\alpha$ is such that $\pr_{\beta\downarrow \alpha}\omega_\beta'=\omega'_\alpha\text{ for all }\alpha\leq \beta\text{ from }F'$, then there is $\omega\in \Omega$ such that $\omega'=\omega\vert_{F'}$.
 \end{enumerate}
Then there exists a unique probability $\mu$ on $(\Omega,\lor_{\alpha\in F}(\pr_\alpha)^{-1}(\FF_\alpha))$ satisfying ${\pr_\alpha}_\star\mu=\mu_\alpha$ for all $\alpha\in F$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:42.313271+00:00","domain":"probability theory","id":"claim_fa4ba5506ca8a546f0dd53a7615fa627973a89d2a0bfe401cb8cf619c50e60e3","kind":"concept","schema_version":1,"statement":"[Corollary 33 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] There exists a universal constant such that for any martingale difference sequence $D_i$ adapted to a filtration $\mathcal{F}_i$---so $D_i$ is $\mathcal{F}_i$ measurable and $\E[D_i \mid \mathcal{F}_{i-1}] =0$---we have for all $p \geq 2, n \geq 1$, the bounds
