            \mu' := \frac{\sqrt{\alpha'}}{4 \beta'^{3/2}}, \qquad \text{so that} \qquad 4 \mu' \alpha' = \left(\frac{\alpha'}{\beta'}\right)^{3/2} = \kappa'^{-3/2}, \qquad \kappa' := \frac{\beta'}{\alpha'} \leq \kappa.
