{"assumptions":[],"created_at":"2026-10-27T19:35:19.870939+00:00","domain":"probability theory","id":"claim_fcc6e6534cc709d359e38a39af8da9f524b8757373a9e5b347b8d210d83dbac0","kind":"theorem","schema_version":1,"statement":"[Theorem cor:pointwise of arXiv:2608.24731, 'Optimal Alternating Regret for Online Learning and Games\thanks{Authors are alphabetically'] For every horizon $T \ge 1$, (alg:main of the paper) with the uniform probability measure $\mu \in \Delta_{\+X}$ guarantees
\begin{equation}
  \max_{\boldsymbol{u} \in \+X}\operatorname{Reg}_{\mathrm{Alt}}^T(\boldsymbol{u})
  \le
  8d\left(1+\log_{+}\frac{T}{2d}\right) + \frac{1}{4},
\end{equation}
where $\log_{+} z:=\max\{0,\log z\}$. Since $\max_{\boldsymbol{u} \in \+X}\operatorname{Reg}_{\mathrm{Alt}}^T(\boldsymbol{u}) \le 4T$ trivially, we have
\begin{align*}
    \max_{\boldsymbol{u} \in \+X}\operatorname{Reg}_{\mathrm{Alt}}^T(\boldsymbol{u}) = O\left( \min\left\{T, d\left (1+\log_{+} \frac{T}{2d}\right) \right\} \right) = O(d \log(1+T/d))
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:30:07.876299+00:00","domain":"probability theory","id":"claim_fcc92a58afa25b6610a7bcdaedd40e5f2a237043865f78ed9e758e2885b52e82","kind":"concept","schema_version":1,"statement":"[Proposition prop_upper_bound of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] Assume (equation p_cont of the paper) and (equation p_lower of the paper).
\begin{enumerate}[label=\textup{(\alph*)}]

\item  \textup{(Typical convex chain)}
Let $\alpha$ be the constant from Theorem~(thm_uniform_known of the paper). Then
\eeq{ 
\limsup_{n\to\infty} \frac{\mathscr{L}_n}{n^{1/3}} \leqslant \frac{\alpha}{2}J_\star \quad \text{almost surely}.
}

\item  \textup{(Typical convex chains that are far from maximizers)}
For every $\varepsilon>0$, there exists $\theta>0$ such that
\eeq{ 
\limsup_{n\to\infty}\frac{\mathscr{L}_n^\mathsf{far}(\varepsilon)}{n^{1/3}} \leqslant \frac{\alpha}{2}(J_\star-\theta) \quad \text{almost surely}.
}

\item  \textup{(Full convex chain)}
We have
\eeq{ 
\limsup_{n\to\infty}\frac{1}{n}\log\Big[\frac{(3n)!}{n!}\mathbb{P}(\mathscr{L}_n=n)\Big] \leqslant \log\Big(\frac{27 J_\star^3}{4}\Big).
}

\item  \textup{(Full convex chains that are far from maximizers)}
For every $\varepsilon>0$, we have
\eeq{ 
\limsup_{n\to\infty}\frac{1}{n}\log\Big[\frac{(3n)!}{n!}\mathbb{P}\big(\mathscr{L}_n^\mathsf{far}(\varepsilon)=n\big)\Big] < \log\Big(\frac{27 J_\star^3}{4}\Big).
}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:19:47.225783+00:00","domain":"probability theory","id":"claim_fccfb0f14a0a598d0e3fe5706a5750aabd115242d2c47091a0b8585c5b1b9a56","kind":"theorem","schema_version":1,"statement":"[Proposition prop:L1contraction_new of arXiv:2512.18598, 'Long-time reverse transportation inequalities for non-globally-dissipative Langevin dynami'] Under Assumption (ass:farfield of the paper), consider the coupling structure (equation eq:coupling of the paper) with (equation eq:reflectednoise of the paper) replaced by (equation eq:reflectnoise1 of the paper). Fix any $a\in \mathbb{R}$ and $\delta \in (0,1)$. Choose
 \begin{equation}
    \eta_t = \textbf{1}_{\{t \in [\delta T, T]\}} 2\sqrt{|X_{\delta T}-X''_{\delta T}|}\frac{aL-\frac{L}{2}}{e^{(aL-\frac{L}{2})(T-\delta T)}-1}\,e^{aL(t-\delta T)}.
\end{equation} 
We take $\eta_t|_{a=\frac{1}{2}} = \lim_{\tilde{a}\rightarrow \frac{1}{2}}\eta_t|_{a=\tilde{a}}$. Then for any $x \neq x'$,
 \begin{enumerate}
\item For $t\in[0,\delta T]$,
\begin{equation}
    \mathbb{E}|X_t-X_t''| \leq C_1e^{-2\nu t}|x-x'|.
\end{equation}
The definitions of $C_1$ and $\nu$ above are the same as in Proposition (prop:L1contraction of the paper).
\item For $t \in [\delta T, T]$,
\begin{equation}
    |X_t - X_t''| \leq e^{L(t-\delta T)}|X_{\delta T}-X''_{\delta T}| \left(1 - \frac{e^{(aL-\frac{L}{2})(t-\delta T)}-1}{e^{(aL-\frac{L}{2})(T-\delta T)}-1}\right)^2\,\,a.s..
\end{equation}
Consequently, 
\begin{equation}
    X_T = X_T''\,\,a.s..
\end{equation}

 \end{enumerate}","status":"unverified"}

