{"assumptions":[],"created_at":"2026-10-27T05:47:53.327748+00:00","domain":"probability theory","id":"claim_fcdb19fff1f6d7204ffd05211d11b7ed3f72cc8e0ca99180f4c08b9f24e71b8e","kind":"lemma","schema_version":1,"statement":"[Lemma 19 (Clipped $\operatorname{ReLU-MLP}$) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $n, D, J_n \in \mathbb{N}_{+}$, and $\boldsymbol{\alpha} \in \mathbb{N}^{J_n \times D}$ with $|\boldsymbol{\alpha}|=\sum_{r=1}^{D}\sum_{j=1}^{J_n}\alpha_{j,r}=n$ (cf.~also Lemma \ref{lem:tensorized_Hermite_poly_approx_on_compact}). Then, for every $\varepsilon \in (0,1)$, positive constant $B>0$, there exists a $\operatorname{ReLU-MLP}$ $\Phi_{\boldsymbol{\alpha}, B, \varepsilon}:\mathbb{R}^{J_n \times D} \to \mathbb{R}$ satisfying:
\begin{itemize}
    \item \textbf{Effective uniform approximation:} $\sup_{\boldsymbol{z} \in[-B,B]^{J_n\times D}}\left| h_{\boldsymbol\alpha}(\boldsymbol{z})-\Phi_{\boldsymbol{\alpha}, B, \varepsilon}(\boldsymbol{z})\right| \le \varepsilon$.
    \item \textbf{Global growth:} $\left|\Phi_{\boldsymbol{\alpha}, B, \varepsilon}(\boldsymbol{z})\right| \le |h_{\boldsymbol\alpha}(\boldsymbol{z})|+1$, for every $\boldsymbol{z}\in\mathbb R^{J_n\times D}$.
\end{itemize}
Moreover, for fixed $B, J_n, D$ and $\boldsymbol{\alpha}$, the $\operatorname{ReLU-MLP}$ $\Phi_{\boldsymbol{\alpha}, B, \varepsilon}$ has $\operatorname{depth}(\Phi_{\boldsymbol{\alpha}, B, \varepsilon}) \in \mathcal{O}(\log_2(Q_n+1)\log(\varepsilon^{-1}))$, $\operatorname{width}(\Phi_{\boldsymbol{\alpha}, B, \varepsilon}) \in \mathcal{O}(Q_n + n)$, and $\operatorname{size}(\Phi_{\boldsymbol{\alpha}, B, \varepsilon}) \in \mathcal{O}((Q_n + n)\log_2(Q_n \vee 2)\log(\varepsilon^{-1}))$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:26:52.677507+00:00","domain":"probability theory","id":"claim_fcdb2fce8b470e8ac84675ddc529ad8ed7bde29fa66215f2335a4ab3412e05db","kind":"lemma","schema_version":1,"statement":"[Lemma 10 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3} and \eqref{PETNs-3.01} hold. Then, for every $\tau \in \mathbb{R}$ and $D = \{D(t), t \in \mathbb{R}\} \in \mathfrak{D}$, there exist ${T} := {T}(\tau, D) > 0$ and  $\epsilon_{0}\in (0,1)$ such that for all $\epsilon\in (0,\epsilon_{0})$ and $t \geq {T}$, the solution $v$ of \eqref{PEeq-2.15} satisfies
	\begin{align}
		&~~\mathbb{E}\left[|\partial_{z}{v}(\tau, \tau - t, \zeta)|^4\right] + \int_{\tau - t}^\tau e^{-\kappa(\tau - s)}\mathbb{E}\left[|\partial_{z}v(s, \tau - t, \zeta)|^2\|\partial_{z}v(s, \tau - t, \zeta)\|^2\right]{d}s\\ \notag
		&\leq \mathcal{R}_3 + \mathcal{R}_3\int_{-\infty}^\tau e^{-\kappa(\tau - s)}|\partial_{z}g(s)|^{4} {d}s,
	\end{align}

	where $\zeta\in L^4(\Omega,\mathscr F_{\tau-t};\mathcal H)$ with $\mathscr{L}(\zeta) \in D(\tau - t)$, and $\mathcal{R}_3$ is a positive constant independent of $\tau$, $\epsilon$ and $D$.","status":"unverified"}

