\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:24.613369+00:00","domain":"probability theory","id":"claim_fd4adb4229c16675ff19e3091dd21ac5a05fd7ad121c9601ca05d84d4f1971b1","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2506.09333, 'On the Dimension-Free Concentration of Simple Tensors via Matrix Deviation'] Let $Z_1,\ldots,Z_N$ be i.i.d. copies of a mean-zero subgaussian isotropic random vector $Z$, and let $T\subset \R^d$ be a bounded set. Then, for any integer $p\ge 2$, we have
    $$
    \E\sup_{v\in T}\abs*{\sum_{i=1}^N \ip{Z_i}{v}^p - N \E \ip{Z}{v}^p} 
    \lesssim_{K,p} \gamma(T)^p + \sqrt{N}\gamma(T)\rad(T)^{p-1},
    $$
    where the sign $\lesssim_{K,p}$ hides factors that depend only on $K$ and $p$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.439164+00:00","domain":"probability theory","id":"claim_fd4cdca16d478dd6218e65bef9d728c2fb561d26dfdead3bc19248f35aebbea6","kind":"concept","schema_version":1,"statement":"[Proposition neq gamma/gamma+1 joint invariance of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
Let $\{S_n\}_{n\geq 0}$ be the SRRW-RVM with zero mean, unit variance innovation sequence $\{\xi_n\}$. Then:
    \begin{align*}
        \left(\overline{\boldsymbol{T}}_{n,\lfloor nt\rfloor}:t\geq 0\right)&\to_{\rm{w}} \left(\mathcal{\overline{W}}(t): t\geq 0\right) \quad \text{in $(D([0,\infty)),\mathcal{D})$,} \quad \text{for $p\in[0,\widehat{p})$},\\
        \left(\widetilde{\boldsymbol{T}}_{n,\lfloor nt\rfloor}: t\geq 0\right)&\to_{\rm{w}} \left(\widetilde{\mathcal{W}}(t): t\geq 0\right) \quad \text{in $(D([0,\infty)),\mathcal{D})$,} \quad \text{for $p=\widehat{p}$},\\
     \left(\boldsymbol{T}_{n,\lfloor nt\rfloor}: t\geq 0\right) &\to_{\rm{w}} \left(\mathcal{W}(t): t\geq 0\right) \quad \text{in $(D([0,\infty)),\mathcal{D})$,} \quad \text{for $p\in(\widehat{p},p_c)$},
    \end{align*}
    where $(\mathcal{\overline{W}}(t) :t\geq 0)$, $(\widetilde{\mathcal{W}}(t) :t\geq 0)$ and $(\mathcal{W}(t) :t\geq 0)$ are continuous $\mathbb{R}^2$ valued centered Gaussian processes, with the covariance kernels given by
    \begin{align*}
        \mathbb{E}(\mathcal{\overline{W}}(s)\mathcal{\overline{W}}(t))&=\boldsymbol{\overline{W}}(s), \quad \text{for } 0\leq s\leq t, \quad \text{when $p\in[0,\widehat{p})$},\\
    \mathbb{E}(\widetilde{\mathcal{W}}(s) \widetilde{\mathcal{W}}(t))&=\widetilde{\boldsymbol{W}}(s), \quad \text{for } 0\leq s\leq t, \quad \text{when $p=\widehat{p}$},\\
         \mathbb{E}(\mathcal{W}(s)\mathcal{W}(t))&=\boldsymbol{W}(s), \quad \text{for } 0\leq s\leq t, \quad \text{when $p\in(\widehat{p}, p_c)$}.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:27:32.384428+00:00","domain":"probability theory","id":"claim_fd4f4bc7171f3e06aac275661d8323982d42079dbf6493021e8348f25faf8fbb","kind":"definition","schema_version":1,"statement":"[Definition coupling_optimality_definition of arXiv:2509.23086, 'On Optimal Markovian Couplings of L\'evy Processes'] Let $\mu,\nu\in \mathcal{M}(\mathbb R^d)$ be a pair of bounded measures with equal mass: $\mu(\mathbb R^d)=\nu(\mathbb R^d)$. 

    (i) A \emph{coupling measure} is a (bounded) measure $\gamma\in\mathcal{M}(\mathbb R^{2d})$ such that it holds for all measurable $E\subset \mathbb R^{d}$
    \begin{align*}

        \gamma(E\times \mathbb R^d)=\mu(E),\qquad \gamma(\mathbb R^d\times E)=\nu(E). 
    \end{align*}
    Denote $\Gamma(\mu,\nu)$ \emph{the family of all coupling}. 

    (ii) The \emph{2-optimal transport cost between $\mu,\nu$} is defined by
    \begin{align*}
        \mathcal{C}_2(\mu,\nu):=\inf_{\gamma\in\Gamma(\mu,\nu)} \left\langle \gamma,c_2 \right\rangle=\inf_{\gamma\in\Gamma(\mu,\nu)} \int_{\mathbb R^{2d}}\frac 12 |x-y|^2 d\gamma(x,y).
    \end{align*}

    (iii) A \emph{2-optimal coupling} of the pair $\mu,\nu$ is a coupling measure $\gamma_*\in\Gamma(\mu,\nu)$ such that 
    \begin{align*}
        \left\langle \gamma_*,c_2 \right\rangle=\int_{\mathbb R^{2d}} \frac 12 |x-y|^2 d\gamma_*(x,y)&= \mathcal{C}_2(\mu,\nu). 
    \end{align*}

    (iv) A bounded measure $\gamma\in \mathcal{M}(\mathbb R^{2d})$ is \emph{2-optimal} if it is it is 2-optimal w.r.t. its marginal.","status":"unverified"}

