{"assumptions":[],"created_at":"2026-10-28T00:32:56.076826+00:00","domain":"probability theory","id":"claim_fdfff96b4e7442149fadc1882efaccb226a4c7498b07cd6ad4db822e7685fbf9","kind":"theorem","schema_version":1,"statement":"[Proposition prop:V-sb of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Recall that $\{V(t,x), t \ge 0, x \in \mathbb{R}^d\}$ and $\theta_2$ are defined in (equation e:de-V of the paper) and (equation e:theta12 of the paper), respectively.

\begin{enumerate}[(1)]
 \item (Small ball probability in time). Assume the conditions (equation e:DL of the paper) and (equation e:tilde-U-exist of the paper) hold. Assume additionally either $\beta+\gamma-2\le0$
 or \begin{equation*}
      \begin{cases}
        \beta+\gamma-2>0, \\
        -H_0+\frac{\beta}{\alpha}(d-H)<1.
      \end{cases}
    \end{equation*}
  Then, there exists a constant $C>0$ such that for every $x \in \mathbb{R}^d$,
  \begin{equation*}
    \mathbb{P}\bigg\{\sup_{t\in[0,1]}|V(t,x)-V(0,x)|\le\varepsilon \bigg\}\ge \exp\left(-\frac{C}{\varepsilon}\right) \text{ for all }\varepsilon>0.
  \end{equation*}
  \item (Small ball probability in space). Assume the conditions (equation e:DL of the paper) and (equation e:hat-U-exist of the paper) hold. For $\lambda=(\alpha-d+H)\wedge1$,
  there exists a constant $C>0$ depending on $t>0$ such that
  \begin{equation*}
    \mathbb{P}\bigg\{\sup_{x\in[-1,1]^d}|V(t,x)-V(t,0)|\le\varepsilon \bigg\}\ge \exp\left(-\frac{C}{\varepsilon^{d/\lambda}}\right) \ \text{ for all }\varepsilon>0.
  \end{equation*}
  \item  (Space-time joint small ball probability). Assume the condition (equation e:DL of the paper) and (equation e:U-exist of the paper). Assume additionally either $\beta+\gamma-2\le0$ or
  \begin{equation*}
      \begin{cases}
        \beta+\gamma-2>0, \\
        -H_0+\frac{\beta}{\alpha}(d-H)<1.
      \end{cases}
    \end{equation*}
    For $\lambda=(\alpha-d+H)\wedge1$, there exists a constant $C>0$ such that
  \begin{equation*}
    \mathbb{P}\bigg\{\sup_{(t,x)\in[0,1]\times[-1,1]^d}|V(t,x)|\le\varepsilon \bigg\}\ge \exp\left(-\frac{C}{\varepsilon^{1+d/\lambda}}\right)\ \text{ for all }\varepsilon>0.
  \end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.436812+00:00","domain":"probability theory","id":"claim_fe043280d542329116106ea496f3b14aa64d495cdbbbf84b2281e3856dcffe90","kind":"lemma","schema_version":1,"statement":"[Lemma lem:independence-across-disjoint-balls of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] For each $M>0$, $p,q \in (0,1)$, and $s>0$, there exists $n_* = n_*(M,p,q,s) \in \BN$ such that the following is true. Let $x_1,\ldots,x_n \in \partial \BD$ with $n \geq n_*$. Let $r>0$. Suppose that $|x_j - x_k| \geq 2(s+1) r$ for all distinct $j,k \in [1,n]_{\BZ}$. Let also $\Psi$ be a GFF on $\BD$ with boundary conditions given by a measurable function bounded by $M$. Let $E_1,\ldots,E_n$ be a family of events such that each $E_j$ is measurable with respect to the $\sigma$-algebra generated by $\Psi|_{B_r(x_j) \cap \BD}$. Suppose that $\BP[E_j] \geq p$ for all $j \in [1,n]_{\BZ}$. Then
	\begin{equation*}
		\BP\!\left\lbrack\bigcup_{j = 1}^n E_j\right\rbrack \ge q. 
\end{equation*}","status":"unverified"}

