			\Phi^\epsilon(t,\omega)z,
			\Phi^0(t,\omega)z
			\big)
			\longrightarrow0
			\qquad\text{as }\epsilon\to0.
		\end{align*}
	\end{itemize}
	Then, for every $\omega\in\Omega$,
	\begin{align}
		\operatorname{dist}_{\mathbb X}\big(
		\mathcal A^\epsilon(\omega),
		\mathcal A^0(\omega)
		\big)
		\longrightarrow0
		\qquad\text{as }\epsilon\to0.
	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:29:08.706364+00:00","domain":"probability theory","id":"claim_fed8e1d61bdaaf9b2fabb85646de2aa786f70204d7da71fcabc280bcb921273c","kind":"concept","schema_version":1,"statement":"[Corollary cor:asymp_miss_prob of arXiv:2412.00279, 'Optimal local storage policy based on stochastic intensities and its large scale behavior'] Under the same hypothesis as Theorem (thm:asymp_miss_rate of the paper), the optimal miss probability satisfies:
