        := \frac{1}{Z^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}, \times}_{L , \beta , r}}\exp \left( - \frac{1}{2\beta}\sum_{\{ x , y\} \in E(\ensuremath{\mathbb{Z}}^2)} \frac{\left( \varphi(x) - \varphi(y)\right)^2}{r_{x} r_y } - \frac{1}{2\beta} \sum_{\{ x , y\} \in E_\times(\ensuremath{\mathbb{Z}}^2) \setminus E(\ensuremath{\mathbb{Z}}^2)} \left( \varphi(x) - \varphi(y)\right)^2 \right).
    \end{multline*}
    We denote by $\mathrm{Var}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}, \times}_{L , \beta, r}$ the variance with respect to this measure.","status":"unverified"}

