{"assumptions":[],"created_at":"2026-10-27T20:48:25.220707+00:00","domain":"probability theory","id":"claim_ffbf76489eb46b5ebef8fd1bc6da0e522b01e2c0df35086ef5dab0dcf91c6001","kind":"lemma","schema_version":1,"statement":"[Lemma lem: 358 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] {LS20}} and {[Vova25a]}]
Let $g$, $f$, $\tilde{f}$, $\eta_{0}$, and $\chi$ be as in Theorem (thm: 96 of the paper) and Proposition (prop: 147 of the paper).
Consider a domain $\Omega$ of the form
\begin{equation*}
	\Omega = \{z=x+\mathrm{i}\eta\in\mathbb{C}: x \in (a,b),\, \eta\in(cN^{-\tau}\eta_{0},1) \},
\end{equation*}
such that $\textnormal{supp}(f)\subset (a,b)$ and $\tau,c$ are positive constants.
Let $K(z)$ be a holomorphic function on $\Omega$ satisfying
\begin{equation*}
	|K(z)| \le C|\eta|^{-s}, \quad z\in\Omega,
\end{equation*}
for some constants $C>0$ and $s\ge0$. Then there exists a constant $C'>0$ depending only on $g$, $\chi$, and $s$, such that
\begin{equation*}
	\bigg| \int_{\Omega}\frac{\partial\tilde{f}}{\partial\bar{z}} K(x+\mathrm{i}\eta) \mathrm{d}x\mathrm{d}\eta \bigg|
	\le
	\begin{cases}
		CC'\eta_{0}^{1-s}\log{N}, & s\in[0,2] \\
		c^{2-s}CC'N^{-\tau(2-s)}\eta_{0}^{1-s}\log{N}, & s > 2
	\end{cases}
	.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:33.549518+00:00","domain":"probability theory","id":"claim_ffc428482c97edfd5c756af7bbd32aca25b8efde226cc409391d41dd2a9bf5a9","kind":"theorem","schema_version":1,"statement":"[Theorem 21 (Window/profile cut-off for small exponents $\gamma<1/3$) of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] \hfill

	\noindent
	Let $0<\gamma<\tfrac{1}{3}$, let $k\in\mathbb{N}$, and for $1\le j\le k$ let $\psi_{j,\varepsilon}$ be the $j$-th non-constant eigenfunction of $-\mathcal L_\varepsilon$ with eigenvalue $\lambda_{j,\varepsilon}=\lambda_j\varepsilon^{\frac{\gamma-1}{1+\gamma}}$. Let the initial density be as in \cref{eq:initialcond} with $\delta(\varepsilon)=\varepsilon^{\frac{1-\gamma}{1+\gamma}}$.
	For $x_0\neq0$, with the notation of \cref{lem:pointwise_smallgamma,lem:time_smallgamma} let $t_\varepsilon$ be the unique time defined by \cref{eq:teps_def} and set $w_\varepsilon=\varepsilon^{\frac{1-\gamma}{1+\gamma}}$. Then for any fixed $r\in\mathbb{R}$ it follows that
	\begin{equation*}
		\lim_{\varepsilon\to0} d_{k,\varepsilon}(t_\varepsilon+r w_\varepsilon,x_0)
		= e^{-\lambda_k r}.
	\end{equation*}
	In particular, the truncated $\chi^2$--distance exhibits window cut-off (indeed profile cut-off) with cut-off time $t_\varepsilon$, window $w_\varepsilon$ and profile function $\mathfrak p(r)=e^{-\lambda_k r}$, $r\in \mathbb{R}$.

	For $x_0=0$, let
	\begin{equation*}
		E_k:=\{1\leq j\leq k:\ \psi_j(0)\neq 0\}.
	\end{equation*}
	If $E_k=\emptyset$, then $d_{k,\varepsilon}(t,0)=0$ for all $t\geq 0$. Otherwise, letting $m:=\max E_k$, the centered initial datum exhibits window cut-off (indeed profile cut-off) with cut-off time determined by the condition
	\begin{equation*}
		e^{-2\lambda_m \varepsilon^{\frac{\gamma-1}{1+\gamma}} t_\varepsilon}
		\left(\int \varrho_{\varepsilon,0}(x)\psi_{m,\varepsilon}(x)\,\dx\right)^2=1,
	\end{equation*}
	the same time window $w_\varepsilon:=\varepsilon^{\frac{1-\gamma}{1+\gamma}}$, and profile function $\mathfrak p(r)=e^{-\lambda_m r}$.","status":"unverified"}

